(182963, '2249637', 'ISO 23717', 'Steel wire and wire products - Hose reinforcement wire', 'Active', '', '', '', 'ISO 23717:2006', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the composition, dimensions and mechanical properties of steel wire with a high mass fraction of carbon, generally brass coated, for reinforcing high-pressure hoses.\nIt is applicable to multiple parallel wires, braided or spirally wrapped for reinforcement in a rubber or synthetic hose that is made to withstand a relatively high bursting pressure.', '73', '81.00', '127.00', 'USD', 'ISO 23717:2006', '1263244', '03.060* 77.140* 77.140.65', 'Acceptance specification*Armouring*Brass*Carbon content*Chemical composition*Classification*Coating thickness*Composition*Definitions*Delivery conditions*Designations*Dimensions*Finishes*Hoses*Iron*Layers*Limit deviations*Marking*Materials*Materials testing*Measurement*Mechanical properties*Mechanical testing*Metal coatings*Orders (sales documents)*Plastics hose*Reinforcement*Reverse-bend tests*Rubber hoses*Specification (approval)*Steel products*Steel wires*Steels*Tensile strength*Tensile testing*Testing*Thickness*Tolerances (measurement)*Torsional tests*Wire rods*Wires*Strengthening*Amplification*Flexible pipes', '', '2022', '20', '', '', '', '', ''),
(182964, '2248254', 'ISO 18665', 'Traditional Chinese medicine - Herbal decoction apparatus', 'Active', '', '', '', 'ISO 18665:2015', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the general requirements of herbal decoction apparatus with design pressures less than 0,1MPa. It includes both hermetic and non-hermetic decoction apparatus.\nThis document is applicable to herbal decoction apparatus for individual herbal formula prescriptions and for commercial use as well as private use. It also applies to the decocting part of the integrated apparatus of decoction and package.', '73', '81.00', '127.00', 'USD', 'ISO 18665:2015', '1905766', '01* 23.020* 23.020.30* 11* 11.040* 11.040.99* 13* 27.060* 27.060.30', '', '', '2022', '16', '', '', '', '', ''),
