(184855, '1897829', 'ISO 12646', 'Graphic technology - Displays for colour proofing - Characteristics', 'Active', 'CIE 116*ISO 15076-1*IEC 61966-4*CEI 61966-4*ISO 9241-306*ISO 9241-302*CIE 122*ISO 11664-2*CIE S 014-2*IEC 61223-2-5*CEI 61223-2-5*IEC 61966-2-1*CEI 61966-2-1*ISO 15930-7*ISO 12641*ISO 9241-305*CIE 159*ISO 9241-303*ISO 9241-304*ISO 9241-2*ISO 11664-1*CIE S 014-1*ISO 9241-307*ISO 3664*ISO 9241-1', '', '', 'ISO/DIS 12646 (2014-01)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 12646:2015 specifies requirements for two conformance levels for the characteristics of displays to be used for soft proofing of colour images. Included are requirements for uniformity and variations of electro-optical properties with viewing direction for different driving signals.', '0', '81.00', '127.00', 'USD', 'ISO 12646:2008;ISO 12646:2004', '1566340;1159188', '37.100.01', 'Convergence*Definitions*Display*Dissolution*Electrooptics*Graphic technology*Graphic trade*Indicators*Luminance factor*Presentation of colour*Printing*Screens*Testing*Uniformity*Viewing conditions*Regularity*Evenness', '', '2015', '12', '', '', '', '', ''),
(184870, '1897833', 'ISO 15247', 'Zinc sulfide concentrates - Determination of silver content - Acid dissolution and flame atomic absorption spectrometric method', 'Active', 'ISO 4787*ISO 5725-2*ISO 385*ISO 648*ISO 1042', '', '', 'ISO/FDIS 15247 (2015-02)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 15247:2015 specifies an acid dissolution and flame atomic absorption spectrometric method for the determination of silver content of zinc sulfide concentrates.The method is applicable to the determination of silver in zinc sulfide concentrates containing up to 60 % (m/m) zinc in the form of zinc blende and related materials.The method is applicable to silver contents from 10 g/t to 500 g/t.', '0', '124.00', '191.00', 'USD', 'ISO 15247:1999', '223818', '73.060.99', 'Acid dissolution*Chemical analysis and testing*Determination of content*Flame atomic absorption spectrometry*Flame photometry*Silver*Zinc ores*Zinc sulfide', '', '2015', '15', '', '', '', '', ''),
(184872, '1897843', 'ISO 18619', 'Image technology colour management - Black point compensation', 'Active', 'ISO 15076-1', '', '', 'ISO/DIS 18619 (2014-04)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 18619:2015 specifies a procedure, including computation, by which a transform between ICC profiles can be adjusted (compensated) to take into account differences between the dark end of the source colour space and the dark end of the destination colour space. This is referred to as black point compensation (BPC). The relative colorimetric encoding of ICC profile transforms already provides a mechanism for such adjustment of the light (white) end of the tone scale.', '0', '124.00', '191.00', 'USD', '', '', '35.240.30* 37.100.99', 'Black*Blackening value*CIELAB formulae*Colour*Colour value*Colours technology*Compensation*Computers*Definitions*Digital*Image processing*Image production*Mathematical calculations*Printing*Process colours*Transformation', '', '2015', '14', '', '', '', '', ''),
(184873, '1897837', 'ISO 16954', 'Dentistry - Test methods for dental unit waterline biofilm treatment', 'Active', 'ISO 14457*ISO 7494-2*ISO 1942*ISO 16266*ISO 7494-1*ISO 8199*IEC 60601-1*CEI 60601-1', '', '', 'ISO/FDIS 16954 (2015-01)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 16954:2015 provides type test methods for evaluating the effectiveness of treatment methods intended to prevent or inhibit the formation of biofilm or to remove biofilm present in dental unit procedural water delivery systems under laboratory conditions.It does not apply to devices intended to deliver sterile procedural water or sterile solution. It also does not apply to lines, tubing, or hoses that deliver compressed air within the dental unit.It does not establish specific upper limits for bacterial contamination or describe test methods to be used in clinical situations. It also does not establish test methods for evaluating any deleterious side effects potentially caused by treatment methods.The test methods provided in ISO 16954:2015 can be used to test other dental equipment that delivers non-sterile water to the oral cavity.', '0', '124.00', '191.00', 'USD', 'ISO/TS 11080:2009', '1630287', '11.060.20', 'Bacterial*Bacterial count*Biofilm*Definitions*Dental*Dental working unit*Dentistry*Evaluations*Germs*Infection*Medical technology*Microbiological*Microbiology*Pipelines*Testing*Treatment*Water hoses*Water pollution*Cords*Conduits*Electric cables', '', '2015', '14', '', '', '', '', ''),
