(185247, '1891608', 'ISO 13574', 'Industrial furnaces and associated processing equipment - Vocabulary', 'Active', 'IEC 61511-1*CEI 61511-1*ISO 8421-1*IEC 61508-2*CEI 61508-2*IEC 61511-3*CEI 61511-3*IEC 61508-4*CEI 61508-4*ISO 10241-2*ISO 10241-1*IEC 61508-7*CEI 61508-7*EN 676*IEC 61508-3*CEI 61508-3*IEC 61508-5*CEI 61508-5*IEC 61511-2*CEI 61511-2*IEC 61508-6*CEI 61508-6*ISO 13577-1*IEC 61511-1 Corrigendum 1*CEI 61511-1 Corrigendum 1*IEC 61508-1*CEI 61508-1', '', '21771073-1', '', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 13574:2015 establishes the vocabulary for all industrial furnaces and associated processing equipment (TPE). It provides terms and definitions which are intended to be applied to the following documents:- ISO 13577 (all parts); - ISO 13579 (all parts).', '0', '278.00', '434.00', 'USD', '', '', '01.040.25* 25.180.01', 'Definitions*Furnaces*Heat treatment*Incinerators*Industrial*Industrial ovens*Processing equipment*Terminology*Vocabulary', '', '2015', '143', '', '', '', '', ''),
