(1660, 225, '_elementor_data', '[{\"id\":\"3246e86\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"custom\",\"size\":1273},\"width_tablet\":{\"unit\":\"custom\",\"size\":\"\",\"sizes\":[]},\"width_mobile\":{\"unit\":\"custom\",\"size\":488},\"background_background\":\"gradient\",\"background_color\":\"#1E00AE\",\"background_color_b\":\"#0C0048\",\"_flex_size\":\"none\",\"_element_width\":\"initial\",\"_element_width_mobile\":\"initial\"},\"elements\":[{\"id\":\"6947181\",\"elType\":\"container\",\"settings\":{\"boxed_width\":{\"unit\":\"px\",\"size\":1405,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"50\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"7272bed\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Join Our Newsletter\",\"align\":\"center\",\"title_color\":\"#FFFFFF\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Ford Antenna\",\"typography_font_size\":{\"unit\":\"px\",\"size\":30,\"sizes\":[]},\"typography_font_weight\":\"500\",\"typography_line_height\":{\"unit\":\"px\",\"size\":36,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"102058b\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Signup to be the first to hear about exclusive deals, special offers and upcoming collections\",\"align\":\"center\",\"title_color\":\"#FFFFFF\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Ford Antenna\",\"typography_font_size\":{\"unit\":\"px\",\"size\":14,\"sizes\":[]},\"typography_font_weight\":\"300\",\"typography_line_height\":{\"unit\":\"px\",\"size\":24,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"b320aad\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"shortcode\":\"[contact-form-7 id=\\\"efbcd83\\\" title=\\\"send email\\\"]\",\"_flex_align_self\":\"center\",\"custom_css\":\".flex-container {\\r\\n    display: flex;