(2915, 364, '_messages', 'a:22:{s:12:\"mail_sent_ok\";s:53:\"Xin cảm ơn, form đã được gửi thành công.\";s:12:\"mail_sent_ng\";s:118:\"Có lỗi xảy ra trong quá trình gửi. Xin vui lòng thử lại hoặc liên hệ người quản trị website.\";s:16:\"validation_error\";s:86:\"Có một hoặc nhiều mục nhập có lỗi. Vui lòng kiểm tra và thử lại.\";s:4:\"spam\";s:118:\"Có lỗi xảy ra trong quá trình gửi. Xin vui lòng thử lại hoặc liên hệ người quản trị website.\";s:12:\"accept_terms\";s:67:\"Bạn phải chấp nhận điều khoản trước khi gửi form.\";s:16:\"invalid_required\";s:48:\"Vui lòng nhập dữ liệu cho trường này.\";s:16:\"invalid_too_long\";s:54:\"Trường dữ liệu này có mục nhập quá dài.\";s:17:\"invalid_too_short\";s:51:\"Trường dữ liệu có mục nhập quá ngắn.\";s:13:\"upload_failed\";s:36:\"Tải file lên không thành công.\";s:24:\"upload_file_type_invalid\";s:69:\"Bạn không được phép tải lên file theo định dạng này.\";s:21:\"upload_file_too_large\";s:50:\"Dung lượng file được tải lên quá lớn.\";s:23:\"upload_failed_php_error\";s:36:\"Tải file lên không thành công.\";s:12:\"invalid_date\";s:61:\"Vui lòng nhập ngày tháng theo định dạng YYYY-MM-DD.\";s:14:\"date_too_early\";s:64:\"Trường dữ liệu này có ngày sớm hơn ngày cho phép.\";s:13:\"date_too_late\";s:64:\"Trường dữ liệu này có ngày trễ hơn ngày cho phép.\";s:14:\"invalid_number\";s:37:\"Vui lòng nhập vào một con số.\";s:16:\"number_too_small\";s:57:\"Trường dữ liệu này có một con số quá nhỏ.\";s:16:\"number_too_large\";s:57:\"Trường dữ liệu này có một con số quá lớn.\";s:23:\"quiz_answer_not_correct\";s:30:\"Câu trả lời chưa đúng.\";s:13:\"invalid_email\";s:36:\"Vui lòng nhập địa chỉ email.\";s:11:\"invalid_url\";s:21:\"Vui lòng nhập URL.\";s:11:\"invalid_tel\";s:38:\"Vui lòng nhập số điện thoại.\";}'),
