(2606, 'The New MRCPsych Paper I Practice MCQs and EMIs', 'Authors: Oliver White, Clare Oakley, Alexandra C. Rankin', '', '', '1/25/2009 12:00:00 AM', '', '0', 138, '2406151035001', '', '', 'The Renal Drug Handbook offers information compiled from the UK Renal Pharmacy Group and features drug monographs guiding physicians in how to prescribe, prepare, and administer drugs to patients undergoing renal replacement therapy. Also provides a practice-based review of drug utilization in renal units across the UK. Purchasers of The Renal Drug Handbook receive a free 30-day trial to the The Renal Drug Database. A code to activate the trial may be found on the inside-front cover of The Renal Drug Handbook; the trial is activated by entering the code on the Redeem page of this website, accessible from the homepage. This document has been replaced by ISBN: 9780429863646. View the most recent version.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2607, 'The Biology of Sea Turtles, Volume I', 'John A. Musick|Peter L. Lutz', '', '', '12/9/1996 12:00:00 AM', '', '0', 447, '2407160858001', '', '', '', '0.000000', 330.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2608, 'STESSA 2000: Behaviour of Steel Structures in Seismic Areas Proceedings of the Third International Conference STESSA 2000, Montreal, Canada, 21-24 August 2000', 'Authors: Federico Mazzolani, Robert Tremblay', '', '', '1/1/2000 12:00:00 AM', '', '0', 781, '2407160916001', '', '', 'This standard covers repair and modification of atmospheric-type shop-fabricated carbon and stainless steel aboveground storage tanks (ASTs). It applies to ASTs storing stable, flammable, and combustible liquids, operating at atmospheric pressure and temperatures between ambient temperature and 200°F.', '0.000000', 98.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2609, 'STDMETH STANDARD METHODS', 'APHA, AWWA and WEF', '', '', '12/16/2013 12:00:00 AM', '', '0', 0, '2407160916002', '', '', 'This Standard provides inspection and evaluation criteria required to determine the suitability for continued service of aboveground storage tanks (AST), as defined in this Standard, until the next scheduled inspection. The purpose of conducting inspections is to identify the condition of and\nchanges to the AST.', '0.000000', 120.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
