(2663, 'SPIE ELECTRO-OPTICAL IMAGING S', 'International Society for Optics and Photonics', '', '', '4/10/2017 12:00:00 AM', '', '0', 0, '2407160916056', '', '', 'This standard sets requirements for three levels of performance for elastomeric exterior waterborne high-build coatings suitable for use on above-ground masonry or concrete substrates such as concrete masonry unit (CMU) block walls, precast or poured-in-place concrete, concrete tilt-up construction, stucco, and fiber cement siding. The performance levels are based on results of material testing for weathering and chemical resistance properties, and testing for physical properties, such as tensile elongation and water vapor permeance.', '0.000000', 109.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2664, 'IPI MACHINERYS HDBK, MACHINERYS HANDBOOK GUIDE', 'Industrial Press, Incorporated', '30th', 'active', '3/1/2020 12:00:00 AM', 'Industrial Press, Inc.', '0', 0, '9780831130947', '', 'Technology & Engineering,\nMachinery', 'SOFTCOVER * ISBN: 9780831130947', '0.000000', 126.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2665, 'SCTE 209 2024 Technical Report UHF Leakage, Ingress, Direct Pickup', 'Society of Cable Telecommunication Engineers', '', '', '2024', '', '0', 80, '2407160916057', '', '', 'This document describes the transport subsystem characteristics and normative specifications of the in-band Service Multiplex and Transport Subsystem Standard for Cable Television.', '0.000000', 109.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2666, 'SCTE 197 2024 Recommendations for Spot Check Loudness Measurements', 'Society of Cable Telecommunication Engineers', '', '', '2024', '', '0', 8, '2407160916058', '', '', 'Calibration of signal leakage detection equipment on a regular basis is mandatory to ensure measurement accuracy. This document covers two general types of calibration that can be used: directly-connected RF signal source and calibrated field strength (aka calibrated leak). The first technique is used to establish the general measurement accuracy of a piece of leakage detection equipment, and the second gauges its ability to measure a known signal leakage field strength in the outdoor environment.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2667, 'SCTE 191 2018 (R2024) Test Method for Axial Pull Force, Female “F” Port', 'Society of Cable Telecommunication Engineers', '', '', '2018', '', '0', 9, '2407160916059', '', '', 'This document defines the coding constraints on ITU-T Rec. H.265 | ISO/IEC 230008-2 [MPEG-HEVC] video compression (hereafter called \\\"HEVC\\\") for Cable Television. In particular, this document describes the coding of a single HEVC coded video elementary stream in an SDR or HDR format carried in MPEG2 transport (ISO/IEC 13818-1) [MPEG-2 TS] for linear delivery systems supporting ad insertion services [SCTE 35] or for adaptive bitrate streaming delivery technologies [SCTE 214-1]. Beyond linear delivery with DPI, signaling is provided for segmentation of content for xDVR applications.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2668, 'SCTE 172 2024 Constraints on NAL Structured Video Coding for Digital Program Insertion', 'Society of Cable Telecommunication Engineers', '', '', '2024', '', '0', 14, '2407160916060', '', '', 'Until recently, cable system signal leakage monitoring and repair activities were necessarily focused on preventing interference to aeronautical navigation and communication systems in the 108 megahertz (MHz) to 137 MHz and 225 MHz to 400 MHz very high frequency (VHF) and ultra high frequency (UHF) bands.1 Although Section 76.605(c) of the Federal Communications Commission (FCC) Rules contains leakage limits for frequencies above 400 MHz, cable signals in the UHF spectrum were generally unobserved because (1) there were no explicit FCC requirements to monitor leakage on those frequencies, and (2) there were few if any complaints of interference.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2669, 'SCTE 135-1 2018 (R2024) DOCSIS 3.0 Part 1: Physical Layer Specification', 'Society of Cable Telecommunication Engineers', '', '', '2018', '', '0', 153, '2407160916061', '', '', 'As part of managing the relative audio loudness of content, this document provides recommendations for measuring content carried in a single programming channel of a program network for 24-hours with an audio loudness meter consistent with the measurement techniques discussed in [A/85] as well as recording the measured loudness and loudness metadata value 1 .  The document also recommends some approaches for interpretation of the measurement data and for actions to be taken.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2670, 'SA/SNZ TS ISO 16975.4:2024', 'Standards Australia / SNZ', '', '', '3/28/2024 12:00:00 AM', '', '0', 32, '2407160916062', '', '', 'This test procedure is used to evaluate the mechanical strength of female \\\"F ports when an axial pull force is applied.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2671, 'SA/SNZ TS IEC 63446:2024', 'Standards Australia / SNZ', '', '', '4/12/2024 12:00:00 AM', '', '0', 17, '2407160916063', '', '', 'This document defines additional video coding and transport constraints on [SCTE 128-1] and [SCTE 128-2] (which constrains ITU-T H.264/ ISO/IEC [14496-10](“AVC”) video compression [14496-10] or on [SCTE 215-1], and [SCTE 215-2](which constrains ITU-T H.265/ISO/IEC [23008-2] (“HEVC”) video compression [23008-2]) or on [SCTE 281-1] and [SCTE 281-2] (which constrains ITU-T H.266/ ISO/IEC [23090-3](“VVC”) video compression [23090-3]) for Digital Program Insertion applications using SCTE 35 messaging [SCTE 35]. AVC, HEVC, VVC video uses a network abstraction layer structure to carry video and in this document “NAL structured video” will collectively refer to AVC, HEVC, and VVC Video.  Note: This standard applies only when both the insertion content and the network both use AVC video coding, or both use HEVC video coding, or both use VVC video coding.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2672, 'PPI MAB-09 2023 Design of HDPE Water Mains for the Lateral Spread Seismic Hazard', 'Plastics Pipe Institute', '', '', '2023', '', '0', 3, '2407160916064', '', '', 'This specification is part of the DOCSIS family of specifications. In particular, this specification is part of a series of specifications that defines the third generation of high-speed data-over-cable systems. This specification was developed for the benefit of the cable industry and includes contributions by operators and vendors from North America, Europe, China, and other regions.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2673, 'IET SPECTRUM AND NETWORK MEAS, SPECTRUM AND NETWORK MEASUREMENTS', 'Institution of Engineering and Technology', '', '', '1/1/2014 12:00:00 AM', '', '0', 0, '9781613530146', '', '', 'SBEW5060 * ISBN: 9781613530146', '0.000000', 90.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
