(2677, 'PIP PNSMV059 Nickel and Nickel Alloy Other Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 5, '2407160916068', '', '', 'This Practice provides the mechanical design, fabrication, examination, inspection, and documentation requirements for pressure vessel process trays, tower structured packing, tower random packing, distributors, and related components welded to the pressure boundary.', '0.000000', 300.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2678, 'PIP PNSMV058 Nickel and Nickel Alloy Plug Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 14, '2407160916069', '', '', 'This Practice provides procedures for installing ceramic fiber refractory linings in fired heaters and other process equipment. Installation includes steel surface preparation and coating, ceramic fiber installation, and repair of ceramic fiber linings. Ceramic fiber refractories in this Practice include: a. Alkaline earth silicate fiber, b. Refractory ceramic fiber, and c. Polycrystalline wool. This Practice does not include installation procedures for mineral wool, fiberglass, or other non-refractory fiber insulation materials.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2679, 'PIP PNSMV054 Nickel and Nickel Alloy Globe Valve Descriptions', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '0', 30, '2407160916070', '', '', 'This Practice describes guidelines for selecting non-lubricated flexible couplings for general purpose applications for most types of rotating equipment. General purpose coupling applications include loads with steady, non-fluctuating torque characteristics within the power and speed ranges defined in this Practice.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2680, 'PIP PNSMV049 Plastic and Plastic-Lined Other Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 9, '2407160916071', '', '', 'This Practice provides requirements for suppliers providing nickel and nickel alloy valves (other than gate, globe, check, ball, butterfly, and plug valves) included in the PIP Piping Material Specifications (PMSs).', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2681, 'PIP PNSMV048 Plastic and Plastic-Lined Plug Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 5, '2407160916072', '', '', 'This Practice provides detailed descriptions for the purchase of nickel and nickel alloy plug valves included in PIP Piping Material Specifications (PMSs).', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2682, 'PIP PNSMV047 Plastic and Plastic-Lined Butterfly Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 6, '2407160916073', '', '', 'This Practice provides the detailed purchase descriptions for nickel and nickel alloy globe valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for nickel and nickel alloy globe valve tag numbers to applicable PIP PMSs.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2683, 'PIP PNSMV037 Bronze and Iron Butterfly Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 11, '2407160916074', '', '', 'This Practice provides requirements for suppliers providing other valves (other than gate, globe, check, ball, butterfly, and plug valves) included in the PIP Piping Material Specifications (PMSs).', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
