(2688, 'PIP PNSMV013 Low and Intermediate Alloy Steel Gate Valve Descriptions', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '0', 57, '2407160916079', '', '', 'This Practice provides requirements for suppliers providing stainless steel plug valves included in PIP Piping Material Specifications (PMSs).', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2689, 'PIP PNSMV004 Carbon Steel Globe Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2024 12:00:00 AM', '', '0', 21, '2407160916080', '', '', 'This Practice provides the detailed purchase descriptions for stainless steel gate valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for stainless steel gate valve tag numbers to applicable PIP PMSs.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2690, 'PIP PNSMV003 Carbon Steel Gate Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2024 12:00:00 AM', '', '0', 40, '2407160916081', '', '', 'This Practice provides the detailed purchase descriptions for intermediate alloy steel globe valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for intermediate alloy steel globe valve tag numbers to applicable PIP PMSs.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2691, 'PIP PN01SA0S01 Piping Material Specification 1SA0S01 Class 150, 304/304L Stainless Steel, Socket Weld, C.A.- None, Process', 'Process Industry Practices', '', '', '3/1/2023 12:00:00 AM', '', '0', 6, '2407160916082', '', '', 'This Practice provides the detailed purchase descriptions for low and intermediate alloy steel gate valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for low and intermediate alloy steel gate valve tag numbers to applicable PIP Piping Material Specifications.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2692, 'PIP PLSMV005 Carbon Steel Check Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 23, '2407160916083', '', '', 'This Practice provides the detailed purchase descriptions for carbon steel globe valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for carbon steel globe valve tag numbers to applicable PIP PMSs.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2693, 'PIP PLE00012 Piping Examination and Leak Testing Guide - B31.8 Pipelines', 'Process Industry Practices', '', '', '4/1/2024 12:00:00 AM', '', '0', 8, '2407160916084', '', '', 'This Practice provides the detailed purchase descriptions for carbon steel gate valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for carbon steel gate valve tag numbers to applicable PIP Piping Material Specifications.', '0.000000', 75.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2694, 'PIP PHDVEV001 Documentation Requirements for Hygienic Stainless Steel and Nickel Alloy Vessels ASME Code Section VIII, Divisions 1 and 2', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '0', 28, '2407160916085', '', '', '', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2695, 'PIP PCTPK001 Packaged Equipment Instrumentation Inspection and Testing Requirements Sheet', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '0', 3, '2407160916086', '', '', 'This Practice provides requirements for suppliers providing carbon steel check valves included in PIP Pipeline Systems Material Specifications (PMSs).', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2696, 'PIP PCSPK010 Small, General Purpose Packaged Equipment Instrumentation Specification', 'Process Industry Practices', '', '', '4/1/2024 12:00:00 AM', '', '0', 12, '2407160916087', '', '', 'This Practice describes guidelines for specifying requirements for examination and leak testing of metallic pipeline systems designed in accordance with ASME B31.8 Gas Transmission and Distribution Piping Systems. This Practice provides guidelines for specifying requirements for examination of piping materials, components, fabrication, assembly, installation, and associated documentation. This Practice provides guidelines for the extent of examination, criteria for acceptance, and correction of defective work. This Practice describes the types of leak tests, basis for selecting the appropriate tests, and arrangements for testing piping.', '0.000000', 180.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2697, 'PIP PCEPA002 Process Analyzer Project Implementation Guidelines', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '0', 12, '2407160916088', '', '', 'This Practice provides data forms and the associated instructions for specifying requirements for Stainless Steel and Nickel Alloy pressure vessels for hygienic service constructed in accordance with ASME Boiler and Pressure Vessel Code, Section VIII, Division 1 or Division 2, henceforth referred to as the Code. Requirements that are specific to Code, Section VIII, Division 2 are shown in braces { }. This Practice is used with PIP VECV1001, PIP VEDV1003 (when required), and PIP VESV1002 to specify information necessary for the manufacturer to design and fabricate a pressure vessel. Polymer and Glass lined vessels are not covered in this scope.', '0.000000', 50.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2698, 'PIP PCEFL001 Flow Measurement Guideline', 'Process Industry Practices', '', '', '4/1/2024 12:00:00 AM', '', '0', 26, '2407160916089', '', '', '', '0.000000', 150.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2699, 'PIP PCDPK001 Packaged Equipment Instrumentation Documentation Requirements Sheet and Instructions', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '0', 10, '2407160916090', '', '', 'This Practice provides the minimum requirements for the performance, design, fabrication, testing, and inspection of instrumentation and control systems installed on small, general purpose packaged equipment units. This Practice is not intended for packaged analyzers systems or for safety-instrumented systems (SIS). For instrumentation associated with larger, more complex equipment packages, see PIP PCSPK001. This Practice was previously published as PCSPS010.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2700, 'PIP PCCPR001 Packaged Equipment Instrumentation Documentation Requirements Sheet and Instructions', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '0', 7, '2407160916091', '', '', 'This Practice provides guidelines for the design, specification, purchasing, and installation of process analyzer systems. This requires knowledge, integration, and management of multi-disciplinary engineering skills and resources that may bridge several different organizations. This Practice can be used to assist in assessment and definition of roles and responsibilities for those tasks required for a given project.', '0.000000', 120.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2701, 'PIP ELSSG12 Design and Fabrication of Outdoor Enclosures for Motor Controllers and Switchgear', 'Process Industry Practices', '', '', '4/1/2024 12:00:00 AM', '', '0', 17, '2407160916092', '', '', 'This Practice provides engineering guidance for the selection, design, and application of flow measurement systems. This Practice provides guidelines, performance considerations, and preliminary recommendations for the selection of flow meters and their general application. This guideline applies to devices used to measure the flow of single phase, homogeneous liquids, vapors, and gases. This Practice presents commonly accepted meter types but does not limit application choices. Unique or special requirements may require consideration of other meter types. Specific custody transfer guidelines are not provided and are only mentioned with reference to other industry practices.', '0.000000', 50.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2702, 'PIP ELSPK01 Electrical Requirements for Packaged Equipment', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '0', 32, '2407160916093', '', '', 'This Practice provides the purchaser with the method for preparing PIP PCDPK001-R, Packaged Equipment Instrumentation Documentation Requirements Sheet. Packaged equipment suppliers should also become familiar with the symbology used. This Practice contains key information about the requirements of the owner, which are important to clearly communicate to the Packaged System Supplier. The documentation requirements sheet is to be completed by the designer with owner input, review, and approval. This documentation requirements sheet is to be used in conjunction with PIP PCSPK001 and PIP PCTPK001. This Practice was previously published as PCDPS001.', '0.000000', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2703, 'PID Tuning A Modern Approach via the Weighted Sensitivity Problem', 'Authors: Salvador Alcántara Cano, Ramon Vilanova Arbós, Carles Pedret i Ferré', '', '', '11/20/2020 12:00:00 AM', '', '0', 155, '2407160916094', '', '', 'This Practice provides requirements criteria for pressure measurement equipment selection and for design of pressure measurement systems. This Practice describes the design requirements for pressure and differential pressure measurement systems excluding DP level and flow measurements.', '0.000000', 150.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2704, 'PIC16F1847 Microcontroller-Based Programmable Logic Controller Intermediate Concepts', 'Author: Murat Uzam', '', '', '10/23/2020 12:00:00 AM', '', '0', 483, '2407160916095', '', '', 'This Practice describes the requirements for the design, fabrication, inspection, testing, and shipping of free-standing outdoor enclosures. This equipment is used for housing low and medium voltage motor controllers and switchgear. The requirements of this Practice shall apply to walk-in and non-walk-in enclosures located in a non-classified area. This Practice is not intended for enclosures that will be located in classified areas. These enclosures are not intended for climate-controlled or pressurized applications. When pressurized or insulated climate-controlled enclosures are required, see PIP ELSSG11.', '0.000000', 200.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2705, 'PIC16F1847 Microcontroller-Based Programmable Logic Controller Advanced Concepts', 'Author: Murat Uzam', '', '', '10/23/2020 12:00:00 AM', '', '0', 587, '2407160916096', '', '', 'This Practice describes the electrical requirements for design, manufacture, inspection, testing, and shipping of packaged equipment (also referred to as skid mounted equipment). Electrical systems for packaged equipment may include components such as electrical enclosures, motors, motor controllers, heaters and process heaters, relays, controls and control panels, control stations, pilot devices, indicating lights, transformers, wires, and conduits. This Practice does not address requirements for motor control centers, switchracks, substations, power control centers or remote instrument enclosures.', '0.000000', 143.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2706, 'PDA TR 15 Technical Report No. 15, Revised 2009 (TR 15) Validation of Tangential Flow Filtration in Biopharmaceutical Applications', 'Parenteral Drug Association', '', '', '6/1/2009 12:00:00 AM', '', '0', 55, '2407160916097', '', '', 'Respiratory diseases include the mild forms of upper respiratory infection (the common cold),for which a doctor is not usually consulted, and the acute respiratory infections - influenza,pneumonia, etc.In the United States, the National Health Survey estimated that there were about 215 millionrespiratory illnesses per year, but other studies suggest there may actually be four to fivetimes that, or more than one billion such illnesses per year. Studies of respiratory diseasesin Europe have estimated that in many European countries, about one third of all sicknessabsenteeism in the working population were due to respiratory diseases (1).\n\nThe incidence of colds always rises at the beginning of September, and increases with fluctuations until January and February, then declines to lower levels in the spring. This cyclical variation which occurs in conjunction with changes in weather has been studied by many investigators. Although respiratory diseases are frequently blamed on changes in the weather and cold weather, the indoor atmospheric condition likely plays a more important role in the incidence of colds than that of the weather, because in industrial nations, 95% of the time is spent indoors (7).\n\nThis paper has assembled the results of six investigations by independent researchers indifferent countries.', '0.000000', 395.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2707, 'PCR Technology', 'Stephen A. Bustin|Tania Nolan', '', '', '6/13/2013 12:00:00 AM', '', '0', 447, '2407160916098', '', '', 'These recommended practices apply to facilities that are equipped with regulated or non-regulated USTs and shop-fabricated ASTs, associated piping, diking and spill containment, and equipment intended to operate a system that contains petroleum products.\n\nThese recommended practices do not apply to:\n• pressure vessels;\n• field-erected tanks.\n\nThis document is not intended to endorse or recommend particular materials, equipment, suppliers or contractors.\n\nThe inclusion of procedures for the closure of USTs and shop-fabricated ASTs is not meant to imply that such procedures supersede any mandated regulatory requirements. This document also is not meant to provide interpretation of regulatory or legislative requirements related to closure of USTs and shop-fabricated ASTs.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2708, 'S51 -- Dedicated Outdoor Air Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 7, '2407160916099', '', '', 'This chapter lists important codes and standards from a broad spectrum of engineering societies, and provides contact information for the issuing organizations.', '0.000000', 110.61, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2709, 'BIOS Instant Notes in Plant Biology', 'Authors: Andrew Lack, David Evans', '', '', '1/1/2005 12:00:00 AM', '', '0', 366, '2407160859001', '', '', 'All current amendments available at time of purchase are included with the purchase of this document.', '0.000000', 33.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2710, 'BIOS Instant Notes in Molecular Biology [ Revised ]', 'Authors: Phil Turner, Alexander McLennan, Andy Bates, Michael White', '', '', '1/24/2007 12:00:00 AM', '', '0', 385, '2407160859002', '', '', 'All current amendments available at time of purchase are included with the purchase of this document.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2711, 'BIOS Instant Notes in Neuroscience', 'Author: Alan Longstaff', '', '', '3/16/2011 12:00:00 AM', '', '0', 390, '2407160859003', '', '', 'All current amendments available at time of purchase are included with the purchase of this document.', '0.000000', 48.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2712, 'NR NR/L3/SCO/313/SP-1.12 ISSUE 4', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 13, '2407160859004', '', '', 'PDF ONLY\n\nThis document applies to all staff that perform preventative or corrective maintenance to signalling assets on Network Rail managed infrastructure. The intervals relate to the maintenance tasks defined in the Signal Maintenance Specifications, or that need to be applied for Reliability-Centred Maintenance.\n\nPurpose\n\nThe purpose of this document is to set the safety and performance intervals applicable for carrying out signalling maintenance tasks and tests. The intervals shown are intended to maintain the designed safety and reliability, by detecting and correcting deficiencies to signalling equipment before there is deterioration or failure.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2713, 'NR NR/L3/SCO/313/SP-1.10/FA1 ISSUE 3', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 9, '2407160859005', '', '', 'PDF ONLY\n\nThis Network Rail standard specifies/provides guidance for:\n\na) Network Rail staff involved in the assessment and monitoring of OTM crew; and\n\nb) those involved in incident and accident investigation.\n\nPurpose\n\nTo provide a common approach to the extraction, validation, analysis and storage of data from data recorders where fitted to On-track Machines (OTM) worked by Network Rail OTM crew. The evidence shall be used to support driving and OTM performance monitoring, speed management and associated follow up actions, training and investigations.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2714, 'NR NR/L3/SCO/313/SP-1.10 ISSUE 4', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 19, '2407160859006', '', '', 'PDF ONLY\n\nThis procedure applies to all persons who require access to OTM cabs. This includes:\n\na) employees of Network Rail;\n\nb) employees of companies with which agreement has been reached for controlled access of their staff; and\n\nc) external organisations such as ORR, RAIB and their Accredited Agents.\n\nPurpose\n\nTo provide a system to control access to Directly Operated Fleet (DOF) driving, intermediate and rear On-track machine (OTM) cabs thereby reducing risk of distraction to OTM Drivers and others in the execution of their duties.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2715, 'NR NR/L3/SCO/313/SP-1.04 ISSUE 3', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 8, '2407160859007', '', '', 'PDF ONLY\n\nThis procedure applies to:\n\na) any new OTM driver;\n\nb) existing OTM drivers;\n\nc) people involved in the recruitment and training of OTM drivers; and\n\nd) doctors, psychometric assessors and training and examination centre’s who assess new train drivers.\n\nThis procedure does not apply to OTM drivers employed to work only:\n\na) in engineering possessions; or\n\nb) on depot operations only.\n\nPurpose\n\nTo provide On Track Machine (OTM) train driver licence and certificate arrangements for driving requirements outside possessions.\n\nTo provide a process for Network Rail to comply with the Train Driving Licenses and Certificates Regulations (TDLCR) 2010.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2716, 'NR NR/L3/OPS/045/4.10 ISSUE 5', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 9, '2407160859008', '', '', 'NR/L3/SCO/313/SP-1.10/FA1\n\nThis module specifies the process for carrying out Route Risk Assessments.\n\nIt is applicable to:\n\na) those involved in the creating route risk assessments and calculating the durations of Route Learning for OTM drivers\n\nb) those involved in assessing OTM drivers’ route knowledge.\n\nPurpose\n\nThis module defines the arrangements for the compilation of Route Risk Assessments (RRA).', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0);
INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(2717, 'NR NR/L3/OPS/045/3.18 ISSUE 3', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 10, '2407160859009', '', '', 'PDF ONLY\n\nThis Network Rail standard specifies the process for managing OTM driver route learning and the management of external route conductors. It includes the assessment of initial route learning and route knowledge retention for OTM drivers.\n\nIt is applicable to:\n\na) all Network Rail Directly Operated Fleet OTM drivers;\n\nb) those involved in training OTM drivers\n\nc) those involved in assessing OTM drivers’ route knowledge\n\nd) those involved in hiring in external route conductors\n\nPurpose\n\nThis procedure defines the arrangements for the training, assessing and retention of route knowledge for On-Track Machine (OTM) drivers.\n\nThe procedure also defines the arrangements for the managing the risks arising from the hiring in of External Route Conductors to undertake route conducting duties for Directly Operated Fleet (DOF).', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2718, 'NR NR/L2/SIG/11201/MOD B2 ISSUE 7 Signalling Design Handbook: Safety Hazards', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 13, '2407160859010', '', '', 'PDF ONLY\n\nThis module summarises the subject of bonding & earthing of signalling equipment; bonding & earthing is required primarily:\n\n• to protect staff against electric shock from dangerous touch potentials including those from functional signalling power supplies;\n\n• to reduce damage as well as shock, particularly in electric traction areas, by providing a fault current path and facilitating automatic disconnection;\n\n• to protect equipment from electrical transients and shield from interference [Electromagnet Interference, EMI];\n\n• to provide a functional reference to allow equipment to operate (generally a heritage necessity);\n\n• to provide a test earth (which being a separate earth will always be insulated and treated as a live conductor).\n\nOccasionally an earth connection may be required to comply with the enforceable standards of the electricity supply industry (for ‘PME’ installations).\n\nParticular clarity is given for all signalling equipment when earthing and bonding of the electrification system is designed to meet EN 50122-1 and which changes traditional British signalling practice. It also clarifies the requirements for the form of functional and fast transient earths. The adoption of these revised approaches will maintain safety and performance and reduce on-track time, construction effort and both initial and through-life costs.\n\nThis module applies to electrified and non-electrified railway:\n\n• Infrastructure Projects Advice Note PAN/E&P-E/EE/ESD/0102 ‘Earthing and Bonding for AC Electrification Schemes applying Common Bonding’ initially served to describe all bonding requirements; it gave particular details for signalling equipment.\n\nNOTE: This PAN has now lapsed with the publishing of Network Rail standard NR/L2/ELP/21085; the content of both documents are valid, but where difference exists, 21085 takes precedence. The PAN is a Reference Design under CSM-RA legislation in the meantime; this will include a module or reference of the requirements for bonding of small signalling ‘piece’ parts in the overhead contact line zone.\n\n• In dc traction areas bespoke engineering is required\n\nNOTE: EN 50122-1 applies and should form the basis of an engineered solution.\n\n• Where there is a requirement for a safety earth to protect from electric shock from signalling power distribution systems, Company Standard NR/L2/SIGELP/27418 Design, Installation and Testing of Earthing in Signalling Power Systems applies however it should be understood that the preference for signalling power distribution is to adopt Class II [NR/L2/SIGELP/27410 Specification for Class II based Signalling Power Systems] or hybrid protection so that new installations minimise the requirement for a safety earth ‘at the equipment housing’ to protect against electric shock from the signalling power system.\n\n• NR/L2/SIGELP/27418 also describes the construction design for a lineside earth and this SDH Module describes the practical minimum necessities of this ‘ground connection’ when used solely for transient and functional purposes.\n\nPurpose and Introduction\n\nThis module forms part of the Signalling Design handbook (SDH: NR/L2/SIG/11201) and is to be read in conjunction with the other modules of the handbook and reference documentation.\n\nThis Network Rail standard contains requirements and guidance on signalling engineering applications. The content supports the specific and general requirements described in Railway Group Standards and the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009].\n\nNOTE: Where there is a conflict between this standard and a Railway Group Standard or the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009] then this standard shall not take precedence\n\nDecisions made by a competent person should be supported by appropriate evidence or documentation.\n\nNOTE: Use of designer notes on drawings (otherwise known as Y-Notes; also see HSE CDM guidance) will generally suffice as may Design Log entries.\n\nAny adoption of alternative solutions requires an assessment commensurate with the significance of the proposed change and which follows the guidance provided by the Common Safety Method for Risk Evaluation and Assessment [CSM-RA]; Network Rail’s adopted method for the control of safety risks.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2719, 'NR NR/L2/SIG/11201/MOD B12 ISSUE 6 Signalling Design Handbook: Transmission Systems - (Cable Terminations & Cable Routes)', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 24, '2407160859011', '', '', 'PDF ONLY\n\nPURPOSE and INTRODUCTION\n\nThis module forms part of the Signalling Design handbook (SDH: NR/L2/SIG/11201) and is to be read in conjunction with the other modules of the handbook and reference documentation.\n\nIt contains requirements and guidance on signalling engineering applications. The content supports the specific and general requirements described in Railway Group Standards and the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009].\n\nNOTE Where there is a conflict between this standard and a Railway Group Standard or the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009] then this standard does not take precedence.\n\nDecisions made by a competent person should be supported by appropriate evidence or documentation.\n\nNOTE Use of designer notes on drawings (see HSE CDM guidance) will generally suffice as may Design Log entries.\n\nAny adoption of alternative solutions requires an assessment commensurate with the significance of the proposed change and which follows the guidance provided by the Common Safety Method for Risk Evaluation and Assessment [CSM-RA]; Network Rail’s adopted method for the control of safety risks.', '0.000000', 62.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2720, 'NR NR/L2/SIG/11201 ISSUE 19 Signalling Design Handbook', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 15, '2407160859012', '', '', 'PDF ONLY\n\n2.1 Inclusions\n\nThis module applies to the design of electrical circuits associated with:\n\na) electro-mechanical signalling systems;\n\nb) electro-pneumatic signalling systems;\n\nc) relay based signalling systems; and\n\nd) electronic signalling systems.\n\nIt applies to both internal and external circuits, commencing on the load side of the final busbar.\n\n2.2 Exclusions\n\nIt does not apply to wiring associated with the power supply side of the final busbar, which is covered in NR/L2/SIG/30050 , nor to circuits associated with signaller’s voice communication systems, which are covered in NR/L2/TEL/30002 , NR/L2/TEL/30031 , NR/L2/TEL/30032 & NR/L2/TEL/30143 .\n\nFor the presentation and use of circuit diagrams within the design process see NR/L2/SIG/11201 , Module A2-8 & A4-8 Relay and circuit nomenclature, as well as symbols, are defined in NR/L2/SIG/11201, Module A5-2\n\n2.3 Supporting Modules and other documentation\n\nThe following guidelines and specifications support the guidance within this module:\n\na) guidelines on fusing and looping in NR/L2/SIG/11201, Module B4;\n\nb) guidelines on the electromagnetic compatibility of electronic equipment in NR/L2/SIG/11201, Module B5;\n\nc) guidelines on protection of conductors for occupational safety, in NR/L2/SIG/11201, Module B6;\n\nd) guidelines on the application of different types of circuit in the relevant parts of this standard;\n\ne) the typical circuits listed in NR/GN/SIG/CAT005; and\n\nf) the relay specifications listed in NR/LS/CAT006 .\n\n2.4 Consistency\n\nThe content of this module describes best practice requirements and guidance for adoption in ‘greenfield’ applications. Where greenfield new works abuts existing installations it is important to consider whether the use of current best practice would either be confusing or incompatible with the existing practice at the adjacent place.\n\nIt should not be presumed that adoption of the latest approaches needs to supersede or influence existing application design; it has to be a judgment as to where boundaries between different practices should lie and how much overlap gives the better compromise.\n\nNOTE: As an often-encountered example in the design of line circuits, the British Railways, Western Region practice of fusing the negative polarity of DC power supplies contradicts the more usual practice of fusing the positive. Circuits with their origin in a Western Region locality should adopt the Western practice whereas those originating in an adjacent new works locality should follow that practice. This is practicable and sufficiently consistent because a relay load simply needs to be configured to accept the delivered incoming supply polarity and, when a neutral circuit, the polarity is actually of no consequence.\n\nPURPOSE & INTRODUCTION\n\nThis module forms part of the Signalling Design handbook (SDH: NR/L2/SIG/11201) and is to be read in conjunction with the other modules of the handbook and reference documentation.\n\nThis Network Rail standard contains requirements and guidance on signalling engineering applications. The content supports the specific and general requirements described in Railway Group Standards and the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009].\n\nNOTE 1: Where there is a conflict between this standard and a Railway Group Standard or the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009] then this standard shall not take precedence.\n\nDecisions made by a competent person should be supported by appropriate evidence or documentation.\n\nNOTE 2: Use of designer notes on drawings (see HSE CDM guidance) will generally suffice as may Design Log entries.\n\nAny adoption of alternative solutions requires an assessment commensurate with the significance of the proposed change and which follows the guidance provided by the Common Safety Method for Risk Evaluation and Assessment [CSM-RA]; Network Rail’s adopted method for the control of safety risks.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2721, 'NR NR/L2/SIG/10027 ISSUE 6  Surveillance of Signal Maintenance Activities', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 14, '2407160859013', '', '', 'PDF ONLY\n\nThis module details the action to be undertaken when undertaking detailed design at existing signalling installations. When alterations are undertaken on existing signalling installations, the infrastructure controller should consider whether certain retrospective safety work should be carried out: both on the parts of the installation being altered and on those parts directly associated with the installation being altered.\n\nPurpose and Introduction\n\nThis module forms part of the Signalling Design handbook (SDH: NR/L2/SIG/11201) and is to be read in conjunction with the other modules of the handbook and reference documentation\n\nIt contains requirements and guidance on signalling engineering applications. The content supports the specific and general requirements described in Railway Group Standards and the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009].\n\nNOTE 1: Where there is a conflict between this standard and a Railway Group Standard or the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009] then this standard does not take precedence\n\nDecisions made by a competent person should be supported by appropriate evidence or documentation.\n\nNOTE 2: Use of designer notes on drawings (see HSE CDM guidance) will generally suffice as may Design Log entries.\n\nAny adoption of alternative solutions requires an assessment commensurate with the significance of the proposed change and which follows the guidance provided by the Common Safety Method for Risk Evaluation and Assessment [CSM-RA]; Network Rail’s adopted method for the control of safety risks.', '0.000000', 62.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2722, 'NR NR/L2/RSE/100/03 ISSUE 4 Network Rail Assurance Panel Processes: The Application of the Railways (Interoperability) Regulations for Network Rail', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 24, '2407160859014', '', '', 'PDF ONLY\n\nThis module applies to the design of Transmission Systems (including Cables, Terminations and Cable Routes).\n\nTransmission systems (including cables) are provided as a means of interconnecting systems, sub-systems or items of equipment. Additionally, cables (commonly, but not universally single core) are provided as part of the internal circuitry of individual items of equipment.\n\nCables fall into four broad areas of application:\n\na) internal wires within an installation or sub-system (predominantly single core);\n\nNOTE Internal wiring of manufactured units is covered by the product approval process.\n\nb) main cables providing external transmission between installations or subsystems including power distribution, direct-wired, remote control and datalink systems;\n\nc) tail cables providing connection from lineside equipment housings to trackside or on-track equipment (sometimes via disconnection boxes), including track circuit connections and lineside operational telephone cables;\n\nd) bonding cables (usually single core) provided for track circuit, earth and equipotential bonding.\n\nTerminations are provided as a means of interfacing between differing types and/or sizes of cable and also in order to provide circuit disconnection and/or test facilities.\n\nCable routes are provided as a means of constraining cables and also protecting them from their environment.\n\nThe Design Principles in Section 2 give the minimum requirements, even when the risk-based approach is used. These principles are mandated in NR/L2/SIG/11201 .\n\nThe Network Rail standards on the following subjects should satisfy the principles encompassed within this module:\n\na) details of approved railway signalling cable;\n\nb) details of approved railway signalling cable with preformed ends and plug coupled ends;\n\nc) details of approved railway signalling cable for aerial use;\n\nd) details of cables for railway telecommunications;\n\ne) details of cable for data links;\n\nf) details of coaxial cables;\n\ng) guidelines on the construction of cable routes; and\n\nh) guidelines on the installation of cables in NR/L3/SIG/11303 (Appendices 2A10 & 2A15).\n\nPURPOSE\n\nThis module forms part of the Signalling Design handbook (SDH: NR/L2/SIG/11201) and is to be read in conjunction with the other modules of the handbook and reference documentation.\n\nIt contains requirements and guidance on signalling engineering applications. The content supports the specific and general requirements described in Railway Group Standards and the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009].\n\nNOTE Where there is a conflict between this standard and a Railway Group Standard or the Network Rail Signalling Principles Handbook [NR/L2/SIG/30009] then this standard does not take precedence\n\nDecisions made by a competent person should be supported by appropriate evidence or documentation.\n\nNOTE Use of designer notes on drawings (see HSE CDM guidance) will generally suffice as may Design Log entries.\n\nAny adoption of alternative solutions requires an assessment commensurate with the significance of the proposed change and which follows the guidance provided by the Common Safety Method for Risk Evaluation and Assessment [CSM-RA]; Network Rail’s adopted method for the control of safety risks.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2723, 'NR NR/L2/RSE/100/01 ISSUE 3 Network Rail Assurance Panel Processes: Network Rail Assurance Panel', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 15, '2407160859015', '', '', 'PDF ONLY\n\nThis standard lays down the requirements for:\n\na) the design of signalling works applicable to the infrastructure;\n\nb) the design of signalling systems;\n\nc) the design of software and data used in programmable signalling systems; and\n\nd) the tools, including software, used in design.\n\nIt applies from scheme conception through to acceptance into service or, where applicable, to decommissioning and disposal.\n\nPurpose\n\nThis standard sets out the requirements for the production of signalling design detail to support:\n\na) safe development and design of new and altered signalling systems impacting on Network Rail controlled infrastructure;\n\nb) safe interfaces between all parties and systems;\n\nc) design details that are prepared and presented clearly, accurately, consistently and unambiguously; and\n\nd) client’s specified requirements are met by a design that is fit for purpose.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2724, 'NR NR/L2/OHS/CP0036 ISSUE 5 The Provision of Welfare Facilities for Temporary and Transient Work Activities (formerly NR/L3/INI/CP0036)', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 19, '2407160859016', '', '', 'PDF ONLY\n\nThis document applies to all staff performing Signal Engineering activities holding the occupational competencies shown in Appendix A, at Level 3 or above which include:\n\na) Corrective and preventative maintenance;\n\nb) Equipment replacement/minor works;\n\nc) Signal Maintenance Testing;\n\nd) Signal Intermediate Testing.\n\nPurpose\n\nThe purpose of this document is to:\n\na) confirm that work on signalling assets is being completed correctly;\n\nb) provide additional assurance of staff competency when working on signalling assets; and\n\nc) assist in gathering evidence to support IRSE licensing processes.', '0.000000', 62.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2725, 'NR NR/L2/CIV/1000/08 ISSUE 2 Competence Management for Asset Protection and Optimisation (ASPRO)', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 20, '2407160859017', '', '', 'PDF ONLY', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2726, 'NR NR/L2/CIV/086/MOD09 ISSUE 2 Management of Earthworks Manual: Earthworks Adverse/Extreme Weather Risk Assessment', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 17, '2407160859018', '', '', 'PDF ONLY', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2727, 'NR NR/L2/CIV/086/MOD06 ISSUE 2 Management of Earthworks Manual: Earthwork Monitoring Strategy Selection and Implementation', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 16, '2407160859019', '', '', 'PDF ONLY\n\nThis standard specifies the minimum standards for the planning and provision of welfare facilities on all temporary sites of work where welfare is the responsibility of Network Rail, Principal Contractors or any contractors or suppliers employed by them.\n\nNOTE: Specific legislation might demand a higher standard of welfare facilities, e.g. working with asbestos or lead.\n\nPurpose\n\nThe purpose of this standard is to provide the approach to the planning of suitable and sufficient sanitary and messing facilities for staff who are working away from permanent amenities (e.g. infrastructure maintenance depot). Compliance to this standard will provide:\n\na) access to clean, properly maintained toilet, washing and messing facilities for all staff who are required to work away from permanent facilities;\n\nb) improved welfare and wellbeing of all staff through better planning and provision of welfare facilities, promoting inclusivity for a diverse workforce;\n\nc) compliance to legislative requirements, such as The Workplace (Health, Safety and Welfare) regs 1992, The Equality Act 2010 and application of good practice such as that provided through the Health & Safety Executive Approved Code of Practice and Guidance.\n\nThis standard interprets the Construction (Design and Management) Regulations 2015 and other applicable Health and Safety legislation.', '0.000000', 62.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2728, 'NR NR/L2/CIV/086/MOD03 ISSUE 2  Management of Earthworks Manual: Geohazard Assessment', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 71, '2407160859020', '', '', 'PDF ONLY\n\nThis document covers the procedures for:\n\na) selecting earthworks (or Operational Route Sections) for inclusion in an A/EWP\n\nb) identifying the actions to be taken during A/EW events to maintain levels of safety and performance\n\nc) developing, reviewing and updating an A/EWP.\n\nd) geotechnical considerations when risk ranking Operational Route Sections (ORS)\n\nThese procedures apply to all earthworks within the Network Rail boundary, and slopes outside of the boundary which may affect the Network Rail infrastructure.\n\nThe Convective Analysis Tool (CAT) identifies developing storms which can lead to very intense rainfall totals at short notice. Business processes associated with mitigations in response to CAT are not covered within this document, with the exception of ORS risk ranking guidance (which is described in Appendix C).\n\nNOTE: For more information about business processes in response to intense rainfall or emergency events consult NR/L2/OPS/021 and NR/L3/OPS/021/08\n\nThe threat of A/EW to earthworks relates to intense or prolonged rainfall or flooding. It does not include strong winds or periods of drought. Risks associated with clay shrinkage impacting track quality should be managed within the appropriate seasonal preparedness window in advance of Summer.\n\nPurpose\n\nThe purpose of this module is to identify assets or Operational Route Sections (ORS) that are to be included in an Adverse/Extreme Weather Plan (A/EWP). The A/EWP is a controlled list of asset locations that are included within the Integrated Weather Management Plan (IWMP), which every Route is required to have under the operational control framework.\n\nEarthworks identified from risk assessment as Risk level 4 (as described in AppendixA.5) will be reviewed for potential inclusion, to which additional sites may be added to from local knowledge and through core business processes (e.g. earthwork evaluation).\n\nThis procedure manages the control, ‘weather – managing operational risk’ mitigating the following risks:\n\na) loss of track support; or\n\nb) loss of gauge capability.', '0.000000', 62.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2729, 'NR NR/L2/CIV/086/MOD02 ISSUE 2  Management of Earthworks Manual: Earthwork Assessments', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 553, '2407160859021', '', '', 'PDF ONLY\n\nThis procedure applies to earthworks monitoring to better understand potential failure mechanisms or to manage the risk of earthworks failure until an intervention will be carried out.\n\nThe scope covers earthworks monitoring:\n\na) system selection, and the strategy for the mitigation of earthworks where the condition potentially affects the safe operation of the railway;\n\nb) strategy for implementation as part of the earthworks risk control;\n\nc) on new earthworks and earthworks remediation projects.\n\nThis document does not apply to the monitoring of track over or adjacent to construction works, this is covered in NR/L2/CIV/177.\n\nPurpose\n\nThis document defines the methodology for selecting and implementing a monitoring strategy for mitigating earthworks at risk of failure, or earthwork assets that have failed and are awaiting completion of a permanent solution.\n\nEarthwork monitoring helps to control risks associated with the following loss events:\n\na) slope failure leading to loss of gauge capability\n\nb) slope failure leading to loss of track support and/or geometry; and\n\nc) slope failure leading to loss of safe environment without loss of gauge capability or track support/geometry.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2730, 'NR NR/L2/CIV/086/MOD01 ISSUE 3  Management of Earthworks Manual: Earthwork Evaluations', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 61, '2407160859022', '', '', 'PDF ONLY\n\nThis procedure covers:\n\na) Remitting of the intervention works;\n\nb) Deferred interventions;\n\nc) Emergency works.\n\nIt applies to:\n\na) All earthworks within the Network Rail boundary as defined in NR/L2/CIV/086;\n\nb) Slopes outside the boundary that might affect the Network Rail infrastructure.\n\nPurpose\n\nThis procedure defines how to decide when, and at what level, earthworks interventions will be carried out.\n\nInterventions are chosen to manage risks once cyclical examination is no longer considered to be acceptable for controlling asset risk.\n\nInterventions include the following types:\n\na) Maintenance;\n\nb) Refurbishment;\n\nc) Renewal.\n\nThis document manages the control, ‘earthwork interventions’, mitigating the following risks:\n\na) Loss of track support or track geometry;\n\nb) Slope failure leading to loss of loss of gauge capability or track support/geometry.', '0.000000', 62.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2731, 'NR NR/L2/CIV/086 ISSUE 12 Management of Earthworks', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 31, '2407160859023', '', '', 'PDF ONLY\n\nThis module details the process to prepare for and carry out a geohazard assessment and report the results into Network Rail’s earthworks database.\n\nA geohazard assessment is carried out:\n\n• when the evaluation of an earthworks examination identifies there is a risk of failure from earthworks and outside party natural slopes which warrants further investigation and analysis; or\n\n• where the railway has been identified to be at risk from a natural slope.\n\nThis document applies to outside party natural slopes adjacent to the Network Rail boundary, where failure could pose a risk to the safe operation or performance of the railway infrastructure. This includes:\n\na) outside party natural slopes (such as mountainsides);\n\nb) coastal cliffs.\n\nThis business process does not apply to:\n\na) mapping of vegetation other than factors affecting slope stability;\n\nNOTE: See NR/L2/OTK/5201 or NR/L2/TRK/5201 for mapping of vegetation\n\nb) earthworks and natural slope drainage other than factors affecting slope stability of outside party earthworks;\n\nNOTE: See NR/L2/CIV/005.\n\nc) the assessment of ground movements resulting from, for example, natural cavities formed by dissolution of susceptible geologies, mineral extraction including tipping and stockpiling, landfill operations or subterranean fire.\n\nNOTE: See NR/L3/CIV/191.\n\nPurpose\n\nThis module details the geohazard assessment process which is part of Network Rail’s earthworks management process.\n\nA geohazard assessment relates to:\n\na) Identification of hazards from natural slopes;\n\nb) Assessment of the consequence of a natural slope failure.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2732, 'NR NR/GN/CIV/200/07 ISSUE 2 Station Design Manual: Footbridges & Subways', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 310, '2407160859024', '', '', 'PDF ONLY\n\nThe procedure set out in this document applies to all Network Rail owned or managed earthworks. This includes natural slopes inventoried and inspected as if they are earthworks. For geohazard assessment of Outside Party slopes, see NR/L2/CIV/086/mod03.\n\nThe procedure offers a tiered framework for earthwork assessment. The framework comprises four levels (0 to 3) of assessment of increasing sophistication, and therefore cost, but consequently reducing application. Level 0 assessment is applied to all earthworks. Level 1 to 3 assessment is applied at the discretion of an evaluator. The scope of an individual level 1 to 3 assessment is as determined during earthwork evaluation (and for assessment levels 2 and 3 recorded in the assessment remit).\n\nThis document does not cover:\n\na) Operational or occupational health and safety requirements related to carrying out earthwork assessments, see NR/L2/OHS/019 or NR/L3/OHS/005 as applicable;\n\nb) Guidance for how to undertake ground investigation in support of earthwork assessment, see NR/L2/CIV/071 Design of Geotechnical Structures; and\n\nc) Guidance for how to undertake extended monitoring beyond ground investigation in support of earthwork assessment, see NR/L2/CIV/086/mod06.\n\nPurpose\n\nThis document defines the procedure for carrying out earthwork assessment. Earthwork assessment is the qualitative or quantitative determination of the stability or the safe load-carrying capacity of an earthwork.\n\nEarthwork assessment helps control risks associated with the following loss events:\n\na) Earthwork or slope failure leading to loss of gauge capability;\n\nb) Earthwork or slope failure leading to loss of track support and/or geometry; and\n\nc) Earthwork or slope failure leading to loss of safe environment without loss of gauge capability or track support/geometry.\n\nEarthwork assessment works in harmony with earthwork evaluation (see NR/L2/CIV/086/mod01). The outcome of an assessment provides an essential input to an earthwork evaluation whilst the requirement for further assessment is determined during earthwork evaluation.', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2733, 'NR NR/GN/CIV/200 ISSUE 9 Station Design Manual', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 10, '2407160859025', '', '', 'PDF ONLY\n\nThe procedure set out in this document applies to all Network Rail owned or managed earthworks. This includes natural slopes inventoried and inspected as if they are earthworks. The procedure also applies to the evaluation of geotechnical risks to the railway arising from Outside Party owned or managed slopes. Outside Party slopes comprise earthworks and natural slopes.\n\nThe procedure offers a universal approach to evaluation that is applicable to all earthworks and slopes.\n\nThis document does not cover:\n\na) Operational or occupational health and safety requirements related to carrying out geotechnical evaluations (see NR/L2/OHS/019 or NR/L3/OHS/005 as applicable); and\n\nb) Guidance for how to undertake actions arising from geotechnical evaluations (see references throughout document).\n\nPurpose\n\nThis document defines the procedure for carrying out geotechnical evaluation. Geotechnical evaluation is the appraisal of all information about the stability, condition, use and location of an earthwork or slope, to determine the actions required to maintain acceptable levels of safety and performance.\n\nGeotechnical evaluation helps control risks associated with the following loss events:\n\na) Earthwork or slope failure leading to loss of gauge capability;\n\nb) Earthwork or slope failure leading to loss of track support and/or geometry; and\n\nc) Earthwork or slope failure leading to loss of safe environment without loss of gauge capability or track support/geometry.', '0.000000', 62.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2734, 'NR NR/GN/CIV/100/02 ISSUE 2 Strategic Design Manual: Station Design Guidance', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 129, '2407160859026', '', '', 'PDF ONLY\n\nThis business process applies to all earthworks within the boundary of the Network Rail infrastructure (including approach embankments, approach cuttings, tunnel cuttings, slopes above tunnel portals, nailed or reinforced soil structures and any embankment, irrespective of its height, that also acts as a coastal, estuarine or river defence).\n\nIt also covers outside party slopes which might impact the infrastructure, and can be examined using the Soil Cutting Hazard Index (SCHI), Soil Embankment Hazard Index (SEHI) and the Rock Slope Hazard Index (RSHI).\n\nNOTE 1: Approach embankments applies to overline bridges that are equal to or greater than 3 metres high, except those owned by a highway authority, roads authority or other competent authority.\n\nNOTE 2: Reinforced soil structures applies to those whose face angle is less than or equal to 70 degrees to the horizontal.\n\nThis business process does not apply to:\n\na) examinations specifically carried out to assess ground movements resulting from mineral extraction, (refer to NR/L2/CIV/191);\n\nb) the examination of vegetation (refer to NR/L2/OTK/5201);\n\nc) the examination of drainage condition and structure (refer to NR/L3/CIV/005);\n\nd) the examination of nailed or reinforced soil structures steeper than 70 degrees, retaining walls and gabion walls (refer to NR/L3/CIV/006);\n\ne) the examination of coastal, estuarine or river defence works that are not also embankments (refer to NR/L3/CIV/006);\n\nPurpose\n\nThis document defines procedures and processes documented within the geotechnical control framework to manage earthwork assets. Earthwork management helps to control risks associated with the following loss events:\n\na) Slope failure leading to loss of gauge capability;\n\nb) Slope failure leading to loss of track support and/or geometry; and\n\nc) Slope failure leading to loss of safe environment without loss of gauge capability or track support/geometry', '0.000000', 81.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2735, 'NR NR/GN/CIV/100 ISSUE 7 Strategic Design Manual', 'Network Rail', '', '', '6/1/2024 12:00:00 AM', '', '0', 10, '2407160859027', '', '', 'PDF ONLY\n\nThis document covers primarily footbridges and subways for station environments but includes also a section on standard designs of footbridges for non-station environments. It is intended for projects at the initial stages of the design or of the project-requirements definition.\n\nPurpose\n\nNearly all railway stations have to provide access for passengers across the railway line, in most cases via footbridges or subways. This guidance document sets out the principles and considerations for all new footbridges and subways and helps you in the selection of the best solution for your project.\n\nNetwork Rail commissioned standard footbridge designs, and these should be the first options when considering a new footbridge. This guidance sets out the principles for these designs, and identifies the overall criteria when a bespoke approach may be more appropriate.\n\nThis document also explains the challenges faced when working with existing live infrastructure, or upgrading an existing structure. Many existing subways are poorly illuminated and inadequate, with issues such as water ingress. This document advises on how these can be invigorated and made more user friendly.\n\nGuidance is also provided on how to create a new subway, and why subways can often provide greater benefits than footbridges.\n\nThe guidance refers to a range of Network Rail and external standards that can help the user with their project. A summary of Footbridge Requirements is provided in Appendix B, and it also contains assessment criteria for establishing whether footbridges require dispensation from Roof Cover and whether Lift provision can be dispensed with, in certain locations. Appendix D and E provide a breakdown of Carbon calculations and Capital cost for the standard footbridge designs.', '0.000000', 25.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2736, 'NR NB 215 ISSUE 2 Frauscher Wheel Sensor RSR123', 'Network Rail', '', '', '4/16/2024 12:00:00 AM', '', '0', 8, '2407160859028', '', '', 'PDF ONLY\n\nThe 200 series of design manuals covers station environments and other public areas associated with the transit of passengers. The documents are aimed at sponsors, public authorities, third party developers, designers, engineers, project managers, and anyone involved in the design and delivery of stations.\n\nThis standard and the associated modules should be applied to all UK Managed Stations and Non-Managed UK categories of stations and related buildings.\n\nPurpose\n\nThis manual provides advisory guidance which supports Network Rail’s broad objectives, goals, strategies and policy requirements for station design and planning. It references UK legislation and British Standards, and provides a framework for design processes, assurance systems and specified controls that will encourage good design, legal assurance and control at all levels of station and infrastructure development.', '0.000000', 118.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2737, 'NR NB 134 ISSUE 6 Transpositions on DC Track Circuits', 'Network Rail', '', '', '3/26/2024 12:00:00 AM', '', '0', 3, '2407160859029', '', '', 'PDF ONLY\n\nThis guidance in this document is focused on the passenger journey and experience when using stations. The document aims to provide a holistic overview of the different elements that contribute to successful, sustainable well designed stations.\n\nMany of the topics discussed in this manual are covered comprehensively in dedicated documents within the NR Design Manual suite. This document provides references throughout to the design manual suite, and explains where these documents can further assist.\n\nThis document is designed to compliment the Design Manual for Medium to Small Stations, and reference is made to this document and the key HUB station themes.\n\nAppendix A provides reference to the full suite of Design Manuals.\n\nPurpose of this Document\n\nThis document offers high level guidance aimed at the Sponsors, designers, and planners of new railway station infrastructure in the UK. It outlines not just the factors determining physical space within stations but other components that need to be considered to achieve world class station design.\n\nThe document therefore references other guidance, standards and applicable legislation and acts as a signpost to other parts of the Network Rail guidance suite. References are provided throughout to the guidance suite, and suggests where these documents can further assist.\n\nRailway projects are subject to the procedures of the PACE (Project Acceleration in a Controlled Environment) process, and this guidance helps users to navigate this process.\n\nKey design considerations are set out and aligned to the PACE stages in Section 6 of this document as a design considerations toolkit: a practical checklist of action for anyone embarking on new station works in the UK.\n\nWho is the document aimed at?\n\nThis document is primarily aimed at supporting project teams and design teams defining, preparing and delivering station projects. It also defines the key components of a station and station journey, to help Sponsors develop quality criteria for the project, and help design teams develop their proposals to address the key requirements and objectives of a station and its contextual design, as well as Network Rail’s principles of good design. Refer to image 1.2 which shows which sections are most applicable to each user group.\n\nThe following gives an overview of the key document users:\n\nDesign/Project teams:\n\n→ Project sponsors\n\n→ Project managers\n\n→ Architects, Urban Designers and Engineers\n\n→ Viability and market consultants\n\n→ Cost consultants and Economists\n\n→ Sustainability consultants\n\n→ Planners\n\nProject stakeholders:\n\n→ Public Authorities and Public Bodies (governmental organisations that carry out tasks in the public interest such as Network Rail, the Greater London Authority, the Department for Transport)\n\n→ Local Authorities (County Councils, District Council, Metropolitan Districts, London Boroughs)\n\n→ Transport Authorities\n\n→ Station Operators\n\n→ Asset Managers\n\n→ Train Operating Companies', '0.000000', 44.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2738, 'NPES B65-3 Graphic technology – Safety requirements for graphic technology equipment and systems – Part 3: Binding and finishing equipment and systems', 'Association for Suppliers of Printing, Publishing and Converting Technologies', '', '', '1/1/2001 12:00:00 AM', '', '0', 0, '2407160859030', '', '', 'PDF ONLY\n\nThe 100 series of design manuals covers station environments and other public buildings associated with the transit of passengers. They are aimed at sponsors, public authorities, third party developers, designers, engineers, project managers, and anyone involved in the design and delivery of stations.\n\nThis standard and the associated modules should be applied to all National Managed Stations, and it is advised is also applied to all UK categories of stations.\n\nPurpose\n\nThis standard provides advisory guidance which supports Network Rail’s broad objectives, goals, strategies and policy requirements for station design and planning. It references UK legislation and British Standards and provides a framework for design processes, assurance systems and specified controls that will encourage good design, assurance and control at all levels of station and infrastructure.', '0.000000', 19.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2739, 'NPES ANSI B65.3 SAFETY STANDARD FOR GUILLOTINE PAPER CUTTERS, MILL TRIMMERS AND INTEGRAL HANDLING EQUIPMENT', 'Association for Suppliers of Printing, Publishing and Converting Technologies', '', '', '1/1/2001 12:00:00 AM', '', '0', 0, '2407160859031', '', '', 'PDF ONLY\n\nThe Scope of this Notice Board is all Frauscher RSR123 wheel sensors installed on Network Rail infrastructure. This includes installations used with the FAdC axle counter, level crossing systems, track worker safety systems and any other RSR123 installations.\n\nPurpose\n\nThe purpose of this Notice Board is to provide installation and maintenance guidance for the Frauscher RSR123 wheel sensors.\n\nIssue 2 of this Notice Board provides additional guidance on the installation of the RSR123 wheel sensors and advance notice of forthcoming changes to Periodic Task 2 within NR/SMS/PartC/AX41.', '0.000000', 19.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2740, 'NOVEL OPTICAL MATERIALS, Ophthalmic optics - Contact lenses and contact lens care products - Determination of biocompatibility by ocular study with rabbit eyes', 'Cesare Umeton|Francesco Simoni|Iam Choon Khoo', '', '', '11/24/2023 12:00:00 AM', '', '0', 322, '2407160859032', '', '', 'PDF ONLY\n\nApplies to all single rail DC track circuits on non electrified lines [on electrified lines it is likely that the need for continuous traction return would not cause the circumstances of this Notice Board to have occurred].\n\nPurpose\n\nTo remind staff that the use of transpositions in single rail DC track circuits can import risk into the signalling system.', '0.000000', 48.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2741, '.NET Programming with Visual C++: Tutorial, Reference, and Immediate Solutions', 'Max Fomitchev', '', '', '7/27/2017 12:00:00 AM', '', '0', 737, '2407160859033', '', '', 'Silvered flat glass mirror products can be fabricated to provide additional aesthetic appeal such as beveled edges and surface accents. As additional fabrication features are applied, is it critical to ensure proper fabrication conditions and techniques are utilized during every step of fabrication in order to protect and maintain the integrity of the mirror backing and edges and to reduce the chances of black edge developing. The Technical Services Division of the National Glass Association (NGA) has produced this Glass Technical Paper solely for informational purposes. This Paper was developed by dedicated member volunteers and subject matter experts. The original version of this document was published in 2009. This version of the document was updated and published in April 2024.', '0.000000', 35.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2742, 'NEBB PSFHPT', 'NEBB', '', '', '12/1/2016 12:00:00 AM', '', '0', 0, '2407160859034', '', '', 'ClimateTalk is an open standard that defines a set of messages and commands to enable interoperability, enhanced user interface, and machine-to-machine control independent of the physical layer connecting the devices.\n\nThe messages and commands defined by the ClimateTalk Information Model (CIM) are the presentation and application layers as defined by the OSI Model . ClimateTalk applications are fully defined at Layer 7 of the OSI model by a combination of a device-specific application profile, the Generic Application Specification, and the command reference.\n\nClimateTalk messages can be carried over any physical medium following the OSI model. The ClimateTalk presentation layer defines how messages are executed over the various physical mediums in use.\n\nCT-485 and CT-LWP are wired serial physical and network layers designed to support the formation of ClimateTalk networks and transport ClimateTalk messages, but other OSI based protocols, including wireless transports, can be used, as well.\n\nThis document provides a single repository for all control commands and messages in the ClimateTalk Common Information Model. ClimateTalk applications are fully defined at Layer 7 of the OSI model by a combination of a device-specific application profile, the Generic Application Specification, and this document.\n\nThe ClimateTalk Open Standards package shown in Figure 1 prescribes the mandatory requirements to ensure proper network formation of interoperable devices. Membership in the ClimateTalk Alliance, as well as successful completion of mandatory conformance testing, is required for listing a product as a ClimateTalk certified device.', '0.000000', 49.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2743, 'NEBB PROCEDURAL STANDARDS [ Revised ]', 'NEBB', '', '', '1/1/1983 12:00:00 AM', '', '0', 0, '2407160859035', '', '', 'The requirements of this Annex applies to the enclosure that are additionally considered to be concrete tight.', '0.000000', 75.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2744, 'NEBB PROCEDURAL STANDARDS', 'NEBB', '', '', '1/1/2019 12:00:00 AM', '', '0', 0, '2407160859036', '', '', 'Covers wiring devices and accessories intended to help protect sensitive equipment from malfunction due to noise on the equipment grounding path and covers safety installation requirements for compliance with the National Electrical Code ® (NEC), applications for isolated ground circuits, and troubleshooting and maintenance of such installations.', '0.000000', 213.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
