INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(2751, 'NAVISTAR MPAPS G-5', 'Navistar International Corporation', '', '', '4/1/2024 12:00:00 AM', '', '0', 25, '2407160859043', '', '', '', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2752, 'NAVISTAR MPAPS G-4516', 'Navistar International Corporation', '', '', '4/1/2024 12:00:00 AM', '', '0', 5, '2407160859044', '', '', '', '0.000000', 30.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2753, 'NAVISTAR MPAPS F-7006', 'Navistar International Corporation', '', '', '3/1/2024 12:00:00 AM', '', '0', 6, '2407160859045', '', '', 'This specification covers the general requirements, property and performance requirements, quality, qualification, source approval, and quality control for exhaust pipe insulation.\n\nRestricted Chemical Substances\n\nAll product supplied to the requirements of this specification must comply with the requirements of the MPAPS B-50 specification.\n\nClassification\n\nNOTE: There are currently only four types of approved piping insulation. Additional types of piping insulation are expected to be identified and added to this specification in the future.\n\nType I: Blanket Type - Ceramic blanket insulation wrapped with aluminum foil tape and secured at each end with stainless steel clamps.\n\nType II: Insulation Wrap – Ceramic blanket insulation with fiberglass fabric inner layer and laminated aluminum foil/fiberglass outer layer secured around pipe.\n\nType III: Steel Encapsulated Fiber Mat – Stainless steel outer shell with an inner layer of wrapped silicate fiber needle mat.\n\nType IV: Knitted Basalt Sleeve – Dense wall knitted basalt fiber sleeve secured at each end with stainless steel clamps.', '0.000000', 30.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2754, 'NAVISTAR MPAPS F-1 Fluid Connections (Liquid/Gas/Hose/Tube)', 'Navistar International Corporation', '', '', '4/1/2024 12:00:00 AM', '', '0', 20, '2407160859046', '', '', 'The requirements described in this section are used in conjunction with the Property Requirements indicated for each specific grade in the tables at the end of the specification. MPAPS G-5 is divided into multiple sections as follows:\n\nPaint Finish Requirements - Outlines classes of finish for Navistar. It defines requirements and describes physical properties, which govern durability, corrosion protection, and overall appearance quality. It also outlines the procedure for specifying paint materials. All test designations refer to the latest issue unless otherwise stated. Unless otherwise specified, all test methods refer to Navistar MPAPS GT – Paint methods.\n\nTopcoats - This part of the specification covers the requirements for topcoats used by the Company as finish coatings on its products, as well as topcoats that are packaged and sold by the company for service. The General Requirements described in this section are used in conjunction with the Property Requirements indicated for each specific grade of topcoat to describe the complete requirements for each grade. Film requirements for interior paints are detailed in MPAPS G-9008 or MPAPS G-9009 Class IIIA.\n\nGrade – 17HS Hi Solids Urethane\n\nGrade – 18 1K Base Coat / 2K Urethane Clear Coat\n\nGrade – 19HS Hi Solids TSA\n\nGrade – 22 2K Urethane Base Coat / 2K Urethane Clear Coat\n\nChassis and Miscellaneous Paints - This part of the specification covers the requirements for engine, chassis, and miscellaneous paints. Heat resistant grades used as a finish coating on exhaust system components are covered by MPAPS G-9015. Components purchased already painted are covered by MPAPS G-9008 or MPAPS G-9009.\n\nGrade -32 HS/Ur Urethane Chassis Paint\n\nGrade -32 W Waterborne Chassis Paint (bus)\n\nCasting Sealers - This covers the requirements for paints/sealers used to seal steel, malleable, nodular, and gray iron castings. This specification no longer covers materials for this purpose. Please see MPAPS G-9009 for requirements.\n\nPrimers - This part of the specification covers the requirements for primers used with various topcoats. Primed parts that are received as a finished part are covered by MPAPS G-9009.\n\nGrade -52 Adhesion Promoter / Primer\n\nGrade -54 Repair Primer\n\nGrade -56 E-Coat Primer\n\nPaints for Repair and Service - This part of the specification covers the requirements for materials used in repair or refinishing. These materials are also for sale under the Navistar trademark. All paints formulated to this part of the specification must be manufactured with compounds that are lead and chrome free.\n\nGrade -61 Repair Paint, Pressurized Containers\n\nGrade -62 Air Dry Paint for Refinishing, Repair\n\nEngine Paints - This part of the specification covers the General Requirements for paints used by the Company as a finish coating on engines and engine products.\n\nGrade –81W Waterborne Engine Paint\n\nPre-Treatment Systems – This covers the requirements for chemicals used to pre-treat metals and other materials prior to priming or painting for production, service or repair.\n\nGrade -100 Zinc Phosphate System\n\nGrade -200 Two component non-sanding pretreatment on bare metal\n\nGrade-300 Thin Film Pretreatment System\n\nRestricted Chemical Substances\n\nAll product supplied to the requirements of this specification must comply with the requirements of the MPAPS B-50 specification. All paints formulated to this specification must be manufactured with compounds that are lead and chrome free.', '0.000000', 30.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2755, 'NAVISTAR MPAPS D-7028 Bonded Trim Composites, Interior', 'Navistar International Corporation', '', '', '2/1/2024 12:00:00 AM', '', '0', 6, '2407160859047', '', '', 'This specification covers the general requirements, property and performance requirements, qualification, and source approval and quality control requirements for five types of corrosion preventive compounds.\n\nRestricted Chemical Substances\n\nAll product supplied to the requirements of this specification must comply with the requirements of the MPAPS B-50 specification.\n\nAPPLICATION\n\nThis specification covers corrosion preventive materials used to protect newly machined surfaces and/or unpainted parts from corrosion during outside storage and/or ocean transit. Some of these materials or Types are also used for underbody coating and to inhibit galvanic corrosion between dissimilar metals. These materials consist of coated and uncoated adhesive dielectric tapes and primer-type paints or thin, waxy, self-healing films. Types I – V are suitable for application by spraying, dipping, or brushing at temperatures of 10-35°C (50-95° F). Type VI application is from a roll of tape-like material or pre-cut shapes.', '0.000000', 30.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2756, 'NAVISTAR MPAPS B-21 Diesel Engine/Crankcase Oils', 'Navistar International Corporation', '', '', '4/1/2024 12:00:00 AM', '', '0', 8, '2407160859048', '', '', 'This specification covers the general requirements, property and performance requirements, quality control and KPC requirements for two types of non-metallic tubing.\n\nType A: This is non-reinforced tubing for use in secondary air system applications outside of the primary braking system.\n\nType B: This is reinforced tubing that may be used in the primary braking system as well as other air system applications and in the fuel system.\n\nNOTE 1: These tubing types should not be used for compressor discharge lines or pressures exceed 1034 KPa (150 psi).\n\nNOTE 2: Some existing engineering drawings may refer to TMS-7006, Type C – in these applications, tube provided will meet the requirements of TMS-7134 / MPAPS F-7134, Type A.\n\nNOTE 3: Some existing engineering drawings may refer to TMS-7006, Type D – in these applications, tube provided will meet the requirements of TMS-7134 / MPAPS F-7134, Type B.\n\nRestricted Chemical Substances\n\nAll product supplied to the requirements of this specification must comply with the requirements of the MPAPS B-50 specification.\n\nAPPLICATION\n\nThis specification outlines the minimum requirements for non-metallic tubing that may be used in certain portions of the air brake systems (see Restrictions in SAE J844 and J1394), in the secondary air system (such as air horns, air shift lines, air wipers, and air seats). This tubing is restricted to a maximum working pressure of 1034 kPa (150 psi). Contact Materials Engineering for guidance on temperature limitations.', '0.000000', 30.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2757, 'NATO STANAG 4609 NATO DIGITAL MOTION IMAGERY STANDARD', 'NATO Publication', '', '', '7/30/2020 12:00:00 AM', '', '0', 5, '2407160859049', '', '', 'This document covers general specifications and dimensions for fluid tubes, hoses, and clamps. It includes all the requirements needed for a reliable and sealed connection.\n\nRestricted Chemical Substances\n\nAll product supplied to the requirements of this specification must comply with the requirements of the MPAPS B-50 specification.\n\nAPPLICATION\n\nThis specification covers coolant, oil, and air hose/tube joints with clamps.', '0.000000', 30.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2758, 'NATO STANAG 2525 ALLIED JOINT DOCTRINE FOR OPERATIONAL-LEVEL PLANNING - AJP-5', 'NATO Publication', '', '', '4/5/2024 12:00:00 AM', '', '0', 4, '2407160859050', '', '', 'This specification covers the general requirements for the individual components of the composite (i.e. fabric, padding, and backing) and property and performance requirements of the bonded or molded, finished composite. Requirements for quality, qualification, shipping and identification, and source approval and quality control are included.\n\nRestricted Chemical Substances\n\nAll product supplied to the requirements of this specification must comply with the requirements of the MPAPS B-50 specification.\n\nAPPLICATION\n\nThis specification covers interior trim composites, typically consisting of a facing fabric or material, padding, and a backing. These components are chemically, thermally, and/or dielectrically bonded or laminated parts suitable for interior uses such as wall panels, head liners, sun visors, cabinets, seat inserts, floor mats, and door trim panels.', '0.000000', 30.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2759, 'NATO AOP-68 PROFILS DE FUSÉES DOGIVE ET LOGEMENTS DE FUSÉES COMPATIBLES POUR PROJECTILES DARTILLERIE ET DE MORTIER', 'NATO Publication', '', '', '8/14/2019 12:00:00 AM', '', '0', 46, '2407160859051', '', '', 'This specification covers the engineering requirements for oils used in the diesel engines of Navistar products.\n\nAPPLICATION\n\nFour grades of engine oil are covered by this specification. These grades may also be merchandized under the Fleetrite brand name.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2760, 'NATO AMEDP-8.16 SYSTÈME DE REGISTRE DES TRAUMATISMES DE L’OTAN', 'NATO Publication', '', '', '8/21/2019 12:00:00 AM', '', '0', 24, '2407160859052', '', '', 'ENGLISH/FRENCH * FREE * ELECTRONIC ONLY\n\nAIM\n\nThe aim of this NATO standardization agreement (STANAG) is to respond to the following interoperability requirements.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2761, 'NATO AJP-6 ALLIED JOINT DOCTRINE FOR COMMUNICATION AND INFORMATION SYSTEMS', 'NATO Publication', '', '', '4/5/2024 12:00:00 AM', '', '0', 90, '2407160859053', '', '', 'ENGLISH/FRENCH * FREE * ELECTRONIC ONLY\n\nAIM\n\nThe aim of this NATO standardization agreement (STANAG) is to respond to the following interoperability requirements.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2762, 'NATO AJP-5 DOCTRINE ALLIÉE INTERARMÉES SUR LA PLANIFICATION AU NIVEAU OPÉRATIF', 'NATO Publication', '', '', '6/26/2013 12:00:00 AM', '', '0', 190, '2407160859054', '', '', 'VERSION 1 * FREE * ELECTRONIC ONLY', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2763, 'NATO AAP-77  MANUEL DE TERMINOLOGIE DE L’OTAN', 'NATO Publication', '', '', '8/27/2018 12:00:00 AM', '', '0', 72, '2407160859055', '', '', 'VERSION 1 * FREE * ELECTRONIC ONLY', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2764, 'NATO AAP-03 DIRECTIVE FOR THE PRODUCTION, MAINTENANCE AND MANAGEMENT OF NATO STANDARDIZATION DOCUMENTS', 'NATO Publication', '', '', '10/17/2022 12:00:00 AM', '', '0', 76, '2407160859056', '', '', 'VERSION 1 * FREE * ELECTRONIC ONLY', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2765, 'NATO AAMEDP-1.2 AEROMEDICAL TRAINING OF FLIGHT PERSONNEL', 'NATO Publication', '', '', '5/3/2024 12:00:00 AM', '', '0', 30, '2407160859057', '', '', '', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2766, 'NASA GSFC-HDBK-8010 Laboratory Test to Evaluate the Vapor-Inhibiting Ability of Volatile Corrosion Inhibitor Materials for Temporary Protection of Ferrous Metal Surfaces', 'National Association of Corrosion Engineers', '', '', '9/27/2023 12:00:00 AM', '', '0', 18, '2407160859058', '', '', 'VERSION 1 * FREE * ELECTRONIC ONLY', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2767, 'NACE TM0208-2024  Laboratory Test to Evaluate the Vapor-Inhibiting Ability of Volatile Corrosion Inhibitor Materials for Temporary Protection of Ferrous Metal Surfaces', 'National Association of Corrosion Engineers', '', '', '4/4/2024 12:00:00 AM', '', '0', 21, '2407160859059', '', '', 'VERSION 2 * AVAILABLE ELECTRONIC ONLY\n\nPURPOSE AND SCOPE\n\nThe purpose of this directive is to establish procedures for the production, maintenance and management of NATO standardization documents in accordance with NATO relevant regulations.\n\nThis document establishes procedures for tasking authorities (TAs), delegated tasking authorities (DTAs), their subordinate working groups 2 (WGs), custodians, Allies, partner nations, NATO bodies, and anyone involved with producing, maintaining and managing NATO standardization documents.\n\nDetailed requirements concerning structure, format and layout of NATO standardization documents are defined in AAP-32. 3\n\n2 In the context of this publication, the term working group (WG) is used for any element, without delegated authority, subordinate to a DTA or directly to a TA.\n\n3 For easier reference, general information on structure, format and layout of covering documents as well as templates are provided at annex D of this publication.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2768, 'Mycotoxins in Food and Feed Detection and Management Strategies', 'Authors: Pradeep Kumar, Madhu Kamle, Dipendra Kumar Mahato', '', '', '1/1/2023 12:00:00 AM', '', '0', 481, '2407160859060', '', '', 'This handbook provides a uniform approach for performing LLA as a living risk assessment document for GSFC missions that is performed concurrently with design efforts and refined as the designs, materials, mission parameters, or processes are refined.\n\nLLA can provide the following project benefits:\n\nVerification of NASA limited-life requirement and Goddard Open Learning Design (GOLD) Rule compliance Identification of candidates for Critical Items List Risk identification Identification of items requiring maintenance or refurbishment Input to sparing plans Input to test plans\n\nProper LLA greatly reduces the risk of premature mission failures by ensuring life margin for wear-out or age-limited items. It also enables missions to be extended with some confidence that hardware will not fail due to life-limiting characteristics.\n\nPublicly Accessible', '0.000000', 109.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2769, 'Mycotoxins in Food and Beverage Innovations and Advances, Part II', 'Authors: Didier Montet, Catherine Brabet, Sabine Schorr-Galindo, Ramesh C. Ray', '', '', '1/1/2021 12:00:00 AM', '', '0', 277, '2407160859061', '', '', 'This standard test method evaluates the vapor-inhibiting ability (VIA) of various forms of VCI materials for temporary corrosion protection of ferrous metal surfaces, which is also called the “VIA-Ferrous” test.', '0.000000', 109.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2770, 'Mycotoxins in Agriculture and Food Safety', 'Authors: Kaushal K. Shinha, Deepak Bhatnagar', '', '', '7/16/1998 12:00:00 AM', '', '0', 530, '2407160859062', '', '', 'This standard provides technical and quality assurance guidelines for handling and installing nickel alloy, stainless steel, and titanium linings in air pollution control equipment such as FGD systems, ducts, and stacks.\n\nThe guidelines in this standard are also applicable to installation of thin, high-performance metallic linings in a wide variety of other process equipment. However, titanium welding procedures contained herein are only applicable to seal welds in air pollution control equipment.\n\nIt is the responsibility of users of this standard to determine the suitability of construction materials specified for particular applications.\n\nThis standard is applicable to wallpapering materials of 1.6 to 3.2 mm (0.063 to 0.13 in) thickness applied as linings over new or existing metallic structures. General safety requirements to perform this work are beyond the scope of this standard. It is assumed that users will incorporate specific safety requirements in accordance with their individual needs.\n\nNew and improved welding techniques as well as new alloys applicable to wallpaper installation are being developed. References to specific weld designs and techniques in this standard are not intended to preclude the use of newer technology. Use of alternative techniques shall be mutually agreed on by all contractual parties after adequate engineering analysis.\n\nThe corresponding ASME(1) material specifications may be used instead of the ASTM(2) material specifications cited in this standard.\n\nWhile the techniques described in this standard have demonstrated high levels of success, some extreme environmental and/or design conditions encountered in the use of air pollution control equipment can result in corrosive conditions so severe that even the most corrosion resistant construction material will occasionally fail. Such failures generally affect a relatively small percentage of the total lined surface and may require periodic maintenance.', '0.000000', 220.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2771, 'MOOC Learning Platform Development', 'Authors: Varun Gupta, Durg Singh Chauhan, Thomas Hanne', '', '', '10/31/2019 12:00:00 AM', '', '0', 57, '2407160859063', '', '', 'Flanges specified in the Standard Practice should be used only with the lens gaskets specified herein. This Standard Practice is similar in intent to ASME B16.5; however, it governs a higher pressure class and a lens gasket connection. At the time of writing this Standard Practice, no American Standard existed for pipe walls as heavy as required for this pressure class. Such piping is done mostly with seamless steel tubing. However, for purposes of flange and stub standardization, a defined set of outside diameters has been specified.\n\nThis Standard Practice establishes requirements for cast and forged steel flanges (welding neck and straight threaded) and threaded stubs, designed especially for use in the chemical industry, with end connections making use of lens gaskets.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2772, 'Materials for Energy Storage', 'Authors: Niroj Kumar Sahu, Arpan Kumar Nayak, Andrews Nirmala Grace', '', '', '1/1/2025 12:00:00 AM', '', '0', 319, '2407160859064', '', '', 'This pocket-sized booklet is intended as a guide for UT personnel. Contents: 10 sections on subjects such as frequently used formulas, trigonometry, geometry, circumferential scanning and formula examples. Also, 9 pages of detailed solutions are included.', '0.000000', 143.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2773, 'Lucys Engineering Adventure - Arabic', 'Danielle Passaglia', '', '', '2021', '', '0', 24, '2407160859065', '', '', 'This is a Spanish translation of Lucys Engineering Adventure completed by Walter Lenzi of the ASHRAE Brazil Chapter.\n**************************\nJoin Lucy on an Engineering Adventure!\n“How do they work? Why don’t they fall?\nWhat lights them up? Do they need to be tall?”\nLucy goes to work with her father to explore how buildings work.\nHelp her find unique solutions to STEM problems and see if you’d like to be an engineer too!\n**************************\nThis rhyming picture book introduces children to building and HVAC engineering through a young girls visit to an unfinished building, where her father uses a metaphor of the human body to explain the buildings beams and columns, electrical system, and HVAC ducts. Lucys curiosity is encouraged by her father throughout.\nThis is ASHRAEs first picture book and was developed by ASHRAE’s Student Activities Committee as part of their goal to promote and encourage engineering and HVAC&R careers.\n**************************\nDanielle Passaglia, EIT, LEED® Green Associate, Associate Member ASHRAE, is a Mechanical Engineer at Arup in Chicago, IL. She has nearly a decade of experience volunteering with STEM outreach in the K-12 arena via Engineering Ambassadors, TechGirlz, and ASHRAE’s Student Activities Committee.\nGabriella Vagnoli has illustrated multiple books, including three books in the Cayuga Island Kids chapter book series by Judy Bradbury (City of Light Publishing). She is Italian and Brazilian, was born and raised in Italy, and currently resides in Illinois with her American husband, two wonderful multicultural kids, and four crazy cats.\nJanice K. Means, PE, LEED® AP, FESD, Fellow ASHRAE, Life Member ASHRAE, Professor Emerita at Lawrence Technological University, provided educational oversight for this book. She holds a BA in Secondary Education (Social Science, Physics Minor), a BS in Engineering, and an MS in Mechanical Engineering.', '0.000000', 13.50, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2774, 'Lubrication in Practice', 'Author: W. L. Robertson', '', '', '3/7/1984 12:00:00 AM', '', '0', 237, '2407160859066', '', '', 'This is a Croatian translation of Lucys Engineering Adventure facilitated by the ASHRAE Danube Chapter.\n**************************\nJoin Lucy on an Engineering Adventure!\n“How do they work? Why don’t they fall?\nWhat lights them up? Do they need to be tall?”\nLucy goes to work with her father to explore how buildings work.\nHelp her find unique solutions to STEM problems and see if you’d like to be an engineer too!\n**************************\nThis rhyming picture book introduces children to building and HVAC engineering through a young girls visit to an unfinished building, where her father uses a metaphor of the human body to explain the buildings beams and columns, electrical system, and HVAC ducts. Lucys curiosity is encouraged by her father throughout.\nThis is ASHRAEs first picture book and was developed by ASHRAE’s Student Activities Committee as part of their goal to promote and encourage engineering and HVAC&R careers.\n**************************\nDanielle Passaglia, EIT, LEED® Green Associate, Associate Member ASHRAE, is a Mechanical Engineer at Arup in Chicago, IL. She has nearly a decade of experience volunteering with STEM outreach in the K-12 arena via Engineering Ambassadors, TechGirlz, and ASHRAE’s Student Activities Committee.\nGabriella Vagnoli has illustrated multiple books, including three books in the Cayuga Island Kids chapter book series by Judy Bradbury (City of Light Publishing). She is Italian and Brazilian, was born and raised in Italy, and currently resides in Illinois with her American husband, two wonderful multicultural kids, and four crazy cats.\nJanice K. Means, PE, LEED® AP, FESD, Fellow ASHRAE, Life Member ASHRAE, Professor Emerita at Lawrence Technological University, provided educational oversight for this book. She holds a BA in Secondary Education (Social Science, Physics Minor), a BS in Engineering, and an MS in Mechanical Engineering.', '0.000000', 13.50, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2775, 'Lubrication Fundamentals, Third Edition, Revised and Expanded', 'Authors: Don M. Pirro, Martin Webster, Ekkehard Daschner', '', '', '3/17/2016 12:00:00 AM', '', '0', 609, '2407160859067', '', '', 'This is an Arabic translation of Lucys Engineering Adventure completed by Ade Awujoola of the ASHRAE Nigeria Chapter and Osama Khayata of the ASHRAE Falcon Chapter in Dubai, UAE.\n**************************\nJoin Lucy on an Engineering Adventure!\n“How do they work? Why don’t they fall?\nWhat lights them up? Do they need to be tall?”\nLucy goes to work with her father to explore how buildings work.\nHelp her find unique solutions to STEM problems and see if you’d like to be an engineer too!\n**************************\nThis rhyming picture book introduces children to building and HVAC engineering through a young girls visit to an unfinished building, where her father uses a metaphor of the human body to explain the buildings beams and columns, electrical system, and HVAC ducts. Lucys curiosity is encouraged by her father throughout.\nThis is ASHRAEs first picture book and was developed by ASHRAE’s Student Activities Committee as part of their goal to promote and encourage engineering and HVAC&R careers.\n**************************\nDanielle Passaglia, EIT, LEED® Green Associate, Associate Member ASHRAE, is a Mechanical Engineer at Arup in Chicago, IL. She has nearly a decade of experience volunteering with STEM outreach in the K-12 arena via Engineering Ambassadors, TechGirlz, and ASHRAE’s Student Activities Committee.\nGabriella Vagnoli has illustrated multiple books, including three books in the Cayuga Island Kids chapter book series by Judy Bradbury (City of Light Publishing). She is Italian and Brazilian, was born and raised in Italy, and currently resides in Illinois with her American husband, two wonderful multicultural kids, and four crazy cats.\nJanice K. Means, PE, LEED® AP, FESD, Fellow ASHRAE, Life Member ASHRAE, Professor Emerita at Lawrence Technological University, provided educational oversight for this book. She holds a BA in Secondary Education (Social Science, Physics Minor), a BS in Engineering, and an MS in Mechanical Engineering.', '0.000000', 264.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2776, 'Lucy Goes Green', 'Danielle Passaglia', '', '', '2023', '', '0', 32, '2407160859068', '', '', 'This is a Greek translation of Lucys Engineering Adventure completed by Alkis Triantafilopoulos, Chrysostomos Bouras, Petros Dalavouras, and Nikolas Nikolopoulos of the ASHRAE Hellenic Chapter.\n**************************\nJoin Lucy on an Engineering Adventure!\n“How do they work? Why don’t they fall?\nWhat lights them up? Do they need to be tall?”\nLucy goes to work with her father to explore how buildings work.\nHelp her find unique solutions to STEM problems and see if you’d like to be an engineer too!\n**************************\nThis rhyming picture book introduces children to building and HVAC engineering through a young girls visit to an unfinished building, where her father uses a metaphor of the human body to explain the buildings beams and columns, electrical system, and HVAC ducts. Lucys curiosity is encouraged by her father throughout.\nThis is ASHRAEs first picture book and was developed by ASHRAE’s Student Activities Committee as part of their goal to promote and encourage engineering and HVAC&R careers.\n**************************\nDanielle Passaglia, EIT, LEED® Green Associate, Associate Member ASHRAE, is a Mechanical Engineer at Arup in Chicago, IL. She has nearly a decade of experience volunteering with STEM outreach in the K-12 arena via Engineering Ambassadors, TechGirlz, and ASHRAE’s Student Activities Committee.\nGabriella Vagnoli has illustrated multiple books, including three books in the Cayuga Island Kids chapter book series by Judy Bradbury (City of Light Publishing). She is Italian and Brazilian, was born and raised in Italy, and currently resides in Illinois with her American husband, two wonderful multicultural kids, and four crazy cats.\nJanice K. Means, PE, LEED® AP, FESD, Fellow ASHRAE, Life Member ASHRAE, Professor Emerita at Lawrence Technological University, provided educational oversight for this book. She holds a BA in Secondary Education (Social Science, Physics Minor), a BS in Engineering, and an MS in Mechanical Engineering.', '0.000000', 13.50, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2777, 'Lubricant Base Oil and Wax Processing', 'Avilino Sequeira', '', '', '8/9/1994 12:00:00 AM', '', '0', 303, '2407160859069', '', '', 'Join Lucy as she Goes Green!\nLucy goes with her classmates on a field trip to a sustainable farm, where they learn about storing energy using solar panels and windmills and recycling water through rainwater collection.\nHelp her find unique solutions to STEM problems and see if you’d like to be an engineer too!\n\n*************\n\nThis rhyming picture book is the second book in ASHRAEs Engineering Adventures Series. It was developed by the ASHRAE Student Activities Committee as part of their goal to promote and encourage engineering and HVAC&R careers.\n\n*************\n\nDanielle Passaglia, PE, LEED® Green Associate, Associate Member ASHRAE, is a Mechanical Engineer at Arup in Chicago, IL. She is a University of Nebraska alumna with a BA and an MA in Architectural Engineering and has nearly a decade of experience volunteering with STEM outreach in the K-12 arena via Engineering Ambassadors, TechGirlz, and ASHRAE’s Student Activities Committee. She is also the 2023–2024 President of the ASHRAE Illinois Chapter.\n\nGabriella Vagnoli has illustrated numerous books, including three books in the Cayuga Island Kids chapter book series (City of Light Publishing) and Billie the Brain (Blue Manatee Press). She is Italian and Brazilian, was born and raised in Italy, and currently resides in Seattle with her American husband, two wonderful multicultural kids, and four crazy cats. Find her portfolio at GabriellaVagnoli.com\n\nJanice K. Means, PE, LEED® AP, FESD, Fellow ASHRAE, Life Member ASHRAE, Professor Emerita at Lawrence Technological University, provided educational oversight for this book. She holds a BA in Secondary Education (Social Science, Physics Minor), a BS in Engineering, and an MS in Mechanical Engineering.', '0.000000', 176.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2778, 'JEDEC JESD239.01 Graphics Double Data Rate 7 SGRAM Standard (GDDR7)', 'JEDEC Solid State Technology Association', '', '', '4/1/2024 12:00:00 AM', '', '0', 322, '2407160859070', '', '', 'This standard applies to components and assemblies that contain Pb-free and Pb-containing solders and finishes. This standard describes the marking of components and the labeling of their shipping containers to identify their 2nd level terminal finish or material, and applies to components that are intended to be attached to boards or assemblies with solder or mechanical clamping or are press fit. This standard also applies to 2nd level terminal materials for bumped die that are used for direct board attach.\n\nThis standard applies to boards/assemblies, to identify the type of Pb-free or Pb-containing solder used. This standard documents a method for identifying board surface finishes and Printed Circuit Board (PCB) resin systems. This standard applies to PCB base materials and for marking the type of conformal coating utilized on Printed Circuit Board Assemblies (PCBAs). Material and their containers previously marked or labeled according to JESD 97, IPC-1066, or previous versions of this standard need not be remarked unless agreed upon by the supplier and customer.\n\nLabeling of exterior surfaces of finished articles, such as computers, printers, servers, and the like, is outside the scope of this standard. However internal PCBs and PCBAs are covered by this standard. Labeling of retail packages containing electronic products is also outside the scope of this standard. Markings under this standard do not denote EU RoHS compliance, or any other regional substance restriction legislation addressing lead content.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2779, 'JEDEC JEP199 Procedure for Reliability Characterization of Metal-Insulator-Metal Capacitors', 'JEDEC Solid State Technology Association', '', '', '4/1/2024 12:00:00 AM', '', '0', 24, '2407160859071', '', '', 'This standard defines the DDR5 SDRAM specification, including features, functionalities, AC and DC characteristics, packages, and ball/signal assignments. The purpose of this Standard is to define the minimum set of requirements for JEDEC compliant 8 Gb through 32 Gb for x4, x8, and x16 DDR5 SDRAM devices. This standard was created based on the DDR4 standards (JESD79-4) and some aspects of the DDR, DDR2, DDR3, and LPDDR4 standards (JESD79, JESD79-2, JESD79-3, and JESD209-4).', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2780, 'JCT 2005: Clause by Clause', 'Author: Phil Griffiths', '', '', '6/30/2017 12:00:00 AM', '', '0', 268, '2407160859072', '', '', 'This standard defines the specifications of interface parameters, signaling protocols, and features for PMIC device as used for memory module applications. The designation PMIC5020 refers to the device specified by this document.\n\nThe purpose is to provide a standard for the PMIC5020 device for uniformity, multiplicity of sources, elimination of confusion, ease of device specification, and ease of use.\n\nUnless otherwise noted in the document, any illegal operation is not allowed and device operation is not guaranteed.\n\nNOTE: The designation PMIC5020 refers to a portion of the part number designation of a series of commercial logic devices common in the industry. This number is normally preceded by a series of manufacturer specific characters to make up a complete part designation.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2781, 'JAK-STAT Pathway in Disease', 'Richard H. Bell, Jr.', '', '', '6/11/2009 12:00:00 AM', '', '0', 191, '2407160859073', '', '', 'This standard defines the Graphics Double Data Rate 7 (GDDR7) Synchronous Graphics Random Access Memory (SGRAM) specification, including features, functionality, package, and pin assignments.\n\nThe purpose of this standard is to define the minimum set of requirements for 16 Gb through 64 Gb x8 quad channel GDDR7 SGRAM devices. System designs based on the required aspects of this standard will be supported by all GDDR7 SGRAM vendors providing compatible devices. Some aspects of the GDDR7 standard such as AC timings and capacitance values were not standardized. Some features are optional and therefore may vary among vendors. In all cases, vendor data sheets should be consulted for specifics. This document was created based on some aspects of the GDDR6 Standard (JESD250) and other JEDEC device standards.', '0.000000', 215.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2782, 'ISPE Guide: 503B Compounding', 'International Society for Pharmaceutical Engineering', '', '', '8/1/2023 12:00:00 AM', '', '0', 122, '2407160859074', '', '', 'In 2022 ISPE worked with McKinsey and Company to provide technical and Chemistry, Manufacturing, and Controls (CMC) information on two workstreams to inform the newly, created European Commission Directorate-General, Health Emergency Preparedness and Response Authority (DG HERA). The workstreams were stockpiling antimicrobial resistance medical countermeasures, and flexible manufacturing and innovation countermeasures. This report summarizes the discussions and recommendations made by ISPE to the projects.\n\nISPE produced this report in response to a request from the US Department of Air Force Acquisition COVID-19 Task Force (DAF ACT) to advise regulatory, technical, and workforce elements favorable to creating a more robust and sustainable domestic pharmaceutical manufacturing base for Active Pharmaceutical Ingredients (APIs). The report lays out technical, regulatory and workforce changes that stakeholders in any country or region could consider to reduce the risks of API shortages to meet demands for essential medicines at any time, but particularly in pandemics and other emergencies.\n\nISPE has bundled these reports in keeping with its vision and mission and to provide solutions to complex pharmaceutical industry challenges and enhance efforts to develop, manufacture and reliably deliver quality medicines to patients. Together the reports reflect ISPE’s commitment to provide guidance on the supply of medicines to the people of every nation.', '0.000000', 695.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2783, 'ISPE Good Practice Guide: Process Gases, Second Edition', 'International Society for Pharmaceutical Engineering', '', '', '10/1/2023 12:00:00 AM', '', '0', 152, '2407160859075', '', '', 'As gene therapy products race towards the clinic and commercial launch, sponsor companies are faced with significant hurdles posed by evolving manufacturing platforms, process improvements across multiple stages of development, and a rapidly growing tool kit for the characterization of viral vectors. Taken together, this creates a complex landscape for demonstrating comparability driven by process changes.\n\nFurther, a lack of specific regulatory guidance on viral vector comparability studies pushes gene therapy companies to adapt and interpret principles of ICH Q5E for demonstrating comparability of biological products when changes are made in their manufacturing processes. As ICH Q5E guidelines are not fit for purpose in the context of Advanced Therapy Medicinal Products (ATMP), different approaches have been adopted across the industry to define comparability studies.\n\nThe ISPE Guide: ATMPs - Recombinant AAV Comparability and Lifecycle Management considers requirements and guidance for recombinant Adeno-Associated Virus (rAAV) manufacturing and comparability from the US FDA, EU EudraLex Volume 4 Part IV, EMA Q&A, and ICH Q5E. Drawing on a team of industry experts with global experience, the Guide provides current understanding and best practices on rAAV comparability exercises, offering manufacturers a standardized approach for developing process and product comparability strategies. It provides considerations for evaluating rAAV vector products comparability pre and post-change to the manufacturing process and proposes strategies to address the unique challenges posed by this new class of products.\n\nThe Guide is intended as a reference and practical guide for addressing common challenges that may arise when demonstrating comparability across the rAAV product lifecycle. It discusses host cell type selection, rAAV gene delivery methods, and the advantages, disadvantages, and impact on upstream and downstream operations, including differences in impurity profiles depending on the platform used. Comparison of scale-out versus scale-up of unit operations is included.\n\nAn extensive list of analytical techniques applicable to rAAV comparability studies is explored that should support virtually any type of rAAV product comparability study.\n\nProcess changes may occur throughout product development and after approval for various reasons. While a comprehensive list assigning risk to specific process changes is not possible given the product-dependent nature of these risks, the Guide contains general observations about levels of risk associated with common changes. Strategies for considering this knowledge with the analytical tools presented to develop comparability studies at various stages in the product lifecycle are described.\n\nIn addition, the Guide presents three realistic case studies for changes likely to be encountered during an rAAV product’s lifecycle. They cover various phases, pre-clinical, clinical, and commercial, detailing changes, how to assess them, what kind of development and characterization data should be generated, how the data informs the comparability protocol, and what additional considerations should be included in the comparability protocol.', '0.000000', 595.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2784, 'ICML 55.1 – Requirements for the Optimized Lubrication of Mechanical Physical Assets', 'Authors: The International Council for Machinery Lubrication (ICML), USA', '', '', '1/1/2023 12:00:00 AM', '', '0', 92, '2407160859076', '', '', 'The overall objective of the IEA EBC Annex 68” Project, “Indoor Air Quality Design and Control in Low Energy Residential Buildings”, has been to develop the fundamental basis for optimal design and control strategies for good Indoor Air Quality (IAQ) in highly energy efficient residential buildings, and to disseminate this information for use in practoce. The project was defined in 2015, the working phase lasted for the years 2016-19, and the project was concluded with publications on 2020. The project has engaged researchers from 21 companies and institutions from 15 countries.The work has gathered laboratory and field data and developed new knowledge on pollution sources in buildings and how the transport mechanisms for the pollutants interact with heat, air and moisture conditions in materials and indoor zones. Furthermore, the project has assembled a set of contemporary models to simulate the combined heat, air, moisture and pollution conditions of buildings and their assemblies. In addition, a set of so-called “common exercises” about the various subjects have been developed and tested. The purpose has been to identify and describe amenable ways to optimize the provision of ventilation and air-conditioning and to assess possibilities to bring this knowledge into practice.\n\nThe paper will review the original intentions of the project against the final achievements with the purpose to focus on which elements have been successfully achieved, and to identify areas where the project has only opened research and applications that should be followed up.', '0.000000', 124.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2785, 'ICC IPMC-2024 2024 International Property Maintenance Code', 'International Code Council', '', '', '2024', '', '0', 57, '2407160859077', '', '', 'The 2024 International Codes® (I-Codes®) have undergone substantial formatting changes as part of the digital transformation strategy of the International Code Council® (ICC®) to improve the user experience. The changes, promoting a cleaner, more modern look and enhancing readability and sustainability, include:\n\nSingle column text format and modernized font styles improves readability\nQR Codes replace vertical margin sidebars and arrows to identify code changes more accurately\nShading for table headers and notes improves locating tables and applicable notes\nGrouping of associated content brings tables and figures immediately after the parent section\nUsers have capability to validate authenticity of their book and register it with the ICC to receive incentives.\nThe 2024 IPMC® provides requirements for continued use and maintenance of building elements, site conditions, swimming pools, plumbing, mechanical, electrical and fire protection systems in existing residential and nonresidential structures.', '0.000000', 50.50, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2786, 'ICC IFGC-2024 2024 International Fuel Gas Code', 'International Code Council', '', '', '2024', '', '0', 215, '2407160859078', '', '', 'The 2024 International Codes® (I-Codes®) have undergone substantial formatting changes as part of the digital transformation strategy of the International Code Council® (ICC®) to improve the user experience. The changes, promoting a cleaner, more modern look and enhancing readability and sustainability, include:\n\nSingle column text format and modernized font styles improves readability\nQR Codes replace vertical margin sidebars and arrows to identify code changes more accurately\nShading for table headers and notes improves locating tables and applicable notes\nGrouping of associated content brings tables and figures immediately after the parent section\nUsers have capability to validate authenticity of their book and register it with the ICC to receive incentives.\n \n\nThe 2024 IFGC® addresses the design and installation of fuel gas systems and gas fired appliances through prescriptive and performance requirements.\n\nKey changes in the 2024 IFGC® include:\n\nAppendix D- D105.2, Test for combustion air and vent drafting for natural draft and Category I appliances. Existing code language has been deleted. The entire section is new for the 2024 Codes.\n[BS] 302.3.1 Engineered wood products. Sections 302.3.2, 302.3.3, and 302.3.4 have all been deleted.\n304.1 -General. The entire section is new for the 2024 Codes. Existing code language has been deleted. The entire section is new for the 2024 Codes.\n304.12 Protection from fumes and gases. Existing code language has been deleted. The entire section is new for the 2024 Codes.\n403.6 Workmanship and defects. Existing code language has been rewritten and additional code language has been added for the 2024 Codes.\nTable 503.8- Note: Revisions to Table 503.8 are errata to the 2021 IFGS text that is also applicable to the 2024 IFGS text.', '0.000000', 56.75, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2787, 'ICC IEBC-2024 2024 International Existing Building Code', 'International Code Council', '', '', '2024', '', '0', 295, '2407160859079', '', '', 'The 2024 IEBC encourages the use and reuse of existing buildings. This code covers repair, alteration, addition and change of occupancy for existing buildings. and historic buildings, while achieving appropriate levels of safety without requiring full compliance with the new construction requirements contained in the other I-Codes. Key changes in the 2024 IEBC® include:\n\nOccupiable roofs. The concept of occupiable roofs requirements have been incorporated in a variety of locations to correlate with the IBC.\nStorm Shelters. The storm shelter requirements have been coordinated with revisions in the IBC and ICC 500. The provisions have also been clarified that where constructed shall be comply with IBC Section 423 and ICC 500.\nRisk category increase. Clarifies how risk categories should be assigned for structural design where the addition and the existing building have different uses. The provisions in the Prescriptive and Work Area methods.\nSmoke compartment requirements. Existing Group I-1, condition 2 occupancies and ambulatory care facilities may be required to divide stories into no fewer than two smoke compartments for more substantial additions and alterations.\nAdult Changing stations. Where additional toilet facilities are being added and IBC Section 1110.4.1 would require adult changing stations, Section 306.7.15 would require that at least one accessible family or assisted use toilet room is required to contain one.\nExterior wall covering and wall envelopes sprinkler requirement. Section 309.2.1 has been added to require that if combustible exterior wall envelopes or coverings are installed on a high-rise building the building must be equipped throughout with a sprinkler system. There are some exceptions for smaller installations and when only a combustible water resistive barrier is installed.\nPerformance method renumbering. Though editorial in nature, Chapter 13 was renumbered to assist in the useability of that method.\nOwners’ responsibility at construction sites. Section 1502 was added to address the need for the owner to properly develop, implement and maintain a site safety plan during construction. A site safety director must be designated and is responsible to conduct daily fire safety inspections.\nNon required automatic sprinkler system. A section has been added to Chapter 10 under the change of occupancy classification requirements to allow the removal of a nonrequired existing automatic sprinkler system. This section includes a number of criteria that must be met.\nAPPENDIX E TEMPORARY EMERGENCY USES. This new appendix was created to provide guidance for designers, engineers, architects and fire and building officials to allow temporary emergency uses of existing buildings with respect to the minimum code requirements. This appendix is intended to serve as a template or checklist for use during an emergency that references the relevant code requirements.', '0.000000', 117.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0);
INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(2788, 'ICC ICCPC-2024 2024 ICC Performance Code for Buildings and Facilities', 'International Code Council', '', '', '2024', '', '0', 153, '2407160859080', '', '', 'The 2024 International Codes® (I-Codes®) have undergone substantial formatting changes as part of the digital transformation strategy of the International Code Council® (ICC®) to improve the user experience. The changes, promoting a cleaner, more modern look and enhancing readability and sustainability, include:\n\nSingle column text format and modernized font styles improves readability QR Codes replace vertical margin sidebars and arrows to identify code changes more accurately Shading for table headers and notes improves locating tables and applicable notes Grouping of associated content brings tables and figures immediately after the parent section Users have capability to validate authenticity of their book and register it with the ICC to receive incentives.\n\nThe 2024 IPMC® provides requirements for continued use and maintenance of building elements, site conditions, swimming pools, plumbing, mechanical, electrical and fire protection systems in existing residential and nonresidential structures.', '0.000000', 103.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2789, 'ICAC EP-7 ELECTROSTATIC PRECIPITATOR GAS FLOW MODEL STUDIES', 'Institute of Clean Air Companies', '', '', '1/1/2004 12:00:00 AM', '', '0', 0, '2407160859081', '', '', 'ENGLISH\n\nFOREWORD\n\nThis manual identifies and reviews various operational opportunities and techniques for minimizing noise in civil aviation operations. It is intended to be used in conjunction with the Guidance on the Balanced Approach to Aircraft Noise Management (Doc 9829) and expands on and offers further guidance on one of the principal elements of the Balanced Approach - \\\"Noise Abatement Operational Procedures,\\\" as outlined in Doc 9829.\n\nThe information contained in this manual has been assembled by the ICAO Committee on Aviation Environmental Protection (CAEP) and provides background on current practices that are available to aircraft operators, airport operators, air navigation services providers (ANSPs), other industry organizations and States to reduce aircraft noise impacts from civil air transport. It also highlights recent opportunities resulting from emerging technologies and considers what advances may become available in the near future that the aerospace manufacturing industry and airspace service providers are currently developing. The manual is therefore aimed at airlines, airport operators, air traffic management and air traffic control service providers, airworthiness authorities, environmental agencies as well as other government bodies and interested parties.\n\nIt should be noted that this manual is not intended as a basis for regulatory action and the choice of which operational procedure is appropriate depends upon many factors other than noise benefits, as highlighted in the interdependencies section.\n\nSafety must always be the overriding consideration in all civil aviation operations and the operator, in conjunction with the operating crew, must ultimately exercise their judgment in tactical application of noise reducing practices during operations while maintaining the necessary safety margins.\n\nThe objectives of this manual are to:\n\na) document current industry experience to minimize aircraft noise exposure through operational measures;\n\nb) identify opportunities where practicable and operationally safe to do so that could result in measurable noise impact reductions;\n\nc) highlight emerging technology that, when used, could result in reductions in operational noise impacts;\n\nd) demonstrate that a more efficient use of infrastructure is an effective means of reducing civil aviation noise impacts and therefore promote enhanced use of the capabilities inherent in existing aircraft, ground service equipment and infrastructure, including airspace management; and\n\ne) highlight the importance of stakeholder collaboration to address operational changes that impact community noise exposure.\n\nThe opportunities and issues are addressed in this manual in a generic way but include practical examples where they are available. Wherever possible, a general indication of the magnitude of the benefits is also given.\n\nCollaborative efforts are paramount in any operational improvement initiative. Before specific changes to aircraft operations are introduced, it is necessary for proponents to consult with the operators, regulators, aircraft and engine manufacturers, the supporting ANSP, the airport operator and community representatives about the potential benefits and technical limitations of such changes. Before contemplating any changes to infrastructure, it is also advisable to carry out a more general consultation and environmental review as may be required with the major aviation stakeholders and those who will be affected by the changes.\n\nKEY CONSIDERATIONS\n\nFor environmental, economic and efficiency reasons, the commercial aviation industry has already developed and implemented many techniques to reduce aircraft noise. There has been steady progress in making aircraft and airport operations quieter, but it takes time for technological advancements in aircraft and engine design to be certified and then spread through the fleet. Changes to operating procedures or improvements to airport, airspace and ATM infrastructure may offer significant and more immediate ways of reducing noise impacts.\n\nWhile this manual is focused on reducing aircraft noise, the primary concern for all operations is safety. Safety standards must not be compromised by any of the changes made in the interest of aircraft noise impact reduction.\n\nAll decisions regarding changes to operational procedures depend on the specific situation (such as weather, equipment and facilities) associated with each flight, aircraft and crew. It should be noted that not all techniques identified may be practical or even possible, to incorporate into the majority of flights and individual operators may already have incorporated several of them into their current operations. Whenever possible, standard (arrival and departure) procedures should aim to minimize noise impacts.\n\nAnnex 16 - Environmental Protection, Volume I - Aircraft Noise states that \\\".operating procedures for noise abatement shall be developed in consultation with operators that use the aerodrome concerned.\\\" Implementation of operational opportunities and techniques should consider airport and air traffic constraints, operational requirements and individual operator circumstances on a given flight.\n\nMany operational opportunities require collaboration and cooperation among all civil aviation stakeholders and communities. Stakeholder collaboration is essential to ensure that potential changes to equipment, procedures and practices for noise abatement are effective, safe, reliable and cost-efficient. The ICAO Balanced Approach and Community Engagement for Aviation Environmental Management (Circular 351) further promote public education, information dissemination and information exchange among the airport, aircraft operators, ANSPs, regulators and local communities in order to explain the context of new procedures and current and future environmental, social and economic benefits and impacts.\n\nA final consideration is the management of potential interdependencies (both trade-offs and synergies) that can exist between noise and emission (and fuel burn with associated CO2 emissions) goals in the vicinity of airports as well as non- environmental interdependencies such as airport and airspace capacity and operating costs. Potential operational developments need to be assessed in the context of the forecast increase in air travel demand for the future and the resultant air traffic growth. Changes in air traffic volume may affect noise exposure and influence operational decisions related to aircraft noise impacts.\n\nComments on this manual, particularly with respect to its application and usefulness, and relevant examples would be appreciated. These will be taken into account in the preparation of subsequent editions and should be addressed to:', '0.000000', 116.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2790, 'Hypertrophic Cardiomyopathy A Practical Guide to Diagnosis and Management', 'Authors: Srilakshmi M. Adhyapak, V. Rao Parachuri', '', '', '12/21/2020 12:00:00 AM', '', '0', 175, '2407160859082', '', '', 'SPANISH', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2791, 'Hyperthermia in Oncology', 'Clifford L. K. Pang', '', '', '5/27/2015 12:00:00 AM', '', '0', 380, '2407160859083', '', '', 'ARABIC', '0.000000', 275.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2792, 'Hyperthermia and Oncology Volume 1 Thermal Effects on Cells and Tissues', 'Authors: Urano, Douple', '', '', '1/1/1988 12:00:00 AM', '', '0', 221, '2407160859084', '', '', '', '0.000000', 198.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2793, 'Greenhouse Gas Carbon Dioxide Mitigation: Science and Technology', 'Martin M. Halmann|Meyer Steinberg', '', '', '11/23/1998 12:00:00 AM', '', '0', 593, '2407160859085', '', '', 'Understanding Grid-Interactive Buildings for Decarbonization\nStay up to date with the future of sustainable building practices with the latest groundbreaking release from ASHRAE’s Task Force for Building Decarbonization (TFBD), Grid-Interactive Buildings for Decarbonization: Design and Operation Resource Guide. This is the second in a series of guides aimed at addressing the challenge of decarbonization in the built environment. Grid interactivity is a relatively new practice for most ASHRAE members, and buildings have a role in decarbonizing the power grid and managing their carbon budget; therefore, this guide provides information to enable readers to maximize carbon reduction through a building’s interaction with the electric power grid.\nDecarbonizing the electric grid requires a shift to a dynamic, two-way relationship between buildings and the grid that allows buildings to respond dynamically to grid conditions, including time-varying carbon emissions rates. This two-way communication has come into focus in the last few years as renewable energy integration and grid reliability issues—particularly around peak conditions brought on by extreme weather conditions, variability of renewable generation, and increased loads—have spurred utilities, grid operators, and the building community to reconsider the role buildings can play in supporting grid reliability and decarbonization by reshaping their energy consumption patterns.\nThese best practices, design considerations, and operational guidelines are all intended to target one or more of the three primary value streams offered by grid integration:\n• Reduced carbon emissions\n• Cost savings\n• Resiliency\nThis guide is focused on commercial and multifamily buildings, though aspects also apply to residential and industrial sectors. Beyond design guidance, this guide provides operational guidance for new and existing buildings to make the best use of their available demand flexibility in practice. Dive into the forefront of architectural innovation and environmental responsibility and explore the transformative power of grid interactivity.', '0.000000', 220.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2794, 'GMNA GM9700P Powder Impact Fusion Test', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 8, '2407160859086', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW18735\n\nThe purpose of this procedure is to describe the standard equipment configuration for powder material and equipment testing. This configuration is required in test procedures for back ionization, applicator longevity, pump longevity and impact fusion.\n\nNote: Nothing in the specification, however, supersedes applicable laws and regulations unless a specific exemption has been obtained.\n\nNote: In the event of a conflict between the English and the domestic language, the English language shall take precedence.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2795, 'GMNA 9986159  Gasoline, Unleaded Regular, Chinese Factory Fill', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 5, '2407160859087', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW18734\n\nThis procedure describes the method used to evaluate the resistance of a powder paint to back ionization with increasing film build. Back ionization will be evaluated visually both before and after baking.\n\nNote: Nothing in this test method supersedes applicable laws and regulations unless a specific exemption has been obtained.\n\nNote: In the event of a conflict between the English and domestic language, the English language shall take precedence.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2796, 'GMNA 9985689 Coatings for Balance Weights for Wheels', 'General Motors North America', '', '', '3/1/2024 12:00:00 AM', '', '0', 3, '2407160859088', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW18733\n\nThe method describes the procedure for determining the degree of compatibility between two different Powder materials (Method A) and different particle classification sizes of the same powder material (Method B). Compatibility is evaluated by inspecting the cured surface of the various powder blends. Powder compatibility should be verified when changing powder materials or target mean particle size at a facility. This verification decreases the potential of detrimental effects on final surface appearance and durability.\n\nNote: Nothing in this test method supersedes applicable laws and regulations unless a specific exemption has been obtained.\n\nNote: In the event of a conflict between the English and domestic language, the English language shall take precedence.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2797, 'GMNA 9984415 Crystal Refiner, Zinc Phosphate System', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 2, '2407160859089', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW18732\n\nThis procedure describes a method to quantity the impact fusion of powder paint materials and evaluate the impact fusion characteristics.\n\nStandard components are to be used with various materials to determine the impact characteristics of these powder materials. This method also allows for a standard material to be used with various components to evaluate and compare the impact characteristics of the components. This occurs by varying only one equipment component per test.\n\nNote: Nothing in this test method supersedes applicable laws and regulations unless a specific exemption has been obtained.\n\nNote: In the event of a conflict between the English and domestic language, the English language shall take precedence.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2798, 'GMNA 9984404 Chromic Acid, Phosphoric Rinse', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 3, '2407160859090', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW18277\n\nMaterial Description.\n\nThis specification covers unleaded regular grade gasoline for factory fill use. Factory fill gasoline is intended for use in vehicles which are stored for extended periods of time or in storage tanks where the rate of turnover is low.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nThis fuel is intended as a factory fill fuel at vehicle assembly. This fuel can also be used for engine durability testing, vehicle durability testing and/or component durability testing.\n\nRemarks.\n\nNothing in this standard supercedes applicable laws and regulations unless specified exemption has been obtained.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2799, 'GMNA 9984402', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 3, '2407160859091', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW18720\n\nMaterial Description.\n\nThis specification defines the basic requirements for coatings for weights used to balance tire and wheels assemblies. The coatings consist of a powder epoxy basecoat and powder polyester topcoat. The specification also defines the requirements for corrosion coatings for the balance weight clips.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nAll coated balance weights used on aluminum or steel wheels.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2800, 'GMNA 9984400  Cleaner, Alkali', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 3, '2407160859092', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW3011\n\nMaterial Description.\n\nThis specification covers the requirements for crystal refiner materials for zinc phosphate coatings applied to bare metal substrates. These conditioners are only intended to be used in conjunction with a specifically approved zinc phosphate system (9984090 and 9984123) from the same supplier.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nMaterials approved to this specification are to enhance the phosphate crystal growth and activate crystal growth.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2801, 'GMNA 9984304  Purge Solvent, HAP-Compliant, for Solventborne Enamel', 'General Motors North America', '', '', '3/1/2024 12:00:00 AM', '', '0', 1, '2407160859093', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW3011\n\nMaterial Description.\n\nThis specification covers the requirements for sealant final rinse materials, either chromium containing or chromium-free, for zinc phosphate coatings applied to bare metal substrates. These sealants are only intended to be used in conjunction with a specifically approved zinc phosphate system (9984090 and 9984123) from the same supplier.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nMaterials approved to this specification are to enhance the subsequent paint adhesion and improve corrosion resistance.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2802, 'GMNA 9984193 Sealer - Preform, for Gauge or Drain Hole Plug Assembly', 'General Motors North America', '', '', '3/1/2024 12:00:00 AM', '', '0', 6, '2407160859094', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW16546\n\nMaterial Description.\n\nThis specification covers the requirements for an alkali cleaner (powder or liquid) that will be used in the cleaning stages of spray, immersion and small parts phosphate systems. This process is engineered to provide a clean body-in-white or part by removing the contaminants including solder dust, flux, excessive mill oils, drawing compounds and prelubes, etc., normally on the body-in-white or part.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nThese materials may be applied either low or high pressure on a fully or partially assembled vehicle body-in-white or part to remove contaminants.\n\nRemarks.\n\nSince the condition of the metal surface is critical to the proper performance of the phosphate, the materials used under this specification must not adversely affect the formation of the proper phosphate coating. Therefore, these materials are considered part of the metal pretreatment process and shall be supplied by the phosphate supplier in each plant. Any exceptions to this rule must be first approved by the appropriate GM Materials Engineering Department (Product Engineering or Manufacturing Engineering).', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2803, 'GMNA 9984181  Sealer - Preformed, Extrudable, Weldable and Expandable', 'General Motors North America', '', '', '3/1/2024 12:00:00 AM', '', '0', 5, '2407160859095', '', '', 'ENGLISH', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2804, 'GMNA 9984117 Body Shop Highlighting Material', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 3, '2407160859096', '', '', 'ENGLISH', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2805, 'GMNA 9984115 Phosphate Pre-Wipe Material', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 3, '2407160859097', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW17969\n\nNote: Nothing in this standard supercedes applicable laws and regulations.\n\nNote: In the event of conflict between the English and domestic language, the English language shall take precedence.\n\nPurpose/Material Description.\n\nThis specification details the material and performance requirements of a preformed sealer, used with plastic gauge or drain hole \\\"plug assemblies\\\". The sealant compound, depending upon its formulation, slightly melts or expands, when processed through the Paint Shop Sealer/Primer Bake Oven. This bake, seals the plug assembly to the body, preventing water, dust, or air intrusion. The sealer must cure to a tack free surface. It must adhere to electrocoated metal. Expanding sealers are expected to meet either the High Bake (Type A) or Low Bake (Type B) requirements. Nonexpanding sealers are expected to meet both the High Bake and Low Bake requirements (Type C). Material must show no sign of trapped air from either an external observation or a sectional view before and after curing. See Table 1.\n\nMaterial Identification.\n\nNot applicable.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nThese sealers, as part of the plug assemblies, are installed to the body manually, in the paint shop sealer line.\n\nRemarks.\n\nTechnology Approval Documentation.\n\nAt the conclusion of testing to this specification, the supplier must provide a document package (1.4.2 thru 1.4.3).\n\nProduct Data.\n\nDocumentation of all attributes and test results are required for the material, per Section 3 of this specification. All test panels should be identified and photographed for full documentation.\n\nBake Charts.\n\nA Bake window that identifies the Bake Conditions where the sealer meets, and no longer meets all requirements of this specification, must be provided. Key Product Characteristics (KPC)s to include, at minimum, Volumetric Expansion and Initial Adhesion. The Bake Chart is to reflect:\n\n• Time at metal temperature on x-axis, minimum range: (0 minutes to 90 minutes).\n\n• Temperature on y-axis, minimum range: (130 °C to 200 °C). Additional direction to be provided by the approving material engineer.\n\nAdditional information may be requested by the responsible GM Engineer, including manufacturing site and trend charting of these attributes for (x) number of the initial production material batches.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2806, 'GMNA 9984094 Medium Build Cathodic Electrocoat', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 3, '2407160859098', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW16292\n\nThis specification details the requirements of an extrudable weld-through material which may be applied in the Metal Center, Assembly Plant Body Shop or, at an outside source.\n\nNote: Nothing in this standard supercedes applicable laws and regulations.\n\nNote: In the event of conflict between the English and domestic language, the English language shall take precedence.\n\nPurpose/Material Description.\n\nThis type of material is a smooth and homogeneous mixture, free of: air; lumps; unmixed particles and foreign matter. These sealing materials are extruded into parts, intended for use between two pieces of (oily) metal that will be welded together. The material is typically tacky throughout and can be referred to as “two side tacky”. A thin, dry film may be applied to one side of the extruded part to improve handling or weldability of the part and is referred to as “one side tacky”.\n\nThe material has low-expansion capability and will expand (Table 1) and cure upon heating in the Paint Shop Electrocoat (E-Coat) Oven. This material is intended to seal interior or exterior body joints against water, dust and air intrusion.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nApplicable to preform sealer materials that are formed into parts and installed prior to the assembly Plant Paint Shop, between two layers of metal.\n\nRemarks.\n\nNone.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2807, 'GMNA 9984090 Zinc Phosphate Conversion Coating – Immersion', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 3, '2407160859099', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW16546\n\nMaterial Description.\n\nThis specification covers the requirements for a sprayable or wipe-on body shop highlighting material that is used to reveal surface defects in the sheet metal. These defects will be repaired/refinished prior to exiting the body shop.\n\nSince the condition of the metal surface is critical to obtain the required paint performance in the end product, the materials used under this specification must not adversely affect the formation of the proper phosphate or thin film pretreatment coatings. Therefore, these materials are considered part of the process and shall be supplied by the paint pretreatment supplier in each assembly plant. Any exceptions to this rule must first be approved by the Manufacturing Engineering Tribology Engineer.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nAll full or partially assembled automobile or truck bodies.\n\nRemarks.\n\nNot applicable.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2808, 'GMNA 9984046 Primer Surfacer - Powder', 'General Motors North America', '', '', '4/1/2024 12:00:00 AM', '', '0', 8, '2407160859100', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW16546\n\nMaterial Description.\n\nThis specification covers the requirements for a phosphate pre-wipe material that can be used to clean off drawing compounds, mill oils, sealants, etc., from metal surfaces. This material will be used in a pre-wipe area ahead of the phosphate system.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nThese materials may be applied on a fully or partially assembled automobile or truck body with rags, Scotchbrite pads, etc., to remove contaminants prior to paint processing.\n\nRemarks.\n\nSince the condition of the metal surface is critical to the proper performance of the phosphate, the materials used under this specification must not adversely affect the formation of the proper phosphate coating. Therefore, these materials are considered part of the metal pretreatment process and shall be supplied by the phosphate supplier in each plant. Any exceptions to this rule must be first approved by the appropriate GM Materials Engineering Department (Product Engineering or Manufacturing Engineering).', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2809, 'GME TEST-240324', 'General Motors Europe', '', '', '8/1/2023 12:00:00 AM', '', '0', 0, '2407160859101', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW3008\n\nMaterial Description.\n\nThis specification covers the requirements for medium build, waterborne cathodic electrodeposition (ELPO) primers for use on vehicle bodies, sheet metal and parts.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nVehicle bodies, sheet metal and small parts.\n\nNote: Medium build cathodic electrocoat must be used in conjunction with Ultraviolet (UV) resistant primer surfacer in any application or body structure areas that are exposed to sunlight.\n\nRemarks.\n\nThis primer provides a smooth, corrosion resistant, adhesion promoting coating over metallic surfaces which may or may not be subsequently topcoated.', '0.000000', 43.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2810, 'GIS for Group Decision Making', 'Piotr Jankowski|Timothy Nyerges', '', '', '1/18/2001 12:00:00 AM', '', '0', 296, '2407160859102', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW3011\n\nMaterial Description.\n\nThis specification covers the material and performance requirements for immersion applied zinc phosphate conversion coatings.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nThese materials are intended for vehicle bodies and parts that will subsequently receive a cathodic electrocoat primer.\n\nRemarks.\n\nConversion coatings are intended to provide a crystalline, corrosion resistant, uniform, chemically converted, adhesion promoting surface on bare steel, electrogalvanized, galvanneal and aluminum substrates.', '0.000000', 1.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2811, 'GIS, Environmental Modeling and Engineering', 'Allan Brimicombe', '', '', '12/23/2009 12:00:00 AM', '', '0', 380, '2407160859103', '', '', 'ENGLISH * INACTIVE FOR NEW DESIGN * USE GMW18730\n\nThis specification covers the qualification and performance requirements of a thermosetting, sandable, powder primer surfacer.\n\nMaterial Description.\n\nThe powder primer surfacer covered in this specification is intended to be applied and baked over an electrodeposition coating (e.g., ELPO, E-Coat, Electrocoat) prior to topcoat. The target bake for this system is 25 minutes at 177 °C (350 °F) substrate temperature.\n\nSymbols.\n\nNot applicable.\n\nApplicability.\n\nThe powder primer surfacer is intended to provide a smooth, adhesion promoting coating over baked electrodeposition coating. It is also intended to provide an easily sanded surface. The powder primer surfacer is typically applied by electrostatic spraying and is subsequently topcoated with high solids acrylic enamel or waterborne color coats.\n\nRemarks.\n\nThe powder primer must be evaluated for plant-specific material layering and processing before release for production use.', '0.000000', 160.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2812, 'Fracture Processes of Concrete', 'Authors: Jan G.M. van Mier', '', '', '7/14/2017 12:00:00 AM', '', '0', 465, '2407160859104', '', '', 'This Manual was created by the members of the National Glass Association to provide guidance and specific best practices for frameless shower enclosures. It is meant to educate and assist glass professionals on designing, measuring and installing safe, functional shower enclosures. The Manual also serves as a tool to the professional installer to point out potentially unsafe design to an end user.', '0.000000', 330.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2813, 'FAA AC 00-56B  Voluntary Industry Distributor Accreditation Program', 'Federal Aviation Administration', '', '', '5/27/2015 12:00:00 AM', '', '0', 16, '2407160859105', '', '', 'PURPOSE.\n\nThis technical standard order (TSO) is for manufacturers applying for a TSO authorization (TSOA) or letter of design approval (LODA). In it, we (the Federal Aviation Administration, (FAA)) tell you what minimum performance standards (MPS) your airborne electronic multifunction display must meet for approval and identification with the applicable TSO marking.', '0.000000', 65.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2814, 'Extrusion Of Foods', 'Author: Judson M. Harper', '', '', '8/22/2019 12:00:00 AM', '', '0', 227, '2407160859106', '', '', 'Purpose.\n\nThis Advisory Circular (AC) provides guidance and specifications for reference material covering Aircraft Fire Extinguishing Agents.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2815, 'A67 -- Codes and Standards (SI)', 'ASHRAE', '', '', '2023', '', '0', 39, '2407160859107', '', '', 'This Technical Information Report (TIR) provides information about how to effectively implement the FDA’s regulation on current good manufacturing practices (CGMP) for combination products. Combination products are therapeutic or diagnostic medical products that combine drugs, devices, and/or biological products with one another. The FDA regulation became effective 22 July 2013 (21 CFR Part 4). Final guidance on CGMPs for combination products was issued in January 2017, and a list of alternative or streamlined mechanisms for compliance with CGMPs for combination products was later issued in September 2022 . This TIR, where appropriate, also considers best practices, guidelines, and standards used in both the United States and other regions. The overall goal of the TIR is to aid informed, risk-based decisions in establishing CGMP operating systems that support development, manufacture, premarket regulatory evaluation, and commercialization of combination products. It should be noted that, while the information contained in the TIR has been carefully considered, it is up to the individual manufacturer to ensure compliance with all regulatory requirements that apply to its products.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2816, 'A67 -- Codes and Standards (I-P)', 'ASHRAE', '', '', '2023', '', '0', 39, '2407160859108', '', '', 'This document provides guidance regarding the understanding and use of product bioburden data including: what bioburden data represent; how to use bioburden data to support a sterilization process; the analysis and characterization of bioburden; establishment and the use of alert and action levels; how to investigate bioburden excursions; trending and maintaining an effective bioburden monitoring program; counting plates and recording results.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2817, 'S50 -- Thermal Storage (SI)', 'ASHRAE', '', '', '2024', '', '0', 41, '2407160916100', '', '', 'This chapter lists important codes and standards from a broad spectrum of engineering societies, and provides contact information for the issuing organizations.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2818, 'S50 -- Thermal Storage (I-P)', 'ASHRAE', '', '', '2024', '', '0', 41, '2407160916101', '', '', 'Dedicated outdoor air systems (DOASs) use separate equipment to condition all of the outdoor air brought into a building for ventilation, and deliver it to each occupied space, either directly or in conjunction with local or central HVAC units serving those same spaces. The local or central HVAC units are used to maintain space temperature. A DOAS unit can be simple, with just a few components (e.g., a fan and a cooling coil), or more complex, with several energy recovery devices, cooling coils, heating coils and one or more fans. Generally, the objective of a DOAS is to condition incoming outdoor air before it mixes (and is diluted) with the remainder of the building air so that it is easier to dehumidify and clean, and so that energy in outgoing air can be recovered to precondition incoming outdoor air. Applications Air Distribution Equipment Configurations Control', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2819, 'S49 -- Room Air Conditioners and Packaged Terminal Air Conditioners (SI)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916102', '', '', 'Dedicated outdoor air systems (DOASs) use separate equipment to condition all of the outdoor air brought into a building for ventilation, and deliver it to each occupied space, either directly or in conjunction with local or central HVAC units serving those same spaces. The local or central HVAC units are used to maintain space temperature. A DOAS unit can be simple, with just a few components (e.g., a fan and a cooling coil), or more complex, with several energy recovery devices, cooling coils, heating coils and one or more fans. Generally, the objective of a DOAS is to condition incoming outdoor air before it mixes (and is diluted) with the remainder of the building air so that it is easier to dehumidify and clean, and so that energy in outgoing air can be recovered to precondition incoming outdoor air. Applications Air Distribution Equipment Configurations Control', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2820, 'S49 -- Room Air Conditioners and Packaged Terminal Air Conditioners (I-P)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916103', '', '', 'Thermal storage systems remove heat from or add heat to a storage medium for use at another time. Thermal energy storage (TES) for HVAC and/or domestic water-heating applications can involve various temperatures associated with heating or cooling. High-temperature storage is typically associated with solar energy or high-temperature heating, and cool storage with air-conditioning, refrigeration, or cryogenic-temperature processes. Energy may be charged, stored, and discharged daily, weekly, annually, or in seasonal or rapid batch process cycles. Fast-acting and/or grid-interactive energy storage systems can provide balancing services and other critical needs of the electric grid, such as frequency control and renewable energy integration. These grid-interactive systems dynamically couple consumer energy usage to the grid’s real-time needs. Historically, thermal storage has been used for comfort and process heating and cooling applications as a way to reduce the total utility bill and/or size of heating and cooling equipment. Sensible Thermal Storage Technology Latent Cool Storage Technology Chiller and Ice Storage Selection Heat Storage Technology Sizing Cool Storage Systems Application of Thermal Storage Systems Operation and Control Other Design Considerations Cost Considerations Maintenance Considerations Commissioning Good Practices', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2821, 'S48 -- Unitary Air Conditioners and Heat Pumps (SI)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916104', '', '', 'Thermal storage systems remove heat from or add heat to a storage medium for use at another time. Thermal energy storage (TES) for HVAC and/or domestic water-heating applications can involve various temperatures associated with heating or cooling. High-temperature storage is typically associated with solar energy or high-temperature heating, and cool storage with air-conditioning, refrigeration, or cryogenic-temperature processes. Energy may be charged, stored, and discharged daily, weekly, annually, or in seasonal or rapid batch process cycles. Fast-acting and/or grid-interactive energy storage systems can provide balancing services and other critical needs of the electric grid, such as frequency control and renewable energy integration. These grid-interactive systems dynamically couple consumer energy usage to the grid’s real-time needs. Historically, thermal storage has been used for comfort and process heating and cooling applications as a way to reduce the total utility bill and/or size of heating and cooling equipment. Sensible Thermal Storage Technology Latent Cool Storage Technology Chiller and Ice Storage Selection Heat Storage Technology Sizing Cool Storage Systems Application of Thermal Storage Systems Operation and Control Other Design Considerations Cost Considerations Maintenance Considerations Commissioning Good Practices', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2822, 'S48 -- Unitary Air Conditioners and Heat Pumps (I-P)', 'ASHRAE', '', '', '2024', '', '0', 15, '2407160916105', '', '', 'Room air conditioners are encased assemblies designed primarily for mounting in a window or through a wall. They are designed to deliver cool or warm conditioned air to the room, either without ducts or with very short ducts (up to a maximum of about 48 in. [1220 mm]). Each unit includes a prime source of refrigeration and dehumidification and a means for circulating and filtering air; it may also include a means for ventilating and/or exhausting and heating. PTACs are designed primarily for commercial installations to provide the total heating and cooling functions for a room or zone and are specifically for through-the-wall installation. The units are mostly used in relatively small zones on the perimeter of buildings such as hotels and motels, apartments, hospitals, nursing homes, and office buildings. In larger buildings, they may be combined with nearly any system selected for environmental control of the building core. This chapter discusses design and application of both types of systems. ROOM AIR CONDITIONERS Sizes and Classifications Design Performance Data Special Features Safety Codes and Standards Installation and Service PACKAGED TERMINAL AIR CONDITIONERS Sizes and Classifications General Design Considerations Design of PTAC/PTHP Components Heat Pump Operation Performance and Safety Testing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2823, 'S47 -- Heat Exchangers (SI)', 'ASHRAE', '', '', '2024', '', '0', 6, '2407160916106', '', '', 'Room air conditioners are encased assemblies designed primarily for mounting in a window or through a wall. They are designed to deliver cool or warm conditioned air to the room, either without ducts or with very short ducts (up to a maximum of about 48 in. [1220 mm]). Each unit includes a prime source of refrigeration and dehumidification and a means for circulating and filtering air; it may also include a means for ventilating and/or exhausting and heating. PTACs are designed primarily for commercial installations to provide the total heating and cooling functions for a room or zone and are specifically for through-the-wall installation. The units are mostly used in relatively small zones on the perimeter of buildings such as hotels and motels, apartments, hospitals, nursing homes, and office buildings. In larger buildings, they may be combined with nearly any system selected for environmental control of the building core. This chapter discusses design and application of both types of systems. ROOM AIR CONDITIONERS Sizes and Classifications Design Performance Data Special Features Safety Codes and Standards Installation and Service PACKAGED TERMINAL AIR CONDITIONERS Sizes and Classifications General Design Considerations Design of PTAC/PTHP Components Heat Pump Operation Performance and Safety Testing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2824, 'S47 -- Heat Exchangers (I-P)', 'ASHRAE', '', '', '2024', '', '0', 6, '2407160916107', '', '', 'Unitary air conditioners are factory-made assemblies that normally include an evaporator or cooling coil and a compressor/condenser combination, and possibly provide heating as well. An air-source unitary heat pump normally includes an indoor conditioning coil, compressor(s), and an outdoor coil. It must provide heating and possibly cooling as well. A water-source heat pump rejects or extracts heat to and from a water loop instead of from ambient air. A unitary air conditioner or heat pump with more than one factory-made assembly (e.g., indoor and outdoor units) is commonly called a split system. General Design Considerations Types of Unitary Equipment Equipment and System Standards Air Conditioners Air-Source Heat Pumps Water-Source Heat Pumps Variable-Refrigerant-Flow Heat Pumps', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2825, 'S46 -- Valves (SI)', 'ASHRAE', '', '', '2024', '', '0', 15, '2407160916108', '', '', 'Unitary air conditioners are factory-made assemblies that normally include an evaporator or cooling coil and a compressor/condenser combination, and possibly provide heating as well. An air-source unitary heat pump normally includes an indoor conditioning coil, compressor(s), and an outdoor coil. It must provide heating and possibly cooling as well. A water-source heat pump rejects or extracts heat to and from a water loop instead of from ambient air. A unitary air conditioner or heat pump with more than one factory-made assembly (e.g., indoor and outdoor units) is commonly called a split system. General Design Considerations Types of Unitary Equipment Equipment and System Standards Air Conditioners Air-Source Heat Pumps Water-Source Heat Pumps Variable-Refrigerant-Flow Heat Pumps', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2826, 'S46 -- Valves (I-P)', 'ASHRAE', '', '', '2024', '', '0', 15, '2407160916109', '', '', 'This chapter describes some of the fundamentals, types, components, applications, selection criteria, and installation of heat exchangers. Chapter 4 of the 2021 ASHRAE Handbook -- Fundamentals covers the subject of heat transfer. Specific applications of heat exchangers are detailed in other chapters of this and other volumes of the Handbook series. Fundamentals Types of Heat Exchangers Components Application Selection Criteria Installation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2827, 'S45 -- Motors, Motor Controls, and Variable-Frequency Drives (SI)', 'ASHRAE', '', '', '2024', '', '0', 21, '2407160916110', '', '', 'This chapter describes some of the fundamentals, types, components, applications, selection criteria, and installation of heat exchangers. Chapter 4 of the 2021 ASHRAE Handbook -- Fundamentals covers the subject of heat transfer. Specific applications of heat exchangers are detailed in other chapters of this and other volumes of the Handbook series. Fundamentals Types of Heat Exchangers Components Application Selection Criteria Installation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2828, 'S45 -- Motors, Motor Controls, and Variable-Frequency Drives (I-P)', 'ASHRAE', '', '', '2024', '', '0', 21, '2407160916111', '', '', 'Valves are the manual or automatic fluid-controlling elements in a piping system. They are constructed to withstand a specific range of temperature, pressure, corrosion, and mechanical stress. The designer selects and specifies the proper valve for the application to give the best service for the economic requirements. Fundamentals Manual Valves Balancing Valves Control Valves Multiple-Purpose Valves Safety Devices Self-Contained Temperature Control Valves Pressure-Reducing Valves Check Valves Stop-Check Valves Backflow Prevention Devices Steam Traps', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2829, 'S44 -- Centrifugal Pumps (SI)', 'ASHRAE', '', '', '2024', '', '0', 18, '2407160916112', '', '', 'Valves are the manual or automatic fluid-controlling elements in a piping system. They are constructed to withstand a specific range of temperature, pressure, corrosion, and mechanical stress. The designer selects and specifies the proper valve for the application to give the best service for the economic requirements. Fundamentals Manual Valves Balancing Valves Control Valves Multiple-Purpose Valves Safety Devices Self-Contained Temperature Control Valves Pressure-Reducing Valves Check Valves Stop-Check Valves Backflow Prevention Devices Steam Traps', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2830, 'S44 -- Centrifugal Pumps (I-P)', 'ASHRAE', '', '', '2024', '', '0', 18, '2407160916113', '', '', 'Many types of alternating-current (AC) motors are available; direct-current (DC) motors are also used, but to a more limited degree. National Electrical Manufacturers Association (NEMA) Standard MG 1 provides technical information on most types of AC and DC motors. MOTORS Alternating-Current Power Supply Codes and Standards Motor Efficiency General-Purpose Motors Permanent-Magnet AC Motors Hermetic Motors Integral Thermal Protection Motor Protection and Control AIR VOLUME CONTROL Variable-Frequency Drives Power Distribution System Effects Performance Testing and Rating Standards', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2831, 'S43 -- Liquid-Chilling Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916114', '', '', 'Many types of alternating-current (AC) motors are available; direct-current (DC) motors are also used, but to a more limited degree. National Electrical Manufacturers Association (NEMA) Standard MG 1 provides technical information on most types of AC and DC motors. MOTORS Alternating-Current Power Supply Codes and Standards Motor Efficiency General-Purpose Motors Permanent-Magnet AC Motors Hermetic Motors Integral Thermal Protection Motor Protection and Control AIR VOLUME CONTROL Variable-Frequency Drives Power Distribution System Effects Performance Testing and Rating Standards', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0);
INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(2832, 'S43 -- Liquid-Chilling Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916115', '', '', 'Centrifugal pumps provide the primary force to distribute and recirculate hot and chilled water in a variety of space-conditioning and plumbing systems. The pump provides a predetermined flow of water to the space load terminal units or to a thermal storage chamber for release at peak loads. The effect of centrifugal pump performance on the application, control, and operation of various terminal units is discussed in Chapter 13 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Other hydronic systems that use pumps include (1) condensing water circuits to cooling towers (Chapters 14 and 40 in that volume), (2) water-source heat pumps (Chapter 9 in that volume), (3) boiler feeds, and (4) condensate returns (Chapter 11 in that volume). Boiler feed and condensate return pumps for steam boilers should be selected based on boiler manufacturer’s requirements. Centrifugal pumps can also be found in water treatment and service water-heating systems. Centrifugal Pumping Construction Features Pump Types Pump Performance Curves Hydronic System Curves Pump and Hydronic System Curves Pump Power Pump Efficiency Affinity Laws Radial Thrust Net Positive Suction Characteristics Selection of Pumps Arrangement of Pumps Motive Power Energy Conservation in Pumping Installation, Operation, and Commissioning Troubleshooting', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2833, 'S42 -- Liquid Coolers (SI)', 'ASHRAE', '', '', '2024', '', '0', 6, '2407160916116', '', '', 'Centrifugal pumps provide the primary force to distribute and recirculate hot and chilled water in a variety of space-conditioning and plumbing systems. The pump provides a predetermined flow of water to the space load terminal units or to a thermal storage chamber for release at peak loads. The effect of centrifugal pump performance on the application, control, and operation of various terminal units is discussed in Chapter 13 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Other hydronic systems that use pumps include (1) condensing water circuits to cooling towers (Chapters 14 and 40 in that volume), (2) water-source heat pumps (Chapter 9 in that volume), (3) boiler feeds, and (4) condensate returns (Chapter 11 in that volume). Boiler feed and condensate return pumps for steam boilers should be selected based on boiler manufacturer’s requirements. Centrifugal pumps can also be found in water treatment and service water-heating systems. Centrifugal Pumping Construction Features Pump Types Pump Performance Curves Hydronic System Curves Pump and Hydronic System Curves Pump Power Pump Efficiency Affinity Laws Radial Thrust Net Positive Suction Characteristics Selection of Pumps Arrangement of Pumps Motive Power Energy Conservation in Pumping Installation, Operation, and Commissioning Troubleshooting', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2834, 'S42 -- Liquid Coolers (I-P)', 'ASHRAE', '', '', '2024', '', '0', 6, '2407160916117', '', '', 'Liquid-chilling systems cool water, brine, or other secondary coolant for air conditioning or refrigeration. The chiller maybe either factory-assembled and wired or shipped in sections for erection in the field. The most frequent application is water chilling for air conditioning, although brine cooling for low-temperature refrigeration and chilling fluids in industrial processes are also common. For information on absorption equipment, see Chapter 18 of the 2022 ASHRAE Handbook -- Refrigeration. GENERAL CHARACTERISTICS Principles of Operation Common Liquid-Chilling Systems Selection Control Standards and Testing General Maintenance SCROLL AND RECIPROCATING LIQUID CHILLERS Equipment Performance Characteristics and Operating Problems Method of Selection Control Considerations Special Applications CENTRIFUGAL LIQUID CHILLERS Equipment Performance and Operating Characteristics Selection Control Considerations Auxiliaries Special Applications Operation and Maintenance SCREW LIQUID CHILLERS Equipment Performance and Operating Characteristics Selection Control Considerations Auxiliaries Special Applications Maintenance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2835, 'S41 -- Evaporative Air-Cooling Equipment (SI)', 'ASHRAE', '', '', '2024', '', '0', 14, '2407160916118', '', '', 'Liquid-chilling systems cool water, brine, or other secondary coolant for air conditioning or refrigeration. The chiller maybe either factory-assembled and wired or shipped in sections for erection in the field. The most frequent application is water chilling for air conditioning, although brine cooling for low-temperature refrigeration and chilling fluids in industrial processes are also common. For information on absorption equipment, see Chapter 18 of the 2022 ASHRAE Handbook -- Refrigeration. GENERAL CHARACTERISTICS Principles of Operation Common Liquid-Chilling Systems Selection Control Standards and Testing General Maintenance SCROLL AND RECIPROCATING LIQUID CHILLERS Equipment Performance Characteristics and Operating Problems Method of Selection Control Considerations Special Applications CENTRIFUGAL LIQUID CHILLERS Equipment Performance and Operating Characteristics Selection Control Considerations Auxiliaries Special Applications Operation and Maintenance SCREW LIQUID CHILLERS Equipment Performance and Operating Characteristics Selection Control Considerations Auxiliaries Special Applications Maintenance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2836, 'S41 -- Evaporative Air-Cooling Equipment (I-P)', 'ASHRAE', '', '', '2024', '', '0', 14, '2407160916119', '', '', 'A liquid cooler (hereafter called a cooler) is a heat exchanger in which refrigerant is evaporated, thereby cooling a fluid (usually water or brine) circulating through the cooler. This chapter addresses the performance, design, and application of coolers. Types of Liquid Coolers Heat Transfer Pressure Drop Vessel Design Application Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2837, 'S40 -- Cooling Towers (SI)', 'ASHRAE', '', '', '2024', '', '0', 26, '2407160916120', '', '', 'A liquid cooler (hereafter called a cooler) is a heat exchanger in which refrigerant is evaporated, thereby cooling a fluid (usually water or brine) circulating through the cooler. This chapter addresses the performance, design, and application of coolers. Types of Liquid Coolers Heat Transfer Pressure Drop Vessel Design Application Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2838, 'S40 -- Cooling Towers (I-P)', 'ASHRAE', '', '', '2024', '', '0', 26, '2407160916121', '', '', 'This chapter addresses direct and indirect evaporative equipment, air washers, and their associated equipment used for air cooling, humidification, dehumidification, and air cleaning. Humidification equipment for residential and industrial applications is covered in Chapter 22 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Direct Evaporative Air Coolers Indirect Evaporative Air Coolers Indirect/Direct Combinations Air Washers Humidification/Dehumidification Sound Attenuation Maintenance and Water Treatment VAV Adiabatic Humidification with Heat Recovery Economizer Cold-Climate Adiabatic Humidification', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2839, 'S39 -- Condensers (SI)', 'ASHRAE', '', '', '2024', '', '0', 20, '2407160916122', '', '', 'This chapter addresses direct and indirect evaporative equipment, air washers, and their associated equipment used for air cooling, humidification, dehumidification, and air cleaning. Humidification equipment for residential and industrial applications is covered in Chapter 22 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Direct Evaporative Air Coolers Indirect Evaporative Air Coolers Indirect/Direct Combinations Air Washers Humidification/Dehumidification Sound Attenuation Maintenance and Water Treatment VAV Adiabatic Humidification with Heat Recovery Economizer Cold-Climate Adiabatic Humidification', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2840, 'S39 -- Condensers (I-P)', 'ASHRAE', '', '', '2024', '', '0', 21, '2407160916123', '', '', 'Most air-conditioning systems and industrial processes generate heat that must be removed and dissipated. Water is commonly used as a heat transfer medium to remove heat from refrigerant condensers or industrial process heat exchangers. In the past, this was accomplished by drawing a continuous stream of water from a utility water supply or a natural body of water, heating it as it passed through the process, and then discharging the water directly to a sewer or returning it to the body of water. Water purchased from utilities for this purpose has become prohibitively expensive because of increased water supply and disposal costs. Similarly, cooling water drawn from natural sources is relatively unavailable because the ecological disturbance caused by the increased temperature of discharge water has become unacceptable. Principle of Operation Design Conditions Types of Cooling Towers Materials of Construction Selection Considerations Application Performance Curves Cooling Tower Thermal Performance Cooling Tower Theory Tower Coefficients Additional Information', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2841, 'S38 -- Compressors (SI)', 'ASHRAE', '', '', '2024', '', '0', 44, '2407160916124', '', '', 'Most air-conditioning systems and industrial processes generate heat that must be removed and dissipated. Water is commonly used as a heat transfer medium to remove heat from refrigerant condensers or industrial process heat exchangers. In the past, this was accomplished by drawing a continuous stream of water from a utility water supply or a natural body of water, heating it as it passed through the process, and then discharging the water directly to a sewer or returning it to the body of water. Water purchased from utilities for this purpose has become prohibitively expensive because of increased water supply and disposal costs. Similarly, cooling water drawn from natural sources is relatively unavailable because the ecological disturbance caused by the increased temperature of discharge water has become unacceptable. Principle of Operation Design Conditions Types of Cooling Towers Materials of Construction Selection Considerations Application Performance Curves Cooling Tower Thermal Performance Cooling Tower Theory Tower Coefficients Additional Information', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2842, 'S38 -- Compressors (I-P)', 'ASHRAE', '', '', '2024', '', '0', 44, '2407160916125', '', '', 'The condenser in a refrigeration system is a heat exchanger that rejects all the heat from the system. This heat consists of heat absorbed by the evaporator plus the heat from the energy input to the compressor. The compressor discharges hot, high-pressure refrigerant gas into the condenser, which rejects heat from the gas to some cooler medium. Thus, the cool refrigerant condenses back to the liquid state and drains from the condenser to continue in the refrigeration cycle. Condensers may be classified by their cooling medium as (l) water-cooled, (2) air-cooled, (3) evaporative (air- and water-cooled), and (4) refrigerant-cooled (cascade systems). The first three types are discussed in this chapter; see Chapter 48 in the 2022 ASHRAE Handbook -- Refrigeration for a discussion of cascade-cooled condensers. WATER-COOLED CONDENSERS Heat Removal Heat Transfer Water Pressure Drop Liquid Subcooling Water Circuiting Types Noncondensable Gases Testing and Rating Operation and Maintenance AIR-COOLED CONDENSERS Types Fans and Air Requirements Heat Transfer and Pressure Drop Condensers Remote from Compressor Condensers as Part of Condensing Unit Water-Cooled Versus Air-Cooled Condensing Testing and Rating Control Installation and Maintenance EVAPORATIVE CONDENSERS Heat Transfer Condenser Configuration Condenser Location Multiple-Condenser Installations Ratings Desuperheating Coils Refrigerant Liquid Subcoolers Multicircuit Condensers and Coolers Water Treatment Water Consumption Capacity Modulation Purging Maintenance Testing and Rating', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2843, 'S37 -- Solar Energy Equipment and Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 25, '2407160916126', '', '', 'The condenser in a refrigeration system is a heat exchanger that rejects all the heat from the system. This heat consists of heat absorbed by the evaporator plus the heat from the energy input to the compressor. The compressor discharges hot, high-pressure refrigerant gas into the condenser, which rejects heat from the gas to some cooler medium. Thus, the cool refrigerant condenses back to the liquid state and drains from the condenser to continue in the refrigeration cycle. Condensers may be classified by their cooling medium as (l) water-cooled, (2) air-cooled, (3) evaporative (air- and water-cooled), and (4) refrigerant-cooled (cascade systems). The first three types are discussed in this chapter; see Chapter 48 in the 2022 ASHRAE Handbook -- Refrigeration for a discussion of cascade-cooled condensers. WATER-COOLED CONDENSERS Heat Removal Heat Transfer Water Pressure Drop Liquid Subcooling Water Circuiting Types Noncondensable Gases Testing and Rating Operation and Maintenance AIR-COOLED CONDENSERS Types Fans and Air Requirements Heat Transfer and Pressure Drop Condensers Remote from Compressor Condensers as Part of Condensing Unit Water-Cooled Versus Air-Cooled Condensing Testing and Rating Control Installation and Maintenance EVAPORATIVE CONDENSERS Heat Transfer Condenser Configuration Condenser Location Multiple-Condenser Installations Ratings Desuperheating Coils Refrigerant Liquid Subcoolers Multicircuit Condensers and Coolers Water Treatment Water Consumption Capacity Modulation Purging Maintenance Testing and Rating', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2844, 'S37 -- Solar Energy Equipment and Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 25, '2407160916127', '', '', 'A compressor is one of the four essential components of the basic vapor compression refrigeration system; the others are the condenser, evaporator, and expansion device. The compressor circulates refrigerant through the system and increases refrigerant vapor pressure to create the pressure differential between the condenser and evaporator. This chapter describes the design features of several categories of commercially available refrigerant compressors. POSITIVE-DISPLACEMENT COMPRESSORS Performance Abnormal Operating Conditions, Hazards, and Protective Devices Motors RECIPROCATING COMPRESSORS ROTARY COMPRESSORS Rolling-Piston Compressors Rotary-Vane Compressors Screw Compressors Scroll Compressors Trochoidal Compressors CENTRIFUGAL COMPRESSORS Application Mechanical Design Isentropic Analysis Polytropic Analysis Operation and Maintenance Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2845, 'S36 -- Hydronic Heat-Distributing Units and Radiators (SI)', 'ASHRAE', '', '', '2024', '', '0', 6, '2407160916128', '', '', 'A compressor is one of the four essential components of the basic vapor compression refrigeration system; the others are the condenser, evaporator, and expansion device. The compressor circulates refrigerant through the system and increases refrigerant vapor pressure to create the pressure differential between the condenser and evaporator. This chapter describes the design features of several categories of commercially available refrigerant compressors. POSITIVE-DISPLACEMENT COMPRESSORS Performance Abnormal Operating Conditions, Hazards, and Protective Devices Motors RECIPROCATING COMPRESSORS ROTARY COMPRESSORS Rolling-Piston Compressors Rotary-Vane Compressors Screw Compressors Scroll Compressors Trochoidal Compressors CENTRIFUGAL COMPRESSORS Application Mechanical Design Isentropic Analysis Polytropic Analysis Operation and Maintenance Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2846, 'S36 -- Hydronic Heat-Distributing Units and Radiators (I-P)', 'ASHRAE', '', '', '2024', '', '0', 6, '2407160916129', '', '', 'Solar energy use is becoming more economical, primarily due to technological maturity, economies of scale, and governmental policies with immediate interest in low-carbon and sustainable construction. In addition, many countries consider solar and renewable energy a security measure, to ensure the availability of power under adverse conditions. While the United States continues to grow its solar industry, China, Europe, Asia, and the Mediterranean basin are leading development of advanced manufacturing techniques and applications. However, equipment and systems are still very similar in all markets; therefore, this chapter primarily discusses the basic equipment used, with particular attention to collectors. More detailed descriptions of systems and designs can be found in Chapter 36 of the 2023 ASHRAE Handbook -- HVAC Applications. SOLAR HEATING SYSTEMS Air-Heating Systems Liquid-Heating Systems Solar Thermal Energy Collectors Row Design Array Design Thermal Collector Performance Thermal Energy Storage Heat Exchangers Controls PHOTOVOLTAIC SYSTEMS', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2847, 'S35 -- Chimney, Vent, and Fireplace Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 34, '2407160916130', '', '', 'Solar energy use is becoming more economical, primarily due to technological maturity, economies of scale, and governmental policies with immediate interest in low-carbon and sustainable construction. In addition, many countries consider solar and renewable energy a security measure, to ensure the availability of power under adverse conditions. While the United States continues to grow its solar industry, China, Europe, Asia, and the Mediterranean basin are leading development of advanced manufacturing techniques and applications. However, equipment and systems are still very similar in all markets; therefore, this chapter primarily discusses the basic equipment used, with particular attention to collectors. More detailed descriptions of systems and designs can be found in Chapter 36 of the 2023 ASHRAE Handbook -- HVAC Applications. SOLAR HEATING SYSTEMS Air-Heating Systems Liquid-Heating Systems Solar Thermal Energy Collectors Row Design Array Design Thermal Collector Performance Thermal Energy Storage Heat Exchangers Controls PHOTOVOLTAIC SYSTEMS', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2848, 'S35 -- Chimney, Vent, and Fireplace Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 36, '2407160916131', '', '', 'Radiators, convectors, and baseboard and finned-tube units are heat-distributing devices used in hot-water and steam heating systems. They supply heat by a combination of radiation and convection and maintain the desired air temperature and/or mean radiant temperature in a space without fans. In heating systems, radiant panels are also used. Units are inherently self-adjusting in the sense that heat output is based on temperature differentials; cold spaces receive more heat and warmer spaces receive less heat. Description Ratings of Heat-Distributing Units Design Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2849, 'S34 -- Residential In-Space Heating Equipment (SI)', 'ASHRAE', '', '', '2024', '', '0', 7, '2407160916132', '', '', 'Radiators, convectors, and baseboard and finned-tube units are heat-distributing devices used in hot-water and steam heating systems. They supply heat by a combination of radiation and convection and maintain the desired air temperature and/or mean radiant temperature in a space without fans. In heating systems, radiant panels are also used. Units are inherently self-adjusting in the sense that heat output is based on temperature differentials; cold spaces receive more heat and warmer spaces receive less heat. Description Ratings of Heat-Distributing Units Design Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2850, 'S34 -- Residential In-Space Heating Equipment (I-P)', 'ASHRAE', '', '', '2024', '', '0', 7, '2407160916133', '', '', 'A properly designed chimney or vent system provides and controls draft to convey flue gas from an appliance to the outdoors. This chapter describes the design of chimneys and vent systems that discharge flue gas from appliances and fireplace systems. Terminology Draft Operating Principles Chimney Functions Steady-State Chimney Design Equations Steady-State Chimney Design Graphical Solutions Vent and Chimney Capacity Calculation Examples Gas Appliance Venting Oil-Fired Appliance Venting Fireplace Chimneys Air Supply to Fuel-Burning Appliances Vent and Chimney Materials Vent and Chimney Accessories Draft Fans Terminations: Caps and Wind Effects Codes and Standards Conversion Factors Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2851, 'S33 -- Furnaces (SI)', 'ASHRAE', '', '', '2024', '', '0', 10, '2407160916134', '', '', 'A properly designed chimney or vent system provides and controls draft to convey flue gas from an appliance to the outdoors. This chapter describes the design of chimneys and vent systems that discharge flue gas from appliances and fireplace systems. Terminology Draft Operating Principles Chimney Functions Steady-State Chimney Design Equations Steady-State Chimney Design Graphical Solutions Vent and Chimney Capacity Calculation Examples Gas Appliance Venting Oil-Fired Appliance Venting Fireplace Chimneys Air Supply to Fuel-Burning Appliances Vent and Chimney Materials Vent and Chimney Accessories Draft Fans Terminations: Caps and Wind Effects Codes and Standards Conversion Factors Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2852, 'S33 -- Furnaces (I-P)', 'ASHRAE', '', '', '2024', '', '0', 10, '2407160916135', '', '', 'In-space heating equipment differs from central heating in that fuel is converted to heat in the space to be heated. In-space heaters may be either permanently installed or portable and may transfer heat by a combination of radiation, natural convection, and forced convection. The energy source may be liquid, solid, gaseous, or electric. GAS IN-SPACE HEATERS Controls Vent Connectors Sizing Units OIL AND KEROSENE IN-SPACE HEATERS ELECTRIC IN-SPACE HEATERS Radiant Heating Systems SOLID-FUEL IN-SPACE HEATERS Fireplaces Stoves GENERAL INSTALLATION PRACTICES', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2853, 'S32 -- Boilers (SI)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916136', '', '', 'In-space heating equipment differs from central heating in that fuel is converted to heat in the space to be heated. In-space heaters may be either permanently installed or portable and may transfer heat by a combination of radiation, natural convection, and forced convection. The energy source may be liquid, solid, gaseous, or electric. GAS IN-SPACE HEATERS Controls Vent Connectors Sizing Units OIL AND KEROSENE IN-SPACE HEATERS ELECTRIC IN-SPACE HEATERS Radiant Heating Systems SOLID-FUEL IN-SPACE HEATERS Fireplaces Stoves GENERAL INSTALLATION PRACTICES', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2854, 'S32 -- Boilers (I-P)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916137', '', '', 'Furnaces are self-enclosed, permanently installed major appliances that provide heated air through ductwork to the space being heated. In addition, a furnace may provide the indoor fan necessary for circulating heated or cooled air from a split or single-package air conditioner or heat pump (see Chapter 10 of the ASHRAE Handbook -- HVAC Systems and Equipment). Components Heat Source Types Commercial Equipment Controls and Operating Characteristics Equipment Selection Calculations Technical Data Installation Agency Listings', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2855, 'S31 -- Automatic Fuel-Burning Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 23, '2407160916138', '', '', 'Furnaces are self-enclosed, permanently installed major appliances that provide heated air through ductwork to the space being heated. In addition, a furnace may provide the indoor fan necessary for circulating heated or cooled air from a split or single-package air conditioner or heat pump (see Chapter 10 of the ASHRAE Handbook -- HVAC Systems and Equipment). Components Heat Source Types Commercial Equipment Controls and Operating Characteristics Equipment Selection Calculations Technical Data Installation Agency Listings', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2856, 'S31 -- Automatic Fuel-Burning Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 23, '2407160916139', '', '', 'Excluding special and unusual fluids, materials, and methods, a boiler is a cast-iron, carbon or stainless steel, aluminum, or copper pressure vessel heat exchanger designed to (1) burn fossil fuels (or use electric current) and (2) transfer the released heat to water (in water boilers) or to water and steam (in steam boilers). Boiler heating surface is the area of fluid-backed surface exposed to the products of combustion, or the fire-side surface. Various manufacturers define allowable heat transfer rates in terms of heating surface based on their specific boiler design and material limitations. Boiler designs provide for connections to a piping system, which delivers heated fluid to the point of use and returns the cooled fluid to the boiler. In the 2024 ASHRAE Handbook -- HVAC Systems and Equipment, Chapters 6, 11, 12, 13, and 15 cover applications of heating boilers, and Chapter 7 discusses cogeneration, which may require boilers. Classifications Selection Parameters Efficiency: Input and Output Ratings Performance Codes and Standards Sizing Burner Types Boiler Controls Flame Safeguard Controls', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2857, 'S30 -- Air Pollution Control and Industrial Process Cleaning (SI)', 'ASHRAE', '', '', '2024', '', '0', 31, '2407160916140', '', '', 'Excluding special and unusual fluids, materials, and methods, a boiler is a cast-iron, carbon or stainless steel, aluminum, or copper pressure vessel heat exchanger designed to (1) burn fossil fuels (or use electric current) and (2) transfer the released heat to water (in water boilers) or to water and steam (in steam boilers). Boiler heating surface is the area of fluid-backed surface exposed to the products of combustion, or the fire-side surface. Various manufacturers define allowable heat transfer rates in terms of heating surface based on their specific boiler design and material limitations. Boiler designs provide for connections to a piping system, which delivers heated fluid to the point of use and returns the cooled fluid to the boiler. In the 2024 ASHRAE Handbook -- HVAC Systems and Equipment, Chapters 6, 11, 12, 13, and 15 cover applications of heating boilers, and Chapter 7 discusses cogeneration, which may require boilers. Classifications Selection Parameters Efficiency: Input and Output Ratings Performance Codes and Standards Sizing Burner Types Boiler Controls Flame Safeguard Controls', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2858, 'S30 -- Air Pollution Control and Industrial Process Cleaning (I-P)', 'ASHRAE', '', '', '2024', '', '0', 31, '2407160916141', '', '', 'Fuel-burning systems provide a means to mix fuel and air in the proper ratio, ignite it, control the position of the flame envelope within the combustion chamber, and control a fuel flow rate for safe combustion-heat energy release for space conditioning, water heating, and other processes. This chapter covers the design and use of automatic fuel-burning systems. The fuel can be gaseous (e.g., natural or liquefied petroleum gas), liquid (primarily the lighter grades of fuel oil or biodiesel), or solid (e.g., coal, or renewable items such as wood or corn). For discussion of some of these fuels, their combustion chemistry, and thermodynamics, see Chapter 28 of the 2021 ASHRAE Handbook -- Fundamentals. GENERAL CONSIDERATIONS Terminology System Application Safety Efficiency and Emission Ratings GAS-BURNING APPLIANCES Gas-Fired Combustion Systems Residential Appliances Commercial-Industrial Appliances Applications OIL-BURNING APPLIANCES Residential Oil Burners Commercial/Industrial Oil Burners Dual-Fuel Gas/Oil Burners Equipment Selection SOLID-FUEL-BURNING APPLIANCES Capacity Classification of Stokers Stoker Types by Fuel-Feed Methods CONTROLS Safety Controls and Interlocks Operating Controls', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2859, 'S29 -- Air Cleaners for Particulate Contaminants (SI)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916142', '', '', 'Fuel-burning systems provide a means to mix fuel and air in the proper ratio, ignite it, control the position of the flame envelope within the combustion chamber, and control a fuel flow rate for safe combustion-heat energy release for space conditioning, water heating, and other processes. This chapter covers the design and use of automatic fuel-burning systems. The fuel can be gaseous (e.g., natural or liquefied petroleum gas), liquid (primarily the lighter grades of fuel oil or biodiesel), or solid (e.g., coal, or renewable items such as wood or corn). For discussion of some of these fuels, their combustion chemistry, and thermodynamics, see Chapter 28 of the 2021 ASHRAE Handbook -- Fundamentals. GENERAL CONSIDERATIONS Terminology System Application Safety Efficiency and Emission Ratings GAS-BURNING APPLIANCES Gas-Fired Combustion Systems Residential Appliances Commercial-Industrial Appliances Applications OIL-BURNING APPLIANCES Residential Oil Burners Commercial/Industrial Oil Burners Dual-Fuel Gas/Oil Burners Equipment Selection SOLID-FUEL-BURNING APPLIANCES Capacity Classification of Stokers Stoker Types by Fuel-Feed Methods CONTROLS Safety Controls and Interlocks Operating Controls', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2860, 'S29 -- Air Cleaners for Particulate Contaminants (I-P)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916143', '', '', 'Equipment that removes particulate matter from a gas stream may also remove or create some gaseous contaminants; on the other hand, equipment that is primarily intended for removal of gaseous pollutants might also remove or create objectionable particulate matter to some degree. In all cases, gas-cleaning equipment changes the process stream, and it is therefore essential that the engineer evaluate the consequences of those changes to the plant’s overall operation. In this chapter, each generic type of equipment is discussed on the basis of its primary method for gas or particulate abatement. The development of systems that incorporate several of the devices discussed here for specific industrial processes is left to the engineer. Regulations and Standards PARTICULATE CONTAMINANT CONTROL Mechanical Collectors Centrifugal Collectors Electrostatic Precipitators Fabric Filters Mist Collectors Particulate Scrubbers (Wet Collectors) GASEOUS CONTAMINANT CONTROL Spray Dry Scrubbing Wet-Packed Scrubbers Adsorption of Gaseous Contaminants Incineration of Gases and Vapors AUXILIARY EQUIPMENT Ducts Dust- and Slurry-Handling Equipment OPERATION AND MAINTENANCE', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2861, 'S28 -- Unit Ventilators, Unit Heaters, and Makeup Air Units (SI)', 'ASHRAE', '', '', '2024', '', '0', 10, '2407160916144', '', '', 'Equipment that removes particulate matter from a gas stream may also remove or create some gaseous contaminants; on the other hand, equipment that is primarily intended for removal of gaseous pollutants might also remove or create objectionable particulate matter to some degree. In all cases, gas-cleaning equipment changes the process stream, and it is therefore essential that the engineer evaluate the consequences of those changes to the plant’s overall operation. In this chapter, each generic type of equipment is discussed on the basis of its primary method for gas or particulate abatement. The development of systems that incorporate several of the devices discussed here for specific industrial processes is left to the engineer. Regulations and Standards PARTICULATE CONTAMINANT CONTROL Mechanical Collectors Centrifugal Collectors Electrostatic Precipitators Fabric Filters Mist Collectors Particulate Scrubbers (Wet Collectors) GASEOUS CONTAMINANT CONTROL Spray Dry Scrubbing Wet-Packed Scrubbers Adsorption of Gaseous Contaminants Incineration of Gases and Vapors AUXILIARY EQUIPMENT Ducts Dust- and Slurry-Handling Equipment OPERATION AND MAINTENANCE', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2862, 'S28 -- Unit Ventilators, Unit Heaters, and Makeup Air Units (I-P)', 'ASHRAE', '', '', '2024', '', '0', 10, '2407160916145', '', '', 'This chapter discusses removal of contaminants from both ventilation and recirculated air used for conditioning building interiors. The filters mentioned in this chapter are primarily used for HVAC systems and for the protection of equipment. Complete air cleaning may require removing of airborne particles, microorganisms, and gaseous contaminants, but this chapter only covers removal of airborne particles and briefly discusses bioaerosols. Chapter 47 of the 2023 ASHRAE Handbook -- HVAC Applications covers the removal of gaseous contaminants. Chapter 62 of the 2023 ASHRAE Handbook -- HVAC Applications covers bioaerosols and UV air cleaners in more depth. Terminology Atmospheric Aerosols Aerosol Characteristics Air-Cleaning Applications Mechanisms of Particle Collection Types of Air Cleaners and Performance Air Cleaner Test Methods Selection and Maintenance Air Cleaner Installation Safety Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2863, 'S27 -- Air-Heating Coils (SI)', 'ASHRAE', '', '', '2024', '', '0', 5, '2407160916146', '', '', 'This chapter discusses removal of contaminants from both ventilation and recirculated air used for conditioning building interiors. The filters mentioned in this chapter are primarily used for HVAC systems and for the protection of equipment. Complete air cleaning may require removing of airborne particles, microorganisms, and gaseous contaminants, but this chapter only covers removal of airborne particles and briefly discusses bioaerosols. Chapter 47 of the 2023 ASHRAE Handbook -- HVAC Applications covers the removal of gaseous contaminants. Chapter 62 of the 2023 ASHRAE Handbook -- HVAC Applications covers bioaerosols and UV air cleaners in more depth. Terminology Atmospheric Aerosols Aerosol Characteristics Air-Cleaning Applications Mechanisms of Particle Collection Types of Air Cleaners and Performance Air Cleaner Test Methods Selection and Maintenance Air Cleaner Installation Safety Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2864, 'S27 -- Air-Heating Coils (I-P)', 'ASHRAE', '', '', '2024', '', '0', 5, '2407160916147', '', '', 'This chapter discusses unit ventilators, unit heaters, and makeup air units and how they are deployed in HVAC systems. Unit Ventilators Unit Heaters Makeup Air Units', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2865, 'S26 -- Air-to-Air Energy Recovery Equipment (SI)', 'ASHRAE', '', '', '2024', '', '0', 39, '2407160916148', '', '', 'This chapter discusses unit ventilators, unit heaters, and makeup air units and how they are deployed in HVAC systems. Unit Ventilators Unit Heaters Makeup Air Units', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2866, 'S26 -- Air-to-Air Energy Recovery Equipment (I-P)', 'ASHRAE', '', '', '2024', '', '0', 39, '2407160916149', '', '', 'Air-heating coils are used to heat air under forced convection. The total coil surface may consist of a single coil section or several coil sections assembled into a bank. The coils described in this chapter apply primarily to comfort heating and air conditioning using steam, hot water, refrigerant vapor heat reclaim (including heat pumps), and electricity. The choice between the various methods of heating depends greatly on the cost of the various available energy sources. For instance, in areas where electric power is cheaply available and heating requirements are limited, heat pumps are a very viable option. With available power and higher heat requirements, electric heat is used. If electric power is considerably expensive, steam or hot water generated using gas-fired sources is used in larger buildings and district cooling. In smaller buildings, heat is supplied using gas furnaces, which are covered in Chapters 33 and 34 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Water and steam heating are also widely used where process waste heat is available. Coil Construction and Design Coil Selection Installation Guidelines Coil Maintenance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2867, 'S25 -- Mechanical Dehumidifiers and Related Components (SI)', 'ASHRAE', '', '', '2024', '', '0', 13, '2407160916150', '', '', 'Air-heating coils are used to heat air under forced convection. The total coil surface may consist of a single coil section or several coil sections assembled into a bank. The coils described in this chapter apply primarily to comfort heating and air conditioning using steam, hot water, refrigerant vapor heat reclaim (including heat pumps), and electricity. The choice between the various methods of heating depends greatly on the cost of the various available energy sources. For instance, in areas where electric power is cheaply available and heating requirements are limited, heat pumps are a very viable option. With available power and higher heat requirements, electric heat is used. If electric power is considerably expensive, steam or hot water generated using gas-fired sources is used in larger buildings and district cooling. In smaller buildings, heat is supplied using gas furnaces, which are covered in Chapters 33 and 34 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Water and steam heating are also widely used where process waste heat is available. Coil Construction and Design Coil Selection Installation Guidelines Coil Maintenance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2868, 'S25 -- Mechanical Dehumidifiers and Related Components (I-P)', 'ASHRAE', '', '', '2024', '', '0', 13, '2407160916151', '', '', 'Air-to-air energy recovery is the process of recovering heat or/and moisture between two airstreams at different temperatures and humidities. This process is important in maintaining acceptable indoor air quality (IAQ) while maintaining low energy costs and reducing overall energy consumption. This chapter describes various technologies for air-to-air energy recovery. Thermal and economic performance, maintenance, and related operational issues are presented, with emphasis on energy recovery for ventilation. Applications Basic Heat or Heat and Water Vapor Transfer Relations Types of Air-to-Air Heat Exchangers Performance Ratings Additional Technical Considerations Types and Applications of Air-to-Air Heat Exchangers Comparison of Air-to-Air Heat or Heat and Mass Exchanger Characteristics Use of Air-to-Air Heat or Heat and Mass Exchangers in Systems Economic Considerations Energy and/or Mass Recovery Calculation Procedure Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2869, 'S24 -- Desiccant Dehumidification and Pressure-Drying Equipment (SI)', 'ASHRAE', '', '', '2024', '', '0', 17, '2407160916152', '', '', 'Air-to-air energy recovery is the process of recovering heat or/and moisture between two airstreams at different temperatures and humidities. This process is important in maintaining acceptable indoor air quality (IAQ) while maintaining low energy costs and reducing overall energy consumption. This chapter describes various technologies for air-to-air energy recovery. Thermal and economic performance, maintenance, and related operational issues are presented, with emphasis on energy recovery for ventilation. Applications Basic Heat or Heat and Water Vapor Transfer Relations Types of Air-to-Air Heat Exchangers Performance Ratings Additional Technical Considerations Types and Applications of Air-to-Air Heat Exchangers Comparison of Air-to-Air Heat or Heat and Mass Exchanger Characteristics Use of Air-to-Air Heat or Heat and Mass Exchangers in Systems Economic Considerations Energy and/or Mass Recovery Calculation Procedure Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2870, 'S24 -- Desiccant Dehumidification and Pressure-Drying Equipment (I-P)', 'ASHRAE', '', '', '2024', '', '0', 17, '2407160916153', '', '', 'The correct moisture level in the air is important for health and comfort. Controlling humidity and condensation is important to prevent moisture damage and mold or mildew development, thus protecting buildings and occupants, and preserving building contents This chapter covers mechanical dehumidification using a cooling process only, including basic dehumidifier models (with moisture removal capacity of less than 3 lb/h [1.4 kg/h]) used for home basements and small storage areas, as well as larger sizes required for commercial applications. Requirements for testing and rating mechanical dehumidifiers’ energy efficiency are published in AHRI Standards 910 and 920. Mechanical Dehumidifiers Controls and Sensors Installation and Service Considerations Wraparound Heat Exchangers', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2871, 'S23 -- Air-Cooling and Dehumidifying Coils (SI)', 'ASHRAE', '', '', '2024', '', '0', 17, '2407160916154', '', '', 'The correct moisture level in the air is important for health and comfort. Controlling humidity and condensation is important to prevent moisture damage and mold or mildew development, thus protecting buildings and occupants, and preserving building contents This chapter covers mechanical dehumidification using a cooling process only, including basic dehumidifier models (with moisture removal capacity of less than 3 lb/h [1.4 kg/h]) used for home basements and small storage areas, as well as larger sizes required for commercial applications. Requirements for testing and rating mechanical dehumidifiers’ energy efficiency are published in AHRI Standards 910 and 920. Mechanical Dehumidifiers Controls and Sensors Installation and Service Considerations Wraparound Heat Exchangers', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2872, 'S23 -- Air-Cooling and Dehumidifying Coils (I-P)', 'ASHRAE', '', '', '2024', '', '0', 17, '2407160916155', '', '', 'This chapter covers (1) the types of dehumidification equipment for liquid and solid desiccants, including high-pressure equipment;(2) performance curves; (3) variables of operation; and (4) some typical applications. Using desiccants to dry refrigerants is addressed in Chapter 8 of the 2022 ASHRAE Handbook -- Refrigeration. Methods of Dehumidification Desiccant Dehumidification Liquid Desiccant Equipment Solid-Sorption Equipment Rotary Solid-Desiccant Dehumidifiers Equipment Ratings Equipment Operating Recommendations Applications for Atmospheric-Pressure Dehumidification Desiccant Drying at Elevated Pressure Equipment Types Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2873, 'S22 -- Humidifiers (SI)', 'ASHRAE', '', '', '2024', '', '0', 19, '2407160916156', '', '', 'This chapter covers (1) the types of dehumidification equipment for liquid and solid desiccants, including high-pressure equipment;(2) performance curves; (3) variables of operation; and (4) some typical applications. Using desiccants to dry refrigerants is addressed in Chapter 8 of the 2022 ASHRAE Handbook -- Refrigeration. Methods of Dehumidification Desiccant Dehumidification Liquid Desiccant Equipment Solid-Sorption Equipment Rotary Solid-Desiccant Dehumidifiers Equipment Ratings Equipment Operating Recommendations Applications for Atmospheric-Pressure Dehumidification Desiccant Drying at Elevated Pressure Equipment Types Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2874, 'S22 -- Humidifiers (I-P)', 'ASHRAE', '', '', '2024', '', '0', 19, '2407160916157', '', '', 'Most equipment used today for cooling and dehumidifying an airstream under forced convection incorporates a coil section that contains one or more cooling coils assembled in a coil bank arrangement. Such coil sections are used extensively as components in room terminal units; larger factory-assembled, self-contained air conditioners; central station air handlers; and field built-up systems. Applications of each coil type are limited to the field within which the coil is rated. Other limitations are imposed by code requirements, proper choice of materials for the fluids used, the configuration of the air handler, and economic analysis of the possible alternatives for each installation. This chapter discusses uses, selection, performance, and maintenance of these coils. Uses for Coils Coil Construction and Arrangement Coil Selection Airflow Resistance Heat Transfer Performance of Sensible Cooling Coils Performance of Dehumidifying Coils Determining Refrigeration Load. Maintenance Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2875, 'S21 -- Fans (SI)', 'ASHRAE', '', '', '2024', '', '0', 18, '2407160916158', '', '', 'Most equipment used today for cooling and dehumidifying an airstream under forced convection incorporates a coil section that contains one or more cooling coils assembled in a coil bank arrangement. Such coil sections are used extensively as components in room terminal units; larger factory-assembled, self-contained air conditioners; central station air handlers; and field built-up systems. Applications of each coil type are limited to the field within which the coil is rated. Other limitations are imposed by code requirements, proper choice of materials for the fluids used, the configuration of the air handler, and economic analysis of the possible alternatives for each installation. This chapter discusses uses, selection, performance, and maintenance of these coils. Uses for Coils Coil Construction and Arrangement Coil Selection Airflow Resistance Heat Transfer Performance of Sensible Cooling Coils Performance of Dehumidifying Coils Determining Refrigeration Load. Maintenance Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2876, 'S21 -- Fans (I-P)', 'ASHRAE', '', '', '2024', '', '0', 18, '2407160916159', '', '', 'In the selection and application of humidifiers, the designer considers (1) the environmental conditions of the occupancy or process and (2) the characteristics of the building enclosure. Because these may not always be compatible, compromise is sometimes necessary, particularly in the case of existing buildings. Environmental Conditions Enclosure Characteristics Energy and Water Considerations Equipment Controls Application Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2877, 'S20 -- Room Air Distribution Equipment (SI)', 'ASHRAE', '', '', '2024', '', '0', 18, '2407160916160', '', '', 'In the selection and application of humidifiers, the designer considers (1) the environmental conditions of the occupancy or process and (2) the characteristics of the building enclosure. Because these may not always be compatible, compromise is sometimes necessary, particularly in the case of existing buildings. Environmental Conditions Enclosure Characteristics Energy and Water Considerations Equipment Controls Application Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0);
INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(2878, 'S20 -- Room Air Distribution Equipment (I-P)', 'ASHRAE', '', '', '2024', '', '0', 18, '2407160916161', '', '', 'A fan uses a power-driven rotating impeller to move air. The impeller does work on the air, imparting to it both static and kinetic energy, which vary in proportion, depending on the fan type. This chapter discusses types of fans used in HVAC design and the underlying principles of their use. Types of Fans Principles of Operation Testing and Rating Field Testing of Fans for Air Performance Fan Laws Fan and System Pressure Relationships Air Temperature Rise Across Fans Duct System Characteristics System Effects Selection Parallel Fan Operation Series Fan Operation Noise Vibration Arrangement and Installation Fan Control Fan Inlet Cone Instrumented for Airflow Measurement Fan Terminology Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2879, 'S19 -- Duct Construction (SI)', 'ASHRAE', '', '', '2024', '', '0', 15, '2407160916162', '', '', 'A fan uses a power-driven rotating impeller to move air. The impeller does work on the air, imparting to it both static and kinetic energy, which vary in proportion, depending on the fan type. This chapter discusses types of fans used in HVAC design and the underlying principles of their use. Types of Fans Principles of Operation Testing and Rating Field Testing of Fans for Air Performance Fan Laws Fan and System Pressure Relationships Air Temperature Rise Across Fans Duct System Characteristics System Effects Selection Parallel Fan Operation Series Fan Operation Noise Vibration Arrangement and Installation Fan Control Fan Inlet Cone Instrumented for Airflow Measurement Fan Terminology Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2880, 'S19 -- Duct Construction (I-P)', 'ASHRAE', '', '', '2024', '', '0', 15, '2407160916163', '', '', 'Supply air outlets, terminal units, chilled beams, fan-coil units, and air curtain units introduce air into a conditioned space to obtain a desired indoor atmospheric environment. Return and exhaust air are removed from a space through return and exhaust inlets (inlet and outlet are defined relative to the duct system and not the room). This chapter describes this equipment, details its proper use, and is intended to help HVAC designers select room air distribution equipment applicable to the air distribution methods outlined in Chapter 58 of the 2023 ASHRAE Handbook -- HVAC Applications. SYSTEMS OVERVIEW SYSTEM CLASSIFICATIONS Fully Mixed Systems Fully Stratified Systems Partially Mixed Systems EQUIPMENT Supply Air Outlets Return and Exhaust Air Inlets Grilles Nozzles and Drum Louvers Diffusers Terminal Units Fan-Coil Units Chilled Beams Air Curtain Units', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2881, 'S18 -- Variable Refrigerant Flow (SI)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916164', '', '', 'Supply air outlets, terminal units, chilled beams, fan-coil units, and air curtain units introduce air into a conditioned space to obtain a desired indoor atmospheric environment. Return and exhaust air are removed from a space through return and exhaust inlets (inlet and outlet are defined relative to the duct system and not the room). This chapter describes this equipment, details its proper use, and is intended to help HVAC designers select room air distribution equipment applicable to the air distribution methods outlined in Chapter 58 of the 2023 ASHRAE Handbook -- HVAC Applications. SYSTEMS OVERVIEW SYSTEM CLASSIFICATIONS Fully Mixed Systems Fully Stratified Systems Partially Mixed Systems EQUIPMENT Supply Air Outlets Return and Exhaust Air Inlets Grilles Nozzles and Drum Louvers Diffusers Terminal Units Fan-Coil Units Chilled Beams Air Curtain Units', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2882, 'S18 -- Variable Refrigerant Flow (I-P)', 'ASHRAE', '', '', '2024', '', '0', 15, '2407160916165', '', '', 'This chapter covers construction of HVAC and exhaust duct systems for residential, commercial, and industrial applications. Building Code Requirements Pressure Classifications Duct Cleaning HVAC System Leakage Air-Handling Unit Leakage Residential and Commercial Duct Construction Industrial Duct Construction Antimicrobial-Treated Ducts Duct Construction for Grease- and Moisture-Laden Vapors Rigid Plastic Ducts Air Dispersion Systems Underground Ducts Ducts Outside Buildings Seismic Qualification Sheet Metal Welding Thermal Insulation Specifications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2883, 'S17 -- Germicidal Ultraviolet Lamp Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916166', '', '', 'This chapter covers construction of HVAC and exhaust duct systems for residential, commercial, and industrial applications. Building Code Requirements Pressure Classifications Duct Cleaning HVAC System Leakage Air-Handling Unit Leakage Residential and Commercial Duct Construction Industrial Duct Construction Antimicrobial-Treated Ducts Duct Construction for Grease- and Moisture-Laden Vapors Rigid Plastic Ducts Air Dispersion Systems Underground Ducts Ducts Outside Buildings Seismic Qualification Sheet Metal Welding Thermal Insulation Specifications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2884, 'S17 -- Germicidal Ultraviolet Lamp Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916167', '', '', 'Variable-refrigerant-flow (VRF) HVAC systems are a direct-expansion (DX) heat pump technology platform built on the standard reverse Rankine vapor compression cycle. These systems are thermodynamically similar to unitary and other common DX systems, and share many of the same components (i.e., compressor, expansion device, heat exchangers). VRF systems transport heat between an outdoor condensing unit and a network of indoor units located near or within the conditioned space through refrigerant piping installed in the building. Attributes that distinguish VRF from other DX system types are multiple indoor units connected to a common outdoor unit (single or combined modules), scalability, variable capacity, distributed control, and simultaneous heating and cooling. Standards Equipment VRF System Operation Modeling Considerations Design Considerations VRF System Design Example Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2885, 'S16 -- Infrared Radiant Heating (SI)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916168', '', '', 'Variable-refrigerant-flow (VRF) HVAC systems are a direct-expansion (DX) heat pump technology platform built on the standard reverse Rankine vapor compression cycle. These systems are thermodynamically similar to unitary and other common DX systems, and share many of the same components (i.e., compressor, expansion device, heat exchangers). VRF systems transport heat between an outdoor condensing unit and a network of indoor units located near or within the conditioned space through refrigerant piping installed in the building. Attributes that distinguish VRF from other DX system types are multiple indoor units connected to a common outdoor unit (single or combined modules), scalability, variable capacity, distributed control, and simultaneous heating and cooling. Standards Equipment VRF System Operation Modeling Considerations Design Considerations VRF System Design Example Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2886, 'S16 -- Infrared Radiant Heating (I-P)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916169', '', '', 'This chapter includes a review of the fundamentals of UV-C energy’s impact on microorganisms; how UV-C lamps generate germicidal radiant energy; various components that comprise UV-C devices and systems; and a review of human safety and maintenance issues. Terminology GUV Fundamentals Germicidal Ultraviolet Sources and Equipment UV-C LEDs UVC Photodegradation of Materials Maintenance Safety Installation and Commissioning Unit Conversions', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2887, 'S15 -- Medium- and High-Temperature Water Heating (SI)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916170', '', '', 'This chapter includes a review of the fundamentals of UV-C energy’s impact on microorganisms; how UV-C lamps generate germicidal radiant energy; various components that comprise UV-C devices and systems; and a review of human safety and maintenance issues. Terminology GUV Fundamentals Germicidal Ultraviolet Sources and Equipment UV-C LEDs UVC Photodegradation of Materials Maintenance Safety Installation and Commissioning Unit Conversions', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2888, 'S15 -- Medium- and High-Temperature Water Heating (I-P)', 'ASHRAE', '', '', '2024', '', '0', 8, '2407160916171', '', '', 'Infrared radiant heating principles discussed in this chapter apply to equipment with thermal radiation source temperatures ranging from 300 to 5000F (150 to 2760C). (Equipment with source temperatures starting from below the indoor air temperature to 300F [150C] is classified as panel heating and cooling equipment, discussed in Chapter 6 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment.) Energy Conservation Infrared Energy Sources System Efficiency Reflectors Controls Precautions Maintenance Design Considerations for Beam Radiant Heaters', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2889, 'S14 -- Condenser Water Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 4, '2407160916172', '', '', 'Infrared radiant heating principles discussed in this chapter apply to equipment with thermal radiation source temperatures ranging from 300 to 5000F (150 to 2760C). (Equipment with source temperatures starting from below the indoor air temperature to 300F [150C] is classified as panel heating and cooling equipment, discussed in Chapter 6 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment.) Energy Conservation Infrared Energy Sources System Efficiency Reflectors Controls Precautions Maintenance Design Considerations for Beam Radiant Heaters', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2890, 'S14 -- Condenser Water Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 4, '2407160916173', '', '', 'Medium-temperature water (MTW) systems have operating temperatures ranging from 250F to 350F (120C to 175C) and are designed to a pressure rating of 125 to 150 psig (860 to 1030 kPa [gage]). High-temperature water (HTW) systems are classified as those operating with supply water temperatures above 350F (175C) and designed to a pressure rating of 300 psig (2000 kPa [gage]). The usual practical temperature limit is about 450F (230C) because of pressure limitations on pipe fittings, equipment, and accessories. The rapid pressure rise that occurs as the temperature rises above 450F (230C) increases cost because components rated for higher pressures are required. The design principles for both medium- and high-temperature systems are basically the same. This chapter presents the general principles and practices that apply to MTW/HTW systems and distinguishes them from low-temperature water systems operating below 250F (120C). See Chapter 13 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment for basic design considerations applicable to all hot-water systems. System Characteristics Basic System Design Considerations Distribution Piping Design Heat Exchangers Air-Heating Coils Space-Heating Equipment Instrumentation and Controls Water Treatment Heat Storage Safety Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2891, 'S13 -- Hydronic Heating and Cooling (SI)', 'ASHRAE', '', '', '2024', '', '0', 26, '2407160916174', '', '', 'Medium-temperature water (MTW) systems have operating temperatures ranging from 250F to 350F (120C to 175C) and are designed to a pressure rating of 125 to 150 psig (860 to 1030 kPa [gage]). High-temperature water (HTW) systems are classified as those operating with supply water temperatures above 350F (175C) and designed to a pressure rating of 300 psig (2000 kPa [gage]). The usual practical temperature limit is about 450F (230C) because of pressure limitations on pipe fittings, equipment, and accessories. The rapid pressure rise that occurs as the temperature rises above 450F (230C) increases cost because components rated for higher pressures are required. The design principles for both medium- and high-temperature systems are basically the same. This chapter presents the general principles and practices that apply to MTW/HTW systems and distinguishes them from low-temperature water systems operating below 250F (120C). See Chapter 13 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment for basic design considerations applicable to all hot-water systems. System Characteristics Basic System Design Considerations Distribution Piping Design Heat Exchangers Air-Heating Coils Space-Heating Equipment Instrumentation and Controls Water Treatment Heat Storage Safety Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2892, 'S13 -- Hydronic Heating and Cooling (I-P)', 'ASHRAE', '', '', '2024', '', '0', 26, '2407160916175', '', '', 'As part of the vapor-compression cycle for mechanical refrigeration, the heat of compression produced must be rejected to complete the refrigeration cycle. Refrigerant systems may be cooled by air or water. In water-cooled systems, water flows through the condenser and is called condenser water. Condenser water systems are classified as (1) once-through systems (e.g., city water, well-water, or lake/groundwater systems), or (2) recirculating or cooling tower systems. This chapter focuses on open condenser water systems and evaporative coolers; for information on closed-loop systems used in ground-source heat pump loops, see Chapter 49 of this volume and Chapter 35 of the 2023 ASHRAE Handbook -- HVAC Applications. Once-Through City Water Systems Open Cooling Tower Systems Low-Temperature (Water Economizer) Systems Closed-Circuit Evaporative Coolers Other Sources of Water Overpressure Caused by Thermal Fluid Expansion', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2893, 'S12 -- District Heating and Cooling (SI)', 'ASHRAE', '', '', '2024', '', '0', 50, '2407160916176', '', '', 'As part of the vapor-compression cycle for mechanical refrigeration, the heat of compression produced must be rejected to complete the refrigeration cycle. Refrigerant systems may be cooled by air or water. In water-cooled systems, water flows through the condenser and is called condenser water. Condenser water systems are classified as (1) once-through systems (e.g., city water, well-water, or lake/groundwater systems), or (2) recirculating or cooling tower systems. This chapter focuses on open condenser water systems and evaporative coolers; for information on closed-loop systems used in ground-source heat pump loops, see Chapter 49 of this volume and Chapter 35 of the 2023 ASHRAE Handbook -- HVAC Applications. Once-Through City Water Systems Open Cooling Tower Systems Low-Temperature (Water Economizer) Systems Closed-Circuit Evaporative Coolers Other Sources of Water Overpressure Caused by Thermal Fluid Expansion', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2894, 'S12 -- District Heating and Cooling (I-P)', 'ASHRAE', '', '', '2024', '', '0', 50, '2407160916177', '', '', 'This chapter describes forced recirculating systems. Successful water system design depends on awareness of the many complex interrelationships between various elements. In a practical sense, no component can be selected without considering its effect on the other elements. For example, design water temperature and flow rates are interrelated, as are the system layout and pump selection. The type and control of heat exchangers used affect the flow rate and pump selection, and the pump selection and distribution affect the controllability. The designer must thus work back and forth between tentative points and their effects until a satisfactory integrated design has been reached. Because of these relationships, rules of thumb usually do not lead to a satisfactory design. TEMPERATURE CLASSIFICATIONS CLOSED WATER SYSTEMS Method of Design Thermal Components Hydraulic Components Piping Circuits Capacity Control of Load System Low-Temperature Heating Systems Chilled-Water Systems Dual-Temperature Systems Other Design Considerations Other Design Procedures Antifreeze Solutions', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2895, 'S11 -- Steam Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 17, '2407160916178', '', '', 'This chapter describes forced recirculating systems. Successful water system design depends on awareness of the many complex interrelationships between various elements. In a practical sense, no component can be selected without considering its effect on the other elements. For example, design water temperature and flow rates are interrelated, as are the system layout and pump selection. The type and control of heat exchangers used affect the flow rate and pump selection, and the pump selection and distribution affect the controllability. The designer must thus work back and forth between tentative points and their effects until a satisfactory integrated design has been reached. Because of these relationships, rules of thumb usually do not lead to a satisfactory design. TEMPERATURE CLASSIFICATIONS CLOSED WATER SYSTEMS Method of Design Thermal Components Hydraulic Components Piping Circuits Capacity Control of Load System Low-Temperature Heating Systems Chilled-Water Systems Dual-Temperature Systems Other Design Considerations Other Design Procedures Antifreeze Solutions', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2896, 'S11 -- Steam Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 17, '2407160916179', '', '', 'District heating and cooling (DHC) or district energy (DE) distributes thermal energy from a central source to residential, commercial, and/or industrial consumers for use in space heating, cooling, water heating, and/or process heating. The energy is distributed by steam or hot- or chilled-water lines. Thus, thermal energy comes from a distribution medium rather than being generated onsite at each facility. SYSTEM MASTER PLANNING Economic Considerations CENTRAL PLANT Heating and Cooling Production Chilled-Water Distribution Design Considerations DISTRIBUTION SYSTEM Hydraulic Considerations Thermal Considerations Methods of Heat Transfer Analysis Expansion Provisions Distribution System Construction CONSUMER INTERCONNECTIONS Direct Connections Indirect Connections Steam Connections Components Temperature Differential Control Operation and Maintenance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2897, 'S10 -- Small Forced-Air Heating and Cooling Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 14, '2407160916180', '', '', 'District heating and cooling (DHC) or district energy (DE) distributes thermal energy from a central source to residential, commercial, and/or industrial consumers for use in space heating, cooling, water heating, and/or process heating. The energy is distributed by steam or hot- or chilled-water lines. Thus, thermal energy comes from a distribution medium rather than being generated onsite at each facility. SYSTEM MASTER PLANNING Economic Considerations CENTRAL PLANT Heating and Cooling Production Chilled-Water Distribution Design Considerations DISTRIBUTION SYSTEM Hydraulic Considerations Thermal Considerations Methods of Heat Transfer Analysis Expansion Provisions Distribution System Construction CONSUMER INTERCONNECTIONS Direct Connections Indirect Connections Steam Connections Components Temperature Differential Control Operation and Maintenance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2898, 'S10 -- Small Forced-Air Heating and Cooling Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 14, '2407160916181', '', '', 'Steam systems use the vapor phase of water to supply heat or kinetic energy through a piping system. As a source of heat, steam can heat a conditioned space with suitable terminal heat transfer equipment such as fan-coil units, unit heaters, radiators, and convectors (finned tube or cast iron), or through a heat exchanger that supplies hot water or some other heat transfer medium to the terminal units. In addition, steam is commonly used in heat exchangers (shell-and-tube, plate, or coil types) to heat domestic hot water and supply heat for industrial and commercial processes such as in laundries and kitchens. Steam is also used as a heat source for certain cooling processes such as single-stage and two-stage absorption refrigeration machines. Advantages Fundamentals Effects of Water, Air, and Gases Heat Transfer Basic Steam System Design Steam Source Boiler Connections Design Steam Pressure Piping Condensate Removal from Temperature-Regulated Equipment Steam Traps Pressure-Reducing Valves Terminal Equipment Convection Steam Heating Steam Distribution Temperature Control Heat Recovery Combined Steam and Water Systems Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2899, 'S09 -- Applied Heat Pump and Heat Recovery Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 26, '2407160916182', '', '', 'Steam systems use the vapor phase of water to supply heat or kinetic energy through a piping system. As a source of heat, steam can heat a conditioned space with suitable terminal heat transfer equipment such as fan-coil units, unit heaters, radiators, and convectors (finned tube or cast iron), or through a heat exchanger that supplies hot water or some other heat transfer medium to the terminal units. In addition, steam is commonly used in heat exchangers (shell-and-tube, plate, or coil types) to heat domestic hot water and supply heat for industrial and commercial processes such as in laundries and kitchens. Steam is also used as a heat source for certain cooling processes such as single-stage and two-stage absorption refrigeration machines. Advantages Fundamentals Effects of Water, Air, and Gases Heat Transfer Basic Steam System Design Steam Source Boiler Connections Design Steam Pressure Piping Condensate Removal from Temperature-Regulated Equipment Steam Traps Pressure-Reducing Valves Terminal Equipment Convection Steam Heating Steam Distribution Temperature Control Heat Recovery Combined Steam and Water Systems Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2900, 'S09 -- Applied Heat Pump and Heat Recovery Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 26, '2407160916183', '', '', 'This chapter describes the basics of design and component selection of small forced-air heating and cooling systems, explains their importance, and describes the system’s parametric effects on energy consumption. It also gives an overview of test methods for thermal distribution system efficiency, and considers the interaction between the building thermal/pressure envelope and the forced-air heating and cooling system, which is critical to the energy efficiency and cost-effectiveness of the overall system. This chapter pertains to residential and certain small commercial systems; large commercial systems are beyond the scope of this chapter. Applicable standards are listed in the Standards section at the end of the chapter. Components Common System Problems System Design Detailed Duct Design Small Commercial Systems Testing for Duct Efficiency.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2901, 'S08 -- Combustion Turbine Inlet Cooling (SI)', 'ASHRAE', '', '', '2024', '', '0', 10, '2407160916184', '', '', 'This chapter describes the basics of design and component selection of small forced-air heating and cooling systems, explains their importance, and describes the system’s parametric effects on energy consumption. It also gives an overview of test methods for thermal distribution system efficiency, and considers the interaction between the building thermal/pressure envelope and the forced-air heating and cooling system, which is critical to the energy efficiency and cost-effectiveness of the overall system. This chapter pertains to residential and certain small commercial systems; large commercial systems are beyond the scope of this chapter. Applicable standards are listed in the Standards section at the end of the chapter. Components Common System Problems System Design Detailed Duct Design Small Commercial Systems Testing for Duct Efficiency.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2902, 'S08 -- Combustion Turbine Inlet Cooling (I-P)', 'ASHRAE', '', '', '2024', '', '0', 9, '2407160916185', '', '', 'A heat pump extracts heat from a source and transfers it to a sink at a higher temperature. According to this definition, all pieces of refrigeration equipment, including air conditioners and chillers with refrigeration cycles, are heat pumps. In engineering, however, the term heat pump is generally reserved for equipment that heats for beneficial purposes, rather than that which removes heat for cooling only. Dual-mode heat pumps alternately provide heating or cooling. Heat reclaim heat pumps provide heating only, or simultaneous heating and cooling. An applied heat pump requires competent field engineering for the specific application, in contrast to the use of a manufacturer-designed unitary product. Applied heat pumps include built-up heat pumps (field- or custom-assembled from components) and industrial process heat pumps. Most modern heat pumps use a vapor compression (modified Rankine) cycle or absorption cycle. Any of the other refrigeration cycles discussed in Chapter 2 of the 2021 ASHRAE Handbook -- Fundamentals are also suitable. Although most heat pump compressors are powered by electric motors, limited use is also made of engine and turbine drives. Applied heat pumps are most commonly used for heating and cooling buildings, but they are gaining popularity for efficient domestic and service water heating, pool heating, and industrial process heating. TERMINOLOGY APPLIED HEAT PUMP SYSTEMS Heat Pump Cycles Heat Sources and Sinks Types of Heat Pumps Heat Pump Components Industrial Process Heat Pumps APPLIED HEAT RECOVERY SYSTEMS Waste Heat Recovery Water-Loop Heat Pump Systems Balanced Heat Recovery Systems Heat Pumps in District Heating and Cooling Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2903, 'S07 -- Combined Heat and Power Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 56, '2407160916186', '', '', 'A heat pump extracts heat from a source and transfers it to a sink at a higher temperature. According to this definition, all pieces of refrigeration equipment, including air conditioners and chillers with refrigeration cycles, are heat pumps. In engineering, however, the term heat pump is generally reserved for equipment that heats for beneficial purposes, rather than that which removes heat for cooling only. Dual-mode heat pumps alternately provide heating or cooling. Heat reclaim heat pumps provide heating only, or simultaneous heating and cooling. An applied heat pump requires competent field engineering for the specific application, in contrast to the use of a manufacturer-designed unitary product. Applied heat pumps include built-up heat pumps (field- or custom-assembled from components) and industrial process heat pumps. Most modern heat pumps use a vapor compression (modified Rankine) cycle or absorption cycle. Any of the other refrigeration cycles discussed in Chapter 2 of the 2021 ASHRAE Handbook -- Fundamentals are also suitable. Although most heat pump compressors are powered by electric motors, limited use is also made of engine and turbine drives. Applied heat pumps are most commonly used for heating and cooling buildings, but they are gaining popularity for efficient domestic and service water heating, pool heating, and industrial process heating. TERMINOLOGY APPLIED HEAT PUMP SYSTEMS Heat Pump Cycles Heat Sources and Sinks Types of Heat Pumps Heat Pump Components Industrial Process Heat Pumps APPLIED HEAT RECOVERY SYSTEMS Waste Heat Recovery Water-Loop Heat Pump Systems Balanced Heat Recovery Systems Heat Pumps in District Heating and Cooling Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2904, 'S07 -- Combined Heat and Power Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 56, '2407160916187', '', '', 'Power output capacity of all combustion turbines (CTs) varies with ambient air temperature and site elevation. The rated capacities of all CTs are based on standard ambient air at 59F (15C), 60% rh, 14.7 psia (101.35 kPa) at sea level, and zero inlet and exhaust pressure drops, as selected by the International Organization for Standardization (ISO). For all CTs, increased ambient air temperature or site elevation decreases power output; increased ambient air temperature also reduces fuel efficiency (i.e., increases the heat rate, defined as fuel energy required per unit of electric energy produced). However, the extent of the effect of these changes on output and efficiency varies with CT design. This chapter provides a detailed discussion on combustion turbine inlet cooling (CTIC). Additional information on applying CTIC to combined heat and power systems (cogeneration) is provided in Chapter 7 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Advantages Disadvantages Definition and Theory System Types Calculation of Power Capacity Enhancement and Economics', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2905, 'S06 -- Radiant Heating and Cooling (SI)', 'ASHRAE', '', '', '2024', '', '0', 21, '2407160916188', '', '', 'Power output capacity of all combustion turbines (CTs) varies with ambient air temperature and site elevation. The rated capacities of all CTs are based on standard ambient air at 59F (15C), 60% rh, 14.7 psia (101.35 kPa) at sea level, and zero inlet and exhaust pressure drops, as selected by the International Organization for Standardization (ISO). For all CTs, increased ambient air temperature or site elevation decreases power output; increased ambient air temperature also reduces fuel efficiency (i.e., increases the heat rate, defined as fuel energy required per unit of electric energy produced). However, the extent of the effect of these changes on output and efficiency varies with CT design. This chapter provides a detailed discussion on combustion turbine inlet cooling (CTIC). Additional information on applying CTIC to combined heat and power systems (cogeneration) is provided in Chapter 7 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Advantages Disadvantages Definition and Theory System Types Calculation of Power Capacity Enhancement and Economics', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2906, 'S06 -- Radiant Heating and Cooling (I-P)', 'ASHRAE', '', '', '2024', '', '0', 21, '2407160916189', '', '', 'This chapter describes the increasing role of combined heat and power (CHP) in sustainable design strategies, presents typical system designs, provides means and methods to understand system performance, and describes prime movers, such as reciprocating and Stirling engines, combustion and steam turbines, and fuel cells, and their characteristics for various uses. It also describes thermally activated technologies (TAT) such as heat recovery, absorption chillers, steam turbine-driven chillers, and desiccant dehumidifiers, as well as organic Rankine cycle (ORC) machines for waste heat recovery. Related issues, such as fuels, lubricants, instruments, noise, vibration, emissions, and maintenance, are discussed for each type of prime mover. Siting, interconnection, installation, and operation issues are also discussed. Thermal distribution systems are presented in Chapters 12 and 13 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Additional, in-depth guidance for CHP planning and design is provided in ASHRAE’s (2015) Combined Heat and Power Design Guide. Terminology CHP System Concepts Performance Parameters Fuel-to-Power Components Thermal-to-Power Components Thermal-to-Thermal Components Electrical Generators and Components System Design Codes and Installation Economic Evaluation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2907, 'S05 -- In-Room Terminal Systems (SI)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916190', '', '', 'This chapter describes the increasing role of combined heat and power (CHP) in sustainable design strategies, presents typical system designs, provides means and methods to understand system performance, and describes prime movers, such as reciprocating and Stirling engines, combustion and steam turbines, and fuel cells, and their characteristics for various uses. It also describes thermally activated technologies (TAT) such as heat recovery, absorption chillers, steam turbine-driven chillers, and desiccant dehumidifiers, as well as organic Rankine cycle (ORC) machines for waste heat recovery. Related issues, such as fuels, lubricants, instruments, noise, vibration, emissions, and maintenance, are discussed for each type of prime mover. Siting, interconnection, installation, and operation issues are also discussed. Thermal distribution systems are presented in Chapters 12 and 13 of the 2024 ASHRAE Handbook -- HVAC Systems and Equipment. Additional, in-depth guidance for CHP planning and design is provided in ASHRAE’s (2015) Combined Heat and Power Design Guide. Terminology CHP System Concepts Performance Parameters Fuel-to-Power Components Thermal-to-Power Components Thermal-to-Thermal Components Electrical Generators and Components System Design Codes and Installation Economic Evaluation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2908, 'S05 -- In-Room Terminal Systems (I-P)', 'ASHRAE', '', '', '2024', '', '0', 16, '2407160916191', '', '', 'Panel heating and cooling systems use temperature-controlled indoor surfaces on the floor, walls, or ceiling; temperature is maintained by circulating water, air, or electric current through a circuit embedded in or attached to the panel. A temperature-controlled surface is called a radiant panel if 50% or more of the design heat transfer on the temperature-controlled surface takes place by thermal radiation. Panel systems are characterized by controlled surface temperatures below 300F (150C). Panel systems may be combined either with a central forced-air system of one-zone, constant-temperature, constant-volume design, or with dual-duct, reheat, multizone or variable-volume systems, decentralized convective systems, or in-space fan-coil units. In decoupled systems, the air system provides ventilation air and meets dehumidification needs. In hybrid (or load-sharing) systems, the air system may provide significant additional capacity (e.g., where cooling loads exceed the capabilities of a radiant slab system). This chapter covers temperature-controlled surfaces that are the primary source of sensible heating and cooling in the conditioned space. For snow-melting and freeze-protection applications, see Chapter 52 of the 2023 ASHRAE Handbook -- HVAC Applications. Chapter 16 of this volume covers high-temperature panels over 300F (150C), which may be energized by gas or electricity. PRINCIPLES OF RADIANT SYSTEMS Heat Transfer Factors Affecting Heat Transfer Panel Design General Design Considerations Hybrid Systems RADIANT HEATING AND COOLING SYSTEMS Hydronic Ceiling Panels Embedded Systems with Tubing in Ceilings, Walls, or Floors Electrically Heated Radiant Systems DESIGN PROCEDURE Controls', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2909, 'S04 -- Air Handling and Distribution (SI)', 'ASHRAE', '', '', '2024', '', '0', 20, '2407160916192', '', '', 'Panel heating and cooling systems use temperature-controlled indoor surfaces on the floor, walls, or ceiling; temperature is maintained by circulating water, air, or electric current through a circuit embedded in or attached to the panel. A temperature-controlled surface is called a radiant panel if 50% or more of the design heat transfer on the temperature-controlled surface takes place by thermal radiation. Panel systems are characterized by controlled surface temperatures below 300F (150C). Panel systems may be combined either with a central forced-air system of one-zone, constant-temperature, constant-volume design, or with dual-duct, reheat, multizone or variable-volume systems, decentralized convective systems, or in-space fan-coil units. In decoupled systems, the air system provides ventilation air and meets dehumidification needs. In hybrid (or load-sharing) systems, the air system may provide significant additional capacity (e.g., where cooling loads exceed the capabilities of a radiant slab system). This chapter covers temperature-controlled surfaces that are the primary source of sensible heating and cooling in the conditioned space. For snow-melting and freeze-protection applications, see Chapter 52 of the 2023 ASHRAE Handbook -- HVAC Applications. Chapter 16 of this volume covers high-temperature panels over 300F (150C), which may be energized by gas or electricity. PRINCIPLES OF RADIANT SYSTEMS Heat Transfer Factors Affecting Heat Transfer Panel Design General Design Considerations Hybrid Systems RADIANT HEATING AND COOLING SYSTEMS Hydronic Ceiling Panels Embedded Systems with Tubing in Ceilings, Walls, or Floors Electrically Heated Radiant Systems DESIGN PROCEDURE Controls', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2910, 'S04 -- Air Handling and Distribution (I-P)', 'ASHRAE', '', '', '2024', '', '0', 20, '2407160916193', '', '', 'Very early in the design process, the HVAC design engineer must analyze and ultimately select appropriate systems, as discussed in Chapter 1. Next, production of heating and cooling is selected as decentralized (see Chapter 2) or centralized (see Chapter 3). Finally, distribution of heating and cooling to the end-use space can be done by an all-air system (see Chapter 4), or a variety of all-water or air/water systems and local terminals, as discussed in this chapter. (Note: all chapters mentioned are in the 2024 ASHRAE Handbook -- HVAC Systems and Equipment.) System Characteristics System Components and Configurations Secondary-Water Distribution Piping Arrangements Fan-Coil Unit and Unit Ventilator Systems Variable-Refrigerant-Flow (VRF) Units Chilled-Beam Systems Radiant-Panel Heating Systems Radiant-Floor Heating Systems Induction Unit Systems Supplemental Heating Units Primary-Air Systems Performance Under Varying Load Changeover Temperature Two-Pipe Systems with Central Ventilation Four-Pipe Systems Automatic Controls and Building Management Systems Maintenance Management Systems and Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2911, 'S03 -- Central Cooling and Heating Plants (SI)', 'ASHRAE', '', '', '2024', '', '0', 12, '2407160916194', '', '', 'Very early in the design process, the HVAC design engineer must analyze and ultimately select appropriate systems, as discussed in Chapter 1. Next, production of heating and cooling is selected as decentralized (see Chapter 2) or centralized (see Chapter 3). Finally, distribution of heating and cooling to the end-use space can be done by an all-air system (see Chapter 4), or a variety of all-water or air/water systems and local terminals, as discussed in this chapter. (Note: all chapters mentioned are in the 2024 ASHRAE Handbook -- HVAC Systems and Equipment.) System Characteristics System Components and Configurations Secondary-Water Distribution Piping Arrangements Fan-Coil Unit and Unit Ventilator Systems Variable-Refrigerant-Flow (VRF) Units Chilled-Beam Systems Radiant-Panel Heating Systems Radiant-Floor Heating Systems Induction Unit Systems Supplemental Heating Units Primary-Air Systems Performance Under Varying Load Changeover Temperature Two-Pipe Systems with Central Ventilation Four-Pipe Systems Automatic Controls and Building Management Systems Maintenance Management Systems and Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2912, 'S03 -- Central Cooling and Heating Plants (I-P)', 'ASHRAE', '', '', '2024', '', '0', 12, '2407160916195', '', '', 'Very early in the design of a new or retrofit building project, the HVAC design engineer must analyze and ultimately select the basic systems, as discussed in Chapter 1, and whether production of primary heating and cooling should be decentralized (see Chapter 2) or central (see Chapter 3). This chapter covers the options, processes, available equipment, and challenges of all-air systems; for all-water, air-and-water, and local terminal systems, see Chapter 5. For additional system selection tools, refer to the HVAC System Analysis and Selection Matrix in ASHRAE Handbook Online (handbook.ashrae.org). AIR-HANDLING UNITS Air-Handling Unit Psychrometric Processes Air-Handling Unit Components Air Distribution AIR-HANDLING SYSTEMS Single-Duct Systems Dual-Duct Systems Multizone Systems Special Systems Air Terminal Units Air Distribution System Controls Automatic Controls and Building Management Systems Maintenance Management System Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2913, 'S02 -- Decentralized Cooling and Heating (SI)', 'ASHRAE', '', '', '2024', '', '0', 12, '2407160916196', '', '', 'Very early in the design of a new or retrofit building project, the HVAC design engineer must analyze and ultimately select the basic systems, as discussed in Chapter 1, and whether production of primary heating and cooling should be decentralized (see Chapter 2) or central (see Chapter 3). This chapter covers the options, processes, available equipment, and challenges of all-air systems; for all-water, air-and-water, and local terminal systems, see Chapter 5. For additional system selection tools, refer to the HVAC System Analysis and Selection Matrix in ASHRAE Handbook Online (handbook.ashrae.org). AIR-HANDLING UNITS Air-Handling Unit Psychrometric Processes Air-Handling Unit Components Air Distribution AIR-HANDLING SYSTEMS Single-Duct Systems Dual-Duct Systems Multizone Systems Special Systems Air Terminal Units Air Distribution System Controls Automatic Controls and Building Management Systems Maintenance Management System Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2914, 'S02 -- Decentralized Cooling and Heating (I-P)', 'ASHRAE', '', '', '2024', '', '0', 12, '2407160916197', '', '', 'This chapter addresses design alternatives that should be considered when centralizing a facility’s cooling and heating sources. Distribution system options and equipment are discussed when they relate to the central equipment, but more information on distribution systems can be found in Chapters 11 to 15. System Characteristics Design Considerations Equipment Distribution Systems Sound, Vibration, Seismic, and Wind Considerations Space Considerations Automatic Controls and Building Management Systems Maintenance Management Systems Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2915, 'S01 -- HVAC System Analysis and Selection (SI)', 'ASHRAE', '', '', '2024', '', '0', 10, '2407160916198', '', '', 'This chapter addresses design alternatives that should be considered when centralizing a facility’s cooling and heating sources. Distribution system options and equipment are discussed when they relate to the central equipment, but more information on distribution systems can be found in Chapters 11 to 15. System Characteristics Design Considerations Equipment Distribution Systems Sound, Vibration, Seismic, and Wind Considerations Space Considerations Automatic Controls and Building Management Systems Maintenance Management Systems Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2916, 'S01 -- HVAC System Analysis and Selection (I-P)', 'ASHRAE', '', '', '2024', '', '0', 10, '2407160916199', '', '', 'For most small to mid-sized installations, decentralized cooling and heating is usually preferable to a centralized system (see Chapter 3). Frequently classified as packaged unit systems (although many are far from being a single packaged unit), decentralized systems can be found in almost all classes of buildings. They are especially suitable for smaller projects with no central plant, where low initial cost and simplified installation are important. These systems are installed in office buildings, shopping centers, manufacturing plants, schools, health care facilities, hotels, motels, apartments, nursing homes, and other multiple-occupancy dwellings. They are also suited to air conditioning existing buildings with limited life or income potential. Applications also include facilities requiring specialized high performance levels, such as computer rooms and research laboratories. Although some of the equipment addressed here can be applied as a single unit, this chapter covers applying multiple units to form a complete heating and air-conditioning system for a building and the distribution associated with some of these systems. For guidance on HVAC system selection, see Chapter 1. System Characteristics Design Considerations Window-Mounted and Through-the-Wall Room HVAC Units Water-Source Heat Pump Systems Multiple-Unit Systems Residential and Light Commercial Split Systems Commercial Self-Contained (Floor-by-Floor) Systems Commercial Outdoor Packaged Systems Automatic Controls and Building Management Systems Maintenance Management Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2917, 'Rutteldruckverdichtung Als Plastodynamisches Problem / Deep Vibration Compaction as Plastodynamic Problem', 'W Fellin', '', '', '1/1/2000 12:00:00 AM', '', '0', 215, '2407160916200', '', '', 'For most small to mid-sized installations, decentralized cooling and heating is usually preferable to a centralized system (see Chapter 3). Frequently classified as packaged unit systems (although many are far from being a single packaged unit), decentralized systems can be found in almost all classes of buildings. They are especially suitable for smaller projects with no central plant, where low initial cost and simplified installation are important. These systems are installed in office buildings, shopping centers, manufacturing plants, schools, health care facilities, hotels, motels, apartments, nursing homes, and other multiple-occupancy dwellings. They are also suited to air conditioning existing buildings with limited life or income potential. Applications also include facilities requiring specialized high performance levels, such as computer rooms and research laboratories. Although some of the equipment addressed here can be applied as a single unit, this chapter covers applying multiple units to form a complete heating and air-conditioning system for a building and the distribution associated with some of these systems. For guidance on HVAC system selection, see Chapter 1. System Characteristics Design Considerations Window-Mounted and Through-the-Wall Room HVAC Units Water-Source Heat Pump Systems Multiple-Unit Systems Residential and Light Commercial Split Systems Commercial Self-Contained (Floor-by-Floor) Systems Commercial Outdoor Packaged Systems Automatic Controls and Building Management Systems Maintenance Management Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0);
INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(2918, 'Rust for Blockchain Application Development', 'Author: Akhil Sharma', '', '', '4/30/2024 12:00:00 AM', '', '0', 392, '2407160916201', '', '', 'HVAC systems are categorized by the method used to produce, deliver, and control heating, ventilating, and air conditioning in the conditioned area. This chapter addresses procedures for selecting an appropriate system for a given application while taking into account pertinent issues associated with designing, building, commissioning, operating, and maintaining the system. It also addresses specific owner requirements and constraints associated with selecting the optimum HVAC system for the application. Chapters 2 to 18 in the HVAC Systems and Equipment volume describe specific approaches and systems along with their attributes, based on their heating and cooling medium, the commonly used variations, constructability, commissioning, operation, and maintenance. Selecting a System HVAC Systems and Equipment Space Requirements Air Distribution Pipe Distribution Security and Environmental Health and Safety Automatic Controls and Building Management Systems Maintenance Management System Building System Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2919, 'RNA, the Epicenter of Genetic Information', 'Authors: John Mattick, Paulo Amaral', '', '', '1/1/2023 12:00:00 AM', '', '0', 400, '2407160916202', '', '', '', '0.000000', 90.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2920, 'RNA Genetics: Volume II: Retroviruses, Viroids, and RNA Recombination', 'Esteban Domingo', '', '', '11/29/2017 12:00:00 AM', '', '0', 258, '2407160916203', '', '', '', '0.000000', 32.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2921, 'RNA Binding Proteins', 'Author: Zdravko Lorkovic', '', '', '8/10/2012 12:00:00 AM', '', '0', 175, '2407160916204', '', '', '', '0.000000', 32.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2922, 'R32 -- Fishery Products (SI)', 'ASHRAE', '', '', '2022', '', '0', 10, '2407160916205', '', '', 'About 69% of the table eggs produced in the United States are sold as shell eggs. The remainder are further processed into liquid, frozen, or dehydrated egg products that are used in food service or as an ingredient in food products. Small amounts of further processed eggs are converted to retail egg products, mainly mayonnaise, salad dressings, and egg substitutes. Shell egg processing includes cleaning, washing, drying, candling for interior and exterior defects, sizing, and packaging. Further processed eggs require shell removal, filtering, blending, pasteurization, and possibly freezing or dehydration. SHELL EGGS Egg Structure and Composition Egg Quality and Safety Shell Egg Processing Effect of Refrigeration on Egg Quality and Safety Packaging Transportation EGG PRODUCTS Egg Breaking Refrigerated Liquid Egg Products Frozen Egg Products Dehydrated Egg Products Egg Product Quality Sanitary Standards and Plant Sanitation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2923, 'R48 -- Ultralow-Temperature Refrigeration (SI)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916206', '', '', 'This chapter seeks to define some of the common terms used in industrial refrigeration systems, specifically those using ammonia as the refrigerant. The following glossary was compiled from a variety of sources throughout the industry, including ASHRAE, the International Institute of Ammonia Refrigeration (IIAR), the U.S. Occupational Safety and Health Administration (OSHA), and the U.S. Environmental Protection Agency (EPA). Specific sources for entries are listed in the endnotes. Minor edits for punctuation, conciseness, and consistency with usage elsewhere in the Handbook have been made.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2924, 'R32 -- Fishery Products (I-P)', 'ASHRAE', '', '', '2022', '', '0', 10, '2407160916207', '', '', 'Raw milk is either processed for beverage milks, creams, and related milk products for marketing, or is used for the manufacture of dairy products. Milk is defined in the U.S. Code of Federal Regulations and the Grade A Pasteurized Milk Ordinance (PMO). Milk products are defined in 21 CFR 131 to 135. Public Law 519 defines butter. Note that there are many nonstandard dairy-based products that may be processed and manufactured by the equipment described in this chapter. Dairy plant operations include receiving raw milk; purchase of equipment, supplies, and services; processing milk and milk products; manufacture of frozen dairy desserts, butter, cheeses, and cultured products; packaging; maintenance of equipment and other facilities; quality control; sales and distribution; engineering; and research. Milk Production and Processing Butter Manufacture Cheese Manufacture Frozen Dairy Desserts Ultrahigh-Temperature (UHT) Sterilization and Aseptic Packaging (AP) Evaporated, Sweetened Condensed, and Dry Milk', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2925, 'R48 -- Ultralow-Temperature Refrigeration (I-P)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916208', '', '', 'This chapter briefly describes many of the principles driving the present growth and development of low-temperature biological applications. An understanding of these principles is required to optimize design of practical apparatus for low-temperature biological processes. Although this field is growing in both breadth and sophistication, this chapter is restricted to processes that involve temperatures below which ice formation is normally encountered (i.e., 32°F [0°C]), and to an overview of the state of the art. Preservation Applications Research Applications Clinical Applications Refrigeration Hardware for Cryobiological Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2926, 'R31 -- Poultry Products (SI)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916209', '', '', 'Raw milk is either processed for beverage milks, creams, and related milk products for marketing, or is used for the manufacture of dairy products. Milk is defined in the U.S. Code of Federal Regulations and the Grade A Pasteurized Milk Ordinance (PMO). Milk products are defined in 21 CFR 131 to 135. Public Law 519 defines butter. Note that there are many nonstandard dairy-based products that may be processed and manufactured by the equipment described in this chapter. Dairy plant operations include receiving raw milk; purchase of equipment, supplies, and services; processing milk and milk products; manufacture of frozen dairy desserts, butter, cheeses, and cultured products; packaging; maintenance of equipment and other facilities; quality control; sales and distribution; engineering; and research. Milk Production and Processing Butter Manufacture Cheese Manufacture Frozen Dairy Desserts Ultrahigh-Temperature (UHT) Sterilization and Aseptic Packaging (AP) Evaporated, Sweetened Condensed, and Dry Milk', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2927, 'R47 -- Cryogenics (SI)', 'ASHRAE', '', '', '2022', '', '0', 32, '2407160916210', '', '', 'This chapter briefly describes many of the principles driving the present growth and development of low-temperature biological applications. An understanding of these principles is required to optimize design of practical apparatus for low-temperature biological processes. Although this field is growing in both breadth and sophistication, this chapter is restricted to processes that involve temperatures below which ice formation is normally encountered (i.e., 32°F [0°C]), and to an overview of the state of the art. Preservation Applications Research Applications Clinical Applications Refrigeration Hardware for Cryobiological Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2928, 'R31 -- Poultry Products (I-P)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916211', '', '', 'This chapter covers preservation and processing of fresh and frozen fishery products; handling of fresh fish aboard vessels and ashore; the technology of freezing fish; and present commercial trends in freezing, frozen storage, and distribution of seafood. See Chapter 40 for additional information regarding fishery products for precooked and prepared foods, and Chapter 26 for more on marine refrigeration. FRESH FISHERY PRODUCTS Care Aboard Vessels Shore Plant Procedure and Marketing Packaging Fresh Fish Fresh Fish Storage FROZEN FISHERY PRODUCTS Packaging Freezing Methods Storage of Frozen Fish Transportation and Marketing', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2929, 'R47 -- Cryogenics (I-P)', 'ASHRAE', '', '', '2022', '', '0', 32, '2407160916212', '', '', 'Ultralow-temperature refrigeration is defined here as refrigeration in the temperature range of –58 to –148°F (–50 to –100°C). What is considered low temperature for an application depends on the temperature range for that specific application. Low temperatures for air conditioning are around 32°F (0°C); for industrial refrigeration, –31 to –58°F (–35 to –50°C); and for cryogenics, approaching 0°R (0 K) (absolute zero). Applications such as freeze-drying, as well as the pharmaceutical, chemical, and petroleum industries, use refrigeration in the ultralow-temperature range as designated in this chapter. The refrigeration cycles presented in this chapter may be used in both standard packaged and custom-designed systems. Cascade systems are emphasized, both autocascade (typical of packaged units) and two-refrigerant cascade (found in custom-engineered ultralow-temperature systems). Autocascade Systems Custom-Designed and Field-Erected Systems Single-Refrigerant Systems Cascade Systems Ultralow-Temperature Materials Insulation Heat Transfer Secondary Coolants', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2930, 'R30 -- Meat Products (SI)', 'ASHRAE', '', '', '2022', '', '0', 18, '2407160916213', '', '', 'This chapter covers preservation and processing of fresh and frozen fishery products; handling of fresh fish aboard vessels and ashore; the technology of freezing fish; and present commercial trends in freezing, frozen storage, and distribution of seafood. See Chapter 40 for additional information regarding fishery products for precooked and prepared foods, and Chapter 26 for more on marine refrigeration. FRESH FISHERY PRODUCTS Care Aboard Vessels Shore Plant Procedure and Marketing Packaging Fresh Fish Fresh Fish Storage FROZEN FISHERY PRODUCTS Packaging Freezing Methods Storage of Frozen Fish Transportation and Marketing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2931, 'R46 -- Refrigeration in the Chemical Industry (SI)', 'ASHRAE', '', '', '2022', '', '0', 9, '2407160916214', '', '', 'Ultralow-temperature refrigeration is defined here as refrigeration in the temperature range of –58 to –148°F (–50 to –100°C). What is considered low temperature for an application depends on the temperature range for that specific application. Low temperatures for air conditioning are around 32°F (0°C); for industrial refrigeration, –31 to –58°F (–35 to –50°C); and for cryogenics, approaching 0°R (0 K) (absolute zero). Applications such as freeze-drying, as well as the pharmaceutical, chemical, and petroleum industries, use refrigeration in the ultralow-temperature range as designated in this chapter. The refrigeration cycles presented in this chapter may be used in both standard packaged and custom-designed systems. Cascade systems are emphasized, both autocascade (typical of packaged units) and two-refrigerant cascade (found in custom-engineered ultralow-temperature systems). Autocascade Systems Custom-Designed and Field-Erected Systems Single-Refrigerant Systems Cascade Systems Ultralow-Temperature Materials Insulation Heat Transfer Secondary Coolants', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2932, 'R30 -- Meat Products (I-P)', 'ASHRAE', '', '', '2022', '', '0', 18, '2407160916215', '', '', 'Poultry, and broilers in particular, are the most widely grown farm animal on earth. Two major challenges face the poultry industry: (1) keeping food safe from human pathogens carried by poultry in small numbers that could multiply, sometimes to dangerous levels, during processing, handling, and meal preparation; and (2) developing environmentally sound, economical waste management facilities. Innovative engineering and refrigeration are a part of the solutions for these issues. Processing Chilling Decontamination of Carcasses Further Processing Freezing Packaging Airflow Systems in Poultry Processing Plants Plant Sanitation Tenderness Control Distribution and Retail Holding Refrigeration Preserving Quality in Storage and Marketing Thawing', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2933, 'R46 -- Refrigeration in the Chemical Industry (I-P)', 'ASHRAE', '', '', '2022', '', '0', 9, '2407160916216', '', '', 'Cryogenic engineering therefore is involved with the design and development of low-temperature systems and components. In such activities the designer must be familiar with the properties of fluids used to achieve these low temperatures as well as the physical properties of components used to produce, maintain, and apply such temperatures. General Applications Low-Temperature Properties Refrigeration and Liquefaction Cryocoolers Separation and Purification of Gases Equipment Low-Temperature Insulations Storage and Transfer Systems Instrumentation Hazards of Cryogenic Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2934, 'R29 -- Industrial Food-Freezing Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916217', '', '', 'Poultry, and broilers in particular, are the most widely grown farm animal on earth. Two major challenges face the poultry industry: (1) keeping food safe from human pathogens carried by poultry in small numbers that could multiply, sometimes to dangerous levels, during processing, handling, and meal preparation; and (2) developing environmentally sound, economical waste management facilities. Innovative engineering and refrigeration are a part of the solutions for these issues. Processing Chilling Decontamination of Carcasses Further Processing Freezing Packaging Airflow Systems in Poultry Processing Plants Plant Sanitation Tenderness Control Distribution and Retail Holding Refrigeration Preserving Quality in Storage and Marketing Thawing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2935, 'R45 -- Concrete Dams and Subsurface Soils (SI)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916218', '', '', 'Cryogenic engineering therefore is involved with the design and development of low-temperature systems and components. In such activities the designer must be familiar with the properties of fluids used to achieve these low temperatures as well as the physical properties of components used to produce, maintain, and apply such temperatures. General Applications Low-Temperature Properties Refrigeration and Liquefaction Cryocoolers Separation and Purification of Gases Equipment Low-Temperature Insulations Storage and Transfer Systems Instrumentation Hazards of Cryogenic Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2936, 'R29 -- Industrial Food-Freezing Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916219', '', '', 'Around the world about 4 to 5 million (0.4 million in the United States) four-legged animals such as hogs, cattle, calves, buffalo, water buffalo, lambs, sheep, goats, and deer are slaughtered each day to supply the demand for red meats and their products. The majority of these animals are slaughtered in commercial slaughterhouses (abattoirs) under supervision, although a small portion (0.08% in the United States) are still killed on the farm. Sanitation Carcass Chilling and Holding Processed Meats Frozen Meat Products Shipping Docks Energy Conservation', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2937, 'R45 -- Concrete Dams and Subsurface Soils (I-P)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916220', '', '', 'This chapter gives guidance to refrigeration engineers working with chemical plant designers so they can design an optimum refrigeration system. Refrigeration engineers must be familiar with the chemical process for which the refrigeration facilities are being designed. Understanding the overall process is also desirable. Computer programs are also available that can calculate cooling loads based on the gas chromatographic analysis of a process fluid. These programs accurately define not only the thermodynamic performance of the fluid to be chilled, but also the required heat transfer characteristics of the chiller. Flow Sheets and Specifications Refrigeration as a Utility Load Characteristics Safety Requirements Equipment Characteristics Start-Up and Shutdown Refrigerants Refrigeration Systems Refrigeration Equipment', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2938, 'R28 -- Methods of Precooling Fruits, Vegetables, and Cut Flowers (SI)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916221', '', '', 'Around the world about 4 to 5 million (0.4 million in the United States) four-legged animals such as hogs, cattle, calves, buffalo, water buffalo, lambs, sheep, goats, and deer are slaughtered each day to supply the demand for red meats and their products. The majority of these animals are slaughtered in commercial slaughterhouses (abattoirs) under supervision, although a small portion (0.08% in the United States) are still killed on the farm. Sanitation Carcass Chilling and Holding Processed Meats Frozen Meat Products Shipping Docks Energy Conservation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2939, 'R44 -- Ice Rinks (SI)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916222', '', '', 'This chapter gives guidance to refrigeration engineers working with chemical plant designers so they can design an optimum refrigeration system. Refrigeration engineers must be familiar with the chemical process for which the refrigeration facilities are being designed. Understanding the overall process is also desirable. Computer programs are also available that can calculate cooling loads based on the gas chromatographic analysis of a process fluid. These programs accurately define not only the thermodynamic performance of the fluid to be chilled, but also the required heat transfer characteristics of the chiller. Flow Sheets and Specifications Refrigeration as a Utility Load Characteristics Safety Requirements Equipment Characteristics Start-Up and Shutdown Refrigerants Refrigeration Systems Refrigeration Equipment', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2940, 'R28 -- Methods of Precooling Fruits, Vegetables, and Cut Flowers (I-P)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916223', '', '', 'Freezing is a method of food preservation that slows the physical changes and chemical and microbiological activity that cause deterioration in foods. Reducing temperature slows molecular and microbial activity in food, thus extending useful storage life. Although every product has an individual ideal storage temperature, most frozen food products are stored at 0 to –30°F (–18 to –35°C).. Chapter 21 lists frozen storage temperatures for specific products. This chapter covers general freezing methods and systems. Additional information on freezing specific products is covered in Chapters 23, 30 to 33, and 38 to 42. Related information can be obtained in Chapters 19 and 20, which cover thermal properties of foods as well as their cooling and freezing times. Information on refrigeration system practices is given in Chapters 1 to 4. Freezing Methods Blast Freezers Contact Freezers Cryogenic Freezers Cryomechanical Freezers Other Freezer Selection Criteria Refrigeration Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2941, 'R44 -- Ice Rinks (I-P)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916224', '', '', 'Refrigeration is one of the more important tools of the heavy construction industry, particularly in the temperature control of large concrete dams. It is also used to stabilize both water-bearing and permanently frozen soil. This chapter briefly describes some of the cooling practices that have been used for these purposes. CONCRETE DAMS Methods of Temperature Control System Selection Parameters CONTROL OF SUBSURFACE WATER FLOW SOIL STABILIZATION Thermal Design Passive Cooling Active Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2942, 'R27 -- Air Transport (SI)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916225', '', '', 'Freezing is a method of food preservation that slows the physical changes and chemical and microbiological activity that cause deterioration in foods. Reducing temperature slows molecular and microbial activity in food, thus extending useful storage life. Although every product has an individual ideal storage temperature, most frozen food products are stored at 0 to –30°F (–18 to –35°C).. Chapter 21 lists frozen storage temperatures for specific products. This chapter covers general freezing methods and systems. Additional information on freezing specific products is covered in Chapters 23, 30 to 33, and 38 to 42. Related information can be obtained in Chapters 19 and 20, which cover thermal properties of foods as well as their cooling and freezing times. Information on refrigeration system practices is given in Chapters 1 to 4. Freezing Methods Blast Freezers Contact Freezers Cryogenic Freezers Cryomechanical Freezers Other Freezer Selection Criteria Refrigeration Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2943, 'R43 -- Ice Manufacture (SI)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916226', '', '', 'Refrigeration is one of the more important tools of the heavy construction industry, particularly in the temperature control of large concrete dams. It is also used to stabilize both water-bearing and permanently frozen soil. This chapter briefly describes some of the cooling practices that have been used for these purposes. CONCRETE DAMS Methods of Temperature Control System Selection Parameters CONTROL OF SUBSURFACE WATER FLOW SOIL STABILIZATION Thermal Design Passive Cooling Active Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2944, 'R27 -- Air Transport (I-P)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916227', '', '', 'Precooling is the rapid removal of field heat from freshly harvested fruits and vegetables before shipping, storage, or processing. Prompt precooling inhibits growth of microorganisms that cause decay, reduces enzymatic and respiratory activity, reduces susceptibility to ethylene damage, and reduces moisture loss. Thus, proper precooling reduces spoilage and retards loss of preharvest freshness and quality (Becker and Fricke 2002). FUNDAMENTALS Product Requirements Calculation Methods COOLING METHODS Hydrocooling Forced-Air Cooling Forced-Air Evaporative Cooling Package Icing Vacuum Cooling Selecting a Cooling Method Cooling Cut Flowers Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2945, 'R43 -- Ice Manufacture (I-P)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916228', '', '', 'Any level sheet of ice made by refrigeration (the term artificial ice is sometimes used) is referred to in this chapter as an ice rink regardless of use and whether it is located indoors or outdoors. Bobsled-luge tracks are not referred to as rinks but are referenced under this chapter. An ice sheet is usually frozen by circulating a heat transfer fluid through a network of pipes or tubes located below the surface of the ice. The heat transfer fluid is predominantly a secondary coolant such as glycol, methanol, ethanol, or calcium chloride (see Chapter 31 of the 2021 ASHRAE Handbook—Fundamentals). Applications Refrigeration Requirements Ice Rink Conditions Equipment Selection Rink Floor Design Building, Maintaining, and Planing Ice Surfaces Imitation Ice-Skating Surfaces', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2946, 'R26 -- Marine Refrigeration (SI)', 'ASHRAE', '', '', '2022', '', '0', 9, '2407160916229', '', '', 'Precooling is the rapid removal of field heat from freshly harvested fruits and vegetables before shipping, storage, or processing. Prompt precooling inhibits growth of microorganisms that cause decay, reduces enzymatic and respiratory activity, reduces susceptibility to ethylene damage, and reduces moisture loss. Thus, proper precooling reduces spoilage and retards loss of preharvest freshness and quality (Becker and Fricke 2002). FUNDAMENTALS Product Requirements Calculation Methods COOLING METHODS Hydrocooling Forced-Air Cooling Forced-Air Evaporative Cooling Package Icing Vacuum Cooling Selecting a Cooling Method Cooling Cut Flowers Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2947, 'R42 -- Chocolates, Candies, Nuts, Dried Fruits, and Dried Vegetables (SI)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916230', '', '', 'Any level sheet of ice made by refrigeration (the term artificial ice is sometimes used) is referred to in this chapter as an ice rink regardless of use and whether it is located indoors or outdoors. Bobsled-luge tracks are not referred to as rinks but are referenced under this chapter. An ice sheet is usually frozen by circulating a heat transfer fluid through a network of pipes or tubes located below the surface of the ice. The heat transfer fluid is predominantly a secondary coolant such as glycol, methanol, ethanol, or calcium chloride (see Chapter 31 of the 2021 ASHRAE Handbook—Fundamentals). Applications Refrigeration Requirements Ice Rink Conditions Equipment Selection Rink Floor Design Building, Maintaining, and Planing Ice Surfaces Imitation Ice-Skating Surfaces', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2948, 'R26 -- Marine Refrigeration (I-P)', 'ASHRAE', '', '', '2022', '', '0', 9, '2407160916231', '', '', 'Air freight service is provided by all-cargo carriers and passenger airlines. The latter companies also have all-cargo aircraft. Wide-body aircraft have a passenger and cargo mix on the main deck, increasing cargo capacity. All lines maintain regularly scheduled flights so shippers may adequately plan delivery time. Special charter flights are also available from regular terminals and from airports located close to producing areas. CARGO REFRIGERATION Perishable Air Cargo Perishable Commodity Requirements Design Considerations Shipping Containers Transit Refrigeration Ground Handling GALLEY REFRIGERATION Galley Air Chillers and Systems Galley Liquid-Chilling System Galley Refrigeration Inserts System Design HYBRID ENVIRONMENTAL CONTROL SYSTEMS', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2949, 'R42 -- Chocolates, Candies, Nuts, Dried Fruits, and Dried Vegetables (I-P)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916232', '', '', 'Most commercial ice production is done with ice makers that produce three basic types of fragmentary ice (flake, tubular, and plate), which vary according to the type and size required for a particular application. Among the many applications for manufactured ice are processing (fish, meat, poultry, dairy, produce, and hydrocooling). storage and transportation (fish, meat, poultry, produce, and dairy products), manufacturing (bakery products, sausage and hot dog products, chemicals and pharmaceuticals, and concrete mixing and curing), and others (retail consumer ice and off-peak thermal storage). Ice Makers Thermal Storage Ice Storage Delivery Systems Commercial Ice Ice-Source Heat Pumps', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2950, 'R25 -- Cargo Containers, Rail Cars, Trailers, and Trucks (SI)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916233', '', '', 'Air freight service is provided by all-cargo carriers and passenger airlines. The latter companies also have all-cargo aircraft. Wide-body aircraft have a passenger and cargo mix on the main deck, increasing cargo capacity. All lines maintain regularly scheduled flights so shippers may adequately plan delivery time. Special charter flights are also available from regular terminals and from airports located close to producing areas. CARGO REFRIGERATION Perishable Air Cargo Perishable Commodity Requirements Design Considerations Shipping Containers Transit Refrigeration Ground Handling GALLEY REFRIGERATION Galley Air Chillers and Systems Galley Liquid-Chilling System Galley Refrigeration Inserts System Design HYBRID ENVIRONMENTAL CONTROL SYSTEMS', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2951, 'R41 -- Bakery Products (SI)', 'ASHRAE', '', '', '2022', '', '0', 7, '2407160916234', '', '', 'Most commercial ice production is done with ice makers that produce three basic types of fragmentary ice (flake, tubular, and plate), which vary according to the type and size required for a particular application. Among the many applications for manufactured ice are processing (fish, meat, poultry, dairy, produce, and hydrocooling). storage and transportation (fish, meat, poultry, produce, and dairy products), manufacturing (bakery products, sausage and hot dog products, chemicals and pharmaceuticals, and concrete mixing and curing), and others (retail consumer ice and off-peak thermal storage). Ice Makers Thermal Storage Ice Storage Delivery Systems Commercial Ice Ice-Source Heat Pumps', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2952, 'R25 -- Cargo Containers, Rail Cars, Trailers, and Trucks (I-P)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916235', '', '', 'Marine refrigeration systems are used aboard seagoing vessels and offshore facilities and generally include cargo hold refrigeration, domestic refrigeration services, and refrigerated containers. These systems differ from stationary systems not only in physical aspects but also in the fact that marine systems must be designed to handle frequent starting and stopping. Process freezing or chilling plants on vessels might run continuously for weeks, but under some conditions may be started and stopped daily. Cold storages are usually shut down after the cargo is discharged, and are restarted before new cargo is loaded. GENERAL CONSIDERATIONS Refrigeration Load Refrigeration System Cargo Holds SHIPS’ REFRIGERATED STORES Commodities Storage Areas Ship Refrigerated Room Design Specific Vessels FISHING VESSELS Refrigeration System Design Refrigeration with Ice Refrigeration with Seawater Process Freezing and Cold Storage', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2953, 'R41 -- Bakery Products (I-P)', 'ASHRAE', '', '', '2022', '', '0', 7, '2407160916236', '', '', 'Air conditioning and refrigeration are essential for successful candy manufacturing. Proper atmospheric control increases production, lowers production costs, and improves product quality. CANDY MANUFACTURE Milk and Dark Chocolate Hand Dipping and Enrobing Bar Candy Hard Candy Hot Rooms Cold Rooms Cooling Tunnels Coating Kettles or Pans Packing Rooms Refrigeration Plant STORAGE Candy Nuts Dried Fruits and Vegetables Controlled Atmosphere', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2954, 'R24 -- Refrigerated-Facility Loads (SI)', 'ASHRAE', '', '', '2022', '', '0', 10, '2407160916237', '', '', 'Marine refrigeration systems are used aboard seagoing vessels and offshore facilities and generally include cargo hold refrigeration, domestic refrigeration services, and refrigerated containers. These systems differ from stationary systems not only in physical aspects but also in the fact that marine systems must be designed to handle frequent starting and stopping. Process freezing or chilling plants on vessels might run continuously for weeks, but under some conditions may be started and stopped daily. Cold storages are usually shut down after the cargo is discharged, and are restarted before new cargo is loaded. GENERAL CONSIDERATIONS Refrigeration Load Refrigeration System Cargo Holds SHIPS’ REFRIGERATED STORES Commodities Storage Areas Ship Refrigerated Room Design Specific Vessels FISHING VESSELS Refrigeration System Design Refrigeration with Ice Refrigeration with Seawater Process Freezing and Cold Storage', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2955, 'R40 -- Processed, Precooked, and Prepared Foods (SI)', 'ASHRAE', '', '', '2022', '', '0', 7, '2407160916238', '', '', 'Air conditioning and refrigeration are essential for successful candy manufacturing. Proper atmospheric control increases production, lowers production costs, and improves product quality. CANDY MANUFACTURE Milk and Dark Chocolate Hand Dipping and Enrobing Bar Candy Hard Candy Hot Rooms Cold Rooms Cooling Tunnels Coating Kettles or Pans Packing Rooms Refrigeration Plant STORAGE Candy Nuts Dried Fruits and Vegetables Controlled Atmosphere', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2956, 'R24 -- Refrigerated-Facility Loads (I-P)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916239', '', '', 'Transport of commodities may be as simple as direct delivery of fresh vegetables from garden to market in a wagon. However, travel time, ambient temperature, and risk of spoilage often make temperature-controlled transport necessary. Because some commodities are sensitive to the relative humidity and chemical composition of their surrounding atmosphere, these conditions may also need to be controlled. Today many commodities travel to distant markets intermodally (i.e., by some combination of highway, ocean, and railroad). This chapter discusses the vehicles, equipment, and related factors that combine to preserve temperature-sensitive commodities as they travel. Vehicles Vehicle Design Considerations Equipment Equipment Design and Selection Factors Qualification Testing System Application Factors Operations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2957, 'R40 -- Processed, Precooked, and Prepared Foods (I-P)', 'ASHRAE', '', '', '2022', '', '0', 7, '2407160916240', '', '', 'Refrigeration plays an important part in modern bakery production. This chapter addresses refrigeration and air conditioning as applied to bakery products, including items distributed (1) at ambient temperature, (2) refrigerated but unfrozen, and (3) frozen. Ingredient Storage Mixing Fermentation Bread Makeup Final Proof Baking Bread Cooling Slicing and Wrapping Bread Freezing Freezing Other Bakery Products Frozen Pre-Proofed Bakery Products Retarding Doughs and Batters Choice of Refrigerants', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2958, 'R23 -- Refrigerated-Facility Design (SI)', 'ASHRAE', '', '', '2022', '', '0', 17, '2407160916241', '', '', 'Transport of commodities may be as simple as direct delivery of fresh vegetables from garden to market in a wagon. However, travel time, ambient temperature, and risk of spoilage often make temperature-controlled transport necessary. Because some commodities are sensitive to the relative humidity and chemical composition of their surrounding atmosphere, these conditions may also need to be controlled. Today many commodities travel to distant markets intermodally (i.e., by some combination of highway, ocean, and railroad). This chapter discusses the vehicles, equipment, and related factors that combine to preserve temperature-sensitive commodities as they travel. Vehicles Vehicle Design Considerations Equipment Equipment Design and Selection Factors Qualification Testing System Application Factors Operations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2959, 'R39 -- Beverages (SI)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916242', '', '', 'Refrigeration plays an important part in modern bakery production. This chapter addresses refrigeration and air conditioning as applied to bakery products, including items distributed (1) at ambient temperature, (2) refrigerated but unfrozen, and (3) frozen. Ingredient Storage Mixing Fermentation Bread Makeup Final Proof Baking Bread Cooling Slicing and Wrapping Bread Freezing Freezing Other Bakery Products Frozen Pre-Proofed Bakery Products Retarding Doughs and Batters Choice of Refrigerants', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2960, 'R23 -- Refrigerated-Facility Design (I-P)', 'ASHRAE', '', '', '2022', '', '0', 17, '2407160916243', '', '', 'Total refrigeration load includes (1) transmission load, which is heat transferred into the refrigerated space through its surface; (2) product load, which is heat removed from and produced by products brought into and kept in the refrigerated space; (3) internal load, which is heat produced by internal sources (e.g., lights, electric motors, and people working in the space); (4) infiltration air load, which is heat gain associated with air entering the refrigerated space; and (5) equipment-related load. The first four segments of load constitute the net heat load for which a refrigeration system is to be provided; the fifth segment consists of all heat gains created by the refrigerating equipment. Thus, net heat load plus equipment heat load is the total refrigeration load for which a compressor must be selected. This chapter contains load calculating procedures and data for the first four segments and load determination recommendations for the fifth segment. Information needed for refrigeration of specific foods can be found in Chapters 28 and 30 to 42. Transmission Load Product Load Internal Load Infiltration Air Load Equipment-Related Load Safety Factor Total Facility Load Calculation Example Load Diversity Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2961, 'R39 -- Beverages (I-P)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916244', '', '', 'There are many categories of prepared foods. This chapter covers prepared meals, fruits, vegetables, and potato products and gives an overview of the HVAC&R requirements of facilities that process these products. Main Dishes, Meals Vegetables Fruits Potato Products Other Prepared Foods Long-Term Storage', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2962, 'R22 -- Food Microbiology and Refrigeration (SI)', 'ASHRAE', '', '', '2022', '', '0', 5, '2407160916245', '', '', 'Total refrigeration load includes (1) transmission load, which is heat transferred into the refrigerated space through its surface; (2) product load, which is heat removed from and produced by products brought into and kept in the refrigerated space; (3) internal load, which is heat produced by internal sources (e.g., lights, electric motors, and people working in the space); (4) infiltration air load, which is heat gain associated with air entering the refrigerated space; and (5) equipment-related load. The first four segments of load constitute the net heat load for which a refrigeration system is to be provided; the fifth segment consists of all heat gains created by the refrigerating equipment. Thus, net heat load plus equipment heat load is the total refrigeration load for which a compressor must be selected. This chapter contains load calculating procedures and data for the first four segments and load determination recommendations for the fifth segment. Information needed for refrigeration of specific foods can be found in Chapters 28 and 30 to 42. Transmission Load Product Load Internal Load Infiltration Air Load Equipment-Related Load Safety Factor Total Facility Load Calculation Example Load Diversity Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2963, 'R38 -- Fruit Juice Concentrates and Chilled Juice Products (SI)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916246', '', '', 'There are many categories of prepared foods. This chapter covers prepared meals, fruits, vegetables, and potato products and gives an overview of the HVAC&R requirements of facilities that process these products. Main Dishes, Meals Vegetables Fruits Potato Products Other Prepared Foods Long-Term Storage', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2964, 'R22 -- Food Microbiology and Refrigeration (I-P)', 'ASHRAE', '', '', '2022', '', '0', 5, '2407160916247', '', '', 'Refrigerated facilities are any buildings or sections of a building that achieve controlled storage conditions using refrigeration. Two basic storage facilities are (1) coolers that protect commodities at temperatures usually above 32°F (0°C) and (2) low-temperature rooms (freezers) operating under 32°F (0°C) to prevent spoilage or to maintain or extend product life. Initial Building Considerations Refrigeration Systems Insulation Techniques Applying Insulation Other Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2965, 'R38 -- Fruit Juice Concentrates and Chilled Juice Products (I-P)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916248', '', '', 'This chapter discusses the processes and use of refrigeration in breweries, wineries, and carbonated beverage plants. BREWERIES Malting Process Aspects Processing Pasteurization Carbon Dioxide Heat Balance Common Refrigeration Systems Vinegar Production WINE MAKING Must Cooling Heat Treatment of Red Musts Juice Cooling Heat Treatment of Juices Fermentation Temperature Control Potassium Bitartrate Crystallization Storage Temperature Control Chill-Proofing Brandies CARBONATED BEVERAGES Beverage and Water Coolers Size of Plant Liquid Carbon Dioxide Storage', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2966, 'R21 -- Commodity Storage Requirements (SI)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916249', '', '', 'Refrigerated facilities are any buildings or sections of a building that achieve controlled storage conditions using refrigeration. Two basic storage facilities are (1) coolers that protect commodities at temperatures usually above 32°F (0°C) and (2) low-temperature rooms (freezers) operating under 32°F (0°C) to prevent spoilage or to maintain or extend product life. Initial Building Considerations Refrigeration Systems Insulation Techniques Applying Insulation Other Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2967, 'R37 -- Vegetables (SI)', 'ASHRAE', '', '', '2022', '', '0', 16, '2407160916250', '', '', 'This chapter discusses the processes and use of refrigeration in breweries, wineries, and carbonated beverage plants. BREWERIES Malting Process Aspects Processing Pasteurization Carbon Dioxide Heat Balance Common Refrigeration Systems Vinegar Production WINE MAKING Must Cooling Heat Treatment of Red Musts Juice Cooling Heat Treatment of Juices Fermentation Temperature Control Potassium Bitartrate Crystallization Storage Temperature Control Chill-Proofing Brandies CARBONATED BEVERAGES Beverage and Water Coolers Size of Plant Liquid Carbon Dioxide Storage', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2968, 'R21 -- Commodity Storage Requirements (I-P)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916251', '', '', 'Refrigeration’s largest overall application is the prevention or retardation of microbial, physiological, and chemical changes in foods. Even at temperatures near the freezing point, foods may deteriorate through growth of microorganisms, changes caused by enzymes, or chemical reactions. Holding foods at low temperatures merely reduces the rate at which these changes take place. A few spoilage organisms can grow at or below temperatures at which food begins to freeze, but their growth rate is greatly reduced below that at ambient temperatures. Refrigeration also plays a major role in maintaining a safe food supply. Overall, the leading factor causing foodborne illness is improper food-holding temperatures. Another important factor is improperly sanitized equipment. Engineering directly affects the safety and stability of the food supply in design of cleanable equipment and facilities, as well as maintenance of environmental conditions that inhibit microbial growth. This chapter briefly discusses the microbiology of foods and the effect of design decisions on the production of safe and wholesome foods. Methods of applying refrigeration to specific foods are discussed in Chapters 30 to 42. Basic Microbiology Critical Microbial Growth Requirements Design for Control of Microorganisms Role of HACCP Sanitation Regulations and Standards', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2969, 'R37 -- Vegetables (I-P)', 'ASHRAE', '', '', '2022', '', '0', 16, '2407160916252', '', '', 'Citrus products, especially orange juice, comprise the largest percentage of the total volume of juices sold in the United States. Much of the technology used in processing noncitrus juices was developed from citrus processing. ORANGE JUICE Orange Concentrate Cold Storage Concentration Methods Quality Control Chilled Juice Refrigeration Pure Fruit Juice Powders OTHER CITRUS JUICES NONCITRUS JUICES Pineapple Juice Apple Juice Grape Juice Strawberry and Other Berry Juices', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2970, 'R20 -- Cooling and Freezing Times of Foods (SI)', 'ASHRAE', '', '', '2022', '', '0', 16, '2407160916253', '', '', 'Refrigeration’s largest overall application is the prevention or retardation of microbial, physiological, and chemical changes in foods. Even at temperatures near the freezing point, foods may deteriorate through growth of microorganisms, changes caused by enzymes, or chemical reactions. Holding foods at low temperatures merely reduces the rate at which these changes take place. A few spoilage organisms can grow at or below temperatures at which food begins to freeze, but their growth rate is greatly reduced below that at ambient temperatures. Refrigeration also plays a major role in maintaining a safe food supply. Overall, the leading factor causing foodborne illness is improper food-holding temperatures. Another important factor is improperly sanitized equipment. Engineering directly affects the safety and stability of the food supply in design of cleanable equipment and facilities, as well as maintenance of environmental conditions that inhibit microbial growth. This chapter briefly discusses the microbiology of foods and the effect of design decisions on the production of safe and wholesome foods. Methods of applying refrigeration to specific foods are discussed in Chapters 30 to 42. Basic Microbiology Critical Microbial Growth Requirements Design for Control of Microorganisms Role of HACCP Sanitation Regulations and Standards', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2971, 'R36 -- Citrus Fruit, Bananas, and Subtropical Fruit (SI)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916254', '', '', 'Citrus products, especially orange juice, comprise the largest percentage of the total volume of juices sold in the United States. Much of the technology used in processing noncitrus juices was developed from citrus processing. ORANGE JUICE Orange Concentrate Cold Storage Concentration Methods Quality Control Chilled Juice Refrigeration Pure Fruit Juice Powders OTHER CITRUS JUICES NONCITRUS JUICES Pineapple Juice Apple Juice Grape Juice Strawberry and Other Berry Juices', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0);
INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(2972, 'R20 -- Cooling and Freezing Times of Foods (I-P)', 'ASHRAE', '', '', '2022', '', '0', 16, '2407160916255', '', '', 'This chapter presents information on storage requirements of many perishable foods that enter the market on a commercial scale. Also included is a short discussion on the storage of furs and fabrics. The data are based on the storage of fresh, high-quality commodities that have been properly harvested, handled, and cooled. Refrigerated Storage Refrigerated Storage Plant Operation Storage of Frozen Foods Other Products', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2973, 'R36 -- Citrus Fruit, Bananas, and Subtropical Fruit (I-P)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916256', '', '', 'This chapter covers postharvest handling, cooling, packaging, in-transit preservation, and storage at destination locations for fresh vegetables. It also gives storage requirements for specific vegetables, including potential product deterioration caused by improper handling and storage conditions. Vegetable precooling is covered in Chapter 28, and vegetable processing and freezing in Chapter 40. Chapter 21 also provides storage requirements for many types of vegetables. Product Selection and Quality Maintenance In-Transit Preservation Preservation in Destination Facilities Refrigerated Storage Considerations Storage of Various Vegetables', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2974, 'R19 -- Thermal Properties of Foods (SI)', 'ASHRAE', '', '', '2022', '', '0', 31, '2407160916257', '', '', 'This chapter presents information on storage requirements of many perishable foods that enter the market on a commercial scale. Also included is a short discussion on the storage of furs and fabrics. The data are based on the storage of fresh, high-quality commodities that have been properly harvested, handled, and cooled. Refrigerated Storage Refrigerated Storage Plant Operation Storage of Frozen Foods Other Products', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2975, 'R35 -- Deciduous Tree and Vine Fruit (SI)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916258', '', '', 'This chapter covers postharvest handling, cooling, packaging, in-transit preservation, and storage at destination locations for fresh vegetables. It also gives storage requirements for specific vegetables, including potential product deterioration caused by improper handling and storage conditions. Vegetable precooling is covered in Chapter 28, and vegetable processing and freezing in Chapter 40. Chapter 21 also provides storage requirements for many types of vegetables. Product Selection and Quality Maintenance In-Transit Preservation Preservation in Destination Facilities Refrigerated Storage Considerations Storage of Various Vegetables', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2976, 'R19 -- Thermal Properties of Foods (I-P)', 'ASHRAE', '', '', '2022', '', '0', 31, '2407160916259', '', '', 'Numerous methods for predicting the cooling and freezing times of foods and beverages have been proposed, based on numerical, analytical, and empirical analysis. Selecting an appropriate estimation method from the many available methods can be challenging. This chapter reviews selected procedures available for estimating the air-blast convective cooling and freezing times of foods and beverages, and presents examples of these procedures. These procedures use the thermal properties of foods, discussed in Chapter 19. Thermodynamics of Cooling and Freezing Cooling Times of Foods and Beverages Sample Problems for Estimating Cooling Time Freezing Times of Foods and Beverages Sample Problems for Estimating Freezing Time Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2977, 'R35 -- Deciduous Tree and Vine Fruit (I-P)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916260', '', '', 'This chapter covers the harvesting, handling, processing, storage requirements, and possible disorders of fresh market citrus fruit grown in Florida, California, Texas, and Arizona; of bananas; and of subtropical fruit grown in California, Florida, Hawaii, and Puerto Rico. CITRUS FRUIT Maturity and Quality Harvesting and Packing Transportation Storage Storage Disorders and Control BANANAS Harvesting and Transportation Diseases and Deterioration Exposure to Excessive Temperatures Wholesale Processing Facilities SUBTROPICAL FRUIT Avocados Mangoes Pineapples', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2978, 'R18 -- Absorption Equipment (SI)', 'ASHRAE', '', '', '2022', '', '0', 17, '2407160916261', '', '', 'Numerous methods for predicting the cooling and freezing times of foods and beverages have been proposed, based on numerical, analytical, and empirical analysis. Selecting an appropriate estimation method from the many available methods can be challenging. This chapter reviews selected procedures available for estimating the air-blast convective cooling and freezing times of foods and beverages, and presents examples of these procedures. These procedures use the thermal properties of foods, discussed in Chapter 19. Thermodynamics of Cooling and Freezing Cooling Times of Foods and Beverages Sample Problems for Estimating Cooling Time Freezing Times of Foods and Beverages Sample Problems for Estimating Freezing Time Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2979, 'R34 -- Eggs and Egg Products (SI)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916262', '', '', 'This chapter covers the harvesting, handling, processing, storage requirements, and possible disorders of fresh market citrus fruit grown in Florida, California, Texas, and Arizona; of bananas; and of subtropical fruit grown in California, Florida, Hawaii, and Puerto Rico. CITRUS FRUIT Maturity and Quality Harvesting and Packing Transportation Storage Storage Disorders and Control BANANAS Harvesting and Transportation Diseases and Deterioration Exposure to Excessive Temperatures Wholesale Processing Facilities SUBTROPICAL FRUIT Avocados Mangoes Pineapples', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2980, 'R18 -- Absorption Equipment (I-P)', 'ASHRAE', '', '', '2022', '', '0', 17, '2407160916263', '', '', 'Thermal properties of foods and beverages must be known to perform the various heat transfer calculations involved in designing storage and refrigeration equipment and estimating process times for refrigerating, freezing, heating, or drying of foods and beverages. Because the thermal properties of foods and beverages strongly depend on chemical composition and temperature, and because many types of food are available, it is nearly impossible to experimentally determine and tabulate the thermal properties of foods and beverages for all possible conditions and compositions. However, composition data for foods and beverages are readily available from sources such as Holland et al. (1991) and USDA (1975). These data consist of the mass fractions of the major components found in foods. Thermal properties of foods can be predicted by using these composition data in conjunction with temperature-dependent mathematical models of thermal properties of the individual food constituents. Thermal Properties of Food Constituents Thermal Properties of Foods Water Content Initial Freezing Point Ice Fraction Density Specific Heat Enthalpy Thermal Conductivity Thermal Diffusivity Heat of Respiration Transpiration of Fresh Fruits and Vegetables Surface Heat Transfer Coefficient', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2981, 'R34 -- Eggs and Egg Products (I-P)', 'ASHRAE', '', '', '2022', '', '0', 14, '2407160916264', '', '', 'The most obvious losses from marketing fruit crops are caused by mechanical injury, decay, and aging. Losses in moisture, vitamins, and sugars are less obvious, but they adversely affect quality and nutrition. Rough handling and holding at undesirably high or low temperatures increase losses. Losses can be substantially reduced by greater care in handling and by following recommended storage practices. Fruit Storage and Handling Considerations Apples Pears Grapes Plums Sweet Cherries Peaches and Nectarines Apricots Berries Strawberries Figs Supplements to Refrigeration', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2982, 'R50 -- Terminology of Refrigeration (I-P)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916265', '', '', 'This chapter lists important codes and standards from a broad spectrum of engineering societies, and provides contact information for the issuing organizations.', '0.000000', 600.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2983, 'R17 -- Household Refrigerators and Freezers (SI)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916266', '', '', 'Thermal properties of foods and beverages must be known to perform the various heat transfer calculations involved in designing storage and refrigeration equipment and estimating process times for refrigerating, freezing, heating, or drying of foods and beverages. Because the thermal properties of foods and beverages strongly depend on chemical composition and temperature, and because many types of food are available, it is nearly impossible to experimentally determine and tabulate the thermal properties of foods and beverages for all possible conditions and compositions. However, composition data for foods and beverages are readily available from sources such as Holland et al. (1991) and USDA (1975). These data consist of the mass fractions of the major components found in foods. Thermal properties of foods can be predicted by using these composition data in conjunction with temperature-dependent mathematical models of thermal properties of the individual food constituents. Thermal Properties of Food Constituents Thermal Properties of Foods Water Content Initial Freezing Point Ice Fraction Density Specific Heat Enthalpy Thermal Conductivity Thermal Diffusivity Heat of Respiration Transpiration of Fresh Fruits and Vegetables Surface Heat Transfer Coefficient Symbols', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2984, 'R33 -- Dairy Products (SI)', 'ASHRAE', '', '', '2022', '', '0', 24, '2407160916267', '', '', 'The most obvious losses from marketing fruit crops are caused by mechanical injury, decay, and aging. Losses in moisture, vitamins, and sugars are less obvious, but they adversely affect quality and nutrition. Rough handling and holding at undesirably high or low temperatures increase losses. Losses can be substantially reduced by greater care in handling and by following recommended storage practices. Fruit Storage and Handling Considerations Apples Pears Grapes Plums Sweet Cherries Peaches and Nectarines Apricots Berries Strawberries Figs Supplements to Refrigeration', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2985, 'R49 -- Biomedical Applications of Cryogenic Refrigeration (SI)', 'ASHRAE', '', '', '2022', '', '0', 11, '2407160916268', '', '', 'This chapter lists important codes and standards from a broad spectrum of engineering societies, and provides contact information for the issuing organizations.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2986, 'R17 -- Household Refrigerators and Freezers (I-P)', 'ASHRAE', '', '', '2022', '', '0', 13, '2407160916269', '', '', 'This chapter surveys and summarizes the types of absorption equipment that are currently manufactured and/or commonly encountered. The equipment can be broadly categorized by whether it uses water or ammonia as refrigerant. The primary products in the water refrigerant category are large commercial chillers, which use lithium bromide (LiBr) as absorbent. There are three primary products in the ammonia refrigerant category: (1) domestic refrigerators, (2) residential chillers, and (3) industrial refrigeration units. WATER/LITHIUM BROMIDE ABSORPTION EQUIPMENT Components and Terminology Equipment Types Chiller and Heat Pump Operation Machine Setup and Maintenance AMMONIA/WATER ABSORPTION EQUIPMENT Residential Chillers and Components Domestic Absorption Refrigerators and Controls Industrial Absorption Refrigeration Units SPECIAL APPLICATIONS AND EMERGING PRODUCTS Combination Systems: Power Production with Waste Heat-Activated Absorption Cooling Triple-Effect Cycles Generator-Absorber Heat Exchange (GAX) Cycle Solid/Vapor Sorption Systems Liquid Desiccant/Absorption Systems INFORMATION SOURCES', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2987, 'R33 -- Dairy Products (I-P)', 'ASHRAE', '', '', '2022', '', '0', 24, '2407160916270', '', '', 'About 69% of the table eggs produced in the United States are sold as shell eggs. The remainder are further processed into liquid, frozen, or dehydrated egg products that are used in food service or as an ingredient in food products. Small amounts of further processed eggs are converted to retail egg products, mainly mayonnaise, salad dressings, and egg substitutes. Shell egg processing includes cleaning, washing, drying, candling for interior and exterior defects, sizing, and packaging. Further processed eggs require shell removal, filtering, blending, pasteurization, and possibly freezing or dehydration. SHELL EGGS Egg Structure and Composition Egg Quality and Safety Shell Egg Processing Effect of Refrigeration on Egg Quality and Safety Packaging Transportation EGG PRODUCTS Egg Breaking Refrigerated Liquid Egg Products Frozen Egg Products Dehydrated Egg Products Egg Product Quality Sanitary Standards and Plant Sanitation', '0.000000', 51.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2988, 'R49 -- Biomedical Applications of Cryogenic Refrigeration (I-P)', 'ASHRAE', '', '', '2022', '', '0', 11, '2407160916271', '', '', 'This chapter seeks to define some of the common terms used in industrial refrigeration systems, specifically those using ammonia as the refrigerant. The following glossary was compiled from a variety of sources throughout the industry, including ASHRAE, the International Institute of Ammonia Refrigeration (IIAR), the U.S. Occupational Safety and Health Administration (OSHA), and the U.S. Environmental Protection Agency (EPA). Specific sources for entries are listed in the endnotes. Minor edits for punctuation, conciseness, and consistency with usage elsewhere in the Handbook have been made.', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2989, 'R16 -- Food Service and General Commercial Refrigeration Equipment (SI)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916272', '', '', 'This chapter surveys and summarizes the types of absorption equipment that are currently manufactured and/or commonly encountered. The equipment can be broadly categorized by whether it uses water or ammonia as refrigerant. The primary products in the water refrigerant category are large commercial chillers, which use lithium bromide (LiBr) as absorbent. There are three primary products in the ammonia refrigerant category: (1) domestic refrigerators, (2) residential chillers, and (3) industrial refrigeration units. WATER/LITHIUM BROMIDE ABSORPTION EQUIPMENT Components and Terminology Equipment Types Chiller and Heat Pump Operation Machine Setup and Maintenance AMMONIA/WATER ABSORPTION EQUIPMENT Residential Chillers and Components Domestic Absorption Refrigerators and Controls Industrial Absorption Refrigeration Units SPECIAL APPLICATIONS AND EMERGING PRODUCTS Combination Systems: Power Production with Waste Heat-Activated Absorption Cooling Triple-Effect Cycles Generator-Absorber Heat Exchange (GAX) Cycle Solid/Vapor Sorption Systems Liquid Desiccant/Absorption Systems INFORMATION SOURCES', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2990, 'R16 -- Food Service and General Commercial Refrigeration Equipment (I-P)', 'ASHRAE', '', '', '2022', '', '0', 8, '2407160916273', '', '', 'This chapter covers design and construction of household refrigerators and freezers. Providing optimized conditions for preserving stored food is the primary function of a refrigerator or freezer. This is done by storing food at reduced temperature. Ice making is an essential secondary function in some markets. A related product, the wine chiller, provides optimum temperatures for storing wine, at temperatures from 45 to 65°F (7 to 18°C). Wine chillers are often manufactured by the same companies using the same technologies as refrigerators and freezers. Dual-use products combining a wine storage compartment with fresh-food and/or freezer compartments have also been manufactured. Primary Functions Cabinets Refrigerating Systems Performance and Evaluation Safety Requirements Durability and Service', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2991, 'R15 -- Retail Food Store Refrigeration and Equipment (SI)', 'ASHRAE', '', '', '2022', '', '0', 30, '2407160916274', '', '', 'This chapter covers design and construction of household refrigerators and freezers. Providing optimized conditions for preserving stored food is the primary function of a refrigerator or freezer. This is done by storing food at reduced temperature. Ice making is an essential secondary function in some markets. A related product, the wine chiller, provides optimum temperatures for storing wine, at temperatures from 45 to 65°F (7 to 18°C). Wine chillers are often manufactured by the same companies using the same technologies as refrigerators and freezers. Dual-use products combining a wine storage compartment with fresh-food and/or freezer compartments have also been manufactured. Primary Functions Cabinets Refrigerating Systems Performance and Evaluation Safety Requirements Durability and Service', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2992, 'R15 -- Retail Food Store Refrigeration and Equipment (I-P)', 'ASHRAE', '', '', '2022', '', '0', 30, '2407160916275', '', '', 'Food service requires refrigerators that meet a variety of needs. This chapter covers refrigerators available for restaurants, fast-food restaurants, cafeterias, commissaries, hospitals, schools, convenience stores, grocery stores, and other specialized applications. Many refrigeration products used in food service applications are self-contained, and the corresponding refrigeration systems are conventional. Some systems, however, do use ice for fish, salad pans, or specialized preservation and/or display. Chapters 15 and 17 have further information on some of these products. Refrigerated Cabinets Food Freezers Blast Chillers and Blast Freezers Walk-In Coolers/Freezers Vending Machines Ice Machines Preparation Tables', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2993, 'R14 -- Forced-Circulation Air Coolers (SI)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916276', '', '', 'Food service requires refrigerators that meet a variety of needs. This chapter covers refrigerators available for restaurants, fast-food restaurants, cafeterias, commissaries, hospitals, schools, convenience stores, grocery stores, and other specialized applications. Many refrigeration products used in food service applications are self-contained, and the corresponding refrigeration systems are conventional. Some systems, however, do use ice for fish, salad pans, or specialized preservation and/or display. Chapters 15 and 17 have further information on some of these products. Refrigerated Cabinets Food Freezers Blast Chillers and Blast Freezers Walk-In Coolers/Freezers Vending Machines Ice Machines Preparation Tables', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2994, 'R14 -- Forced-Circulation Air Coolers (I-P)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916277', '', '', 'In the United States, over 227,000 retail food stores operate their refrigeration systems around the clock to ensure proper merchandising and safety of their food products. Supermarkets and convenience stores make the largest contribution to this total (Progressive Grocer 2017). In U.S. retail food stores, refrigeration consumes about 2.3% of the total electricity consumed by all commercial buildings (EIA 2003). Refrigeration accounts for roughly 50% of the electric energy consumption of a typical supermarket (Arthur D. Little 1996). Display Refrigerators Refrigerated Storage Rooms Refrigeration Systems Condensing Methods Methods of Defrost Sustainable Retail Refrigeration Liquid Subcooling Strategies Heat Reclaim Strategies Supermarket Air-Conditioning Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2995, 'R13 -- Secondary Coolants in Refrigeration Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916278', '', '', 'In the United States, over 227,000 retail food stores operate their refrigeration systems around the clock to ensure proper merchandising and safety of their food products. Supermarkets and convenience stores make the largest contribution to this total (Progressive Grocer 2017). In U.S. retail food stores, refrigeration consumes about 2.3% of the total electricity consumed by all commercial buildings (EIA 2003). Refrigeration accounts for roughly 50% of the electric energy consumption of a typical supermarket (Arthur D. Little 1996). Display Refrigerators Refrigerated Storage Rooms Refrigeration Systems Condensing Methods Methods of Defrost Sustainable Retail Refrigeration Liquid Subcooling Strategies Heat Reclaim Strategies Supermarket Air-Conditioning Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2996, 'R13 -- Secondary Coolants in Refrigeration Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916279', '', '', 'Forced-circulation unit coolers and product coolers are designed to operate continuously in refrigerated enclosures; a cooling coil and motor-driven fan are their basic components, and provide cooling or freezing temperatures and proper airflow to the room. Coil defrost equipment is added for low-temperature operations when coil frosting might impede performance. Any unit (e.g., blower coil, unit cooler, product cooler, cold diffuser unit, air-conditioning air handler) is considered a forced-air cooler when operated under refrigeration conditions. Types of Forced-Circulation Air Coolers Components Air Movement and Distribution Unit Ratings Installation and Operation More Information', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2997, 'R12 -- Lubricants in Refrigerant Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 36, '2407160916280', '', '', 'Forced-circulation unit coolers and product coolers are designed to operate continuously in refrigerated enclosures; a cooling coil and motor-driven fan are their basic components, and provide cooling or freezing temperatures and proper airflow to the room. Coil defrost equipment is added for low-temperature operations when coil frosting might impede performance. Any unit (e.g., blower coil, unit cooler, product cooler, cold diffuser unit, air-conditioning air handler) is considered a forced-air cooler when operated under refrigeration conditions. Types of Forced-Circulation Air Coolers Components Air Movement and Distribution Unit Ratings Installation and Operation More Information', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2998, 'R12 -- Lubricants in Refrigerant Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 36, '2407160916281', '', '', 'Secondary coolants are liquids used as heat transfer fluids that change temperature as they gain or lose heat energy without changing into another phase. For lower refrigeration temperatures, this requires a coolant with a freezing point below that of water. These are generally called brines by the industry. This chapter discusses design considerations for components, system performance requirements, and applications for secondary coolants. Related information can be found in Chapters 3, 4, 22, 30, and 31 of the 2021 ASHRAE Handbook—Fundamentals. Coolant Selection Design Considerations Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(2999, 'R11 -- Refrigerant Control Devices (SI)', 'ASHRAE', '', '', '2022', '', '0', 34, '2407160916282', '', '', 'Secondary coolants are liquids used as heat transfer fluids that change temperature as they gain or lose heat energy without changing into another phase. For lower refrigeration temperatures, this requires a coolant with a freezing point below that of water. These are generally called brines by the industry. This chapter discusses design considerations for components, system performance requirements, and applications for secondary coolants. Related information can be found in Chapters 3, 4, 22, 30, and 31 of the 2021 ASHRAE Handbook—Fundamentals. Coolant Selection Design Considerations Applications', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3000, 'R11 -- Refrigerant Control Devices (I-P)', 'ASHRAE', '', '', '2022', '', '0', 34, '2407160916283', '', '', 'The primary function of a lubricant is to reduce friction and minimize wear. It achieves this by interposing a film between moving surfaces that reduces direct solid-to-solid contact or lowers the coefficient of friction. Understanding the role of a lubricant requires analysis of the surfaces to be lubricated. Although bearing surfaces and other machined parts may appear and feel smooth, close examination reveals microscopic peaks (asperities) and valleys. Lubricant, in sufficient amounts, creates a layer thicker than the maximum height of the mating asperities, so that moving parts ride on a lubricant cushion. Tests for Boundary and Mixed Lubrication Refrigeration Lubricant Requirements Synthetic Lubricants Mineral Oil Composition and Component Characteristics Lubricant Additives Lubricant Properties Lubricant/Refrigerant Solutions Lubricant Influence on Lubricant Return Lubricant Influence on System Performance Wax Separation (Floc Tests) Solubility of Hydrocarbon Gases Lubricants for Carbon Dioxide Solubility of Water in Lubricants Solubility of Air in Lubricants Foaming and Antifoam Agents Oxidation Resistance Chemical Stability Retrofitting from CFC/HCFC to Other Refrigerants', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3001, 'R10 -- Insulation Systems for Refrigerant Piping (SI)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916284', '', '', 'The primary function of a lubricant is to reduce friction and minimize wear. It achieves this by interposing a film between moving surfaces that reduces direct solid-to-solid contact or lowers the coefficient of friction. Understanding the role of a lubricant requires analysis of the surfaces to be lubricated. Although bearing surfaces and other machined parts may appear and feel smooth, close examination reveals microscopic peaks (asperities) and valleys. Lubricant, in sufficient amounts, creates a layer thicker than the maximum height of the mating asperities, so that moving parts ride on a lubricant cushion. Tests for Boundary and Mixed Lubrication Refrigeration Lubricant Requirements Synthetic Lubricants Mineral Oil Composition and Component Characteristics Lubricant Additives Lubricant Properties Lubricant/Refrigerant Solutions Lubricant Influence on Lubricant Return Lubricant Influence on System Performance Wax Separation (Floc Tests) Solubility of Hydrocarbon Gases Lubricants for Carbon Dioxide Solubility of Water in Lubricants Solubility of Air in Lubricants Foaming and Antifoam Agents Oxidation Resistance Chemical Stability Retrofitting from CFC/HCFC to Other Refrigerants', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3002, 'R10 -- Insulation Systems for Refrigerant Piping (I-P)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916285', '', '', 'Control of refrigerant flow, temperatures, pressures, and liquid levels is essential in any refrigeration system. This chapter describes a variety of devices and their application to accomplish these important control functions. Most examples, references, and capacity data in this chapter refer to the more common refrigerants. For further information on control fundamentals, see Chapter 7 of the 2021 ASHRAE Handbook—Fundamentals and Chapter 47 of the 2019 ASHRAE Handbook—HVAC Applications. CONTROL SWITCHES Pressure Switches Temperature Switches (Thermostats) Differential Switches Float Switches CONTROL SENSORS Pressure Transducers Thermistors Resistance Temperature Detectors Thermocouples Liquid Level Sensors CONTROL VALVES Thermostatic Expansion Valves Electric Expansion Valves REGULATING AND THROTTLING VALVES Evaporator-Pressure-Regulating Valves Constant-Pressure Expansion Valves Suction-Pressure-Regulating Valves Condenser-Pressure-Regulating Valves Discharge Bypass Valves High-Side Float Valves Low-Side Float Valves Solenoid Valves Condensing Water Regulators Check Valves Relief Devices DISCHARGE-LINE LUBRICANT SEPARATORS CAPILLARY TUBES Adiabatic Capillary Tube Selection Procedure Capillary-Tube/Suction-Line Heat Exchanger Selection Procedure SHORT-TUBE RESTRICTORS', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3003, 'R09 -- Refrigerant Containment, Recovery, Recycling, and Reclamation (SI)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916286', '', '', 'Control of refrigerant flow, temperatures, pressures, and liquid levels is essential in any refrigeration system. This chapter describes a variety of devices and their application to accomplish these important control functions. Most examples, references, and capacity data in this chapter refer to the more common refrigerants. For further information on control fundamentals, see Chapter 7 of the 2021 ASHRAE Handbook—Fundamentals and Chapter 47 of the 2019 ASHRAE Handbook—HVAC Applications. CONTROL SWITCHES Pressure Switches Temperature Switches (Thermostats) Differential Switches Float Switches CONTROL SENSORS Pressure Transducers Thermistors Resistance Temperature Detectors Thermocouples Liquid Level Sensors CONTROL VALVES Thermostatic Expansion Valves Electric Expansion Valves REGULATING AND THROTTLING VALVES Evaporator-Pressure-Regulating Valves Constant-Pressure Expansion Valves Suction-Pressure-Regulating Valves Condenser-Pressure-Regulating Valves Discharge Bypass Valves High-Side Float Valves Low-Side Float Valves Solenoid Valves Condensing Water Regulators Check Valves Relief Devices DISCHARGE-LINE LUBRICANT SEPARATORS CAPILLARY TUBES Adiabatic Capillary Tube Selection Procedure Capillary-Tube/Suction-Line Heat Exchanger Selection Procedure SHORT-TUBE RESTRICTORS', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3004, 'R09 -- Refrigerant Containment, Recovery, Recycling, and Reclamation (I-P)', 'ASHRAE', '', '', '2022', '', '0', 6, '2407160916287', '', '', 'This chapter is a guide to specifying insulation systems for refrigeration piping, fittings, and vessels operated at temperatures ranging from 35 to –100°F (2 to –70°C). It does not deal with HVAC systems or applications such as chilled-water systems. See Chapters 23, 25, 26, and 27 in the 2021 ASHRAE Handbook—Fundamentals for information about insulation and vapor retarders (barriers) for these systems. Design Considerations for Below-Ambient Refrigerant Piping Insulation Properties at Below Ambient Temperatures Insulation System Moisture Resistance Insulation Systems Installation Guidelines Maintenance of Insulation Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3005, 'R08 -- Equipment and System Dehydrating, Charging, and Testing (SI)', 'ASHRAE', '', '', '2022', '', '0', 7, '2407160916288', '', '', 'This chapter is a guide to specifying insulation systems for refrigeration piping, fittings, and vessels operated at temperatures ranging from 35 to –100°F (2 to –70°C). It does not deal with HVAC systems or applications such as chilled-water systems. See Chapters 23, 25, 26, and 27 in the 2021 ASHRAE Handbook—Fundamentals for information about insulation and vapor retarders (barriers) for these systems. Design Considerations for Below-Ambient Refrigerant Piping Insulation Properties at Below Ambient Temperatures Insulation System Moisture Resistance Insulation Systems Installation Guidelines Maintenance of Insulation Systems', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3006, 'R08 -- Equipment and System Dehydrating, Charging, and Testing (I-P)', 'ASHRAE', '', '', '2022', '', '0', 7, '2407160916289', '', '', 'Containment of refrigerant is an important consideration during installation, service, maintenance, and decommissioning of refrigeration systems. The potential environmental effect of chlorofluorocarbon (CFC) and hydrochlorofluorocarbon (HCFC) refrigerants on ozone depletion, and of these and the hydrofluorocarbon (HFC) and hydrofluoroolefin (HFO) refrigerants on global warming, make it imperative that refrigerants are confined to closed systems and recovered during service and at the end of life. Containment must be considered in all phases of a system’s life, including (1) design and construction of leaktight and easily serviced systems, (2) leak detection and repair, (3) recovery during service, and (4) recovery at system disposal. Additional reference can be found in ASHRAE Standard 147. Emissions Types Design Installation Servicing and Decommissioning Training Leak Detection Recovery, Recycling, and Reclamation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3007, 'R07 -- Control of Moisture and Other Contaminants in Refrigerant Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916290', '', '', 'Containment of refrigerant is an important consideration during installation, service, maintenance, and decommissioning of refrigeration systems. The potential environmental effect of chlorofluorocarbon (CFC) and hydrochlorofluorocarbon (HCFC) refrigerants on ozone depletion, and of these and the hydrofluorocarbon (HFC) and hydrofluoroolefin (HFO) refrigerants on global warming, make it imperative that refrigerants are confined to closed systems and recovered during service and at the end of life. Containment must be considered in all phases of a system’s life, including (1) design and construction of leaktight and easily serviced systems, (2) leak detection and repair, (3) recovery during service, and (4) recovery at system disposal. Additional reference can be found in ASHRAE Standard 147. Emissions Types Design Installation Servicing and Decommissioning Training Leak Detection Recovery, Recycling, and Reclamation', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3008, 'R07 -- Control of Moisture and Other Contaminants in Refrigerant Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916291', '', '', 'Proper dehydration, charging, and testing of packaged refrigeration systems and components (compressors, evaporators, and condensing coils) help ensure proper performance and extend the life of refrigeration systems. This chapter covers the methods used to perform these functions. It does not address criteria such as allowable moisture content, refrigerant quantity, and performance, which are specific to each machine. Dehydration (Moisture Removal) Moisture Measurement Charging Testing for Leaks Performance Testing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3009, 'R06 -- Refrigerant System Chemistry (SI)', 'ASHRAE', '', '', '2022', '', '0', 16, '2407160916292', '', '', 'Proper dehydration, charging, and testing of packaged refrigeration systems and components (compressors, evaporators, and condensing coils) help ensure proper performance and extend the life of refrigeration systems. This chapter covers the methods used to perform these functions. It does not address criteria such as allowable moisture content, refrigerant quantity, and performance, which are specific to each machine. Dehydration (Moisture Removal) Moisture Measurement Charging Testing for Leaks Performance Testing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3010, 'R06 -- Refrigerant System Chemistry (I-P)', 'ASHRAE', '', '', '2022', '', '0', 16, '2407160916293', '', '', 'Moisture (water) is an important and universal contaminant in refrigeration systems. The amount of moisture in a refrigerant system must be kept below an allowable maximum for satisfactory operation, efficiency, and longevity. Moisture must be removed from components during manufacture, assembly, and service to minimize the amount of moisture in the completed system. Any moisture that enters during installation or servicing should be removed promptly. Refrigerant filter-driers are the principal devices used to remove contaminants from refrigeration systems. The filter-drier is not a substitute for good workmanship or design, but a maintenance tool necessary for continued and proper system performance. Contaminants removed by filter-driers include moisture, acids, hydrocarbons with a high molecular weight, oil decomposition products, and insoluble material, such as metallic particles and copper oxide. Moisture Other Contaminants System Cleanup Procedure After Hermetic Motor Burnout Contaminant Control During Retrofit Chiller Decontamination System Sampling', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3011, 'R05 -- Component Balancing in Refrigeration Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 4, '2407160916294', '', '', 'Moisture (water) is an important and universal contaminant in refrigeration systems. The amount of moisture in a refrigerant system must be kept below an allowable maximum for satisfactory operation, efficiency, and longevity. Moisture must be removed from components during manufacture, assembly, and service to minimize the amount of moisture in the completed system. Any moisture that enters during installation or servicing should be removed promptly. Refrigerant filter-driers are the principal devices used to remove contaminants from refrigeration systems. The filter-drier is not a substitute for good workmanship or design, but a maintenance tool necessary for continued and proper system performance. Contaminants removed by filter-driers include moisture, acids, hydrocarbons with a high molecular weight, oil decomposition products, and insoluble material, such as metallic particles and copper oxide. Moisture Other Contaminants System Cleanup Procedure After Hermetic Motor Burnout Contaminant Control During Retrofit Chiller Decontamination System Sampling', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3012, 'R05 -- Component Balancing in Refrigeration Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 4, '2407160916295', '', '', 'System chemistry deals with any chemical reactions that could take place in an HVAC&R system between refrigerants, lubricants, and construction materials of various system components (e.g., compressor, heat transfer coils, connecting tubing, expansion device). Higher temperatures or contaminants such as air, moisture, or residual process chemicals (e.g., metal cutting fluids, cleaning agents) complicate chemical interactions between components. Phase changes occur in the refrigeration cycle; in particular, the temperature extremes from the highest discharge line temperature to the lowest evaporating temperature are of importance to the end user. This chapter covers the chemical aspects of refrigerants and lubricants, and their compatibility with each other as well as with system materials. Two distinct chemical evaluations are generally undertaken when considering new refrigerant or lubricant candidates: (1) chemical compatibility testing to assess the stability of refrigerant and lubricant with each other and with system components, and (2) material compatibility testing to assess the stability of system component materials with refrigerant and/or lubricant. Lubricants are extensively covered in Chapter 12, and contaminant control is discussed in Chapter 7. Detailed information on various refrigerants is provided in Chapters 1 and 2 of this volume, and in Chapters 29 and 30 of the 2021 ASHRAE Handbook—Fundamentals. Refrigerants Lubricants System Reactions Compatibility of Materials Chemical Evaluation Techniques', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3013, 'R04 -- Liquid Overfeed Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 10, '2407160916296', '', '', 'System chemistry deals with any chemical reactions that could take place in an HVAC&R system between refrigerants, lubricants, and construction materials of various system components (e.g., compressor, heat transfer coils, connecting tubing, expansion device). Higher temperatures or contaminants such as air, moisture, or residual process chemicals (e.g., metal cutting fluids, cleaning agents) complicate chemical interactions between components. Phase changes occur in the refrigeration cycle; in particular, the temperature extremes from the highest discharge line temperature to the lowest evaporating temperature are of importance to the end user. This chapter covers the chemical aspects of refrigerants and lubricants, and their compatibility with each other as well as with system materials. Two distinct chemical evaluations are generally undertaken when considering new refrigerant or lubricant candidates: (1) chemical compatibility testing to assess the stability of refrigerant and lubricant with each other and with system components, and (2) material compatibility testing to assess the stability of system component materials with refrigerant and/or lubricant. Lubricants are extensively covered in Chapter 12, and contaminant control is discussed in Chapter 7. Detailed information on various refrigerants is provided in Chapters 1 and 2 of this volume, and in Chapters 29 and 30 of the 2021 ASHRAE Handbook—Fundamentals. Refrigerants Lubricants System Reactions Compatibility of Materials Chemical Evaluation Techniques', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3014, 'R04 -- Liquid Overfeed Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 10, '2407160916297', '', '', 'This chapter describes methods and components used in balancing a primary refrigeration system. A refrigerant is a fluid used for heat transfer in a refrigeration system. The fluid absorbs heat at a low temperature and pressure and transfers heat at a higher temperature and pressure. Heat transfer can involve either a complete or partial change of state in the case of a primary refrigerant. Energy transfer is a function of the heat transfer coefficients; temperature differences; and amount, type, and configuration of the heat transfer surface and, hence, the heat flux on either side of the heat transfer device. Refrigeration System Components Selecting Design Balance Points Energy and Mass Balances System Performance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3015, 'R03 -- Carbon Dioxide Refrigeration Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916298', '', '', 'This chapter describes methods and components used in balancing a primary refrigeration system. A refrigerant is a fluid used for heat transfer in a refrigeration system. The fluid absorbs heat at a low temperature and pressure and transfers heat at a higher temperature and pressure. Heat transfer can involve either a complete or partial change of state in the case of a primary refrigerant. Energy transfer is a function of the heat transfer coefficients; temperature differences; and amount, type, and configuration of the heat transfer surface and, hence, the heat flux on either side of the heat transfer device. Refrigeration System Components Selecting Design Balance Points Energy and Mass Balances System Performance', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3016, 'R03 -- Carbon Dioxide Refrigeration Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 12, '2407160916299', '', '', 'Overfeed systems force liquid in excess of the amount evaporated, either mechanically or by gas pressure, through organized-flow evaporators, separate it from the vapor, and return it to the evaporators. Mechanically pumped systems usually pump from a vessel at the connected suction pressure (i.e., low-temperature liquid). Gas-operated systems can be configured to deliver either low-temperature liquid directly like the mechanically pumped system, or subcooled liquid from a controlled pressure receiver at an intermediate pressure. With the latter, the accumulated overfed liquid is transferred from the low-pressure receiver back to the controlled-pressure receiver. Overfeed System Operation Refrigerant Distribution Oil in System Circulating Rate Pump Selection and Installation Controls Evaporator Design Refrigerant Charge Start-Up and Operation Line Sizing Low-Pressure Receiver Sizing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3017, 'R02 -- Ammonia Refrigeration Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 28, '2407160916300', '', '', 'Overfeed systems force liquid in excess of the amount evaporated, either mechanically or by gas pressure, through organized-flow evaporators, separate it from the vapor, and return it to the evaporators. Mechanically pumped systems usually pump from a vessel at the connected suction pressure (i.e., low-temperature liquid). Gas-operated systems can be configured to deliver either low-temperature liquid directly like the mechanically pumped system, or subcooled liquid from a controlled pressure receiver at an intermediate pressure. With the latter, the accumulated overfed liquid is transferred from the low-pressure receiver back to the controlled-pressure receiver. Overfeed System Operation Refrigerant Distribution Oil in System Circulating Rate Pump Selection and Installation Controls Evaporator Design Refrigerant Charge Start-Up and Operation Line Sizing Low-Pressure Receiver Sizing', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3018, 'R02 -- Ammonia Refrigeration Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 28, '2407160916301', '', '', 'Carbon dioxide (R-744) is one of the naturally occurring compounds collectively known as “natural refrigerants.” It is nonflammable and nontoxic, with no known carcinogenic, mutagenic, or other toxic effects, and no dangerous products of combustion. Using carbon dioxide in refrigerating systems can be considered a form of carbon capture, with a potential beneficial effect on climate change. It has no adverse local environmental effects. In recent years, CO2 has once again become a refrigerant of great interest. However, high-pressure CO2 systems [e.g., 490.8 psia (3.4 MPa) at a saturation temperature of 30°F (–1°C), or 969.6 psia (6.7 MPa) at 80°F (26.7°C)] present some challenges for containment and safety. Applications System Design System Safety Piping Heat Exchangers and Vessels Compressors for CO2 Refrigeration Systems Lubricants Evaporators Defrost Installation, Start-up, and Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3019, 'R01 -- Halocarbon Refrigeration Systems (SI)', 'ASHRAE', '', '', '2022', '', '0', 38, '2407160916302', '', '', 'Carbon dioxide (R-744) is one of the naturally occurring compounds collectively known as “natural refrigerants.” It is nonflammable and nontoxic, with no known carcinogenic, mutagenic, or other toxic effects, and no dangerous products of combustion. Using carbon dioxide in refrigerating systems can be considered a form of carbon capture, with a potential beneficial effect on climate change. It has no adverse local environmental effects. In recent years, CO2 has once again become a refrigerant of great interest. However, high-pressure CO2 systems [e.g., 490.8 psia (3.4 MPa) at a saturation temperature of 30°F (–1°C), or 969.6 psia (6.7 MPa) at 80°F (26.7°C)] present some challenges for containment and safety. Applications System Design System Safety Piping Heat Exchangers and Vessels Compressors for CO2 Refrigeration Systems Lubricants Evaporators Defrost Installation, Start-up, and Commissioning', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0);
INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(3020, 'R01 -- Halocarbon Refrigeration Systems (I-P)', 'ASHRAE', '', '', '2022', '', '0', 38, '2407160916303', '', '', 'Ammonia is the refrigerant of choice for many industrial refrigeration systems. Custom-engineered ammonia (R-717) refrigeration systems often have design conditions that span a wide range of evaporating and condensing temperatures. Examples are (1) a food freezing plant operating from +50 to –50°F (10 to –45°C); (2) a candy storage requiring 60°F (15°C) db with precise humidity control; (3) a beef chill room at 28 to 30°F (–2 to –1°C) with high humidity; (4) a distribution warehouse requiring multiple temperatures for storing ice cream, frozen food, meat, and produce and for docks; and (5) a chemical process requiring multiple temperatures ranging from +60 to –60°F (15 to –50°C). EQUIPMENT Compressors Condensers Evaporators Evaporator Piping Vessels Piping Controls SYSTEMS Single-Stage Systems Economized Systems Multistage Systems Liquid Recirculation Systems Safety Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3021, 'R for Conservation and Development Projects A Primer for Practitioners', 'Author: Nathan Whitmore', '', '', '12/22/2020 12:00:00 AM', '', '0', 391, '2407160916304', '', '', 'Ammonia is the refrigerant of choice for many industrial refrigeration systems. Custom-engineered ammonia (R-717) refrigeration systems often have design conditions that span a wide range of evaporating and condensing temperatures. Examples are (1) a food freezing plant operating from +50 to –50°F (10 to –45°C); (2) a candy storage requiring 60°F (15°C) db with precise humidity control; (3) a beef chill room at 28 to 30°F (–2 to –1°C) with high humidity; (4) a distribution warehouse requiring multiple temperatures for storing ice cream, frozen food, meat, and produce and for docks; and (5) a chemical process requiring multiple temperatures ranging from +60 to –60°F (15 to –50°C). EQUIPMENT Compressors Condensers Evaporators Evaporator Piping Vessels Piping Controls SYSTEMS Single-Stage Systems Economized Systems Multistage Systems Liquid Recirculation Systems Safety Considerations', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3022, 'R Markdown: The Definitive Guide', 'Garrett Grolemund|Yihui Xie, J.J. Allaire', '', '', '7/19/2018 12:00:00 AM', '', '0', 339, '2407160916305', '', '', 'This chapter focuses on systems that use halocarbons (halogenated hydrocarbons) as refrigerants. The most commonly used halogen refrigerants are chlorine (Cl) and fluorine (F). Halocarbon refrigerants are classified into four groups: chlorofluorocarbons (CFCs), which contain carbon, chlorine, and fluorine; hydrochlorofluorocarbons (HCFCs), which consist of carbon, hydrogen, chlorine, and fluorine; hydrofluorocarbons (HFCs), which contain carbon, hydrogen, and fluorine; and hydrofluoroolefins (HFOs), which are HFC refrigerants derived from an alkene (olefin; i.e., an unsaturated compound having at least one carbon-to-carbon double bond). Examples of these refrigerants can be found in Chapter 29 of the 2021 ASHRAE Handbook—Fundamentals. Application System Safety Basic Piping Principles Refrigerant Line Sizing Piping at Multiple Compressors Piping at Various System Components Discharge (Hot-Gas) Lines Defrost Gas Supply Lines Heat Exchangers and Vessels Refrigeration Accessories Head Pressure Control for Refrigerant Condensers Keeping Liquid from Crankcase During Off Cycles Hot-Gas Bypass Arrangements Minimizing Refrigerant Charge in Commercial Systems Refrigerant Retrofitting Temperature Glide', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3023, 'Quick Java', 'Author: David Matuszek', '', '', '1/1/2024 12:00:00 AM', '', '0', 235, '2407160916306', '', '', 'This chapter focuses on systems that use halocarbons (halogenated hydrocarbons) as refrigerants. The most commonly used halogen refrigerants are chlorine (Cl) and fluorine (F). Halocarbon refrigerants are classified into four groups: chlorofluorocarbons (CFCs), which contain carbon, chlorine, and fluorine; hydrochlorofluorocarbons (HCFCs), which consist of carbon, hydrogen, chlorine, and fluorine; hydrofluorocarbons (HFCs), which contain carbon, hydrogen, and fluorine; and hydrofluoroolefins (HFOs), which are HFC refrigerants derived from an alkene (olefin; i.e., an unsaturated compound having at least one carbon-to-carbon double bond). Examples of these refrigerants can be found in Chapter 29 of the 2021 ASHRAE Handbook—Fundamentals. Application System Safety Basic Piping Principles Refrigerant Line Sizing Piping at Multiple Compressors Piping at Various System Components Discharge (Hot-Gas) Lines Defrost Gas Supply Lines Heat Exchangers and Vessels Refrigeration Accessories Head Pressure Control for Refrigerant Condensers Keeping Liquid from Crankcase During Off Cycles Hot-Gas Bypass Arrangements Minimizing Refrigerant Charge in Commercial Systems Refrigerant Retrofitting Temperature Glide', '0.000000', 55.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3024, 'ASHRAE GreenGuide -- Design, Construction, and Operation of Sustainable Buildings, Fifth Edition - Portuguese', 'ASHRAE', '', '', '2023', '', '0', 544, '2407160916307', '', '', '', '0.000000', 115.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3025, 'CPSC 16 CFR PART 1250 SAFETY STANDARD MANDATING ASTM F963 FOR TOYS', 'Clinical and Laboratory Standards Institute', '', '', '1/1/2023 12:00:00 AM', '', '0', 1, '2407160916308', '', '', 'Air pollution, global warming, and the steady decrease in petroleum resources continue to stimulate interest in the development of safe, clean, and highly efficient transportation. Building on the foundation of the bestselling first edition, Modern Electric, Hybrid Electric, and Fuel Cell Vehicles: Fundamentals, Theory, and Design, Second Edition updates and expands its detailed coverage of the vehicle technologies that offer the most promising solutions to these issues affecting the automotive industry. Proven as a useful in-depth resource and comprehensive reference for modern automotive systems engineers, students, and researchers, this book speaks from the perspective of the overall drive train system and not just its individual components. New to the second edition: A case study appendix that breaks down the Toyota Prius hybrid system Corrections and updates of the material in the first edition Three new chapters on drive train design methodology and control principles A completely rewritten chapter on Fundamentals of Regenerative Braking Employing sufficient mathematical rigor, the authors comprehensively cover vehicle performance characteristics, EV and HEV configurations, control strategies, modeling, and simulations for modern vehicles. They also cover topics including: Drive train architecture analysis and design methodologies Internal Combustion Engine (ICE)-based drive trains Electric propulsion systems Energy storage systems Regenerative braking Fuel cell applications in vehicles Hybrid-electric drive train design The first edition of this book gave practicing engineers and students a systematic reference to fully understand the essentials of this new technology. This edition introduces newer topics and offers deeper treatments than those included in the first. Revised many times over many years, it will greatly aid engineers, students, researchers, and other professionals who are working in automotive-related industries, as well as those in government and academia.', '0.000000', 28.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3027, 'AOAC METHODS AOAC OFFICIAL METHODS OF ANALYSIS', 'AOAC International', '', '', '6/7/2023 12:00:00 AM', '', '0', 0, '2407160916310', '', '', '', '0.000000', 1.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3028, 'ENVIRONMENTAL CHEMICAL ANALYSIS', 'B.B. Kebbekus|Pradyot Patnaik|S. Mitra', '', '', '7/19/2018 12:00:00 AM', '', '0', 451, '2407160916311', '', '', 'With its flexible capabilities and open-source platform, R has become a major tool for analyzing detailed, high-quality baseball data. Analyzing Baseball Data with R provides an introduction to R for sabermetricians, baseball enthusiasts, and students interested in exploring the rich sources of baseball data. It equips readers with the necessary skills and software tools to perform all of the analysis steps, from gathering the datasets and entering them in a convenient format to visualizing the data via graphs to performing a statistical analysis. The authors first present an overview of publicly available baseball datasets and a gentle introduction to the type of data structures and exploratory and data management capabilities of R. They also cover the traditional graphics functions in the base package and introduce more sophisticated graphical displays available through the lattice and ggplot2 packages. Much of the book illustrates the use of R through popular sabermetrics topics, including the Pythagorean formula, runs expectancy, career trajectories, simulation of games and seasons, patterns of streaky behavior of players, and fielding measures. Each chapter contains exercises that encourage readers to perform their own analyses using R. All of the datasets and R code used in the text are available online. This book helps readers answer questions about baseball teams, players, and strategy using large, publically available datasets. It offers detailed instructions on downloading the datasets and putting them into formats that simplify data exploration and analysis. Through the book’s various examples, readers will learn about modern sabermetrics and be able to conduct their own baseball analyses. This document has been replaced by ISBN: 9781351107082. View the most recent version.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3029, 'AMCA 540-23 Test Method for Louvers Impacted by Wind Borne Debris', 'Air Movement and Control Association', '', '', '4/17/2023 12:00:00 AM', '', '0', 36, '2407160916312', '', '', 'This document establishes a standard for the design, manufacture, construction, operation, and maintenance of passenger ropeways. For this standard, passenger ropeway categories include: aerial tramways (single and double reversible); aerial lifts (detachable lifts, chair lifts, and similar equipment); surface lifts (T-bar lifts, J-bar lifts, platter lifts, and similar equipment); tows (wire rope and fiber rope tows); and conveyors.', '0.000000', 90.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3030, 'AMCA 511-21 (Rev. 12-22) Certified Ratings Program - Product Rating Manual for Air Control Devices', 'Air Movement and Control Association', '', '', '2023', '', '0', 49, '2407160916313', '', '', 'ISBN: 9789811286971\n\nKoh Seow Chuan likes to see his life as a continuous painting, and himself as the painter. An Unfinished Canvas is about a unique individual who sees life as just that — a canvas that is never finished. This book traces his remarkable life from the age of four, following his journey as a stamp collector, national swimmer, architect and art collector. In all his endeavours, he reached the very top on a global field. The book makes clear how he lived and continues to live his life guided by two principles, his strong belief in the power of knowledge and the power of teamwork, which he found and followed relatively early in his life. Through stamps, he saw what knowledge could do for him academically and how it would always put him in a position of strength in whatever he did later in life. But it is in his absolute embrace of the power of teamwork that sees him succeeding in project after project. People see in him a leader they rarely see in the world of architecture, the leader who insists on we over I, group glory over personal glory. The architecture firm he founded, DP Architects, is more than 50 years old — and is now one of the biggest in the world. In his 80s now, he reminds us that his canvas is still unfinished.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3031, 'AMCA 500-L-23 Laboratory Methods of Testing Louvers for Rating', 'Air Movement and Control Association', '', '', '4/28/2023 12:00:00 AM', '', '0', 96, '2407160916314', '', '', '1. Purpose\n\nThe purpose of this standard is to establish minimum performance requirements and uniform methods for laboratory testing of louvers that are impact tested with the “large missile” as defined in ASTM E1886.\n\n2. Scope\n\nThis standard is to be used for impact testing of louvers that are installed on the outside of buildings and to assist in meeting the requirements of the International Code Council (ICC) International Building Code, the ICC International Residential Code and any other applicable codes or specifications.\n\nThe following precautionary statement pertains to sections 6 and 9 of this document: This standard does not purport to address all of the safety concerns, if any, associated with its use. It is the responsibility of the user of this standard to establish appropriate safety and health practices and determine the applicability of the regulatory limitations prior to use.', '0.000000', 90.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3032, 'AMCA 320-23 Laboratory Method of Sound Testing of Fans Using Sound Intensity', 'Air Movement and Control Association', '', '', '7/28/2023 12:00:00 AM', '', '0', 36, '2407160916315', '', '', '1. Purpose\nThe purpose of this program is to provide a follow-up service for louvers tested in accordance with ANSI/AMCA Standard 540 and/or louvers tested in accordance with ANSI/AMCA Standard 550.\n\n2. Scope\nThe products within the scope of this publication are louvers that are used for high wind and/or high intensity rain areas. This program shall apply only to a complete cataloged series of sizes. It shall not apply to individual sizes in a series or part of a series or special units on which catalog performance ratings are not published. A listing label may be obtained for a louver meeting the requirements of ANSI/AMCA Standard 540, ANSI/AMCA Standard 550 or both.\n\nThe AMCA International Listing Label Program shall be used only in connection with the specifically listed louver. It shall be used only on complete units. The application of the AMCA International Listing Label Program to individual component parts, such as blades, frames, etc., is not permitted.', '0.000000', 90.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3033, 'AMCA 270-23 Laboratory Methods of Aerodynamic Testing Fan Arrays for Rating', 'Air Movement and Control Association', '', '', '6/1/2023 12:00:00 AM', '', '0', 65, '2407160916316', '', '', '1. Purpose\n\nAMCA Publication 511 dictates proper presentation of data and other required technical procedures for certification of air control devices under the AMCA Certified Ratings Program. This manual shall be used in conjunction with the current edition of AMCA Publication 11.\n\n2. Scope\n\nThe products within the scope of this program are air control devices for use in general ventilation and air-conditioning systems.\n\nThis program shall apply only to a complete cataloged series of sizes. In regard to louvers, the program only applies to rectangular and square configurations. It shall not apply to individual sizes in a series, or part of a series of sizes, or to special units on which catalog ratings are not published.\n\nThe AMCA Certified Ratings Program seal shall be used only in connection with the specifically certified device. The AMCA seal shall be used only on complete units. The application of the AMCA Certified Ratings Program seal to individual component parts, such as blades, frames, etc., is not permitted.', '0.000000', 90.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3034, 'AMCA 211-22 (Rev. 01-23) Certified Ratings Program — Product Rating Manual for Fan Air Performance', 'Air Movement and Control Association', '', '', '1/27/2023 12:00:00 AM', '', '0', 99, '2407160916317', '', '', '1. Purpose\n\nThe purpose of this standard is to establish uniform laboratory test methods for louvers. Characteristics to be determined include air leakage, air performance (pressure drop), water penetration, wind-driven rain, wind-driven sand and operational torque. It is not the purpose of this standard to establish minimum or maximum performance ratings.\n\n2. Scope\n\nThis standard may be used as a basis for testing louvers with air as the test gas. Tests conducted in accordance with the requirements of this standard are intended to demonstrate the performance of a louver and are not intended to determine the acceptability of performance. It is not in the scope of this standard to indicate actual sequences of testing or to specify minimum or maximum criteria for testing.', '0.000000', 0.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3035, 'AMCA 201-23 Fans and Systems', 'Air Movement and Control Association', '', '', '2023', '', '0', 104, '2407160916318', '', '', '1. Purpose\n\nThis standard establishes a method of determining a fan’s octave band sound power levels. When all method requirements are met, the reproducibility will be defined in accordance with Annex D.\n\n2. Scope\n\nThis standard is intended to apply to fans of all types and sizes. It is limited to the determination of airborne sound emission for the specified setups. Vibration is not measured, and the sensitivity of airborne sound emission to vibration effects is not determined. The size of a fan that can be tested in accordance with this standard is limited only by the practical aspects of the test setup.\n\nIn this standard, sound power levels are determined using sound intensity measurements on a measurement surface that encloses the sound source. Guidelines are provided on suitable test environment acoustical characteristics, the measurement surface and the number of intensity measurements. Test setups are designated generally to represent the physical orientation of fans as installed following ANSI/AMCA Standard 210 and used in ANSI/AMCA Standard 300.', '0.000000', 90.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3036, 'AICHE G-20 CCPS: GUIDELINES FOR AUDITING PROCESS SAFETY MANAGEMENT SYSTEMS', 'American Institute of Architects', '', '', '3/1/2011 12:00:00 AM', '', '0', 0, '2407160916319', '', '', 'ISBN 0-8169-0422-7', '0.000000', 79.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(3037, 'AICHE G19 GUIDELINES FOR INVESTIGATING CHEMICAL PROCESS INCIDENTS', 'American Institute of Architects', '', '', '3/1/2003 12:00:00 AM', '', '0', 0, '2407160916320', '', '', 'HARDCOVER * PLUS DISKETTE * ISBN 0-8169-0684-X', '0.000000', 402.00, 0.00, '', '', '2024-07-16 21:31:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
