(20210, 'Pilot\\\'s Avionics Survival Guide', 'Maher, Edward R.', '', '', '1993', 'McGraw-Hill Companies, The', '0', 0, '9780070396210', '', 'C004; C005; C006; C007; C070', 'Understanding how avionics systems work and what to do if a system fails inflight is essential for all pilots. For aircraft owners, this knowledge can translate into hundreds of dollars in savings on repair bills. Here, Edward Maher provides helpful details on every major avionics system, explaining how to troubleshoot: Radios; Intercoms, speakers, microphones, and headsets; Antennas; Transmitters and receivers; Navigation systems: Loran, ADF, and GPS; Autopilots; Transponders and collision avoidance systems; Radar systems; Emergency locator transmitters; Gyroscopic instruments and compasses Learn how to eliminate audio system noise Purchase components using the handy manufacturers list Especially geared to lightplane pilots and ownersMaher, Edward R. is the author of \\\'Pilot\\\'s Avionics Survival Guide\\\', published 1993 under ISBN 9780070396210 and ISBN 0070396213.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:02:37', '0000-00-00 00:00:00', 0, 0, 0, 0),
(20211, 'Advanced Aircraft Systems', 'Lombardo, David A.', '', '', '1993', 'McGraw-Hill Companies, The', '0', 0, '9780070386020', '', 'C004; C005; C006; C007; C070', 'David Lombardo is a licensed pilot, an aircraft mechanic, and a professor of aviation.Lombardo, David A. is the author of \\\'Advanced Aircraft Systems\\\', published 1993 under ISBN 9780070386020 and ISBN 0070386021.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:02:37', '0000-00-00 00:00:00', 0, 0, 0, 0),
