(20238, 'Passing the FAA Written Exam : Private Pilot', 'McQueen, Tom', '', '', '1991', 'McGraw-Hill Companies, The', '0', 0, '9780071559898', '', 'C004; C005; C006; C007; C070', 'McQueen, Tom is the author of \\\'Passing the FAA Written Exam : Private Pilot\\\', published 1991 under ISBN 9780071559898 and ISBN 0071559892.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:02:37', '0000-00-00 00:00:00', 0, 0, 0, 0),
(20239, 'Passing the FAA Written Exam : Instrument', 'McQueen, Tom', '', '', '1991', 'McGraw-Hill Companies, The', '0', 0, '9780071559775', '', 'C004; C005; C006; C007; C070', 'This book gives applicants pre-test access to all of the questions that can appear on the actual exams. Each question is accompanied by the only correct answer-unlike competing books, which are padded with a list of possible responses from which to choose. The direct, concise approach of the TAB guides results in a much more compact set of study tools-tools that do not frustrate the learning process with confusing & unnecessary information.McQueen, Tom is the author of \\\'Passing the FAA Written Exam : Instrument\\\', published 1991 under ISBN 9780071559775 and ISBN 0071559779.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:02:37', '0000-00-00 00:00:00', 0, 0, 0, 0),
(20240, 'Passing the FAA Written Exam : Commercial', 'McQueen, Tom', '', '', '1991', 'McGraw-Hill Companies, The', '0', 0, '9780071559645', '', 'C004; C005; C006; C007; C070', 'McQueen, Tom is the author of \\\'Passing the FAA Written Exam : Commercial\\\', published 1991 under ISBN 9780071559645 and ISBN 0071559647.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:02:37', '0000-00-00 00:00:00', 0, 0, 0, 0),
(20243, 'Understanding Aeronautical Charts', 'Lankford, Terry T.', '', '', '1992', 'McGraw-Hill Companies, The', '0', 0, '9780071578004', '', 'C004; C005; C006; C007; C070', 'Filled with practical applications for beginning & veteran pilots, Understanding Aeronautical Charts provides clear, easy-to-follow instruction in a subject many pilots find complicated. With an emphasis on their use for flight planning purposes, Lankford covers all types of charts, including those for VFR, IFR, SID, STAR, Loran, & helicopter flights. In describing his proven system for interpreting & using charts, the author examines the limitations & shortcomings of charts in flight planning & offers helpful tips & techniques for working around them. Lankford includes material on all the new airspace categories proposed by the FAA.Lankford, Terry T. is the author of \\\'Understanding Aeronautical Charts\\\', published 1992 under ISBN 9780071578004 and ISBN 0071578005.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:02:37', '0000-00-00 00:00:00', 0, 0, 0, 0);
