(23929, 'Room Acoustics', 'Kuttruff, Heinrich', '', '', '1991', 'Routledge', '0', 0, '9781851665761', '', 'C150', 'Comprises all acoustic phenomena within enclosures. More specifically it deals with the transmission of speech and music in rooms in which some kind of performance is presented and with the propagation of noise in working environments such as factories or large offices.Kuttruff, Heinrich is the author of \\\'Room Acoustics\\\', published 1991 under ISBN 9781851665761 and ISBN 1851665765.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:13:49', '0000-00-00 00:00:00', 0, 0, 0, 0),
(23943, 'Digital Magnetic Recording', 'Hoagland, Albert S., Monson, James E.', '', '', '1991', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780471401445', '', 'C150', 'Magnetic Recording and Data Storage. Principles of Magnetics. Theory of the Digital Magnetic Recording Process: Reading. Theory of the Digital Magnetic Recording Process: Writing. Magnetic Heads. Magnetic Recording Media. Digital Recording Techniques. Digital Recording: Noise Sources, Error Rates, and ECC. Index.Hoagland, Albert S. is the author of \\\'Digital Magnetic Recording\\\', published 1991 under ISBN 9780471401445 and ISBN 0471401447.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:13:49', '0000-00-00 00:00:00', 0, 0, 0, 0),
