(24718, 'Seeing the Forest among the Trees', 'Hammond, Herb', '', '', '1991', 'Raincoast Book Distribution', '0', 0, '9780919591585', '', 'C008', 'Comprehensive and beautifully illustrated, this is the definitive forest ecology handbook.Hammond, Herb is the author of \\\'Seeing the Forest among the Trees\\\', published 1991 under ISBN 9780919591585 and ISBN 0919591582.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:17:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
