(25606, 'This Old Barn', 'Wysocky, Ken', '', '', '1996', 'Reiman Publications, L.P.', '0', 0, '9780898211757', '', 'C008', 'Wysocky, Ken is the author of \\\'This Old Barn\\\', published 1996 under ISBN 9780898211757 and ISBN 0898211751.', '0.000000', 0.00, 96.61, '', '', '2024-10-18 23:17:20', '0000-00-00 00:00:00', 0, 0, 0, 0),
(25628, 'Logging the Redwoods', 'Carranco, Lynwood, Labbe, John T.', '', '', '1996', 'Caxton Press', '0', 0, '9780870043734', '', 'C008', 'The giant redwood trees are one of California\\\'s best known attractions. Thousands of tourists visit the Northern California groves each year.But redwood is more than a tourist attraction. It has unique qualities. No other wood can take its place where lasting qualities are required. The story of the California redwood lumber industry also tells the stories of the men, the trains, and the land. Historical photographs fill the pages.Carranco, Lynwood is the author of \\\'Logging the Redwoods\\\', published 1996 under ISBN 9780870043734 and ISBN 0870043730.', '0.000000', 0.00, 104.99, '', '', '2024-10-18 23:17:20', '0000-00-00 00:00:00', 0, 0, 0, 0),
