(27094, 'Timber Plantations in the Humid Tropics of Africa', 'Food and Agriculture Organization Staff', '', '', '1993', 'Food &amp; Agriculture Organization of the United Nations', '0', 0, '9789251030202', '', 'C008', 'Food and Agriculture Organization Staff is the author of \\\'Timber Plantations in the Humid Tropics of Africa\\\', published 1993 under ISBN 9789251030202 and ISBN 9251030200.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:17:32', '0000-00-00 00:00:00', 0, 0, 0, 0),
(27099, 'Vegetable Dishes: Second Supplement to Composition of Foods', 'McCance, Robert Alexander, Widdowson, Elsie M., Holland, B.', '', '', '1992', 'Royal Society of Chemistry, The', '0', 0, '9780851863962', '', 'C008', 'Vegetable Dishes creates a new food group containing over 340 vegetable-based dishes and provides information on 53 nutrients per food.Vegetable Dishes is unique in being the only comprehensive source of compositional data on this food group available in the UK. Of the 347 foods covered only 10 have appeared before, in either The Composition of Foods 5th Edition or previous supplements. The extensive selection of foods covered include popular vegetable dishes, vegetarian and vegan foods such as pulse and nut-based dishes, manufactured ready meals and dishes consumed by ethnic populations in the UK.Recipes have been collected from a wide variety of sources for dishes as consumed in the home. Supplementary sections detail recipe ingredients and cooking methods, alternative dish names and an alphabetical index of ingredients.McCance, Robert Alexander is the author of \\\'Vegetable Dishes: Second Supplement to Composition of Foods\\\', published 1992 under ISBN 9780851863962 and ISBN 0851863965.', '0.000000', 0.00, 42.72, '', '', '2024-10-18 23:17:32', '0000-00-00 00:00:00', 0, 0, 0, 0),
(27100, 'Meat, Poultry and Game: Supplement to the Composition of Foods', 'McCance, Robert Alexander, Widdowson, Elsie M., Brown, J.', '', '', '1995', 'Royal Society of Chemistry, The', '0', 0, '9780851863801', '', 'C008', 'Meat, Poultry and Game forms a major update to The Composition of Foods 5th Edition, providing new and extensive nutritional composition data for 429 foods in this significant food group.It provides new information on both raw and cooked meats, including lamb, pork, beef, veal, chicken, turkey, duck, grouse, goose, pheasant, pigeon, hare, rabbit, venison, heart, kidney, liver, oxtail, sweetbread and tongue.Easy-to-read tables provide composition data (per 100g of food) for up to 62 nutrients. The main tables list data for 42 nutrients, and supplementary tables include individual fatty acids (expressed per 100g of total fatty acids), retinol fractions, and vitamin D fractions for selected foods. There are also details on cooking methods, weight losses on cooking meats, a listing of taxonomic and alternative food names, and a food index.Meat, Poultry and Game forms an essential, authoritative and up-to-date source of new nutrient data. It is an essential reference source for professionals and students of food science and nutrition and will also be of interest to the layperson with interests in diet and nutrition.McCance, Robert Alexander is the author of \\\'Meat, Poultry and Game: Supplement to the Composition of Foods\\\', published 1995 under ISBN 9780851863801 and ISBN 0851863809.', '0.000000', 0.00, 42.72, '', '', '2024-10-18 23:17:32', '0000-00-00 00:00:00', 0, 0, 0, 0),
