(39363, 'Failure of Agricultural Collectivization in the People\\\'s Republic of Kampuchea, 1979-1989', 'Frings, Viviane', '', '', '1995', 'Monash University Press', '0', 0, '9780732604738', '', 'C008', 'Frings, Viviane  is the author of \\\'Failure of Agricultural Collectivization in the People\\\'s Republic of Kampuchea, 1979-1989 \\\', published 1995 under ISBN 9780732604738 and ISBN 0732604737.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:30', '0000-00-00 00:00:00', 0, 0, 0, 0),
(39439, 'Soil/sediment Adsorption Constant Program', 'Howard', '', '', '1992', 'C R C Press LLC', '0', 0, '9780873717823', '', 'C008', 'Soil/Sediment Adsorption Constant Program uses the SMILES notation structural input to calculate the soil or sediment adsorption coefficient (Koc) from a correlation of the molecular connectivity indices and correction factors for certain chemical classes. This method was developed by the U.S. Environmental Protection Agency\\\'s (EPA) Office of Toxic Substances and is now available for use on any IBM® or IBM-compatible computer with 240K RAM. This powerful, user-friendly program provides reliable data that will benefit any environmental chemist or regulator, chemical companies, and analytical labs.Howard is the author of \\\'Soil/sediment Adsorption Constant Program \\\', published 1992 under ISBN 9780873717823 and ISBN 0873717821.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:30', '0000-00-00 00:00:00', 0, 0, 0, 0),
