(39719, 'Recent Adv in Animal Nutrition', 'Garnsworthy, P. C., Wiseman, J., Haresign, W.', '', '', '1996', 'Nottingham University Press', '0', 0, '9781897676035', '', 'C008', 'Garnsworthy, P. C. is the author of \\\'Recent Adv in Animal Nutrition \\\', published 1996 under ISBN 9781897676035 and ISBN 1897676034.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:32', '0000-00-00 00:00:00', 0, 0, 0, 0),
(39821, 'Successful Small-Scale Farming', 'Schwenke, Karl, Watson, Ben', '', '', '1991', 'Storey Publishing, LLC', '0', 0, '9780882666433', '', 'C008', '\\\"My advice is as old as the plow.\\\" So says author, Karl Schwenke of his guide to making a full- or part-time living on the land, a book for anyone who plans to own a small farm. With sections on soil management, farm practices, cash crop selections, machinery, and many other topics, as well as comprehensive series of appendices, the author touches upon the basics of getting started with one\\\'s own small-scale farm. Schwenke, himself a small farm owner, has provided a great practical resource for the beginning cash crop grower. Get started on acquiring \\\"the hodgepodge of knowledge blended with a plethora of skills\\\" necessary to becoming a successful organic farmer.Schwenke, Karl is the author of \\\'Successful Small-Scale Farming\\\', published 1991 under ISBN 9780882666433 and ISBN 0882666436.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:32', '0000-00-00 00:00:00', 0, 0, 0, 0),
