(41307, 'Treasury of Traditional Wisdom', 'Perry, Whitall N., Pallis, Marco', '', '', '1992', 'Fons Vitae of Kentucky, Incorporated', '0', 0, '9781870196086', '', 'C008', 'Perry, Whitall N. is the author of \\\'Treasury of Traditional Wisdom\\\', published 1992 under ISBN 9781870196086 and ISBN 1870196082.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41323, 'Tropical Pasture Utilisation', 'Humphreys, L. Ross', '', '', '1991', 'Cambridge University Press', '0', 0, '9780521380300', '', 'C008', 'This book sets out to examine the problems involved in the utilisation of tropical and subtropical pastures and to explain how pastures may be managed to meet the requirements of both plants and animals for growth and replacement.Humphreys, L. Ross is the author of \\\'Tropical Pasture Utilisation\\\', published 1991 under ISBN 9780521380300 and ISBN 0521380308.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41333, 'U.S. National Plant Germplasm System Committee on Managing Global Genetic Resources', 'National Research Council Staff', '', '', '1991', 'National Academies Press', '0', 0, '9780309043908', '', 'C008', 'In the United States, the critical task of preserving our plant genetic resources is the responsibility of the National Plant Germplasm System (NPGS). NPGS undergoes a thorough analysis in this book, which offers wide-ranging recommendations for equipping the agency to better meet U.S. needs--and lead international conservation efforts. The book outlines the importance and status of plant genetic conservation and evaluates NPGS\\\'s multifaceted operations. Two options for revamping NPGS within the U.S. Department of Agriculture are included.National Research Council Staff is the author of \\\'U.S. National Plant Germplasm System Committee on Managing Global Genetic Resources\\\', published 1991 under ISBN 9780309043908 and ISBN 0309043905.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41342, 'Underground Construction in Soft Ground Proceedings of the International Symposium on Underg...', 'Fujita, Keiichiro, Kusakabe, Osamu', '', '', '1995', 'Taylor &amp; Francis Group', '0', 0, '9789054105367', '', 'C008', 'This work presents papers presented at an international symposium, held in India in 1994. The papers were written by research workers and engineers who are engaged in the design and construction of underground structures in soft ground, with a focus on braced wall excavations and shield tunnelling.Fujita, Keiichiro is the author of \\\'Underground Construction in Soft Ground Proceedings of the International Symposium on Underground Construction in Soft Ground/New Delhi/India/3 January 1994\\\', published 1995 under ISBN 9789054105367 and ISBN 9054105364.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41344, 'Under the Shadow of Apartheid Agrarian Transformation in Swaziland', 'Funnell, D. C.', '', '', '1991', 'Ashgate Publishing, Limited', '0', 0, '9781856281126', '', 'C008', 'Under the Shadow of Apartheid brings together a diverse range of material with the aim of highlighting changes in the agrarian structure of Swaziland. With a historical legacy of land-partition, Swaziland is similar to other African countries where white settlement occurred, but since independence has followed its own distinct political evolution. The book examines rural development programmes which have targeted the small farmer on communal land but places the analysis in the wider context of increased Swazi involvement in the large-scale capitalist export sector. Conflicts over land and water are discussed, along with the changing focus of rural policy as the Swazi élite gains an ever-increasing stake in the economy.Funnell, D. C. is the author of \\\'Under the Shadow of Apartheid Agrarian Transformation in Swaziland\\\', published 1991 under ISBN 9781856281126 and ISBN 1856281124.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41384, 'Integrated Animal Waste Management', 'Task Force of Scientists Staff', '', '', '1995', 'Council for Agricultural Science &amp; Technology (CAST)', '0', 0, '9781887383080', '', 'C008', 'Task Force of Scientists Staff is the author of \\\'Integrated Animal Waste Management\\\', published 1995 under ISBN 9781887383080 and ISBN 1887383085.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
