INSERT INTO `wp_tecbook_books_cache` (`id`, `title`, `author`, `edition`, `documentStatus`, `publicationDate`, `publisher`, `doi`, `page`, `isbn`, `subjectsCode`, `subjects`, `abstract`, `keywords`, `pricePrint`, `priceeBook`, `previewPath`, `fullContentBookPath`, `createdDate`, `updatedDate`, `deleted`, `newArrival`, `bestSellers`, `isFree`) VALUES
(41584, 'Surfactants in Agrochemicals', 'Tadros, Tharwat F.', '', '', '1995', 'C R C Press LLC', '0', 0, '9780824791001', '', 'C008', 'This work highlights the physical chemistry of surfactant solutions, detailing a fundamental method of selecting surfactants for agrochemical formulations and delineating how surfactants enhance the biological efficacy of agrochemicals. The unique properties of surfactants that have a major influence on the performance of an agrochemical are summarized.;The book is intended for physical, surface and colloid chemists; biochemists; microbiologists; agronomists; research and development personnel in the pesticide and fertilizer industries; and upper-level undergraduate and graduate students taking chemistry and chemical engineering courses.;College and university bookstores may order five or more copies at a special price which is available on request from Marcel Dekker Inc.Tadros, Tharwat F. is the author of \\\'Surfactants in Agrochemicals\\\', published 1995 under ISBN 9780824791001 and ISBN 0824791002.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41588, 'Survival by Association Supply Management Landscapes of the Eastern Caribbean', 'Welch, Barbara M.', '', '', '1996', 'McGill-Queen&#39;s University Press', '0', 0, '9780773513709', '', 'C008', 'Welch, Barbara M. is the author of \\\'Survival by Association Supply Management Landscapes of the Eastern Caribbean\\\', published 1996 under ISBN 9780773513709 and ISBN 0773513701.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41593, 'Swine Farrowing Handbook Housing and Equipment', 'Midwest Plan Service Personnel Staff, Friday, William H., Jones, Don D.', '', '', '1993', 'MidWest Plan Service', '0', 0, '9780893730840', '', 'C008', 'Midwest Plan Service Personnel Staff is the author of \\\'Swine Farrowing Handbook Housing and Equipment\\\', published 1993 under ISBN 9780893730840 and ISBN 089373084X.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41600, 'Sustainable Agriculture in the American Midwest Lessons from the Past, Prospects for the Future', 'McIsaac, Gregory, Edwards, William R.', '', '', '1994', 'University of Illinois Press', '0', 0, '9780252021008', '', 'C008', 'This timely collection provides a general overview and detailed discussion of social and technical issues related to moving toward a culture and practice of sustainable agriculture in the American Midwest. It develops the concept that because agriculture does not exist in isolation, sustainability must be understood within the context of the many dynamic natural and social systems characteristic of a particular region - from climate to culture. Scholars from diverse disciplines - ecology, geography, economics, agricultural engineering, anthropology, entomology, climatology - provide the historical and contemporary context for this vital discussion.McIsaac, Gregory is the author of \\\'Sustainable Agriculture in the American Midwest Lessons from the Past, Prospects for the Future\\\', published 1994 under ISBN 9780252021008 and ISBN 0252021002.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41601, 'Sustainable Agriculture Research and Education in the Field A Proceedings', 'Board on Agriculture, National Research Council Staff', '', '', '1991', 'National Academies Press', '0', 0, '9780309045780', '', 'C008', 'Board on Agriculture, National Research Council Staff is the author of \\\'Sustainable Agriculture Research and Education in the Field A Proceedings\\\', published 1991 under ISBN 9780309045780 and ISBN 0309045789.', '0.000000', 0.00, 78.82, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41602, 'Sustainable Agriculture Systems', 'Hatfield, J. L., Karlen, D. L.', '', '', '1994', 'C R C Press LLC', '0', 0, '9781566700498', '', 'C008', 'Sustainable agriculture embodies many concepts in its attempt to integrate all the aspects of farming systems into a holistic system. This book explores the processes that occur within the components of a sustainable system and shows where we can build upon our existing knowledge to develop the concepts of sustainable agriculture into the new conventional agriculture. Well-known researchers examine a variety of aspects, including production goals, environmental considerations, and economics, to build a knowledge base that allows readers to see where changes in agriculture must be made and how challenges can be met. They compare existing systems against definitions of sustainability and pinpoint those areas where improvements can be made in current systems to further the concepts of sustainability.Hatfield, J. L. is the author of \\\'Sustainable Agriculture Systems\\\', published 1994 under ISBN 9781566700498 and ISBN 1566700493.', '0.000000', 0.00, 129.10, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41604, 'Sustainable Agriculture in Egypt', 'Faris, Mohamed A., Khan, Mahmood H.', '', '', '1993', 'Rienner Publishers, Lynne', '0', 0, '9781555873707', '', 'C008', 'Faris, Mohamed A. is the author of \\\'Sustainable Agriculture in Egypt\\\', published 1993 under ISBN 9781555873707 and ISBN 1555873707.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41610, 'Sustainable Agriculture and the Environment in the Humid Tropics', 'National Research Council Staff', '', '', '1993', 'National Academies Press', '0', 0, '9780309047494', '', 'C008', 'Rain forests are rapidly being cleared in the humid tropics to keep pace with food demands, economic needs, and population growth. Without proper management, these forests and other natural resources will be seriously depleted within the next 50 years. Sustainable Agriculture and the Environment in the Humid Tropicsprovides critically needed direction for developing strategies that both mitigate land degradation, deforestation, and biological resource losses and help the economic status of tropical countries through promotion of sustainable agricultural practices. The book includes A practical discussion of 12 major land use options for boosting food production and enhancing local economies while protecting the natural resource base. Recommendations for developing technologies needed for sustainable agriculture. A strategy for changing policies that discourage conserving and managing natural resources and biodiversity. Detailed reports on agriculture and deforestation in seven tropical countries.National Research Council Staff is the author of \\\'Sustainable Agriculture and the Environment in the Humid Tropics\\\', published 1993 under ISBN 9780309047494 and ISBN 0309047498.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(41611, 'Sustainable Agriculture and the 1995 Farm Bill', 'Task Force of Scientists Staff', '', '', '1995', 'Council for Agricultural Science &amp; Technology (CAST)', '0', 0, '9781887383004', '', 'C008', 'Task Force of Scientists Staff is the author of \\\'Sustainable Agriculture and the 1995 Farm Bill\\\', published 1995 under ISBN 9781887383004 and ISBN 188738300X.', '0.000000', 0.00, 0.00, '', '', '2024-10-18 23:18:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
