(53002, 'Action Agenda for Managing the Nation\\\'s Floodplains : A Review of Floodplain Management in t...', 'by Unknown Author', '', '', '1992', 'Natural Hazards Research &amp; Applications', '0', 0, '9780685624227', '', 'C031; C073', 'Action Agenda for Managing the Nation\\\'s Floodplains : A Review of Floodplain Management in the United States, an Assessment Report, was published 1992 under ISBN 9780685624227 and ISBN 0685624226.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:11:24', '0000-00-00 00:00:00', 0, 0, 0, 0),
(53065, 'Transportation and Traffic Theory', 'Daganzo, Carlos F.', '', '', '1993', 'Elsevier Science &amp; Technology Books', '0', 0, '9780444894397', '', 'C031; C073', 'This volume contains recent theoretical and empirical results on the study of traffic flows in urban areas, the optimal control and routing of such traffic, and the analysis of the transportation system performance. The 32 papers address a variety of topics on the scientific aspects of transportation phenomena. Special attention is given to \\\"congestion reduction\\\" and the transportation of both passengers and freight, by land, air and water transportation modes. The work will be of special interest to researchers and practitioners of transportation engineering, operations research, control systems, economics and applied mathematics.Daganzo, Carlos F. is the author of \\\'Transportation and Traffic Theory\\\', published 1993 under ISBN 9780444894397 and ISBN 044489439X.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:11:24', '0000-00-00 00:00:00', 0, 0, 0, 0),
(53069, 'Reservoir Eutrophication', 'Lind, O. T.', '', '', '1993', 'Elsevier Science &amp; Technology Books', '0', 0, '9780080423548', '', 'C031; C073', 'Lind, O. T. is the author of \\\'Reservoir Eutrophication\\\', published 1993 under ISBN 9780080423548 and ISBN 008042354X.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:11:24', '0000-00-00 00:00:00', 0, 0, 0, 0),
(53075, 'Comprehensive Rock Engineering, Volume 5-Volume Set', 'Hudson, John A., Brown, E. T., Fairhurst, Charles P.', '', '', '1993', 'Elsevier Science &amp; Technology Books', '0', 0, '9780080359311', '', 'C031; C073', 'Engineers wishing to build structures on, or in, rock use the relatively new discipline known as rock mechanics. Comprehensive Rock Engineering is an authoritative and comprehensive work of reference containing a compilation of knowledge not available from any other source in one coherent publication. Clearly illustrated throughout, this multi-volume publication consists of state-of-the-art articles written by over 200 internationally recognized authorities and covers every aspect of rock mechanics and rock engineering. Comprehensive Rock Engineering is arranged in five volumes under the themes: Fundamentals; Analysis and Design; Rock Testing and Site Characterization; Excavation, Support and Monitoring; and Project Case Histories, providing the key information that is required for any rock engineering application. Case histories and principles relating to specific countries are also included.Hudson, John A. is the author of \\\'Comprehensive Rock Engineering, Volume 5-Volume Set\\\', published 1993 under ISBN 9780080359311 and ISBN 0080359310.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:11:24', '0000-00-00 00:00:00', 0, 0, 0, 0),
(53077, 'Behaviour of Offshore Structures : Geotechnics', 'Prime, H. A.', '', '', '1994', 'Elsevier Science &amp; Technology Books', '0', 0, '9780080419138', '', 'C031; C073', 'Prime, H. A. is the author of \\\'Behaviour of Offshore Structures : Geotechnics\\\', published 1994 under ISBN 9780080419138 and ISBN 0080419135.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:11:24', '0000-00-00 00:00:00', 0, 0, 0, 0),
(53078, 'Comprehensive Rock Engineering, Volume 4: Excavation, Support and Monitoring', 'Hudson, J. A.', '', '', '1995', 'Elsevier Science &amp; Technology Books', '0', 0, '9780080420677', '', 'C031; C073', 'Hudson, J. A. is the author of \\\'Comprehensive Rock Engineering, Volume 4: Excavation, Support and Monitoring\\\', published 1995 under ISBN 9780080420677 and ISBN 0080420672.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:11:24', '0000-00-00 00:00:00', 0, 0, 0, 0),
