(56053, 'Planning and Analysis of Construction Operations', 'Halpin, Daniel W., Riggs, Leland S.', '', '', '1992', 'John Wiley &amp; Sons Inc', '0', 0, '9780471555100', '', 'C002; C011; C015; C026; C035; C036', 'Focuses on the use of simulation techniques to model and evaluate repetitive construction operations. Based on the CYCLONE and MICROCYCLONE software developed by the authors and used at 38 universities nationwide, it uses a variety of examples from all areas of construction to demonstrate the application of simulation to analyze construction operations.Halpin, Daniel W. is the author of \\\'Planning and Analysis of Construction Operations\\\', published 1992 under ISBN 9780471555100 and ISBN 047155510X.', '0.000000', 0.00, 96.45, '', '', '2024-10-19 17:20:47', '0000-00-00 00:00:00', 0, 0, 0, 0),
(56081, 'Complete Roofing Handbook Installation Maintenance Repair', 'Brumbaugh, James E.', '', '', '1992', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780025178519', '', 'C002; C011; C015; C026; C035; C036', 'Foreword.1. Types of Roofs.2. Roofing and Reroofing.3. Roof Deck Preparation.4. Roof and Attic Ventilation.5. Skylights and Roof Openings.6. Dormer Construction.7. Roof Flashing Details.8. Applying Strip Shingles.9. Applying Specialty Shingles.10. Roll Roofing.11. Built-Up Roofing.12. Wood Shingle and Shake Roofing.13. Slate Roofing.14. Tile Roofing.15. Installing Gutters and Downspouts.16. Roofing for Historic Buildings.17. Historic Wooden Shingle Roofs.References.Index.Brumbaugh, James E. is the author of \\\'Complete Roofing Handbook Installation Maintenance Repair\\\', published 1992 under ISBN 9780025178519 and ISBN 0025178512.', '0.000000', 0.00, 46.18, '', '', '2024-10-19 17:20:47', '0000-00-00 00:00:00', 0, 0, 0, 0),
