(56381, 'Project Management Techniques in Planning and Controlling Construction Projects', 'Ahuja, Hira N., AbouRizk, S. M., Dozzi, S. P.', '', '', '1994', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780471591689', '', 'C002; C011; C015; C026; C035; C036', 'Using a systems perspective, this updated version concentrates on the planning, scheduling and control factors of a project needed to bring it in on time and on or under cost. This edition contains expanded coverage of computer simulation and applications, information management and expert systems in project management. Includes a new chapter on Total Quality Management.Ahuja, Hira N. is the author of \\\'Project Management Techniques in Planning and Controlling Construction Projects\\\', published 1994 under ISBN 9780471591689 and ISBN 0471591688.', '0.000000', 0.00, 76.47, '', '', '2024-10-19 17:20:49', '0000-00-00 00:00:00', 0, 0, 0, 0),
(56396, 'Protecting Buildings from Bomb Damage: Transfer of Blast-Effects Mitigation Technologies fro...', 'Feasibility of Applying Blast-Mitigating Technolog', '', '', '1995', 'National Academies Press', '0', 0, '9780309053754', '', 'C002; C011; C015; C026; C035; C036', 'Feasibility of Applying Blast-Mitigating Technolog is the author of \\\'Protecting Buildings from Bomb Damage: Transfer of Blast-Effects Mitigation Technologies from Military to Civilian Applications\\\', published 1995 under ISBN 9780309053754 and ISBN 0309053757.', '0.000000', 0.00, 94.10, '', '', '2024-10-19 17:20:49', '0000-00-00 00:00:00', 0, 0, 0, 0),
