(56894, 'Outdoor Projects for the Country Home', 'Badger, Peter', '', '', '1993', 'McGraw-Hill School Education Group', '0', 0, '9780830643998', '', 'C002; C011; C015; C026; C035; C036', 'Badger, Peter is the author of \\\'Outdoor Projects for the Country Home\\\', published 1993 under ISBN 9780830643998 and ISBN 0830643990.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:20:52', '0000-00-00 00:00:00', 0, 0, 0, 0),
(56912, 'Illustrated Dictionary for Building Construction', 'Traister, John E.', '', '', '1993', 'Fairmont Press, Incorporated', '0', 0, '9780881731736', '', 'C002; C011; C015; C026; C035; C036', 'Designed to serve as an on-the-job quick reference for those actively engaged in the building construction industry, this easy-to-use dictionary provides an alphabetical listing of over 1,000 construction-related terms, augmented by instructive illustrations to further assist the reader in understanding the terms defined. Many of the terms included will not be found in the average dictionary or defined in any technical text-though they are without exception terms that are used in the building construction industry.Traister, John E. is the author of \\\'Illustrated Dictionary for Building Construction\\\', published 1993 under ISBN 9780881731736 and ISBN 0881731730.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:20:52', '0000-00-00 00:00:00', 0, 0, 0, 0),
(56940, 'Fundamentals of Air Conditioning Systems', 'Langley, Billy C.', '', '', '1994', 'Fairmont Press, Incorporated', '0', 0, '9780881731767', '', 'C002; C011; C015; C026; C035; C036', 'Here is your complete guide to the specification & application of all types of commercial & residential air conditioning equipment. Beginning with an examination of the basics of psychrometrics as applied to air conditioning & heating systems in buildings, the book guides the reader through each step of the process of proper system design, including equipment selection, sizing, placement & installation. Topics covered for both commercial & residential installations include heat load calculation, equipment sizing/selection/location, refrigerant lines, duct systems & design options, duct pipe, fitting & insulation specification, indoor air quality considerations & guidelines for system cost estimating. Theoretical subjects are clearly illustrated with practical examples drawn from actual field experience.Langley, Billy C. is the author of \\\'Fundamentals of Air Conditioning Systems\\\', published 1994 under ISBN 9780881731767 and ISBN 0881731765.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:20:52', '0000-00-00 00:00:00', 0, 0, 0, 0);
