(57263, 'Troubleshooting and Repairing Heat Pumps', 'Woodson, R. Dodge', '', '', '1994', 'McGraw-Hill School Education Group', '0', 0, '9780070086128', '', 'C002; C011; C015; C026; C035; C036', 'Woodson, R. Dodge is the author of \\\'Troubleshooting and Repairing Heat Pumps\\\', published 1994 under ISBN 9780070086128 and ISBN 0070086125.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:20:54', '0000-00-00 00:00:00', 0, 0, 0, 0),
(57355, 'Way of the Carpenter Tools and Japanese Architecture', 'Coaldrake, William H.', '', '', '1991', 'Shambhala Publications, Incorporated', '0', 0, '9780834802315', '', 'C002; C011; C015; C026; C035; C036', 'Japanese architecture boasts some of the finest surviving wooden buildings in the world. They are the products of Japan\\\'s \\\"Way of the Carpenter,\\\" the tradition of the master builder, his materials, his methods & his tools. This ground-breaking book describes the venerable guild system through which, until very recently, the art & craft of Japanese architecture were cultivated. It not only catalogues the tools of traditional Japanese carpentry but also explores their history & the interaction between tools, materials, & innovations in architecture through the ages, covering shrine, temple, castle, & domestic architecture. This richly illustrated book is an important reference & fascinating account of Japanese architecture & carpentry from a new perspective.Coaldrake, William H. is the author of \\\'Way of the Carpenter Tools and Japanese Architecture\\\', published 1991 under ISBN 9780834802315 and ISBN 0834802317.', '0.000000', 0.00, 65.95, '', '', '2024-10-19 17:20:55', '0000-00-00 00:00:00', 0, 0, 0, 0),
