(59834, 'Reinforced Masonry Engineering Handbook Clay and Concrete Masonry', 'Amrhein, James E.', '', '', '1992', 'Masonry Institute of America', '0', 0, '9780940116207', '', 'C002; C011; C015; C026; C035; C036', 'Amrhein, James E. is the author of \\\'Reinforced Masonry Engineering Handbook Clay and Concrete Masonry\\\', published 1992 under ISBN 9780940116207 and ISBN 0940116200.', '0.000000', 0.00, 117.64, '', '', '2024-10-19 17:21:10', '0000-00-00 00:00:00', 0, 0, 0, 0),
(59835, 'Variable Air Volume Manual', 'Wendes, Herbert C.', '', '', '1991', 'Fairmont Press, Incorporated', '0', 0, '9780881730838', '', 'C002; C011; C015; C026; C035; C036', 'From complete system design to testing and balancing to trouble-shooting, this practical handbook examines all aspects of variable air volume (VAV) HVAC systems. The concise presentation guides the reader in applying the best methods for reducing installation and operating costs while increasing occupant comfort. Variable air volume applications are examined in detail for dual duct, multizone, terminal bypass fan powered, and other commonly used types of systems. A wide range of topics are addressed, including temperature, pneumatics, direct digital control, coil controls, morning warmup and night heating, VAV point list, fan tracking, fume hood applications, conversion of existing systems to VAV, and cost estimating.Wendes, Herbert C. is the author of \\\'Variable Air Volume Manual\\\', published 1991 under ISBN 9780881730838 and ISBN 0881730831.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:10', '0000-00-00 00:00:00', 0, 0, 0, 0),
(59836, 'HVAC Energy Audit and Balancing Forms Manual', 'Wendes, Herbert C.', '', '', '1995', 'Fairmont Press, Incorporated', '0', 0, '9780881732191', '', 'C002; C011; C015; C026; C035; C036', 'Wendes, Herbert C. is the author of \\\'HVAC Energy Audit and Balancing Forms Manual\\\', published 1995 under ISBN 9780881732191 and ISBN 0881732192.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:10', '0000-00-00 00:00:00', 0, 0, 0, 0),
