(59851, 'Interpreting the National Electrical Code', 'Surbrook, Truman C.', '', '', '1991', 'Delmar Cengage Learning', '0', 0, '9780827333819', '', 'C002; C011; C015; C026; C035; C036', 'Surbrook, Truman C. is the author of \\\'Interpreting the National Electrical Code\\\', published 1991 under ISBN 9780827333819 and ISBN 0827333811.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:10', '0000-00-00 00:00:00', 0, 0, 0, 0),
(59890, 'Masonry Walls: Specification and Design', 'Thomas, Ken', '', '', '1995', 'Elsevier Science &amp; Technology Books', '0', 0, '9780750624657', '', 'C002; C011; C015; C026; C035; C036', 'The book is a useful reference for architects, builders, building surveyors and structural engineers and is an essential text book for professional students in these disciplines. Kenneth Thomas is well known in the construction industry for his many papers and articles on masonry and has for the past eleven years been a consulting engineer and building technologist specialising in masonry. He is a chartered structural engineer, a chartered builder and in 1970 was awarded a Master of Science degree by the University of Salford for his research into brickwork and materials. He was formerly Chief Technical Officer of the Brick Development Association; Head of Construction Technology at Birmingham Polytechnic (now the University of Central England) and Deputy Director of the Timber Research and Development Association. He has for many years served on numerous BSI, DOE and Professional Institutional committees and is a recipient of the Institution of Structural Engineers Oscar Faber Bronze Medal and the BSI\\\'s Distinguished Service Certificate. Details symptoms and causes of defects Of special interest to these investigating building failures and expert witnessesThomas, Ken is the author of \\\'Masonry Walls: Specification and Design\\\', published 1995 under ISBN 9780750624657 and ISBN 0750624655.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
(59896, 'Electrical Wiring: Commercial - Instructors\\\' Guide to 8r.e', 'Mullin, Ray C., Smith, Robert L.', '', '', '1993', 'Delmar Cengage Learning', '0', 0, '9780827350946', '', 'C002; C011; C015; C026; C035; C036', '\\\"This modernized guide to electrical wiring for commercial buildings features new, up-to-date information on data communications and fiber optic wiring. Written to the 2005 National Electrical Code(r), Electrical Wiring Commercial, 12E enables readers to gain expertise in the identification, interpretation, and application of NEC(r) standards for the actual wiring of commercial buildings. A complete set of full-size, ready-to-use plans provides readers with all the information and practical hands-on experience needed to \\\"\\\"meet Code\\\"\\\" when wiring a light commercial building. This popular book is part of Delmar\\\'s best-selling wiring series, and has been used by thousands of apprentices to prepare for and successfully pass journeyman exams.\\\"Mullin, Ray C. is the author of \\\'Electrical Wiring: Commercial - Instructors\\\' Guide to 8r.e\\\', published 1993 under ISBN 9780827350946 and ISBN 0827350945.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
(59960, 'Modern Home Plumbing', 'Creative Homeowner Press Editors', '', '', '1994', 'Meredith Books', '0', 0, '9780696024863', '', 'C002; C011; C015; C026; C035; C036', 'Creative Homeowner Press Editors is the author of \\\'Modern Home Plumbing\\\', published 1994 under ISBN 9780696024863 and ISBN 0696024861.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
(59989, 'Growing a Housebuilder', 'Brady, Mark', '', '', '1994', 'Random House Value Publishing', '0', 0, '9780517134009', '', 'C002; C011; C015; C026; C035; C036', 'Brady, Mark is the author of \\\'Growing a Housebuilder\\\', published 1994 under ISBN 9780517134009 and ISBN 0517134004.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
(60037, 'Carpentry& Construction S/C', 'Miller, Rex, Baker, Glenn E.', '', '', '1991', 'McGraw-Hill Professional Publishing', '0', 0, '9780071576680', '', 'C002; C011; C015; C026; C035; C036', 'Build up your home carpentry skills. Want to tackle every residential construction & remodeling job-large or small-with complete confidence? Rex Miller & Glenn E. Baker\\\'s Carpentry & Construction, Second Edition, shows you how! This exhaustively illustrated nuts-& bolts guide takes you step-by-step through a huge range of projects-from minor repairs & maintenance to every facet of building a new home. Regardless of your experience, you\\\'ll find innovative techniques & best practices you can apply on the job when: preparing the site; building floor frames; framing walls; erecting roof frames; installing windows & doors; covering roofs; insulating for thermal efficiency; preparing interior walls & ceilings; finishing the interior; building stairs, fire place forms, decks, & patios; handling maintenance & remodeling work.Miller, Rex is the author of \\\'Carpentry& Construction S/C\\\', published 1991 under ISBN 9780071576680 and ISBN 0071576681.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
(60066, 'Heating, Ventitating & Air Conditioning - Analysis & Design 4e Sol T/A', 'McQuiston', '', '', '1994', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780471309000', '', 'C002; C011; C015; C026; C035; C036', 'McQuiston is the author of \\\'Heating, Ventitating & Air Conditioning - Analysis & Design 4e Sol T/A\\\', published 1994 under ISBN 9780471309000 and ISBN 0471309001.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:12', '0000-00-00 00:00:00', 0, 0, 0, 0),
(60092, 'The Control of Quality on Construction Sites: Sp140', 'Churcher, D. W., Johnson, S. J.', '', '', '1996', 'Construction Industry Research &amp; Information Association', '0', 0, '9780860174622', '', 'C002; C011; C015; C026; C035; C036', 'This publication presents the results of a project that examined how contractors control site operations and identified common procedures that had beneficial effects on the control of end product quality.Churcher, D. W. is the author of \\\'The Control of Quality on Construction Sites: Sp140\\\', published 1996 under ISBN 9780860174622 and ISBN 086017462X.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:12', '0000-00-00 00:00:00', 0, 0, 0, 0),
