(63694, 'Building Construction', 'Ambrose, James E.', '', '', '1991', 'Chapman &amp; Hall', '0', 0, '9780442002923', '', 'C002; C011; C015; C026; C035; C036', 'Ambrose, James E. is the author of \\\'Building Construction\\\', published 1991 under ISBN 9780442002923 and ISBN 0442002920.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:35', '0000-00-00 00:00:00', 0, 0, 0, 0),
(63699, 'GUIDE TO RECORDING HISTORIC BUILDINGS', 'ICOMOS Staff', '', '', '1991', 'Elsevier Science &amp; Technology Books', '0', 0, '9780750612104', '', 'C002; C011; C015; C026; C035; C036', 'This guide is designed to serve those architects and surveyors who are increasingly obliged to carry out full and detailed measurement of historic and listed buildings. This process of recording involves collaboration between a variety of professionals and will also be of interest to architectural historians, archaeologists, builders and planners. Commissioned by ICOMOS, it charts the steps necessary to ensure the maintenance of adequate records of the original nature and subsequent evolution of historic buildings. It lists all the aspects of technical documentation and scientific measurement of historic buildings, including photogrammetry, electronic distance measurement (EDM) and technical dating methods. The results of this documentation are essential to the proper preparation of schemes of maintenance, repair and adaptation by building owners, planners and members of the building professions.ICOMOS Staff is the author of \\\'GUIDE TO RECORDING HISTORIC BUILDINGS\\\', published 1991 under ISBN 9780750612104 and ISBN 075061210X.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:35', '0000-00-00 00:00:00', 0, 0, 0, 0),
