(64255, 'DESIGN AND CONSTRUCTION OF CONCRETE FLOO', 'Garber, George', '', '', '1991', 'Elsevier Science &amp; Technology Books', '0', 0, '9780340539187', '', 'C002; C011; C015; C026; C035; C036', 'Concrete floors form one of the most common structural elements in construction today and yet they are beset by problems. This text points the way to good practice by providing a clear and logical guide to their design and construction.Garber, George is the author of \\\'DESIGN AND CONSTRUCTION OF CONCRETE FLOO\\\', published 1991 under ISBN 9780340539187 and ISBN 0340539186.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:38', '0000-00-00 00:00:00', 0, 0, 0, 0),
(64292, 'Practical Building Forms and Agreements', 'Pike, Andrew', '', '', '1993', 'Routledge', '0', 0, '9780419181507', '', 'C002; C011; C015; C026; C035; C036', 'The purpose of this book is to help employers and their advisers (especially their Quantity Surveyors) in drawing up all the contracts required on a normal UK building project.Pike, Andrew is the author of \\\'Practical Building Forms and Agreements\\\', published 1993 under ISBN 9780419181507 and ISBN 0419181504.', '0.000000', 0.00, 209.85, '', '', '2024-10-19 17:21:39', '0000-00-00 00:00:00', 0, 0, 0, 0),
