(64477, 'Modern Wiring Practice Design and Installation', 'Steward, W. E., Marks, Trevor, Stubbs, T. A.', '', '', '1995', 'Elsevier Science &amp; Technology Books', '0', 0, '9780750621342', '', 'C002; C011; C015; C026; C035; C036', 'Steward, W. E. is the author of \\\'Modern Wiring Practice Design and Installation\\\', published 1995 under ISBN 9780750621342 and ISBN 0750621346.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(64485, 'Prefabrication With Concrete', 'Bruggeling, A. S., Huyghe, G. F.', '', '', '1991', 'Taylor &amp; Francis Group', '0', 0, '9789061911838', '', 'C002; C011; C015; C026; C035; C036', 'Both authors are innovators of the prefabrication of concrete structures an important advance towards industrialization of the building process. The detailing of connections between the factory produced elements is crucial, and the \\\"strut and tie\\\" models presented here can be directly applied in strBruggeling, A. S. is the author of \\\'Prefabrication With Concrete\\\', published 1991 under ISBN 9789061911838 and ISBN 9061911834.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(64501, 'Vest Pocket Guide to Hvac Electricity', 'Traister, John E.', '', '', '1995', 'Craftsman Book Company', '0', 0, '9781572180123', '', 'C002; C011; C015; C026; C035; C036', 'This handy guide will be a constant source of useful information for anyone working with electrical systems for heating, ventilating, refrigeration, and airconditioning. Includes essential tables and diagrams for calculating and installing electrical systems for powering and controlling motors, fins, heating elements, compressors, transformers, and every electrical part of an HVAC system.Traister, John E. is the author of \\\'Vest Pocket Guide to Hvac Electricity\\\', published 1995 under ISBN 9781572180123 and ISBN 1572180129.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
