(64976, 'Estimating Earthwork Quantities', 'Atcheson, Daniel B., Atcheson, James E.', '', '', '1992', 'Norseman Publishing Company', '0', 0, '9780961320218', '', 'C002; C011; C015; C026; C035; C036', 'Atcheson, Daniel B. is the author of \\\'Estimating Earthwork Quantities\\\', published 1992 under ISBN 9780961320218 and ISBN 0961320214.', '0.000000', 0.00, 127.99, '', '', '2024-10-19 17:21:44', '0000-00-00 00:00:00', 0, 0, 0, 0),
(64982, 'Introduction to Building Management', 'Calvert, R. E., Coles, D., Bailey, G.', '', '', '1995', 'Elsevier Science &amp; Technology Books', '0', 0, '9780750605106', '', 'C002; C011; C015; C026; C035; C036', 'This is the classic practical introduction to the broad principles of building management. It is suitable for both students and practising construction professionals who are concerned with greater efficiency within the construction industry. As a general textbook for the student, the introduction covers the entire field in some depth providing a firm foundation for additional reading. The text is closely geared to the chartered Institute of Building (Member) Parts I and II examinations. The book includes examples based upon and related to working experience. It will also be found valuable by students reading for the examinations of other professional bodies in the construction industry, and by HNC/D students.Calvert, R. E. is the author of \\\'Introduction to Building Management\\\', published 1995 under ISBN 9780750605106 and ISBN 0750605103.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:44', '0000-00-00 00:00:00', 0, 0, 0, 0),
(65015, 'Spon\\\'s Asia Pacific Construction Costs Handbook', 'Davis Langdon and Seah International Firm Staff', '', '', '1996', 'Taylor &amp; Francis Group', '0', 0, '9780419220404', '', 'C002; C011; C015; C026; C035; C036', 'The economies of the Asia Pacific region make up one of world\\\'s key construction markets. For this new edition of \\\"Spon\\\'s Asia Pacific Construction Costs Handbook\\\" the coverage has been extended to include the UK, Canada and India.Davis Langdon and Seah International Firm Staff is the author of \\\'Spon\\\'s Asia Pacific Construction Costs Handbook\\\', published 1996 under ISBN 9780419220404 and ISBN 0419220402.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:44', '0000-00-00 00:00:00', 0, 0, 0, 0),
(65041, 'Reinforced Grouted Brick Masonry', 'Amrhein, James E.', '', '', '1991', 'Masonry Institute of America', '0', 0, '9780940116191', '', 'C002; C011; C015; C026; C035; C036', 'Amrhein, James E. is the author of \\\'Reinforced Grouted Brick Masonry\\\', published 1991 under ISBN 9780940116191 and ISBN 0940116197.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:44', '0000-00-00 00:00:00', 0, 0, 0, 0),
(65049, 'Remedial Treatment of Buildings', 'Richardson, Barry A.', '', '', '1995', 'Elsevier Science &amp; Technology Books', '0', 0, '9780750621588', '', 'C002; C011; C015; C026; C035; C036', 'This book covers the problems and the solutions which arise when wood and other building materials suffer from any of the many types of decay which can arise due to damp, fungal or insect attack. It deals with all aspects of remedial treatment, from the initial survey to how to replace materials effectively when deterioration has progressed too far. Improved diagnostic recommendations, particularly in relation to dampness, are included in this thoroughly revised second edition. As well as updating the terminology, Barry Richardson has added a chapter on health and safety in relation to remedial treatments, a subject of great importance because of the increasingly stringent health and environmental controls. The general descriptions of remedial treatments are followed by seven appendices which are designed as convenient reference sources for architects, surveyors, engineers and contractors. \\\'This book covers in considerable detail some of the more far reaching defects in buildings and how they are best remedied.\\\' - The ASI Journal, November 1995Richardson, Barry A. is the author of \\\'Remedial Treatment of Buildings\\\', published 1995 under ISBN 9780750621588 and ISBN 0750621583.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:21:44', '0000-00-00 00:00:00', 0, 0, 0, 0),
