(69834, 'Nevada Lands : Hearing Before the Subcommittee on National Parks and Public Lands of the Com...', 'by Unknown Author', '', '', '1993', 'United States Government Printing Office', '0', 0, '9780160407758', '', 'C043; C044; C045; C046; C076', 'Nevada Lands : Hearing Before the Subcommittee on National Parks and Public Lands of the Committee on Interior and Insular Affairs, House of Representatives, One Hundred Second Congress, Second Session, on H.R. 4590 ... H.R. 4587 ... Hearing Held in Washi, was published 1993 under ISBN 9780160407758 and ISBN 0160407753.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:29:03', '0000-00-00 00:00:00', 0, 0, 0, 0),
(69839, 'Circuit Bridging of Components by Smoke', 'Tanaka, T. J.', '', '', '1996', 'United States Government Printing Office', '0', 0, '9780160627873', '', 'C043; C044; C045; C046; C076', 'Smoke can adversely affect digital electronics; in the short term, it can lead to circuit bridging and in the long term to corrosion of metal parts. This report focuses on the impact of smoke on digital instrumentation and control equip. The tests focused on short-term effects such as circuit bridging in typical components and the factors that can influence how much the smoke will affect them. These factors include the component tech\\\'y. and packaging, physical board protect., and environ\\\'l. conditions such as the amt. of smoke, temp. of burn, and humidity level.Tanaka, T. J. is the author of \\\'Circuit Bridging of Components by Smoke\\\', published 1996 under ISBN 9780160627873 and ISBN 0160627877.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:29:03', '0000-00-00 00:00:00', 0, 0, 0, 0),
(69850, 'Electric Motors and Their Controls', 'Kenjo, Takashi', '', '', '1991', 'Oxford University Press, Incorporated', '0', 0, '9780198562351', '', 'C043; C044; C045; C046; C076', 'This is an introductory work explaining the principles, construction, and use of electric motors and their associated drive controls. It starts from basic physics and progresses to discuss state-of-the-art topics such as piezoelectric motors and vector control. It is largely non-mathematical in its approach and provides an uncluttered overview of the subject, easily accessible to beginning students in electrical and electronic engineering as well as engineers and scientists from other disciplines. This authoritative text is fully illustrated with precise, clear diagrams and photographs.Kenjo, Takashi is the author of \\\'Electric Motors and Their Controls\\\', published 1991 under ISBN 9780198562351 and ISBN 0198562357.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:29:03', '0000-00-00 00:00:00', 0, 0, 0, 0),
(69852, 'Electric Circuits : Quickprints to Replace Global Environments', 'Nilsson', '', '', '1996', 'Addison-Wesley Longman, Incorporated', '0', 0, '9780201682656', '', 'C043; C044; C045; C046; C076', 'Nilsson is the author of \\\'Electric Circuits : Quickprints to Replace Global Environments\\\', published 1996 under ISBN 9780201682656 and ISBN 0201682656.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:29:03', '0000-00-00 00:00:00', 0, 0, 0, 0);
