(72144, 'Basic Electrical and Electronic Engineering', 'Bell, E. C., Whitehead, R. W., Bell, F. G.', '', '', '1993', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780632034932', '', 'C043; C044; C045; C046; C076', 'The first edition of this highly successful textbook appeared in 1977. with the production of a fourth edition, the opportunity has been taken to change the title, from Basic Electrical Engineering, to indicate the usefulness of the book to both electrical and electronic engineers. Changes include a reorganisation of the early chapters to provide a fuller introduction to basic concepts, the inclusion of chapters on attenuators and filters, and oscillators, as well as the incorporation of more problems with all chapters.Bell, E. C. is the author of \\\'Basic Electrical and Electronic Engineering\\\', published 1993 under ISBN 9780632034932 and ISBN 0632034939.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:29:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
(72178, '1992 Yearbook Supplement to Mcgraw-Hill\\\'s National Electrical Code Handbook', 'McPartland, Joseph F.', '', '', '1992', 'McGraw-Hill Professional Publishing', '0', 0, '9780070459144', '', 'C043; C044; C045; C046; C076', 'McPartland, Joseph F. is the author of \\\'1992 Yearbook Supplement to Mcgraw-Hill\\\'s National Electrical Code Handbook\\\', published 1992 under ISBN 9780070459144 and ISBN 0070459142.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 17:29:19', '0000-00-00 00:00:00', 0, 0, 0, 0),
