(75430, 'Experiments in Grob Basic Electronics', 'Pugh', '', '', '1993', 'Glencoe/McGraw-Hill', '0', 0, '9780028007649', '', 'C047; C048; C049; C077; C135; C148', 'Pugh is the author of \\\'Experiments in Grob Basic Electronics\\\', published 1993 under ISBN 9780028007649 and ISBN 0028007646.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 20:49:35', '0000-00-00 00:00:00', 0, 0, 0, 0),
(75443, 'Electronics and Electrical Systems', 'Deere and Company Staff', '', '', '1993', 'Deere &amp; Company, John Deere Publishing', '0', 0, '9780866912402', '', 'C047; C048; C049; C077; C135; C148', 'Deere and Company Staff is the author of \\\'Electronics and Electrical Systems\\\', published 1993 under ISBN 9780866912402 and ISBN 0866912401.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 20:49:35', '0000-00-00 00:00:00', 0, 0, 0, 0),
(75444, 'Security Management Business Strategies for Success', 'Dalton, Dennis', '', '', '1995', 'Elsevier Science &amp; Technology Books', '0', 0, '9780750694926', '', 'C047; C048; C049; C077; C135; C148', 'Security personnel are being asked to justify their existence in a corporate environment. They must prove their worth in dollars and cents by showing the return on investing in loss prevention. This means security departments are being forced to contribute more to the business as a whole. This book will show security managers and personnel how to go about this, and how to achieve quality in their departments.Dalton, Dennis is the author of \\\'Security Management Business Strategies for Success\\\', published 1995 under ISBN 9780750694926 and ISBN 0750694920.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 20:49:35', '0000-00-00 00:00:00', 0, 0, 0, 0),
