(87471, 'V IEEE International Power Electronics Congress, Cuernavaca, Mexico, October 14-17, 1996 Tec...', 'IEEE, Power Electronics Society Staff, IEEE, Institute of Electrical and Electronics Engineers, Inc. Staff', '', '', '1996', 'IEEE', '0', 0, '9780780336339', '', 'C047; C048; C049; C077; C135; C148', 'IEEE, Power Electronics Society Staff is the author of \\\'V IEEE International Power Electronics Congress, Cuernavaca, Mexico, October 14-17, 1996 Technical Proceedings  Ciep 96\\\', published 1996 under ISBN 9780780336339 and ISBN 078033633X.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 20:51:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
(87487, 'Thin Films for Integrated Optics Applications Symposium Held April 17-20, 1995, San Francisc...', 'Wessels, Bruce W., Walba, David M., Marder, Seth R.', '', '', '1995', 'Materials Research Society', '0', 0, '9781558992955', '', 'C047; C048; C049; C077; C135; C148', 'The combination of electro-optic (EO) thin films with silicon-integrated circuits provides a promising approach to creating optoelectronic integrated circuits (OEICs) capable of sending information at data rates greater than 1 Gbit/second with low power consumption. These devices are of two basic types -- very highly parallel (64K channels or greater) or very high speed (Gbits/second/channel). Materials scientists, chemists and physicists come together in this volume to discuss EO thin-film materials and devices, and to learn about advances in fields outside of their specific areas. Electro-optic materials featured include organic polymers and/or multilayers, liquid crystals, and inorganic thin films. Materials design, processing, and device issues are addressed.Wessels, Bruce W. is the author of \\\'Thin Films for Integrated Optics Applications Symposium Held April 17-20, 1995, San Francisco, California, U.S.A.\\\', published 1995 under ISBN 9781558992955 and ISBN 1558992952.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 20:51:11', '0000-00-00 00:00:00', 0, 0, 0, 0),
