(89406, 'Stormwater Management', 'Wanielista, Martin P., Yousef, Yousef A.', '', '', '1992', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780471571353', '', 'C054; C055; C056; C057; C058; C079; C080', 'Designed for both students and practicing professionals, it addresses critical issues of water quality, focusing on the illustration and application of both hydrologic and economic water management techniques. Stresses applications using worked examples, case studies and problems. Software is included to assist in solving more complex problems and to apply demonstrated techniques.Wanielista, Martin P. is the author of \\\'Stormwater Management\\\', published 1992 under ISBN 9780471571353 and ISBN 0471571350.', '0.000000', 0.00, 189.46, '', '', '2024-10-19 21:57:39', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89449, 'Solid Waste Landfill Engineering and Design', 'McBean, Edward A., Rovers, Frank A., Farquhar, Grahame J.', '', '', '1994', 'Prentice Hall PTR', '0', 0, '9780130791870', '', 'C054; C055; C056; C057; C058; C079; C080', 'Solid waste disposalespecially after the Love Canal incidenthas become the focus of public awareness and concern for pollution. This book provides a synthesis of existing knowledge on solid waste landfillingwith a focus on solving problems with landfill gas, managing leachate, and implementing environmentally secure operating procedures. It explores the fundamentals of solid waste decomposition, and considers how these influence landfill design, operational features, and improvements in overall site performance. Covers social, economic and technical factors associated with solid waste landfilling. Considers all environmental applications especially water quality and the treatment of landfill generated gas. Presents methodologies for predicting landfill gas and leachate production. For engineers, hydrogeologists, and urban planners involved in the design and operation of landfills.McBean, Edward A. is the author of \\\'Solid Waste Landfill Engineering and Design\\\', published 1994 under ISBN 9780130791870 and ISBN 0130791873.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 21:57:39', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89460, 'Water Quality Management of a Natural Resource', 'Perry, James, Vanderklein, Elizabeth', '', '', '1996', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780865424692', '', 'C054; C055; C056; C057; C058; C079; C080', 'Perry, James is the author of \\\'Water Quality Management of a Natural Resource\\\', published 1996 under ISBN 9780865424692 and ISBN 0865424691.', '0.000000', 0.00, 97.61, '', '', '2024-10-19 21:57:39', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89461, 'Pan\\\'s Travail Environmental Problems of the Ancient Greeks and Romans', 'Hughes, J. Donald', '', '', '1996', 'Johns Hopkins Univ Pr', '0', 0, '9780801853630', '', 'C054; C055; C056; C057; C058; C079; C080', '\\\"A book on green issues is something new and \\\'Pan\\\'s Travail\\\', moreover, is a compelling recital of man\\\'s mistreatment of the Mediterranean environment.\\\"Hughes, J. Donald is the author of \\\'Pan\\\'s Travail Environmental Problems of the Ancient Greeks and Romans\\\', published 1996 under ISBN 9780801853630 and ISBN 080185363X.', '0.000000', 0.00, 98.46, '', '', '2024-10-19 21:57:39', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89514, 'Wildland Water Quality Sampling and Analysis', 'Stednick, John D.', '', '', '1991', 'Elsevier Science &amp; Technology Books', '0', 0, '9780126641004', '', 'C054; C055; C056; C057; C058; C079; C080', 'This comprehensive reference combines sampling and analysis of wildland water in one text. It includes sampling techniques for precipitation, surface water, and ground water. Analytical techniques for common water quality constituents are described.Stednick, John D. is the author of \\\'Wildland Water Quality Sampling and Analysis\\\', published 1991 under ISBN 9780126641004 and ISBN 0126641005.', '0.000000', 0.00, 83.39, '', '', '2024-10-19 21:57:39', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89524, 'Whose Backyard, Whose Risk Fear and Fairness in Toxic and Nuclear Waste Siting', 'Gerrard, Michael B.', '', '', '1996', 'MIT Press', '0', 0, '9780262571135', '', 'C054; C055; C056; C057; C058; C079; C080', '\\\"Whose Backyard is an extremely valuable treatment of an important subject.\\\"Gerrard, Michael B. is the author of \\\'Whose Backyard, Whose Risk Fear and Fairness in Toxic and Nuclear Waste Siting\\\', published 1996 under ISBN 9780262571135 and ISBN 0262571137.', '0.000000', 0.00, 78.32, '', '', '2024-10-19 21:57:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89551, 'Washington Waste Minimisation Workshop: Vol. I: Five Waste Streams to Reduce: Vol. II: Which...', 'Organisation for Economic Co-operation and Development Staff', '', '', '1996', 'Organization for Economic Cooperation &amp; Development', '0', 0, '9789264152953', '', 'C054; C055; C056; C057; C058; C079; C080', 'Organisation for Economic Co-operation and Development Staff is the author of \\\'Washington Waste Minimisation Workshop: Vol. I: Five Waste Streams to Reduce: Vol. II: Which Policies, Which Tools?\\\', published 1996 under ISBN 9789264152953 and ISBN 9264152954.', '0.000000', 0.00, 49.95, '', '', '2024-10-19 21:57:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89566, 'Beryllium, Cadmium, Mercury, and Exposures in the Glass Manufacturing Industry', 'World Health Organization Staff', '', '', '1993', 'World Health Organization', '0', 0, '9789283212584', '', 'C054; C055; C056; C057; C058; C079; C080', 'Evaluates the carcinogenic risk to humans posed by exposure to selected metals and their compounds. Separate monographs are presented for beryllium and beryllium compounds cadmium and cadmium compounds and mercury and inorganic and methylmercury compouWorld Health Organization Staff is the author of \\\'Beryllium, Cadmium, Mercury, and Exposures in the Glass Manufacturing Industry\\\', published 1993 under ISBN 9789283212584 and ISBN 9283212584.', '0.000000', 0.00, 47.51, '', '', '2024-10-19 21:57:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89628, 'Practical Handbook of Compost Engineering', 'Haug, Roger T.', '', '', '1993', 'C R C Press LLC', '0', 0, '9780873713733', '', 'C054; C055; C056; C057; C058; C079; C080', 'The Practical Handbook of Compost Engineering presents an in-depth examination of the principles and practice of modern day composting. This comprehensive book covers compost science, engineering design, operation, principles, and practice, stressing a fundamental approach to analysis throughout. Biological, physical, chemical, thermodynamic, and kinetic principles are covered to develop a unified analytical approach to analysis and an understanding of the process. A brief history of the development of composting systems, which leads to descriptions of modern processes, is presented.The Practical Handbook of Compost Engineering also discusses the elements of successful odor management at composting facilities, including state-of-the-art odor treatment and enhanced atmospheric dispersion. The book is excellent for all engineers, practitioners, plant operators, scientists, researchers, and students in the field.Haug, Roger T. is the author of \\\'Practical Handbook of Compost Engineering\\\', published 1993 under ISBN 9780873713733 and ISBN 0873713737.', '0.000000', 0.00, 341.21, '', '', '2024-10-19 21:57:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89648, 'Waste Containment Systems, Waste Stabilization, and Landfills Design and Evaluation', 'Sharma, Hari D., Lewis, Sangeeta P.', '', '', '1994', 'Wiley &amp; Sons, Incorporated, John', '0', 0, '9780471575368', '', 'C054; C055; C056; C057; C058; C079; C080', 'The most comprehensive design reference available on remediation techniques, waste disposal methods and various waste containment systems. Covers several important new issues such as the regulatory structure of RCRA Subtitles C and D; subsurface flow and transport of contaminants; liner systems, leachate collection and removal systems for landfills; and seismic stability analysis of landfills. Describes new waste stabilization technologies including the process of converting non-solid toxic waste into inert solids.Sharma, Hari D. is the author of \\\'Waste Containment Systems, Waste Stabilization, and Landfills Design and Evaluation\\\', published 1994 under ISBN 9780471575368 and ISBN 0471575364.', '0.000000', 0.00, 90.55, '', '', '2024-10-19 21:57:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89660, 'Bioindicators and Environmental Management', 'Jeffrey, D. W., Madden, B.', '', '', '1991', 'Elsevier Science &amp; Technology Books', '0', 0, '9780123825902', '', 'C054; C055; C056; C057; C058; C079; C080', 'This essential book contains material presented at a September 1990 meeting organized by the Commission for Bioindicators, International Union for Biological Sciences.**A key role of the Commission for Bioindicators (IUBS) is to promote the use of bioindicators in environmental management. This means encouraging the transfer of ideas regarding potential bioindicators, and originating in laboratories, into the harsher realities of field environmental monitoring. Although the concept of biomonitoring is ancient, its application to current monitoring problems is relatively slow to develop.**In a bid to rectify this problem, this invaluable book brings together and discusses approaches developed around the world. It will provide both environmental administrators and research scientists with a valuable sense of proportion of the state of the art in their particular field. Key Features * Bioindicators and Environmental Management is organized into four sections * Bioindicators, industry, and administration * Biomonitoring of the Chernobyl accident * Monitoring long-term/large-scale environmental trends * Basic research in biomonitoringJeffrey, D. W. is the author of \\\'Bioindicators and Environmental Management\\\', published 1991 under ISBN 9780123825902 and ISBN 0123825903.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 21:57:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89664, 'Environmental Aspects of Construction with Waste Materials: Proceeding[s] of the Internation...', 'Second International Conference on Environmental I, Goumans, J. J., Sloot, H. A. van der', '', '', '1994', 'Elsevier Science &amp; Technology Books', '0', 0, '9780444818539', '', 'C054; C055; C056; C057; C058; C079; C080', 'The concept of Sustainable Development, implicating the protection of soil and groundwater, the limitation of waste production and the re-use of soild waste materials is still the leading theme of WASCON \\\'94. Although it is clearly recognized in most countries that products derived from solid waste materials can be applied as construction materials, research is still needed to assess various environmental problems.Second International Conference on Environmental I is the author of \\\'Environmental Aspects of Construction with Waste Materials: Proceeding[s] of the International Conference on Environmental Implications of Construction Materials and Technology Developments, Maastricht, the Netherlands, 1-3 June 1994\\\', published 1994 under ISBN 9780444818539 and ISBN 0444818537.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 21:57:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89710, 'Wastewater Organisms A Color Atlas', 'Berk, Sharon G., Gunderson, John', '', '', '1993', 'C R C Press LLC', '0', 0, '9780873716239', '', 'C054; C055; C056; C057; C058; C079; C080', 'Wastewater Organisms contains 210 high-quality full-color micrographs to help you identify organisms found in sewage and sludge. These photos provide the maximum level of detail and will help you better understand the form and dimension of the organisms. Subjects depicted in the micrographs include bacteria, eggs, amoeba, parasitic protozoa, tardigrada (water bears), rotifers, ciliates, parasitic helminths, pollen grain, free-living nematodes, algae, flagellates, and more. There is a chapter on enumeration which provides literature and techniques for fixing and staining, techniques often required for identification to the species level. The book also contains a valuable glossary and index to make the book even easier to use. Wastewater Organisms is an indispensable reference for wastewater managers and supervisors, wastewater operators, environmental consultants, practicing engineers, regulatory agency personnel at all levels of government, and libraries.Berk, Sharon G. is the author of \\\'Wastewater Organisms A Color Atlas\\\', published 1993 under ISBN 9780873716239 and ISBN 087371623X.', '0.000000', 0.00, 407.71, '', '', '2024-10-19 21:57:41', '0000-00-00 00:00:00', 0, 0, 0, 0),
(89785, 'Remediation Engineering Design Concepts', 'Suthersan, Suthan S., Miller, David W.', '', '', '1996', 'Taylor &amp; Francis Group', '0', 0, '9781566701372', '', 'C054; C055; C056; C057; C058; C079; C080', 'Suthersan, Suthan S. is the author of \\\'Remediation Engineering Design Concepts\\\', published 1996 under ISBN 9781566701372 and ISBN 1566701376.', '0.000000', 0.00, 99.98, '', '', '2024-10-19 21:57:42', '0000-00-00 00:00:00', 0, 0, 0, 0),
