(90746, 'Hazardous Substances Resource Guide', 'Pohanish, Richard P., Greene, Stanley A.', '', '', '1996', 'Cengage Gale', '0', 0, '9780810390621', '', 'C054; C055; C056; C057; C058; C079; C080', 'Pohanish, Richard P. is the author of \\\'Hazardous Substances Resource Guide\\\', published 1996 under ISBN 9780810390621 and ISBN 0810390620.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 21:57:50', '0000-00-00 00:00:00', 0, 0, 0, 0),
(90775, 'Use of Waste Materials in Highway Construction', 'Ahmed, Imtiaz', '', '', '1993', 'William Andrew, Incorporated', '0', 0, '9780815513155', '', 'C054; C055; C056; C057; C058; C079; C080', 'This book outlines the state-of-the-practice in the use of waste materials in highway construction in the U.S. and discusses the applications of selected waste materials including: waste tires; waste glass; reclaimed paving materials; slags and ashes; building rubb sewage slud incinerator residue. An evaluation based on technical, environmental, and economic factors indicated that reclaimed paving materials, coal fly ash, blast furnace slag, bottom ash, boiler slag, steel slag, and rubber tires have significant potential to replace conventional materials for various applications in highway construction, and should be projected for future construction. Specific applications of the waste products and potential problems associated with their usage in highway operations are also included.Ahmed, Imtiaz is the author of \\\'Use of Waste Materials in Highway Construction\\\', published 1993 under ISBN 9780815513155 and ISBN 0815513151.', '0.000000', 0.00, 83.39, '', '', '2024-10-19 21:57:50', '0000-00-00 00:00:00', 0, 0, 0, 0),
