(90916, 'Awareness Level Training for Hazardous Materials', 'Wieder, Michael A., Smith, Carol, Brakage, Cynthia', '', '', '1995', 'I F S T A', '0', 0, '9780879391171', '', 'C054; C055; C056; C057; C058; C079; C080', 'Wieder, Michael A. is the author of \\\'Awareness Level Training for Hazardous Materials\\\', published 1995 under ISBN 9780879391171 and ISBN 0879391170.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 21:57:52', '0000-00-00 00:00:00', 0, 0, 0, 0),
(90990, 'Unit Operations in Environmental Engineering', 'Noyes, Robert, Noyes, Robert', '', '', '1994', 'William Andrew, Incorporated', '0', 0, '9780815513438', '', 'C054; C055; C056; C057; C058; C079; C080', 'This book discusses the practical aspects of environmental technology organized into eight chapters relating to unit operations as follows: 1. Biological Technology 2. Chemical Technology 3. Containment and Barrier Technology 4. Immobilization Technology 5. Membrane Technology 6. Physical Technology 7. Radiation and Electrical Technology 8. Thermal Destruction Technology Traditional technologies have been included, as well as those that can be considered innovative and emerging. The traditional approaches have been the most successful, as contractors are careful about bidding on some of the newer technologies. However, as regulatory requirements increase, markets will open for the innovative and emerging processes. There will be increasing pressure to break down complex waste streams, with each subsequent stream demanding separate treatment. In addition, a number of technologies have been developed by combining processes directly, or in a treatment train, and these developments are expected to assume increasing importance. However, such concerns as uncertainties due to liability, regulatory approval, price competition, and client approval have limited the application of some of these newer technologies.Noyes, Robert is the author of \\\'Unit Operations in Environmental Engineering\\\', published 1994 under ISBN 9780815513438 and ISBN 0815513437.', '0.000000', 0.00, 83.39, '', '', '2024-10-19 21:57:52', '0000-00-00 00:00:00', 0, 0, 0, 0),
