(94383, 'Energy Appraisal of Existing Buildings : A Handbook for Surveyors', 'RICS Energy Efficience Office Staff', '', '', '1993', 'RICS Books (Royal Institution of Charter', '0', 0, '9780854065615', '', 'C054; C055; C056; C057; C058; C079; C080', 'RICS Energy Efficience Office Staff is the author of \\\'Energy Appraisal of Existing Buildings : A Handbook for Surveyors\\\', published 1993 under ISBN 9780854065615 and ISBN 085406561X.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 21:58:22', '0000-00-00 00:00:00', 0, 0, 0, 0),
(94396, 'Guidance on the Disposal of Dredged Material to Land', 'Brooke, J.', '', '', '1996', 'Construction Industry Research &amp; Informa', '0', 0, '9780860174509', '', 'C054; C055; C056; C057; C058; C079; C080', 'This book guides the user on the safe, economic and effective disposal and management of dredged material in line with the aims of the Environmental Protection Act 1990 and associated Waste Management Regulations.Brooke, J. is the author of \\\'Guidance on the Disposal of Dredged Material to Land\\\', published 1996 under ISBN 9780860174509 and ISBN 0860174506.', '0.000000', 0.00, 0.00, '', '', '2024-10-19 21:58:22', '0000-00-00 00:00:00', 0, 0, 0, 0);
