(116853, 'Science and Technology in Japan', 'Anderson, Alun M.', '', '', '1991', 'Longman Publishing Group', '0', 0, '9780582036840', '', '', 'Anderson, Alun M. is the author of \\\'Science and Technology in Japan\\\', published 1991 under ISBN 9780582036840 and ISBN 0582036844.', '0.000000', 0.00, 0.00, '', '', '2024-10-20 06:53:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
(116918, 'Technological Transformation of Japan : From the Seventeenth to the Twenty-F', 'Morris-Suzuki, Tessa', '', '', '1994', 'Turtleback Books', '0', 0, '9780613920742', '', '', 'For decades, Japan has been at the cutting edge of much technology, becoming an industrial superpower in the process. It is not widely acknowledged, however, that Japan\\\'s status as technological leader is the result of historical processes over centuries. This landmark book is the first general English-language history of technology in modern Japan. Impressive for its scope and insight, the book also considers the social costs of rapid technological change. It will be read not only by people interested in modern and premodern Japan, but by those who wish to learn from the \\\"Japanese phenomenon.\\\"Morris-Suzuki, Tessa is the author of \\\'Technological Transformation of Japan : From the Seventeenth to the Twenty-F\\\', published 1994 under ISBN 9780613920742 and ISBN 0613920740.', '0.000000', 0.00, 0.00, '', '', '2024-10-20 06:53:40', '0000-00-00 00:00:00', 0, 0, 0, 0),
