(193174, '1205825', 'ISO 15012-1', 'Health and safety in welding and allied processes - Requirements testing and marking of equipment for air filtration - Part 1: Testing of the separation efficiency for welding fume', 'Withdraw', 'EN 1093-6*EN 1070*EN 842*EN 1093-7', '', '', 'ISO/FDIS 15012-1 (2004-07)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 15012-1:2004 deals with the significant hazards caused by the emission of welding fume particles from welding fume separation equipment operated according to its intended use and under the conditions foreseen by the manufacturer.ISO 15012-1:2004 specifies safety requirements concerning the separation of welding fumes and describes a method for determining the particle separation efficiency of welding fume separation equipment.ISO 15012-1:2004 does not deal with:hazards caused by gases emitted by welding, cutting and allied processes or by the welding fume separation equipment itself; hazards caused by the noise and vibrations of the welding fume separation equipment; other fundamental aspects of safety technology, such as electrical, mechanical and pneumatical safety, maintenance, etc.', '0', '145.00', '208.00', 'USD', 'ISO 21904-2:2020;ISO 15012-1:2013', '2103539;1855670', '13.040.40* 25.160.01* 25.160.30', 'Air cleaning equipment*Air filters*Air pollution*Air purification*Arc welding*Chemical analysis and testing*Chemical hazards*Definitions*Determination*Discarding*Emission*Emission measurement*Gases*Hazards*Health protection*Laboratory testing*Marking*Occupational safety*Particulate matter measurement*Personal health*Pollutant gases*Respiratory protections*Safety*Safety measures*Safety requirements*Sampling methods*Separating equipment*Separation*Separation efficiency*Separators*Signals*Smoke*Specification (approval)*Systems*Testing*Ventilation*Warning devices*Warnings*Waste disposal*Welding*Welding engineering*Welding smoke*Working conditions (physical)*Zones of reach', '', '2004', '22', '', '', '', '', ''),
(193175, '1205806', 'ISO 12509', 'Earth-moving machinery - Lighting, signalling and marking lights, and reflex-reflector devices', 'Active', 'ISO 6016*ISO 6165*ISO 6746-1*ISO 6747*ISO 7131*ISO 7132*ISO 7133*ISO 7134*ISO 7135*ISO 7136*CIE S 004/E*JSA JIS A 8340-1*SNV SN EN 500-1+A1*ISO 10896-1*CEN EN 474-1*JSA JIS A 8340-1*BSI BS ISO 17253*ISO 20474-10*CEN EN ISO 3691-2*DIN EN 1459-2*DIN EN ISO 3691-2*DIN EN ISO 3691-2*ISO 20474-1*BSI BS EN 15573*BSI BS EN 474-10 + A1*BSI BS EN 474-11 + A1*BSI BS EN 474-3 + A1*BSI BS EN 474-4 + A2*BSI BS EN 474-7 + A1*BSI BS EN 474-8 + A1*BSI BS EN 474-9 + A1*DIN 22270*DIN EN 474-1*DIN EN 474-1*ISO 10896-2*ISO 17253*BSI BS EN 500-1 + A1*CEN EN 1459-2*ISO 3691-2*SNV SN EN 474-1+A4*ISO 19224*DIN EN 1459-1*DIN EN 1459-1*CEN/TS 1459-8*CEN EN ISO 19296*DIN CEN/TS 1459-8*ISO DIS 20500-1*NEN-EN 1459-1+A1*SNV SN EN 1459-1+A1*BSI BS EN 474-1 + A6*CEN EN 1459-1*ISO 18758-2*ISO 19296*ISO 20297-1*CSA M424.0:22*ISO DIS 6085*NEN-EN 474-1', 'ISO 6016*ISO 6165*ISO 6746-1*ISO 6747*ISO 7131*ISO 7132*ISO 7133*ISO 7134*ISO 7135*ISO 7136*CIE S 004/E*JSA JIS A 8340-1*SNV SN EN 500-1+A1*ISO 10896-1*CEN EN 474-1*JSA JIS A 8340-1*BSI BS ISO 17253*ISO 20474-10*CEN EN ISO 3691-2*DIN EN 1459-2*DIN EN ISO 3691-2*DIN EN ISO 3691-2*ISO 20474-1*BSI BS EN 15573*BSI BS EN 474-10 + A1*BSI BS EN 474-11 + A1*BSI BS EN 474-3 + A1*BSI BS EN 474-4 + A2*BSI BS EN 474-7 + A1*BSI BS EN 474-8 + A1*BSI BS EN 474-9 + A1*DIN 22270*DIN EN 474-1*DIN EN 474-1*ISO 10896-2*ISO 17253*BSI BS EN 500-1 + A1*CEN EN 1459-2*ISO 3691-2*SNV SN EN 474-1+A4*ISO 19224*DIN EN 1459-1*DIN EN 1459-1*CEN/TS 1459-8*CEN EN ISO 19296*DIN CEN/TS 1459-8*ISO DIS 20500-1*NEN-EN 1459-1+A1*SNV SN EN 1459-1+A1*BSI BS EN 474-1 + A6*CEN EN 1459-1*ISO 18758-2*ISO 19296*ISO 20297-1*CSA M424.0:22*ISO DIS 6085*NEN-EN 474-1', '', '', NULL, 'ISO', 'English', 'This International Standard specifies the minimum requirements for installation and performance of lighting, signalling and marking lights, and reflex-reflector devices on earth-moving machines. It is applicable to self-propelled wheel or crawler earth-moving machines as defined in ISO 6165, intended for off-road, as well as on-road, use. It is not applicable to pedestrian-controlled machines.', '225.00', '225.00', '371.00', 'USD', '12509\r\n:2023;\r\nISO 12509\r\n:2004;\r\nISO 12509\r\n/1995', '2523210', '53.100', '', '', '2004', '72', '', '02.03', '', '', ''),
(193176, '1205884', 'ISO 8442-5', 'Materials and articles in contact with foodstuffs Cutlery and table holloware Part 5: Specification for sharpness and edge retention test of cutlery', 'Active', '', '', '27515722-1', '', NULL, 'ISO', 'English', 'ISO 8442-5:2004 specifies the sharpness and edge retention of knives which are produced for professional and domestic use in the preparation of food of all kinds, specifically those knives intended for hand use.Powered blade instruments of any kind are excluded.Generally these types of knife are manufactured with blades of either plain edge design or with edges incorporating particular features to enhance or optimize aspects of cutting ability.The following two types of knife blade are suitable for the cutting test.Type A edges: cutting edges which can be resharpened by the user and edges with a pitch greater than 1mm;Type B edges: cutting edges which are not intended to be resharpened on a steel.Whilst these knives are predominantly manufactured with blades made from various grades of heat treated steels, the testing of knives of any construction or blade material is not precluded providing that the test criteria are met.The principle of the testing is to reproduce a cutting action, by forward and reverse strokes, against a pack of synthetic test medium under controlled parameters.', '0', '81.00', '134.00', 'USD', 'ISO 8442-5\r\n:2004', '', '97.040.60;67.250', 'Articles*Blades*Cutlery*Cutting device*Cutting edge*Cutting tools*Cutting work*Definitions*Edge*Fitness for purpose*Flat ware*Food manufacturing processes*Food preparation equipment*Food products*Foodstuff*Hollow-ware*Knives*Marking*Materials*Materials specification*Metals*Preparation*Processing*Rating tests*Resistance*Sharpness*Specification*Specification (approval)*Steels*Table holloware*Tableware*Testing*Testing conditions*Use', '', '2004', '20', '', '02.07', '', '', ''),
(193177, '1208032', 'ISO 9606-2', 'Qualification test of welders - Fusion welding - Part 2: Aluminium and aluminium alloys', 'Active', 'ISO 857-1*EN ISO 15609-1*EN ISO 4063*EN ISO 6947*EN ISO 15607', '', '13885826-', 'ISO 9606-2 (1994-08)*ISO/FDIS 9606-2 (2004-06)*ISO 9606-2 AMD 1 (1998-08)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 9606-2:2004 specifies the requirements for qualification of welders for fusion welding of aluminium and aluminium alloys.ISO 9606-2:2004 provides a set of technical rules for systematic qualification of welders, which are independent of product type, location and examiner/examining body.The welding processes referred to in ISO 9606-2:2004 include those fusion welding processes which are designated as manual or partly mechanized welding. It does not qualify fully mechanized and automated welding processes.', '0', '194.00', '320.00', 'USD', '', '', '25.160.01', 'Acceptance*Acceptance (approval)*Accident prevention*Aluminium*Aluminium alloys*Approval laboratories*Checks*Definitions*Examination (education)*Examination of welders*Fusion welding*Inspectors*Qualification proof*Qualifications*Specification (approval)*Test certificate*Test certificates*Testing*Testing conditions*Verification*Welders*Welding*Welding engineering*Welding position*Welding work*Welds*Workplace safety*Legalization*Approval*Testing positions', '', '2004', '33', '', '', '', '', ''),
(193179, '1205835', 'ISO 17078-1', 'Petroleum and natural gas industries - Drilling and production equipment - Part 1: Side-pocket mandrels', 'Active', 'ISO 15156-1*ISO 6892*ISO 9712*ISO 11960', '', '', 'ISO/FDIS 17078-1 (2004-09)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 17078:2004 provides requirements for side-pocket mandrels used in the petroleum and natural gas industry. This part of ISO 17078 includes specifying, selecting, designing, manufacturing, quality control, testing, and preparation for shipping of side-pocket mandrels.This part of ISO 17078:2004 does not address nor include requirements for end connections between the side-pocket mandrels and the well conduit. The installation and retrieval of side-pocket mandrels is outside the scope of this part of ISO 17078:2004. Additionally, this part of ISO 17078:2004 does not include specifications for centre-set mandrels, or mandrels that employ or support tubing-retrievable flow control devices.This part of ISO 17078:2004 does not include gas-lift or any other flow-control valves or devices, latches, and/or associated wire line equipment that can or cannot be covered in other ISO specifications.The side-pocket mandrels to which this part of ISO 17078:2004 refers are independent devices that can accept installation of flow-control or other devices down-hole.', '0', '223.00', '347.00', 'USD', '', '', '75.180.10', 'Definitions*Design*Drilling equipment*Inspection*Mandrels*Natural gas industries*Oil industries*Petroleum pipeline system*Pipes*Production*Pumping devices*Selection*Side-pocket mandrels*Specification (approval)*Testing*Hoisting devices*Winding gears*Presentations', '', '2004', '40', '', '', '', '', ''),
(193181, '1205856', 'ISO 22776', 'Footwear Test methods for accessories: Touch and close fasteners Shear strength before and after repeated closing', 'Active', 'FDIS 20358', '', '', '', NULL, 'ISO', 'English', 'ISO 22776:2004 specifies a test method for determining the longitudinal shear strength of touch and close fasteners before and after repeated use.', '81.00', '81.00', '134.00', 'USD', 'ISO 22776\r\n:2004', '', '61.060', '', '', '2004', '16', '', '02.04', '', '', ''),
