(193185, '1205799', 'ISO 11197', 'Medical supply units', 'Active', '', '', '', 'ISO/FDIS 11197 (2004-06)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 11197:2004 specifies requirements and test methods for medical supply units intended for use in healthcare facilities to supply electric power and/ medical gases and/or liquids and anaesthetic gas scavenging systems. It is applicable in conjunction with IEC 60601-1:1988.The requirements of ISO 11197:2004 take priority over those of IEC 60601-1:1988.', '0', '230.00', '330.00', 'USD', 'ISO 11197:2019;ISO 11197:2016', '2093309;1911372', '11.040.10', 'Alpha radiation*Anaesthesiology*Assembling*Beta radiation*Biological hazards*Bodies*Chargings*Clamps*Classes*Cleaning*Combustible*Compensation (errors)*Components*Conglomerates*Connections*Contact*Continuous current*Corners*Covers*Defects*Definitions*Design*Designations*Determinations*Dielectric strength*Disinfection*Earth conductors*Earthing conductor terminations*Edge*Electric appliances*Electric power systems*Electric shock*Electric sockets*Electrical appliances*Electrical engineering*Electrical medical equipment*Electrical safety*Electromagnetic compatibility*Electromedicine*Electrostatics*Electrotherapy equipment*EMC*Enclosures*Energy*Environmental conditions*Environmental testing*Exits*Explosion hazard*Fire prevention*Fire protection*Fire risks*Fire safety*Fuses*Gamma-radiation*Gas supply*Gas technology*Gases*Grids*Heat protection*Hydraulics*Ignition*Information*Infrared radiation*Input current*Instrumentation*Instruments*Interfering emissions*Interruptions*Jigs*Joint efficiency*Laser beams*Layout*Liquids*Luminous radiation*Magnetism*Mains operated*Marking*Mass*Materials*Medical equipment*Medical gases*Medical sciences*Medical technology*Microwave radiation*Moisture*Neutron radiation*Noise*Outlets*Overflows*Overload relays*Paper*Part of a device*Patient auxiliary current*Patients*Pneumatics*Power consumption*Precision*Protection against electric shocks*Protection coverings*Protective devices*Radiation*Radiation protection*Rails*Safety*Safety engineering*Safety requirements*Separation*Sound energy*Specification (approval)*Stability*Sterilization (hygiene)*Strength of materials*Stress*Supply*Supply systems*Surfaces*System earthing*Taking-out*Temperature*Testing*Testing requirements*Ultraviolet radiation*Use*Values*Vibrations*Working data*X-rays*Lines*Compounds*Nets*Junctions*Stabilization*Subunit*Locking devices*Safety devices*Joints*Voltage*Network*Shock resistance', '', '2004', '38', '', '', '', '', '');
INSERT INTO `wp_tecbook_standards` (`id`, `idProduct`, `referenceNumber`, `standardTitle`, `status`, `referencedStandards`, `referencingStandards`, `equivalentStandards`, `replace`, `replacedBy`, `standardby`, `languages`, `fullDescription`, `ebookPrice`, `printPrice`, `bothPrice`, `currency`, `historicalEditions`, `documentHistoryProductId`, `icsCode`, `keyword`, `identicalStandards`, `publishedDate`, `pages`, `byTechnology`, `byIndustry`, `previewPath`, `coverPath`, `fullPath`) VALUES
(193186, '1205838', 'ISO 17432', 'Health informatics Messages and communication Web access to DICOM persistent objects', 'Inactive', '', '', '20287694-1', 'ISO/DIS 17432 (2004-02)', NULL, 'ISO', 'English', 'ISO 17432:2005 specifies a web-based service for accessing and presenting DICOM (Digital Imaging and Communications in Medicine) persistent objects (e.g. images, medical imaging reports). This is intended for distribution of results and images to healthcare professionals. It provides a simple mechanism for accessing a DICOM persistent object from HTML pages or XML documents, through HTTP/HTTPs protocol, using DICOM UIDs (Unique Identifiers). Data may be retrieved either in a presentation-ready form as specified by the requester (e.g. JPEG or GIF) or in a native DICOM format.ISO 17432:2005 does not support facilities for web searching of DICOM images. It relates only to DICOM persistent objects (not to other DICOM objects or to non-DICOM objects). Access control beyond the security mechanisms generally available to web applications is outside the scope of this International Standard.', '0', '118.00', '170.00', 'USD', '', '', '35.240.80', 'Access*Circuit networks*Communication*Computer sciences*Data exchange*Data processing*Definitions*DICOM*Digital*Digital Imaging and Communications in Medicine*EDP*Image processing*Information interchange*Information processing*Information representation*Internet*Medical informatics*Medical sciences*Personal health*Picture description information*Public health*Ratings*Web*Information exchange', '', '2004', '17', '', '02.08', '', '', ''),
(193187, '1205828', 'ISO 15219', 'Earth-moving machinery - Cable excavators - Terminology and commercial specifications', 'Active', 'ISO 6016', '', '', 'ISO/FDIS 15219 (2004-08)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 15219:2004 establishes terminology and the content of commercial literature specifications for self-propelled, crawler and wheeled cable excavators and their equipment.', '0', '223.00', '368.00', 'USD', '', '', '53.100', 'Building machines*Crawler excavators*Definitions*Earth-moving equipment*Excavators*Mechanical shovels*Rope-operated excavators*Self-propelled*Specification (approval)*Terminology*Vocabulary', '', '2004', '36', '', '', '', '', ''),
(193188, '1205872', 'ISO 5543', 'Caseins and Caseinates - Determination of Fat Content - Gravimetric Method (Reference Method)', 'Active', '', '', '', '', NULL, 'ISO', 'English', 'ISO 5543|IDF 127:2004 specifies the reference method for the determination of the fat content of all types of caseins and caseinates.', '111.00', '128.00', '183.00', 'USD', 'ISO 5543\r\n:2004;\r\nISO 5543\r\n:1986', '2252025;1172198', '67.100.99', '', '', '2004', '22', '', '02.07', '', '', ''),
(193189, '1205854', 'ISO 22774', 'Footwear Test methods for accessories: shoe laces Abrasion resistance', 'Active', 'BS EN 15090*FDIS 20358', '', '', '', NULL, 'ISO', 'English', 'ISO 22774:2004 specifies three test methods for determining the abrasion resistance of a shoelace, on repeated rubbing:method 1: lace to lace abrasion;method 2: lace to standard eyelet abrasion;method 3: lace to eyelet (from footwear) abrasion.', '81.00', '81.00', '134.00', 'USD', 'ISO 22774\r\n:2004', '', '61.060', '', '', '2004', '14', '', '02.04', '', '', ''),
(193190, '1205822', 'ISO 14649-10', 'Industrial automation systems and integration Physical device control Data model for computerized numerical controllers Part 10: General process data', 'Active', 'ISO 10303-21*ISO 10303-11*ISO 10303-514', '', '', 'ISO/FDIS 14649-10 (2004-08)', NULL, 'ISO', 'English', 'ISO 14649-10:2004 specifies the process data which is generally needed for NC-machining and therefore common to several machining technologies. These data elements describe the interface between the programming system (i.e. CAM system or shop-floor programming system) and a computerized numerical controller. The programme for the numerical controller includes geometric and technological information. It can be described using ISO 14649-10:2004 together with the technology-specific parts (ISO 14649-11, ISO 14649-12, etc.). ISO 14649-10:2004 provides the control structures for the sequence of programme execution, mainly the sequence of working steps and associated machine functions.The &quot;machining_schema&quot; defined in ISO 14649-10:2004 contains the definition of data types which are generally relevant for different technologies (e.g. milling, turning, grinding). It includes:the general executables, including workplan, workingsteps and NC-functions;the definition of the workpiece;a feature catalogue containing features which might be referenced by several technologies;the basis for an operation definition.Not included in this schema are the following:geometric items;representations, which are referenced from ISO 10303\\\'s generic resources;the technology-specific definitions, which are defined in separate parts of ISO 14649.ISO 14649-10:2004 cannot stand alone. An implementation needs in addition at least one technology-specific part (e.g. ISO 14649-11 for milling, ISO 14649-12 for turning).Additionally, the schema uses machining features similar to ISO 10303-224 and ISO 10303-214. The description of process data is done using the EXPRESS language as defined in ISO 10303-11. The encoding of the data is done using ISO 10303-21.', '0', '278.00', '459.00', 'USD', '', '', '25.040.20', 'Applications*Automation*Data models*Data representation*Definitions*Numerical control*Protocols*Implementation*Records*Use', '', '2004', '', '01.04', '', '', '', ''),
(193191, '1205855', 'ISO 22775', 'Footwear - Test methods for accessories: Metallic accessories - Corrosion resistance', 'Active', '', '', '', '', NULL, 'International Organization for Standardization', 'English', 'ISO 22775:2004 specifies two methods for determining the propensity of a metal surface to either change visually due to contamination by atmospheric pollution (Method 1: sulfide tarnishing), or to corrode due to the action of salt water (Method 2: salt water corrosion).', '54.00', '54.00', '89.00', 'USD', '', '', '', '', '', '2004', '4', '', '', '', '', ''),
(193192, '1205873', 'ISO 5548', 'Caseins and Caseinates - Determination of Lactose Content - Photometric Method', 'Active', '', '', '', '', NULL, 'ISO', 'English', 'ISO 5548|IDF 106:2004 specifies a photometric method for the determination of the content of lactose and other soluble carbohydrates in caseins and caseinates containing less than 2,0 % of total soluble carbohydrates.', '54.00', '54.00', '89.00', 'USD', 'ISO 5548\r\n:2004;\r\nISO 5548\r\n:1980', '', '67.100.99', '', '', '2004', '14', '', '02.07', '', '', ''),
(193193, '1205848', 'ISO 20864', 'Footwear Test methods for stiffeners and toepuffs - Mechanical characteristics', 'Active', 'FDIS 20995', '', '', 'ISO/FDIS 20864 (2004-05)', NULL, 'ISO', 'English', 'ISO 20864:2004 specifies three methods for determining the shape retention properties and compression strength of a domed test specimen. These methods are the following and they are applicable to footwear toepuff and stiffener:method 1: applicable to heat activated materialsmethod 2: applicable to solvent activated materialsmethod 3: applicable to non-thermoplastic fibreboard', '0', '124.00', '205.00', 'USD', 'ISO 20864\r\n:2004', '', '61.060', 'Compressive strength*Definitions*Fitness for purpose*Footwear*Form changes*Hard cardboard*Leather*Leather products*Materials*Mechanical properties*Minimum requirements*Parameters*Properties*Shape characteristic*Soles*Specification (approval)*Stiffening*Testing*Toe protection caps', '', '2004', '24', '', '02.04', '', '', ''),
(193194, '1205845', 'ISO 20645', 'Textile fabrics - Determination of antibacterial activity - Agar diffusion plate test', 'Active', '', '', '', 'ISO/FDIS 20645 (2004-05)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 20645:2004 specifies a method for the determination of the effect of antibacterial treatments applied to woven, knitted and other flat textiles. ISO 20645:2004 is applicable to testing hygienic finishes of hydrophilic, air-permeable materials or antibacterial products incorporated in the fibre. A minimum diffusion of the antibacterial treatment into the test agar is necessary with this procedure. ISO 20645:2004 is applicable to other materials, provided that it is adapted accordingly.ISO 20645:2004 is not suitable for testing textiles treated with antibacterial treatments that react with the agar.', '0', '81.00', '134.00', 'USD', '', '', '59.080.01* 59.080.30', 'Agar diffusion tests*Antimicrobial*Bacteria*Cloth*Definitions*Escapement mechanisms*Inhibition tests*Inspection*Materials testing*Microbiological-resistance tests*Microorganisms*Resistance*Testing*Textile testing*Textiles*Woven fabrics', '', '2004', '9', '', '', '', '', ''),
(193195, '1205859', 'ISO 22917', 'Superabrasives - Limit deviations and run-out tolerances for grinding wheels with diamond or cubic boron nitride', 'Active', '', '', '', 'ISO/FDIS 22917 (2004-08)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 22917:2004 applies to all rotating grinding tools with diamond or cubic boron nitride with metal, vitrified or resinoid bonded cores, and circular bores for mounting the grinding tool on a clamping flange as well as to grinding points with cylindrical spindle for mounting in collets. It contains the significant limit deviations and run-out tolerances of these grinding tools.', '0', '141.00', '203.00', 'USD', 'ISO 22917:2016', '1910930', '25.100.70', 'Abrasives*Boron-nitride wheels*Concentricity tolerance*Definitions*Designations*Diamond tools*Dimensions*Grinding wheels*Limit deviations*Rotating*Run-out tolerances*Terms*Tolerances (measurement)*Tools*Abrasive flap wheels', '', '2004', '18', '', '', '', '', ''),
(193196, '1205861', 'ISO 2911', 'Sweetened Condensed Milk - Determination of Sucrose Content - Polarimetric Method', 'Active', 'EN ISO 22184;NEN-ISO 22184;BS EN ISO 22184;ISO 22184;SN EN ISO 22184', 'EN ISO 22184;NEN-ISO 22184;BS EN ISO 22184;ISO 22184;SN EN ISO 22184', '', '', NULL, 'ISO', 'English', 'ISO 2911|IDF 35:2004 specifies a polarimetric method for the determination of sucrose in sweetened condensed milk.The method is applicable to sweetened condensed milk of normal composition prepared from whole, partially skimmed or skimmed milk and sucrose only and containing no altered sucrose.', '81.00', '81.00', '134.00', 'USD', 'ISO 2911\r\n:2004;\r\nISO 2911\r\n:1976', '', '67.100.10', '', '', '2004', '14', '', '02.07', '', '', ''),
