(193201, '1205817', 'ISO 140-3/Amd1', 'Acoustics - Measurement of sound insulation in buildings and of building elements - Part 3: Laboratory measurements of airborne sound insulation of building elements - Amendment 1: Installation guidelines for lightweight twin leaf partitions', 'Active', '', '', '', '', NULL, 'International Organization for Standardization', 'English', '', '16.00', '18.00', '26.00', 'USD', 'ISO 10140-1:2021;ISO 10140-1:2016;ISO 10140-1:2010;ISO 140-16:2006;ISO 140-11:2005;ISO 140-1/Amd1:2004;ISO 140-6:1998;ISO 140-8:1997;ISO 140-1:1997;ISO 140-3:1995;ISO 140-10:1991', '2222286;1923809;1734126;1279659;1222915;1205816;21327;715679;43757;38860;38864', '', '', '', '2004', '1', '', '', '', '', ''),
(193203, '1205882', 'ISO 7238', 'Butter - Determination of pH of the Serum - Potentiometric Method', 'Active', 'BS 5086-7', '', '', '', NULL, 'ISO', 'English', 'ISO 7238|IDF 104:2004 specifies a potentiometric method for the determination of the pH of the serum from all types of butter.', '54.00', '54.00', '89.00', 'USD', 'ISO 7238\r\n:2004;\r\nISO 7238\r\n:1983', '', '67.100.20', '', '', '2004', '12', '', '02.07', '', '', ''),
(193204, '1205871', 'ISO 5538', 'Milk and Milk Products - Sampling - Inspection by Attributes', 'Active', '', 'ISO 707*ISO 707*BSI BS ISO 20042*BSI BS EN ISO 707*ISO 20042*ISO 20043-1*CEN EN ISO 20042*NEN-EN-ISO 20042*NEN-ISO 20042*BSI 23/30429411 DC*ISO DIS 23548', '', '', NULL, 'ISO', 'English', 'ISO 5538|IDF 113:2004 specifies sampling plans for the inspection by attributes of milk and milk products. It is intended to be used to choose a sample size for any situation where it is required to measure the conformity to a specification of a lot of a dairy product by examination of a representative sample. ISO 5538|IDF 113:2004 is applicable to the sampling of all milk products submitted in discrete lots, irrespective of whether the lots are from the sample production. The acceptance or otherwise of any lot is a matter for the parties to a contract and is outside the scope of ISO 5538|IDF 113:2004.ISO 5538|IDF 113:2004 is intended to be used in all cases where attribute sampling plans are required for a dairy product, except that if specific compositional standards, specifications or contracts include different sampling. ISO 5538|IDF 113:2004 is not applicable to sampling for microbiological defects, unless otherwise agreed by the interested parties.', '166.00', '166.00', '274.00', 'USD', 'ISO 5538\r\n:2004;\r\nISO 5538\r\n:1987', '', '67.100.01', '', '', '2004', '28', '', '02.07', '', '', ''),
(193205, '1205826', 'ISO 1514', 'Paints and varnishes - Standard panels for testing', 'Active', '', '', '16282014-', 'ISO/FDIS 1514 (2004-09)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 1514:2004 specifies several types of standard panel and describes procedures for their preparation prior to painting. These standard panels are for use in general methods of test for paints, varnishes and related products.', '0', '141.00', '203.00', 'USD', 'ISO 1514:2024;ISO 1514:2016', '2910222;1922286', '87.040', 'Aluminium*Asbestos cement*Bearings*Boards*Cements*Cleaning*Coating materials*Coatings*Colour*Fibres*Glass*Glass slabs*Hard*Hardboards*Lacquers*Leaf fibres*Materials*Paints*Panels*Plaster cardboards*Plaster of Paris*Preparation*Sample preparation*Samples*Sampling methods*Sheet materials*Solvents*Specimen preparation*Standard test plate*Steels*Storage*Test equipment*Test panels*Testing*Tin-plate*Varnishes*Plates*Planks*HART*Tiles*Sheets', '', '2004', '16', '', '', '', '', ''),
(193206, '1205833', 'ISO 15989', 'Plastics - Film and sheeting - Measurement of water-contact angle of corona-treated films', 'Active', '', '', '', 'ISO/DIS 15989 (2001-03)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 15989:2004 specifies a method of measuring the contact angle of water droplets on corona-treated polymer film surfaces and subsequently determining the wetting tension of the film.The method is applicable to practically any polymer film. It is not applicable, however, if the surface of the film exhibits a chemical affinity for water.', '0', '81.00', '134.00', 'USD', '', '', '83.140.10', 'Angle of incidence*Definitions*Determination*Dripping water*Films*Foil*Influence of water*Packaging material*Plastic sheets*Plastics*Polymers*Sheets*Specification*Surface tension*Test equipment*Testing*Verification*Wetting*Railways', '', '2004', '12', '', '', '', '', ''),
(193207, '1208017', 'ISO 2380-1', 'Assembly tools for screws and nuts - Screwdrivers for slotted-head screws - Part 1: Tips for hand- and machine-operated screwdrivers', 'Active', '', '', '', 'ISO 2380-1 (1997-12)*ISO/DIS 2380-1 (2003-08)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 2380-1:2004 specifies the shape/form, dimensions and designation of the tips of hand- and machine-operated screwdrivers for slotted-head screws. It also gives the technical specifications and test conditions for the screw-drivers and, in the case of hand-operated screwdrivers, specifies the test torque which the blade-to-handle connection shall withstand.', '0', '54.00', '89.00', 'USD', '', '', '25.140.01', 'Blades*Combination*Cutting edge*Designations*Dimensions*Hand operated*Hand tools*Machine operated*Machine tools*Marking*Screw driver blade*Screw drivers*Screwdrivers*Shape*Slotted screws*Slotted-head fasteners*Specification (approval)*Testing*Tip*Tools*Torque*Coned point*Point', '', '2004', '6', '', '', '', '', ''),
(193208, '1205837', 'ISO 1740', 'Milkfat products and butter - determination of fat acidity (Reference method)', 'Active', '', 'ISO 16958*ISO 17678*CEN EN ISO 17678*ISO 660*CEN EN ISO 16958*BSI BS EN ISO 17678 - TC*CEN EN ISO 660*SNV SN EN ISO 17678*SNV SN EN ISO 16958*SNV SN EN ISO 660*NEN-EN-ISO 660', '', 'ISO 1740 (1991-07)*ISO/FDIS 1740 (2004-08)', NULL, 'ISO', 'English', 'ISO 1740|IDF 6:2004 specifies a method for the determination of the acidity of the fat contained in milkfat products and in butter.', '0', '81.00', '134.00', 'USD', 'ISO 1740\r\n:2004;\r\nISO 1740\r\n:1991', '', '67.100.30;67.100.10', 'Acid number*Agricultural products*Butter*Chemical analysis and testing*Dairy products*Definitions*Determination of content*Edible fats*Fatty acids*Food products*Milk products', '', '2004', '14', '', '02.07', '', '', ''),
(193209, '1205285', 'ISO 8601', 'Data elements and interchange formats - Information interchange - Representation of dates and times', 'Active', '', '', '', 'ISO/FDIS 8601 (2004-07)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 8601:2004 is applicable whenever representation of dates in the Gregorian calendar, times in the 24-hour timekeeping system, time intervals and recurring time intervals or of the formats of these representations are included in information interchange. It includescalendar dates expressed in terms of calendar year, calendar month and calendar day of the month;ordinal dates expressed in terms of calendar year and calendar day of the year;week dates expressed in terms of calendar year, calendar week number and calendar day of the week;local time based upon the 24-hour timekeeping system;Coordinated Universal Time of day;local time and the difference from Coordinated Universal Time;combination of date and time of day;time intervals;recurring time intervals.ISO 8601:2004 does not cover dates and times where words are used in the representation and dates and times where characters are not used in the representation.ISO 8601:2004 does not assign any particular meaning or interpretation to any data element that uses representations in accordance with ISO 8601:2004. Such meaning will be determined by the context of the application.', '0', '186.00', '267.00', 'USD', 'ISO 8601-1:2019', '2036765', '01.140.30* 35.240.30', 'Calendars*Clock time*Data elements*Data exchange*Data processing*Data representation*Dates*Dates (calendar)*Days*Definitions*Documentation*Exchange formats*Formats*Hours*Information exchange*Information interchange*Representations*Terms*Time*Years', '', '2004', '33', '', '', '', '', ''),
