(193213, '1205858', 'ISO 22867', 'Forestry machinery -  Vibration test code for portable hand-held  machines with internal combustion engine - Vibration at the handles', 'Active', '', '', '', '', NULL, 'International Organization for Standardization', 'English', 'ISO 22867:2004 specifies a vibration test code for determining, efficiently and under standardized conditions, the magnitude of vibration at the handles of portable hand-held, internal-combustion-engine-powered forestry machines such as chain-saws, brush-cutters and grass-trimmers. The code is applicable to manufacturer\\\'s product controls as well as type tests. It is intended that the results obtained will be able to be used to compare different machines or different models of the same type of machine. Although the magnitudes measured are obtained in an artificial operation, they nevertheless give an indication of the values to be found in a real work situation.', '106.00', '122.00', '175.00', 'USD', 'ISO 22867:2021;ISO 22867:2011', '2240305;1822404', '', '', '', '2004', '18', '', '', '', '', ''),
(193214, '1205849', 'ISO 21029-1', 'Cryogenic vessels - Transportable vacuum insulated vessels of not more than 1 000 litres volume - Part 1: Design, fabrication, inspection and tests', 'Active', 'ISO 21013-3*ISO 21028-2*ISO 21028-1*EN 13068-3*ISO 9712*ISO 11117*ISO 4126-2*EN 12300', '', '', 'ISO/DIS 21029-1 (2004-01)', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 21029-1:2004 specifies requirements for the design, fabrication, inspection and testing of transportable vacuum-insulated cryogenic vessels of not more than 1 000 l volume designed to operate at a maximum permissible pressure greater than atmospheric.ISO 21029-1:2004 applies to transportable vacuum-insulated cryogenic vessels for non-toxic gases (asphyxiant, oxidizing and flammable).', '0', '267.00', '383.00', 'USD', 'ISO 21029-1:2018', '2013820', '23.020.40', 'Commissioning*Compressed gases*Containers*Cooling equipment*Cryogenic*Cryogenic vessels*Definitions*Design*Fluids*Fuel gases*Gas holders*Gas pressure vessels*Insulated*Insulations*Maintenance*Mobile*Preparation*Production*Safety engineering*Safety requirements*Specification (approval)*Testing*Transport boxes*Vacuum*Volumes*Workplace safety*Tanks*Presentations*Burning gases', '', '2004', '90', '', '', '', '', ''),
