(274751, '2592150', 'TIA ANSI/TIA-604-3-B', 'FOCIS-3 Fiber Optic Connector Intermateability Standard, Type SC and SC-APC', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', 'ANSI APPROVED\n        \n\n      FOCIS 3a presents the intermateability standard for connectors with the commercial designations SC and SC-APC, and includes requirements for PM fiber connectors. This standard is issued as an addendum to TIA/EIA 604, Fiber Optic Connector Intermateability Standards. The provisions of TIA/EIA 604 apply to this document.', '', '100.00', '', 'USD', 'TIA TIA-604-3-B;TIA ANSI/TIA/EIA-604-3A;TIA TIA/EIA-604-3', '2593923;2593973;2591821', '', '', '', '2004', '26', '', '', '', '', ''),
(274753, '2591739', 'TIA ANSI/TIA-604-2-B', 'FOCIS-2 Fiber Optic Connector Intermateability Standard, Type ST', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', 'ANSI APPROVED\n        \n\n      FOCIS 2B presents the intermateability standard for connectors with the commercial designation ST, and includes requirements for PM fiber connectors. This standard is issued as an addendum to TIA/EIA 604, Fiber Optic Connector Intermateability Standards. The provisions of TIA/EIA 604 apply to this document.', '', '100.00', '', 'USD', 'TIA TIA-604-2-B;TIA ANSI/TIA-604-2-A', '2592916;2593876', '', '', '', '2004', '24', '', '', '', '', ''),
(274754, '2592633', 'TIA ANSI/TIA-102.CAAA-B', 'Digital C4FM/CQPSK Transceiver Measurement Methods', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', 'This standard provides definition, methods of measurement, and performance standards for radio equipment used in the Private (Dispatch) Land Mobile Services that employ C4FM or CQPSK modulation, for transmission and reception of voice or data using digital techniques, with or without encryption, with a frequency of 1 GHz or less. The definition and description of the system in which this equipment operates is given in the Project 25 System and Standard Family document (TIA TSB-102-A). The TIA Common Air Interface standard (TIA-102.BAAA-A) defines the requirements of both the Physical Layer and the Data Link Layer in the OSI reference model for the radio interface in which this equipment operates.Use of this standard is encouraged for any application of similar equipment with C4FM or CQPSK modulation, and may be applicable to equipment other than those listed above. However, this standard is not intended to cover transceiver equipment employing any or all modulation types or access methods. Therefore, the applicability of this document to digital transceiver equipment other than that called out in the scope must be carefully examined.', '', '298.00', '', 'USD', 'TIA TIA-102.CAAA-F;TIA ANSI/TIA-102.CAAA-E;TIA ANSI/TIA-102.CAAA-D;TIA ANSI/TIA-102.CAAA-C;TIA ANSI/TIA-102.CAAA-A', '2594166;2591437;2592083;2592392;2593491', '', '', '', '2004', '184', '', '', '', '', ''),
(274755, '2592006', 'TIA ANSI/TIA-604-5-C', 'FOCIS-5 Fiber Optic Connector Intermateability Standard, Type MPO', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', '', '', '100.00', '', 'USD', 'TIA TIA-604-5-F;TIA TIA-604-5-F;TIA TIA-604-5-E;TIA TIA-604-5-D;TIA ANSI/TIA-604-5B;TIA ANSI/TIA/EIA-604-5-A;TIA ANSI/TIA/EIA-604-5', '2911537;2594433;2592238;2593294;2593145;2591701;2591518', '', '', '', '2004', '30', '', '', '', '', ''),
(274756, '2591507', 'TIA ANSI/TIA-603-C', 'Land Mobile FM or PM - Communications Equipment - Measurement and Performance Standards', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', 'This standard provides definition, methods of measurement and\nperformance standards for radio\nequipment used in the Private (Dispatch) Land Mobile Services that\nemploy FM or PM modulation, for\ntransmission of voice or data using analog or digital techniques, with\na frequency of 1 GHz or\nless.\n\nThis standard may be applicable to services other than those listed\nabove. Use of this standard is\nencouraged for any application of similar equipment. However, the user\nshould review the required\nstandards needed for the specific application.\n\nStandards for equipment employing digital C4FM or CQPSK modulation may\nbe found in TIA-102.CAAA-B\nand TIA-102.CAAB-B.\n\nThis standard is promulgated to apply to land-mobile equipment\nlicensed under Federal\nCommunications Commission (FCC Part 90) in the Public Safety, Special\nEmergency, and Industrial\nRadio Services.\n\nThe measurement procedures of this standard are also applicable to the\nGeneral Mobile Radio Service\n(GMRS) (25 kHz spaced channels only) in the 450 to 470 MHz band (FCC\nPart 95), as well as Remote\nBroadcast Pickup (voice quality only) (FCC Part 74). Certain sections\nof this standard are\napplicable to the VHF Marine Radio Service (FCC Part 80) and the\nCommon Carrier Radio Service (FCC\nPart 22). This standard may also have applicability to equipment in\nthe 700 MHz band covered by FCC\nPart 27. However, technical standards may vary depending on FCC rules\nfor those services.', '', '322.00', '', 'USD', 'TIA TIA-603-F;TIA ANSI/TIA-603-E;TIA ANSI/TIA-603-D;TIA ANSI/TIA-603-B;TIA ANSI/TIA/EIA-603-A;TIA ANSI/TIA/EIA-603', '2593837;2591761;2592004;2592770;2593320;2592833', '', '', '', '2004', '226', '', '', '', '', ''),
(275038, '2591347', 'TIA ANSI/TIA/EIA-569-A-7', 'Commercial Building Standard for Telecommunications Pathways and Spaces Addendum 7 - Cable Trays and Wireways', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', '', '', '100.00', '', 'USD', '', '', '', '', '', '2001', '14', '', '', '', '', ''),
(275039, '2593224', 'TIA ANSI/TIA/EIA-124-D', 'Wireless Radio Telecommunications Intersystem Non-Signaling Data Communication DMH (Data Message Handler)', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', '', '', '534.00', '', 'USD', 'TIA ANSI/TIA-124-E;TIA ANSI/TIA-124-E;TIA TIA-124-E;TIA TIA-124-E', '2593221;2593499;2593812;2592248', '', '', '', '2001', '864', '', '', '', '', ''),
(275041, '2594096', 'TIA TIA/EIA-568-B.2-2', 'Commercial Building Telecommunications Cabling Standard Part 2: Balanced Twisted-Pair Cabling Components Addendum 2', 'Revised', '', '', '', '', NULL, 'TIA - Telecommunications Industry Association', 'English', 'Purpose:The purpose of this addendum is to revise sub-clauses 4.3.4.8, 4.4, 4.4.1, 4.4.4.9, and 5.4.3 of TIA/EIA-568-B.2. These revisions are identified in the following text with additions shown in bold italics and deletions shown as strikeout.', '', '100.00', '', 'USD', '', '', '', '', '', '2001', '8', '', '', '', '', ''),
