(1103370, '2522584', 'ICC IEBC-2021 Commentary', '2021 International Existing Building Code and Commentary', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'A practical tool that helps you to master the code you deal with every day!This comprehensive publication provides a convenient reference for regulations in the 2021 International Existing Building Code® (IEBC®).', '', '', '', 'USD', 'ICC IEBC-2018 Commentary;ICC IEBC-2015 Commentary;ICC IEBC-2012 Commentary;ICC IEBC-2009 Commentary;ICC IEBC-2006 Commentary;ICC IEBC-2003 Commentary', '2042440;1939155;1842244;1775586;1743386;1174232', '', '', '', '2022', '487', '', '', '', '', ''),
(1103371, '2560795', 'ICC IFC-2021 Commentary', '2021 International Fire Code and Commentary', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'The 2021 International Fire Code and Commentary is a two volume set (Volumes not sold separately). Volume 1 contains chapters 1 through 19 and Volume 2 contains chapters 20 through 80 and the appendices.A practical tool that helps you to master the code you deal with every day!This comprehensive publication provides a convenient reference for regulations in the 2021 International Fire Code® (IFC®).Presented in an easy-to-reference format, the commentary includes the full text of the code, including tables and figures, followed by corresponding commentary at the end of each section in one document. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures.This in-depth publication focuses on providing the full meaning and implications of the 2021 IFC®. The commentaries are designed to suggest the most effective method of application, and the consequences of not adhering to the code.This is an excellent reference for code officials, engineers, architects, inspectors, plans examiners, contractors and anyone who needs a better understanding of the 2021 IFC®.', '', '', '', 'USD', 'ICC IFC-2018 Commentary;ICC IFC-2015 Commentary;ICC IFC-2012 Commentary;ICC IFC-2009 Commentary;ICC IFC-2006 Commentary;ICC IFC-2003 Commentary', '2037293;1904231;1836614;1694506;1694486;1174229', '', '', '', '2022', '1590', '', '', '', '', ''),
(1103372, '2560842', 'ICC IRC-2021 Vol. 2 Commentary', '2021 International Residential Code and Commentary - Volume 2 (Chapters 12-43)', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'This comprehensive publication provides a convenient reference for regulations in chapters 12 through 43 of the 2021 International Residential Code (IRC®).The commentary series is presented in an easy-to-understand format. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures. This in-depth publication focuses on providing the full meaning and implications of the 2021 IRC®. The commentaries are designed to suggest the most effective method of application, and the consequences of not adhering to the code.', '', '', '', 'USD', 'ICC IRC-2018 Vol. 2 Commentary;ICC IRC-2018 Commentary Combo;ICC IRC-2015 Vol. 2 Commentary;ICC IRC-2015 Commentary Combo;ICC IRC-2012 Vol. 2 Commentary;ICC IRC-2012 Commentary Combo;ICC IRC-2009 Vol. 2 Commentary;ICC IRC-2009 Commentary Combo;ICC IRC-2006 Commentary Combo;ICC IRC2-2006 Commentary', '2037296;2037297;1904233;1904234;1836759;1836764;1743526;1743546;1316525;1316505', '', '', '', '2022', '1105', '', '', '', '', ''),
(1103373, '2560832', 'ICC IRC-2021 Vol. 1 Commentary', '2021 International Residential Code and Commentary - Volume 1 (Chapters 1-11)', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'This comprehensive publication provides a convenient reference for regulations in chapters 1 through 11 of the 2021 International Residential Code® (IRC®).The commentary series is presented in an easy-to-understand format. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures. This in-depth publication focuses on providing the full meaning and implications of the 2021 IRC®.', '', '', '', 'USD', 'ICC IRC-2018 Vol. 1 Commentary;ICC IRC-2018 Commentary Combo;ICC IRC-2015 Vol. 1 Commentary;ICC IRC-2015 Commentary Combo;ICC IRC-2012 Vol. 1 Commentary;ICC IRC-2012 Commentary Combo;ICC IRC-2009 Vol. 1 Commentary;ICC IRC-2009 Commentary Combo;ICC IRC-2006 Commentary Combo;ICC IRC1-2006 Commentary', '2037295;2037297;1904232;1904234;1836758;1836764;1743506;1743546;1316525;1287602', '', '', '', '2022', '949', '', '', '', '', ''),
(1103374, '2560825', 'ICC ISPSC-2021 Commentary', '2021 International Swimming Pool and Spa Code and Commentary', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'This comprehensive publication provides a convenient reference for regulations in the 2021 International Swimming Pool and Spa Code® (ISPSC®). Presented in an easy-to-reference format, the commentary includes the full text of the code, including tables and figures, followed by corresponding commentary at the end of each section in one document. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures.', '', '', '', 'USD', 'ICC ISPSC-2018 Commentary;ICC ISPSC-2015 Commentary', '2077905;1899326', '', '', '', '2022', '161', '', '', '', '', ''),
(1103375, '2502336', 'ICC IBC-2021 Commentary Volume 1', '2021 International Building Code and Commentary Vol, 1 (Chapters 1-15)', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'A practical tool that helps you to master the code you deal with every day!This comprehensive publication provides a convenient reference for regulations in chapters 1 through 15 of the 2021 International Building Code® (IBC®).Presented in an easy-to-reference format the commentary includes the full text of the code, including tables and figures, followed by corresponding commentary at the end of each section in one document. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures.This in-depth publication focuses on providing the full meaning and implications of the 2021 IBC®. The commentaries are designed to suggest the most effective method of application, and the consequences of not adhering to the code.This is an excellent reference for code officials, engineers, architects, inspectors, plans examiners, contractors and anyone who needs a better understanding of the 2021 IBC®.', '', '', '', 'USD', 'ICC IBC-2018 Commentary Combo;ICC IBC-2018 Commentary Volume 1;ICC IBC-2015 Commentary Combo;ICC IBC-2015 Commentary Volume 1;ICC IBC-2012 Commentary Combo;ICC IBC-2012 Commentary Volume 1;ICC IBC-2009 Commentary Combo;ICC IBC-2009 Commentary Volume 1;ICC IBC-2006 Commentary Combo;ICC IBC1-2006 Commentary;ICC IBC-2003 Commentary Set;ICC IBC1-2003 Commentary', '2037300;2037298;1899350;1899327;1836890;1836888;1681186;1681146;1287766;1287600;1174235;1174233', '', '', '', '2022', '1229', '', '', '', '', ''),
(1103376, '2502024', 'ICC IPC-2021 Commentary', '2021 International Plumbing Code and Commentary', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'A practical tool that helps you to master the code you deal with every day!&nbsp;This comprehensive publication provides a convenient reference for regulations in the 2021 International Plumbing Code® (IPC®).', '', '', '', 'USD', 'ICC IPC-2018 Commentary;ICC IPC-2015 Commentary;ICC IPC-2012 Commentary;ICC IPC-2009 Commentary;ICC IPC-2006 Commentary;ICC IPC-2003 Commentary', '2037301;1899324;1836625;1743486;1531745;1159985', '', '', '', '2022', '631', '', '', '', '', ''),
(1103377, '2502337', 'ICC IBC-2021 Commentary Volume 2', '2021 International Building Code and Commentary Vol, 2', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'A practical tool that helps you to master the code you deal with everyday!This comprehensive yet concise publication provides a convenient reference for regulations in chapters 16 through 35 of the 2021 International Building Code® (IBC®).The commentary series is presented in an easy-to-understand format. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures.This in-depth publication focuses on providing the full meaning and implications of the 2021 IBC®. The commentaries are designed to suggest the most effective method of application, and the consequences of not adhering to the code.This is an excellent reference for code officials, engineers, architects, inspectors, plans examiners, contractors and anyone who needs a better understanding of the 2021 IBC®.', '', '', '', 'USD', 'ICC IBC-2018 Commentary Combo;ICC IBC-2018 Commentary Volume 2;ICC IBC-2015 Commentary Combo;ICC IBC-2015 Commentary Volume 2;ICC IBC-2012 Commentary Combo;ICC IBC-2012 Commentary Volume 2;ICC IBC-2009 Commentary Combo;ICC IBC-2009 Commentary Volume 2;ICC IBC-2006 Commentary Combo;ICC IBC2-2006 Commentary;ICC IBC-2003 Commentary Set;ICC IBC2-2003 Commentary', '2037300;2037299;1899350;1899328;1836890;1836889;1681186;1681166;1287766;1287601;1174235;1174234', '', '', '', '2022', '737', '', '', '', '', ''),
(1103378, '2560717', 'ICC 400-2022', 'Standard on the Design and Construction of Log Structures', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'This standard provides the minimum design requirements for new log structures, including structural, thermal envelope and fire-resistance provisions.Notable changes from the 2017 edition include:New tabulated reference provides the weight per square foot of wall surface area of log-walls at 21-percent design moisture content by average width and specific gravity. Additional factors noted to adjust moisture content and/or nominal size/ shape to average width.Section 302.2.4 Notching and boring: Now provides multiple paths (e.g., prescriptive, calculated) for acceptance of notching and boring of beams. Two new illustrations replace Figure 302.2.4.Section 302.3 Mechanical connections and fasteners: Updated prescriptive path compliance for ANSI/AWC specification in the National Design Specification (NDS), alternative evaluation path for proprietary (nonconforming) fasteners, and specified analysis for wood dowels.New tabulated reference providing the bearing capacity (lb/in) of wall-logs, which is useful for calculating the continuous load path.Updated US Climate Zone map to reflect updates in the 2021 IECC.Improved criteria for settling devices to ensure structural integrity.Section 305 Thermal envelope: Updated to clarify the relationship to infiltration (Section 306) and the relationship to the 2021 IECC Commercial and Residential provisions.Table 305.3.1.1: Updated to ½-inch average width increments and notes for modification of U-factor based on shape and climate zone. Table 305.3.1.2: Updated to show prescriptive compliance options given a minimum average log-wall thickness.', '', '', '', 'USD', 'ICC 400-2012;ICC 400-2007', '1831505;1621245', '', '', '', '2021', '94', '', '', '', '', ''),
(1103379, '2505078', 'ICC IECC-2021 Commentary', '2021 IECC Code and Commentary', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'This comprehensive publication provides a convenient reference for regulations in the 2021 International Energy Conservation Code® (IECC®).The commentary series is presented in an easy-to-understand format. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures. This in-depth publication focuses on providing the full meaning and implications of the 2021 IECC®.The commentaries are designed to suggest the most effective method of application, and the consequences of not adhering to the code. This is an excellent reference for code officials, engineers, architects, inspectors, plans examiners, contractors and anyone who needs a better understanding of the 2021 IECC®.', '', '', '', 'USD', 'ICC IECC-2018 Commentary;ICC IECC-2015 Commentary;ICC IECC-2012 Commentary;ICC IECC-2009 Commentary;ICC IECC-2006 Commentary;ICC IECC-2003 Commentary', '2037294;1930606;1866681;1743466;1743406;1174225', '', '', '', '2021', '459', '', '', '', '', ''),
(1103380, '2560799', 'ICC IFGC-2021 Commentary', '2021 International Fuel Gas Code and Commentary', 'Active', '', '', '', '', NULL, 'ICC - International Code Council', 'English', 'A practical tool that helps you to master the code you deal with every day! This comprehensive publication provides a convenient reference for regulations in the 2021 International Fuel Gas Code® (IFGC®). Presented in an easy-to-reference format, the commentary includes the full text of the code, including tables and figures, followed by corresponding commentary at the end of each section in one document. Every chapter begins with \\\"General Comments\\\" and \\\"Purpose\\\" sections followed by code and commentary to subsequent sections, tables and figures.This in-depth publication focuses on providing the full meaning and implications of the 2021 IFGC®. The commentaries are designed to suggest the most effective method of application, and the consequences of not adhering to the code.This is an excellent reference for code officials, engineers, architects, inspectors, plans examiners, contractors and anyone who needs a better understanding of the 2021 IFGC®.', '', '', '', 'USD', 'ICC IFGC-2018 Commentary;ICC IFGC-2015 Commentary;ICC IFGC-2012 Commentary;ICC IFGC-2009 Commentary;ICC IFGC-2006 Commentary;ICC IFGC-2003 Commentary', '2077904;1899322;1836757;1775568;1743407;1174231', '', '', '', '2021', '429', '', '', '', '', ''),
