(1241421, '', 'DIN EN 61280-1-1', 'Fibre optic communication subsystem basic test procedures - Part 1-1: Test procedures for general communication subsystems - Transmitter output optical power measurement for single-mode optical fib...', 'Inactive', '', '', '', '', NULL, 'DIN', 'English', 'Scope and object\r\nThis part of IEC 61280 applies to fibre optic general\r\ncommunication subsystems. The object of this part is to measure the\r\noptical power coupled from the output of a transmitter under test\r\ninto single-mode optical fibre cable containing\r\ndispersion-unshifted fibre or dispersion-shifted fibre.', '', '', '', 'USD', 'DIN EN 61280-1-1\r\n:2011', '', '33.180.10', '', '', '2011', '17', '01.05', '', '', '', ''),
(1241422, '', 'DIN EN 62643-1', 'Electrostatic Micro Electro Mechanical Systems (MEMS) Oscillators of assessed quality - Part 1: Generic specification (IEC 49/939/CD:2011)', 'Inactive', '', '', '', '', NULL, 'DIN', 'English', '', '', '', '', 'USD', 'DIN EN 62643-1\r\n:2011', '', '31.140', '', '', '2011', '167', '01.05', '', '', '', ''),
